static void die_oom(void) {
    fprintf(stderr, "LisPy: out of memory\n");
    exit(2);
}

static void *xmalloc(size_t n) {
    void *p = malloc((n == 0U) ? 1U : n);
    if (p == NULL) die_oom();
    return p;
}

static void *xcalloc(size_t n, size_t s) {
    void *p = calloc((n == 0U) ? 1U : n, (s == 0U) ? 1U : s);
    if (p == NULL) die_oom();
    return p;
}

static void *xrealloc(void *p, size_t n) {
    void *q = realloc(p, (n == 0U) ? 1U : n);
    if (q == NULL) die_oom();
    return q;
}

static char *xstrdup_c(const char *s) {
    size_t n = strlen(s);
    char *out = (char *)xmalloc(n + 1U);
    memcpy(out, s, n + 1U);
    return out;
}

static void strvec_init(StrVec *v) {
    v->data = NULL;
    v->size = 0;
    v->cap = 0;
}

static void strvec_push_owned(StrVec *v, char *s) {
    if (v->size >= v->cap) {
        int nc = (v->cap <= 0) ? 8 : v->cap * 2;
        v->data = (char **)xrealloc(v->data, (size_t)nc * sizeof(char *));
        v->cap = nc;
    }
    v->data[v->size++] = s;
}

static void strvec_push_copy(StrVec *v, const char *s) {
    strvec_push_owned(v, xstrdup_c(s));
}

static void strvec_free(StrVec *v) {
    int i;
    for (i = 0; i < v->size; ++i) free(v->data[i]);
    free(v->data);
    v->data = NULL;
    v->size = 0;
    v->cap = 0;
}

static void compilation_unit_frame_init(CompilationUnitFrame *frame, CompilationUnitFrame *prev, int overridep) {
    frame->prev = prev;
    frame->overridep = overridep;
    strvec_init(&frame->warnings);
}

static void compilation_unit_frame_dispose(CompilationUnitFrame *frame) {
    strvec_free(&frame->warnings);
}

static CompilationUnitFrame *interp_compilation_unit_warning_target(Interp *it) {
    CompilationUnitFrame *frame = NULL;
    CompilationUnitFrame *outermost = NULL;
    if (it == NULL) return NULL;
    for (frame = it->compilation_units; frame != NULL; frame = frame->prev) {
        if (outermost == NULL) outermost = frame;
        if (frame->overridep) return frame;
    }
    return outermost;
}

static int warning_message_emit(Interp *it, Env *env, const char *message, char *err, size_t errsz) {
    Value *error_stream = NULL;
    int is_bound = 0;
    const char *text = (message != NULL) ? message : "warning";
    if (symbol_value_lookup_runtime_special(it, env, "*error-output*", &error_stream, &is_bound) &&
        is_bound &&
        value_is_output_stream_object(error_stream) &&
        stream_object_is_open(error_stream)) {
        output_stream_write_text(it, error_stream, "WARNING: ");
        output_stream_write_text(it, error_stream, text);
        output_stream_write_char(it, error_stream, '\n');
        if (!query_io_finish_output(it, env, error_stream, err, errsz)) return 0;
    } else {
        fprintf(stderr, "WARNING: %s\n", text);
    }
    return 1;
}

static int compilation_unit_flush_warnings(Interp *it, Env *env, CompilationUnitFrame *frame, char *err, size_t errsz) {
    int i;
    if (frame == NULL) return 1;
    for (i = 0; i < frame->warnings.size; ++i) {
        if (!warning_message_emit(it, env, frame->warnings.data[i], err, errsz)) {
            strvec_free(&frame->warnings);
            return 0;
        }
    }
    strvec_free(&frame->warnings);
    return 1;
}

static void binding_array_clone(Binding *src, int src_count, Binding **dst, int *dst_count, int *dst_cap) {
    int i;
    for (i = 0; i < src_count; ++i) {
        if (*dst_count >= *dst_cap) {
            int nc = (*dst_cap <= 0) ? 16 : (*dst_cap * 2);
            *dst = (Binding *)xrealloc(*dst, (size_t)nc * sizeof(Binding));
            *dst_cap = nc;
        }
        (*dst)[*dst_count].name = xstrdup_c(src[i].name);
        (*dst)[*dst_count].symbol = src[i].symbol;
        (*dst)[*dst_count].value = src[i].value;
        ++(*dst_count);
    }
}

static Env *env_clone_root_surface(Env *env) {
    Env *root = env_root(env);
    Env *clone = env_new(NULL);
    int i;
    if (root == NULL) return clone;
    clone->active_model = root->active_model;
    binding_array_clone(root->bindings, root->count, &clone->bindings, &clone->count, &clone->cap);
    binding_array_clone(root->vdocs, root->vdoc_count, &clone->vdocs, &clone->vdoc_count, &clone->vdoc_cap);
    binding_array_clone(root->sbindings, root->scount, &clone->sbindings, &clone->scount, &clone->scap);
    binding_array_clone(root->fbindings, root->fcount, &clone->fbindings, &clone->fcount, &clone->fcap);
    binding_array_clone(root->fdocs, root->fdoc_count, &clone->fdocs, &clone->fdoc_count, &clone->fdoc_cap);
    binding_array_clone(root->cmbindings, root->cmcount, &clone->cmbindings, &clone->cmcount, &clone->cmcap);
    binding_array_clone(root->tbindings, root->tcount, &clone->tbindings, &clone->tcount, &clone->tcap);
    binding_array_clone(root->tdocs, root->tdoc_count, &clone->tdocs, &clone->tdoc_count, &clone->tdoc_cap);
    binding_array_clone(root->setfbindings, root->setfcount, &clone->setfbindings, &clone->setfcount, &clone->setfcap);
    binding_array_clone(root->setfdocs, root->setfdoc_count, &clone->setfdocs, &clone->setfdoc_count, &clone->setfdoc_cap);
    binding_array_clone(root->plists, root->pcount, &clone->plists, &clone->pcount, &clone->pcap);
    binding_array_clone(root->special_bindings, root->special_count, &clone->special_bindings, &clone->special_count, &clone->special_cap);
    binding_array_clone(root->constant_bindings, root->constant_count, &clone->constant_bindings, &clone->constant_count, &clone->constant_cap);
    for (i = 0; i < root->specials.size; ++i) strvec_push_copy(&clone->specials, root->specials.data[i]);
    for (i = 0; i < root->constants.size; ++i) strvec_push_copy(&clone->constants, root->constants.data[i]);
    return clone;
}

static void strbuf_init(StrBuf *b) {
    b->data = NULL;
    b->len = 0U;
    b->cap = 0U;
}

static void strbuf_reserve(StrBuf *b, size_t need) {
    if (need <= b->cap) return;
    if (b->cap == 0U) b->cap = 64U;
    while (b->cap < need) b->cap *= 2U;
    b->data = (char *)xrealloc(b->data, b->cap);
}

static void strbuf_append(StrBuf *b, const char *s) {
    size_t n = strlen(s);
    strbuf_reserve(b, b->len + n + 1U);
    memcpy(b->data + b->len, s, n + 1U);
    b->len += n;
}

static void strbuf_append_n(StrBuf *b, const char *s, size_t n) {
    strbuf_reserve(b, b->len + n + 1U);
    memcpy(b->data + b->len, s, n);
    b->len += n;
    b->data[b->len] = '\0';
}

static void strbuf_append_char(StrBuf *b, char c) {
    strbuf_reserve(b, b->len + 2U);
    b->data[b->len++] = c;
    b->data[b->len] = '\0';
}

static void strbuf_appendf(StrBuf *b, const char *fmt, ...) {
    va_list ap;
    va_list aq;
    int need;
    va_start(ap, fmt);
    va_copy(aq, ap);
    need = vsnprintf(NULL, 0, fmt, ap);
    va_end(ap);
    if (need < 0) {
        va_end(aq);
        fprintf(stderr, "LisPy: formatting error\n");
        exit(2);
    }
    strbuf_reserve(b, b->len + (size_t)need + 1U);
    vsnprintf(b->data + b->len, b->cap - b->len, fmt, aq);
    va_end(aq);
    b->len += (size_t)need;
}

static char *strbuf_take(StrBuf *b) {
    char *out;
    if (b->data == NULL) {
        out = (char *)xmalloc(1U);
        out[0] = '\0';
    } else {
        out = b->data;
    }
    b->data = NULL;
    b->len = 0U;
    b->cap = 0U;
    return out;
}

static void strbuf_free(StrBuf *b) {
    free(b->data);
    b->data = NULL;
    b->len = 0U;
    b->cap = 0U;
}

static int str_ieq(const char *a, const char *b) {
    while (*a != '\0' && *b != '\0') {
        if (tolower((unsigned char)*a) != tolower((unsigned char)*b)) return 0;
        ++a;
        ++b;
    }
    return (*a == '\0' && *b == '\0');
}

#define BIGINT_BASE 1000000000U
#define BITWISE_WORD_BITS 30U
#define BITWISE_WORD_BASE 1073741824U
#define BITWISE_WORD_MASK (BITWISE_WORD_BASE - 1U)
#define BITWISE_WORD_SIGN_BIT (1U << (BITWISE_WORD_BITS - 1U))

static BigInt *bigint_new_zero(void) {
    BigInt *v = (BigInt *)xcalloc(1U, sizeof(BigInt));
    v->d.sign = 0;
    return v;
}

static void bigint_free(BigInt *v) {
    if (v == NULL) return;
    free(v->d.digits);
    free(v);
}

static BigInt *bigint_copy(const BigInt *src) {
    BigInt *out = bigint_new_zero();
    out->d.sign = src->d.sign;
    out->d.len = src->d.len;
    out->d.cap = src->d.len;
    if (src->d.len > 0) {
        out->d.digits = (uint32_t *)xmalloc((size_t)src->d.len * sizeof(uint32_t));
        memcpy(out->d.digits, src->d.digits, (size_t)src->d.len * sizeof(uint32_t));
    }
    return out;
}

static void bigint_reserve(BigInt *v, int need) {
    if (need <= v->d.cap) return;
    if (v->d.cap <= 0) v->d.cap = 4;
    while (v->d.cap < need) v->d.cap *= 2;
    v->d.digits = (uint32_t *)xrealloc(v->d.digits, (size_t)v->d.cap * sizeof(uint32_t));
}

static void bigint_normalize(BigInt *v) {
    while (v->d.len > 0 && v->d.digits[v->d.len - 1] == 0U) --v->d.len;
    if (v->d.len == 0) v->d.sign = 0;
}

static BigInt *bigint_from_u64(uint64_t x) {
    BigInt *v = bigint_new_zero();
    if (x == 0U) return v;
    v->d.sign = 1;
    while (x > 0U) {
        bigint_reserve(v, v->d.len + 1);
        v->d.digits[v->d.len++] = (uint32_t)(x % BIGINT_BASE);
        x /= BIGINT_BASE;
    }
    return v;
}

static BigInt *bigint_from_i64(int64_t x) {
    uint64_t mag;
    BigInt *v;
    if (x == 0) return bigint_new_zero();
    mag = (x < 0) ? (uint64_t)(-(x + 1)) + 1U : (uint64_t)x;
    v = bigint_from_u64(mag);
    v->d.sign = (x < 0) ? -1 : 1;
    return v;
}

static BigInt *bigint_mul_small(const BigInt *a, uint32_t m) {
    BigInt *out = bigint_new_zero();
    uint64_t carry = 0U;
    int i;
    if (a->d.sign == 0 || m == 0U) return out;
    bigint_reserve(out, a->d.len + 1);
    out->d.sign = a->d.sign;
    for (i = 0; i < a->d.len; ++i) {
        uint64_t cur = (uint64_t)a->d.digits[i] * (uint64_t)m + carry;
        out->d.digits[out->d.len++] = (uint32_t)(cur % BIGINT_BASE);
        carry = cur / BIGINT_BASE;
    }
    if (carry != 0U) out->d.digits[out->d.len++] = (uint32_t)carry;
    bigint_normalize(out);
    return out;
}

static BigInt *bigint_add_small(const BigInt *a, uint32_t x) {
    BigInt *out = bigint_copy(a);
    uint64_t carry = x;
    int i = 0;
    if (out->d.sign == 0) {
        free(out->d.digits);
        out->d.digits = NULL;
        out->d.len = 0;
        out->d.cap = 0;
        out->d.sign = 1;
    }
    while (carry != 0U) {
        bigint_reserve(out, i + 1);
        if (i >= out->d.len) out->d.digits[out->d.len++] = 0U;
        carry += out->d.digits[i];
        out->d.digits[i] = (uint32_t)(carry % BIGINT_BASE);
        carry /= BIGINT_BASE;
        ++i;
    }
    bigint_normalize(out);
    return out;
}

static BigInt *bigint_abs_from_decimal(const char *s, int *ok) {
    BigInt *cur = bigint_new_zero();
    const char *p = s;
    *ok = 1;
    if (*p == '\0') {
        *ok = 0;
        return cur;
    }
    while (*p != '\0') {
        BigInt *tmp;
        if (!isdigit((unsigned char)*p)) {
            *ok = 0;
            return cur;
        }
        tmp = bigint_mul_small(cur, 10U);
        free(cur->d.digits);
        free(cur);
        cur = tmp;
        tmp = bigint_add_small(cur, (uint32_t)(*p - '0'));
        free(cur->d.digits);
        free(cur);
        cur = tmp;
        ++p;
    }
    bigint_normalize(cur);
    return cur;
}

static BigInt *bigint_from_decimal(const char *s, int *ok) {
    int sign = 1;
    BigInt *out;
    if (*s == '+' || *s == '-') {
        sign = (*s == '-') ? -1 : 1;
        ++s;
    }
    out = bigint_abs_from_decimal(s, ok);
    if (*ok) out->d.sign = (out->d.len == 0) ? 0 : sign;
    return out;
}

static BigInt *bigint_abs_from_radix(const char *s, int radix, int *ok) {
    BigInt *cur = bigint_new_zero();
    const char *p = s;
    *ok = 1;
    if (*p == '\0') {
        *ok = 0;
        return cur;
    }
    while (*p != '\0') {
        BigInt *tmp;
        int weight = digit_char_weight((unsigned char)*p);
        if (weight < 0 || weight >= radix) {
            *ok = 0;
            return cur;
        }
        tmp = bigint_mul_small(cur, (uint32_t)radix);
        free(cur->d.digits);
        free(cur);
        cur = tmp;
        tmp = bigint_add_small(cur, (uint32_t)weight);
        free(cur->d.digits);
        free(cur);
        cur = tmp;
        ++p;
    }
    bigint_normalize(cur);
    return cur;
}

static BigInt *bigint_from_radix(const char *s, int radix, int *ok) {
    int sign = 1;
    BigInt *out;
    if (*s == '+' || *s == '-') {
        sign = (*s == '-') ? -1 : 1;
        ++s;
    }
    out = bigint_abs_from_radix(s, radix, ok);
    if (*ok) out->d.sign = (out->d.len == 0) ? 0 : sign;
    return out;
}

static int bigint_cmp_abs(const BigInt *a, const BigInt *b) {
    int i;
    if (a->d.len != b->d.len) return (a->d.len < b->d.len) ? -1 : 1;
    for (i = a->d.len - 1; i >= 0; --i) {
        if (a->d.digits[i] != b->d.digits[i]) return (a->d.digits[i] < b->d.digits[i]) ? -1 : 1;
    }
    return 0;
}

static int bigint_cmp(const BigInt *a, const BigInt *b) {
    if (a->d.sign != b->d.sign) return (a->d.sign < b->d.sign) ? -1 : 1;
    if (a->d.sign == 0) return 0;
    if (a->d.sign > 0) return bigint_cmp_abs(a, b);
    return -bigint_cmp_abs(a, b);
}

static BigInt *bigint_add_abs(const BigInt *a, const BigInt *b) {
    BigInt *out = bigint_new_zero();
    int maxlen = (a->d.len > b->d.len) ? a->d.len : b->d.len;
    uint64_t carry = 0U;
    int i;
    bigint_reserve(out, maxlen + 1);
    for (i = 0; i < maxlen; ++i) {
        uint64_t cur = carry;
        if (i < a->d.len) cur += a->d.digits[i];
        if (i < b->d.len) cur += b->d.digits[i];
        out->d.digits[out->d.len++] = (uint32_t)(cur % BIGINT_BASE);
        carry = cur / BIGINT_BASE;
    }
    if (carry != 0U) out->d.digits[out->d.len++] = (uint32_t)carry;
    out->d.sign = (out->d.len == 0) ? 0 : 1;
    bigint_normalize(out);
    return out;
}

static BigInt *bigint_sub_abs(const BigInt *a, const BigInt *b) {
    BigInt *out = bigint_new_zero();
    int64_t borrow = 0;
    int i;
    bigint_reserve(out, a->d.len);
    for (i = 0; i < a->d.len; ++i) {
        int64_t cur = (int64_t)a->d.digits[i] - borrow - ((i < b->d.len) ? (int64_t)b->d.digits[i] : 0);
        if (cur < 0) {
            cur += (int64_t)BIGINT_BASE;
            borrow = 1;
        } else {
            borrow = 0;
        }
        out->d.digits[out->d.len++] = (uint32_t)cur;
    }
    out->d.sign = 1;
    bigint_normalize(out);
    return out;
}

static BigInt *bigint_add(const BigInt *a, const BigInt *b) {
    BigInt *out;
    if (a->d.sign == 0) return bigint_copy(b);
    if (b->d.sign == 0) return bigint_copy(a);
    if (a->d.sign == b->d.sign) {
        out = bigint_add_abs(a, b);
        out->d.sign = a->d.sign;
        return out;
    }
    if (bigint_cmp_abs(a, b) >= 0) {
        out = bigint_sub_abs(a, b);
        out->d.sign = a->d.sign;
    } else {
        out = bigint_sub_abs(b, a);
        out->d.sign = b->d.sign;
    }
    bigint_normalize(out);
    return out;
}

static BigInt *bigint_neg(const BigInt *a) {
    BigInt *out = bigint_copy(a);
    out->d.sign = -out->d.sign;
    return out;
}

static BigInt *bigint_sub(const BigInt *a, const BigInt *b) {
    BigInt *nb = bigint_neg(b);
    BigInt *out = bigint_add(a, nb);
    free(nb->d.digits);
    free(nb);
    return out;
}

static BigInt *bigint_mul(const BigInt *a, const BigInt *b) {
    BigInt *out = bigint_new_zero();
    int i, j;
    if (a->d.sign == 0 || b->d.sign == 0) return out;
    bigint_reserve(out, a->d.len + b->d.len);
    memset(out->d.digits, 0, (size_t)(a->d.len + b->d.len) * sizeof(uint32_t));
    out->d.len = a->d.len + b->d.len;
    for (i = 0; i < a->d.len; ++i) {
        uint64_t carry = 0U;
        for (j = 0; j < b->d.len || carry != 0U; ++j) {
            uint64_t cur = out->d.digits[i + j] + carry;
            if (j < b->d.len) cur += (uint64_t)a->d.digits[i] * (uint64_t)b->d.digits[j];
            out->d.digits[i + j] = (uint32_t)(cur % BIGINT_BASE);
            carry = cur / BIGINT_BASE;
        }
    }
    out->d.sign = a->d.sign * b->d.sign;
    bigint_normalize(out);
    return out;
}

static int bigint_is_zero(const BigInt *a) {
    return a->d.sign == 0;
}

static uint32_t bigint_div_small_inplace(BigInt *a, uint32_t divisor) {
    uint64_t rem = 0U;
    int i;
    if (a == NULL || divisor == 0U || a->d.sign == 0) return 0U;
    for (i = a->d.len - 1; i >= 0; --i) {
        uint64_t cur = rem * (uint64_t)BIGINT_BASE + (uint64_t)a->d.digits[i];
        a->d.digits[i] = (uint32_t)(cur / divisor);
        rem = cur % divisor;
    }
    a->d.sign = 1;
    bigint_normalize(a);
    return (uint32_t)rem;
}

static char *bigint_to_string(const BigInt *v) {
    StrBuf buf;
    int i;
    strbuf_init(&buf);
    if (v->d.sign == 0) {
        strbuf_append(&buf, "0");
        return strbuf_take(&buf);
    }
    if (v->d.sign < 0) strbuf_append_char(&buf, '-');
    strbuf_appendf(&buf, "%u", v->d.digits[v->d.len - 1]);
    for (i = v->d.len - 2; i >= 0; --i) strbuf_appendf(&buf, "%09u", v->d.digits[i]);
    return strbuf_take(&buf);
}

static char *bigint_to_string_base(const BigInt *v, int radix) {
    static const char digits[] = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ";
    StrBuf buf;
    StrBuf rev;
    BigInt *tmp = NULL;
    if (radix < 2 || radix > 36 || radix == 10) return bigint_to_string(v);
    strbuf_init(&buf);
    if (v->d.sign == 0) {
        strbuf_append(&buf, "0");
        return strbuf_take(&buf);
    }
    strbuf_init(&rev);
    tmp = bigint_copy(v);
    if (tmp->d.sign < 0) tmp->d.sign = 1;
    while (!bigint_is_zero(tmp)) {
        uint32_t rem = bigint_div_small_inplace(tmp, (uint32_t)radix);
        strbuf_append_char(&rev, digits[rem]);
    }
    if (v->d.sign < 0) strbuf_append_char(&buf, '-');
    for (int i = (int)rev.len - 1; i >= 0; --i) strbuf_append_char(&buf, rev.data[i]);
    strbuf_free(&rev);
    free(tmp->d.digits);
    free(tmp);
    return strbuf_take(&buf);
}

static int bigint_to_double_checked(const BigInt *v, double *out) {
    char *s = bigint_to_string(v);
    char *end = NULL;
    double d;
    errno = 0;
    d = strtod(s, &end);
    if (errno == ERANGE || end == s || *end != '\0' || !isfinite(d)) {
        free(s);
        return 0;
    }
    free(s);
    *out = d;
    return 1;
}

static int bigint_to_u64_checked(const BigInt *v, uint64_t *out) {
    uint64_t acc = 0U;
    int i;
    if (v->d.sign < 0) return 0;
    if (v->d.sign == 0) {
        *out = 0U;
        return 1;
    }
    for (i = v->d.len - 1; i >= 0; --i) {
        if (acc > (UINT64_MAX - (uint64_t)v->d.digits[i]) / (uint64_t)BIGINT_BASE) return 0;
        acc = acc * (uint64_t)BIGINT_BASE + (uint64_t)v->d.digits[i];
    }
    *out = acc;
    return 1;
}

static int bigint_to_i64_checked(const BigInt *v, int64_t *out) {
    uint64_t mag = 0U;
    int i;
    if (v->d.sign == 0) {
        *out = 0;
        return 1;
    }
    for (i = v->d.len - 1; i >= 0; --i) {
        if (mag > (UINT64_MAX - (uint64_t)v->d.digits[i]) / (uint64_t)BIGINT_BASE) return 0;
        mag = mag * (uint64_t)BIGINT_BASE + (uint64_t)v->d.digits[i];
    }
    if (v->d.sign > 0) {
        if (mag > (uint64_t)INT64_MAX) return 0;
        *out = (int64_t)mag;
        return 1;
    }
    if (mag > (uint64_t)INT64_MAX + 1U) return 0;
    if (mag == (uint64_t)INT64_MAX + 1U) {
        *out = INT64_MIN;
        return 1;
    }
    *out = -(int64_t)mag;
    return 1;
}

static int bigint_is_one(const BigInt *v) {
    return v != NULL && v->d.sign > 0 && v->d.len == 1 && v->d.digits[0] == 1U;
}

static BigInt *bigint_abs_clone(const BigInt *v) {
    BigInt *out = bigint_copy(v);
    if (out != NULL && out->d.sign < 0) out->d.sign = 1;
    return out;
}

static BigInt *bigint_divmod_abs(const BigInt *num, const BigInt *den, BigInt **rem_out) {
    BigInt *n = NULL;
    BigInt *d = NULL;
    BigInt *q = NULL;
    BigInt *r = NULL;
    int i;
    if (rem_out != NULL) *rem_out = NULL;
    if (num == NULL || den == NULL || den->d.sign == 0) return NULL;
    n = bigint_abs_clone(num);
    d = bigint_abs_clone(den);
    if (n == NULL || d == NULL) {
        bigint_free(n);
        bigint_free(d);
        return NULL;
    }
    if (n->d.sign == 0) {
        q = bigint_new_zero();
        r = bigint_new_zero();
        bigint_free(n);
        bigint_free(d);
        if (rem_out != NULL) *rem_out = r;
        else bigint_free(r);
        return q;
    }
    if (bigint_cmp_abs(n, d) < 0) {
        q = bigint_new_zero();
        r = n;
        bigint_free(d);
        if (rem_out != NULL) *rem_out = r;
        else bigint_free(r);
        return q;
    }
    if (d->d.len == 1 && d->d.digits[0] == 1U) {
        q = bigint_copy(n);
        r = bigint_new_zero();
        bigint_free(n);
        bigint_free(d);
        if (rem_out != NULL) *rem_out = r;
        else bigint_free(r);
        return q;
    }
    if (d->d.len == 1) {
        uint32_t rem = 0U;
        q = bigint_copy(n);
        rem = bigint_div_small_inplace(q, d->d.digits[0]);
        r = bigint_from_u64((uint64_t)rem);
        bigint_free(n);
        bigint_free(d);
        if (rem_out != NULL) *rem_out = r;
        else bigint_free(r);
        return q;
    }
    q = bigint_new_zero();
    r = bigint_new_zero();
    for (i = n->d.len - 1; i >= 0; --i) {
        BigInt *tmp = bigint_mul_small(r, BIGINT_BASE);
        BigInt *next_r = bigint_add_small(tmp, n->d.digits[i]);
        uint32_t lo = 0U;
        uint32_t hi = BIGINT_BASE - 1U;
        uint32_t best = 0U;
        bigint_free(tmp);
        bigint_free(r);
        r = next_r;
        while (lo <= hi) {
            uint32_t mid = lo + ((hi - lo) / 2U);
            BigInt *prod = bigint_mul_small(d, mid);
            int cmp = bigint_cmp_abs(prod, r);
            bigint_free(prod);
            if (cmp <= 0) {
                best = mid;
                lo = mid + 1U;
            } else if (mid == 0U) {
                break;
            } else {
                hi = mid - 1U;
            }
        }
        if (best != 0U) {
            BigInt *prod = bigint_mul_small(d, best);
            BigInt *next_rem = bigint_sub_abs(r, prod);
            bigint_free(prod);
            bigint_free(r);
            r = next_rem;
        }
        {
            BigInt *tmp_q = bigint_mul_small(q, BIGINT_BASE);
            BigInt *next_q = bigint_add_small(tmp_q, best);
            bigint_free(tmp_q);
            bigint_free(q);
            q = next_q;
        }
    }
    bigint_normalize(q);
    bigint_normalize(r);
    bigint_free(n);
    bigint_free(d);
    if (rem_out != NULL) *rem_out = r;
    else bigint_free(r);
    return q;
}

static BigInt *bigint_div_exact_abs(const BigInt *num, const BigInt *den) {
    BigInt *rem = NULL;
    BigInt *quot = bigint_divmod_abs(num, den, &rem);
    if (quot == NULL) {
        bigint_free(rem);
        return NULL;
    }
    if (rem == NULL || !bigint_is_zero(rem)) {
        bigint_free(rem);
        bigint_free(quot);
        return NULL;
    }
    bigint_free(rem);
    return quot;
}

static BigInt *bigint_gcd_abs(const BigInt *a, const BigInt *b) {
    BigInt *x = bigint_abs_clone(a);
    BigInt *y = bigint_abs_clone(b);
    if (x == NULL || y == NULL) {
        bigint_free(x);
        bigint_free(y);
        return NULL;
    }
    while (!bigint_is_zero(y)) {
        BigInt *rem = NULL;
        BigInt *q = bigint_divmod_abs(x, y, &rem);
        bigint_free(q);
        bigint_free(x);
        x = y;
        y = rem;
        if (x == NULL || y == NULL) {
            bigint_free(x);
            bigint_free(y);
            return NULL;
        }
    }
    bigint_free(y);
    return x;
}

static BigInt *bigint_sqrt_floor_abs(const BigInt *n, int *is_square) {
    BigInt *low = NULL;
    BigInt *high = NULL;
    BigInt *one = NULL;
    if (is_square != NULL) *is_square = 0;
    if (n == NULL || n->d.sign < 0) return NULL;
    if (n->d.sign == 0) {
        if (is_square != NULL) *is_square = 1;
        return bigint_new_zero();
    }
    low = bigint_new_zero();
    high = bigint_abs_clone(n);
    one = bigint_from_i64(1);
    if (low == NULL || high == NULL || one == NULL) {
        bigint_free(low);
        bigint_free(high);
        bigint_free(one);
        return NULL;
    }
    while (bigint_cmp_abs(low, high) < 0) {
        BigInt *sum = bigint_add(low, high);
        BigInt *sum_plus_one = bigint_add_small(sum, 1U);
        BigInt *mid = bigint_copy(sum_plus_one);
        BigInt *mid_sq = NULL;
        int cmp = 0;
        bigint_free(sum);
        bigint_free(sum_plus_one);
        if (mid == NULL) {
            bigint_free(low);
            bigint_free(high);
            bigint_free(one);
            return NULL;
        }
        bigint_div_small_inplace(mid, 2U);
        mid_sq = bigint_mul(mid, mid);
        if (mid_sq == NULL) {
            bigint_free(mid);
            bigint_free(low);
            bigint_free(high);
            bigint_free(one);
            return NULL;
        }
        cmp = bigint_cmp_abs(mid_sq, n);
        bigint_free(mid_sq);
        if (cmp <= 0) {
            bigint_free(low);
            low = mid;
        } else {
            BigInt *mid_minus_one = bigint_sub(mid, one);
            bigint_free(mid);
            if (mid_minus_one == NULL) {
                bigint_free(low);
                bigint_free(high);
                bigint_free(one);
                return NULL;
            }
            bigint_free(high);
            high = mid_minus_one;
        }
    }
    if (is_square != NULL) {
        BigInt *check = bigint_mul(low, low);
        *is_square = (check != NULL && bigint_cmp_abs(check, n) == 0);
        bigint_free(check);
    }
    bigint_free(high);
    bigint_free(one);
    return low;
}

static Value *value_new(ValueType type);
static Value *make_int_value(BigInt *big);
static Value *make_float_value(double x);
static Value *make_complex_value(Value *realpart, Value *imagpart);
static Value *num_to_value_checked(Num n, char *err, size_t errsz);
static int value_to_num(Interp *it, Value *v, Num *out, char *err, size_t errsz);
static int num_to_double_checked(Num n, double *out);

static Value *make_ratio_value(BigInt *numerator, BigInt *denominator) {
    BigInt *g = NULL;
    BigInt *num_q = NULL;
    BigInt *den_q = NULL;
    int num_sign = 1;
    if (numerator == NULL || denominator == NULL) return NULL;
    if (bigint_is_zero(denominator)) {
        bigint_free(numerator);
        bigint_free(denominator);
        return NULL;
    }
    if (bigint_is_zero(numerator)) {
        bigint_free(numerator);
        bigint_free(denominator);
        return make_int_value(bigint_new_zero());
    }
    if (denominator->d.sign < 0) {
        denominator->d.sign = -denominator->d.sign;
        numerator->d.sign = -numerator->d.sign;
    }
    num_sign = numerator->d.sign;
    if (bigint_is_one(denominator)) {
        bigint_free(denominator);
        return make_int_value(numerator);
    }
    g = bigint_gcd_abs(numerator, denominator);
    if (g == NULL) {
        bigint_free(numerator);
        bigint_free(denominator);
        return NULL;
    }
    num_q = bigint_div_exact_abs(numerator, g);
    den_q = bigint_div_exact_abs(denominator, g);
    if (num_q != NULL) num_q->d.sign = num_sign;
    bigint_free(numerator);
    bigint_free(denominator);
    bigint_free(g);
    if (num_q == NULL || den_q == NULL) {
        bigint_free(num_q);
        bigint_free(den_q);
        return NULL;
    }
    if (bigint_is_one(den_q)) {
        bigint_free(den_q);
        return make_int_value(num_q);
    }
    {
        Value *out = value_new(VALUE_RATIO);
        out->as.ratio.numerator = num_q;
        out->as.ratio.denominator = den_q;
        return out;
    }
}

static Value *make_complex_value(Value *realpart, Value *imagpart) {
    Value *out = NULL;
    if (realpart == NULL || imagpart == NULL) return NULL;
    if ((realpart->type == VALUE_FLOAT || imagpart->type == VALUE_FLOAT)) {
        Num re;
        Num im;
        double dre = 0.0;
        double dim = 0.0;
        char tmp_err[32];
        if (!value_to_num(NULL, realpart, &re, tmp_err, sizeof(tmp_err)) ||
            !value_to_num(NULL, imagpart, &im, tmp_err, sizeof(tmp_err)) ||
            !num_to_double_checked(re, &dre) ||
            !num_to_double_checked(im, &dim)) {
            return NULL;
        }
        realpart = make_float_value(dre);
        imagpart = make_float_value(dim);
    }
    if (value_is_real_numeric_value(realpart) && value_numeric_zero_p(imagpart)) {
        return realpart;
    }
    out = value_new(VALUE_COMPLEX);
    out->as.complex.realpart = realpart;
    out->as.complex.imagpart = imagpart;
    return out;
}

static uint32_t bitwise_popcount_word(uint32_t word) {
    uint32_t count = 0U;
    while (word != 0U) {
        word &= (word - 1U);
        ++count;
    }
    return count;
}

static int bitwise_high_word_bit_length(uint32_t word) {
    int bits = 0;
    while (word != 0U) {
        ++bits;
        word >>= 1U;
    }
    return bits;
}

static void bitwise_words_normalize(uint32_t *words, int *count) {
    if (count == NULL) return;
    while (*count > 1 && words[*count - 1] == 0U) --(*count);
}

static int bigint_abs_to_bitwise_words(const BigInt *value, uint32_t **out_words, int *out_count) {
    BigInt *tmp = NULL;
    uint32_t *words = NULL;
    int count = 0;
    int cap = 0;
    if (out_words == NULL || out_count == NULL) return 0;
    *out_words = NULL;
    *out_count = 0;
    tmp = bigint_copy(value);
    if (tmp == NULL) return 0;
    if (tmp->d.sign < 0) tmp->d.sign = 1;
    while (tmp->d.sign != 0) {
        uint32_t rem = bigint_div_small_inplace(tmp, BITWISE_WORD_BASE);
        if (count >= cap) {
            cap = (cap <= 0) ? 4 : (cap * 2);
            words = (uint32_t *)xrealloc(words, (size_t)cap * sizeof(uint32_t));
        }
        words[count++] = rem & BITWISE_WORD_MASK;
    }
    if (count == 0) {
        words = (uint32_t *)xmalloc(sizeof(uint32_t));
        words[0] = 0U;
        count = 1;
    }
    bigint_free(tmp);
    *out_words = words;
    *out_count = count;
    return 1;
}

static BigInt *bigint_from_bitwise_words_positive(const uint32_t *words, int count) {
    BigInt *acc = bigint_new_zero();
    int i = 0;
    for (i = count - 1; i >= 0; --i) {
        BigInt *tmp = bigint_mul_small(acc, BITWISE_WORD_BASE);
        BigInt *next = bigint_add_small(tmp, words[i] & BITWISE_WORD_MASK);
        bigint_free(tmp);
        bigint_free(acc);
        acc = next;
    }
    return acc;
}

static void bitwise_words_twos_complement_inplace(uint32_t *words, int count) {
    uint64_t carry = 1U;
    int i = 0;
    for (i = 0; i < count; ++i) words[i] = (~words[i]) & BITWISE_WORD_MASK;
    for (i = 0; i < count; ++i) {
        uint64_t cur = (uint64_t)words[i] + carry;
        words[i] = (uint32_t)(cur & BITWISE_WORD_MASK);
        carry = (cur >> BITWISE_WORD_BITS);
        if (carry == 0U) break;
    }
}

static int bigint_to_twos_complement_words(const BigInt *value,
                                           int word_count,
                                           uint32_t **out_words) {
    uint32_t *mag_words = NULL;
    uint32_t *words = NULL;
    int mag_count = 0;
    int i = 0;
    if (out_words == NULL || word_count <= 0) return 0;
    *out_words = NULL;
    if (!bigint_abs_to_bitwise_words(value, &mag_words, &mag_count)) return 0;
    words = (uint32_t *)xcalloc((size_t)word_count, sizeof(uint32_t));
    for (i = 0; i < mag_count && i < word_count; ++i) words[i] = mag_words[i] & BITWISE_WORD_MASK;
    if (value->d.sign < 0) bitwise_words_twos_complement_inplace(words, word_count);
    free(mag_words);
    *out_words = words;
    return 1;
}

static BigInt *bigint_from_twos_complement_words(const uint32_t *words, int count) {
    uint32_t *mag_words = NULL;
    BigInt *out = NULL;
    int negative = 0;
    int mag_count = count;
    int i = 0;
    if (count <= 0) return bigint_new_zero();
    negative = (words[count - 1] & BITWISE_WORD_SIGN_BIT) != 0U;
    if (!negative) return bigint_from_bitwise_words_positive(words, count);
    mag_words = (uint32_t *)xmalloc((size_t)count * sizeof(uint32_t));
    for (i = 0; i < count; ++i) mag_words[i] = words[i] & BITWISE_WORD_MASK;
    bitwise_words_twos_complement_inplace(mag_words, count);
    bitwise_words_normalize(mag_words, &mag_count);
    out = bigint_from_bitwise_words_positive(mag_words, mag_count);
    if (out->d.sign != 0) out->d.sign = -1;
    free(mag_words);
    return out;
}

static BigInt *bigint_abs_minus_one_positive(const BigInt *value) {
    BigInt *abs_value = bigint_copy(value);
    BigInt *one = bigint_from_i64(1);
    BigInt *out = NULL;
    abs_value->d.sign = (abs_value->d.sign == 0) ? 0 : 1;
    out = bigint_sub_abs(abs_value, one);
    bigint_free(abs_value);
    bigint_free(one);
    return out;
}

static uint64_t bigint_integer_length_u64(const BigInt *value) {
    uint32_t *words = NULL;
    int count = 0;
    uint64_t bits = 0U;
    if (value->d.sign == 0) return 0U;
    if (value->d.sign > 0) {
        if (!bigint_abs_to_bitwise_words(value, &words, &count)) return 0U;
    } else {
        BigInt *tmp = bigint_abs_minus_one_positive(value);
        int ok = bigint_abs_to_bitwise_words(tmp, &words, &count);
        bigint_free(tmp);
        if (!ok) return 0U;
    }
    bitwise_words_normalize(words, &count);
    bits = (uint64_t)(count - 1) * (uint64_t)BITWISE_WORD_BITS +
           (uint64_t)bitwise_high_word_bit_length(words[count - 1]);
    free(words);
    return bits;
}

static int bigint_positive_test_bit(const BigInt *value, uint64_t bit_index, int *out_bit) {
    uint32_t *words = NULL;
    int count = 0;
    uint64_t word_index = bit_index / (uint64_t)BITWISE_WORD_BITS;
    uint64_t bit_offset = bit_index % (uint64_t)BITWISE_WORD_BITS;
    if (out_bit == NULL) return 0;
    *out_bit = 0;
    if (!bigint_abs_to_bitwise_words(value, &words, &count)) return 0;
    if (word_index < (uint64_t)count) {
        *out_bit = ((words[word_index] >> bit_offset) & 1U) ? 1 : 0;
    }
    free(words);
    return 1;
}

static int bigint_test_bit_signed(const BigInt *value, uint64_t bit_index, int *out_bit) {
    if (value->d.sign >= 0) return bigint_positive_test_bit(value, bit_index, out_bit);
    {
        BigInt *tmp = bigint_abs_minus_one_positive(value);
        int bit = 0;
        int ok = bigint_positive_test_bit(tmp, bit_index, &bit);
        bigint_free(tmp);
        if (!ok) return 0;
        *out_bit = bit ? 0 : 1;
        return 1;
    }
}

static BigInt *bigint_shift_left(const BigInt *value, uint64_t shift) {
    uint32_t *words = NULL;
    uint32_t *shifted = NULL;
    BigInt *out = NULL;
    int count = 0;
    int shifted_count = 0;
    int word_shift = (int)(shift / (uint64_t)BITWISE_WORD_BITS);
    int bit_shift = (int)(shift % (uint64_t)BITWISE_WORD_BITS);
    int i = 0;
    uint32_t carry = 0U;
    if (value->d.sign == 0) return bigint_new_zero();
    if (!bigint_abs_to_bitwise_words(value, &words, &count)) return NULL;
    shifted_count = count + word_shift + ((bit_shift != 0) ? 1 : 0);
    shifted = (uint32_t *)xcalloc((size_t)shifted_count, sizeof(uint32_t));
    for (i = 0; i < word_shift; ++i) shifted[i] = 0U;
    if (bit_shift == 0) {
        for (i = 0; i < count; ++i) shifted[i + word_shift] = words[i];
    } else {
        for (i = 0; i < count; ++i) {
            uint64_t cur = ((uint64_t)words[i] << bit_shift) | carry;
            shifted[i + word_shift] = (uint32_t)(cur & BITWISE_WORD_MASK);
            carry = (uint32_t)(cur >> BITWISE_WORD_BITS);
        }
        shifted[count + word_shift] = carry & BITWISE_WORD_MASK;
    }
    bitwise_words_normalize(shifted, &shifted_count);
    out = bigint_from_bitwise_words_positive(shifted, shifted_count);
    if (out->d.sign != 0) out->d.sign = value->d.sign;
    free(words);
    free(shifted);
    return out;
}

static BigInt *bigint_shift_right_positive(const BigInt *value, uint64_t shift, int *had_remainder) {
    uint32_t *words = NULL;
    uint32_t *shifted = NULL;
    BigInt *out = NULL;
    int count = 0;
    int shifted_count = 0;
    int word_shift = (int)(shift / (uint64_t)BITWISE_WORD_BITS);
    int bit_shift = (int)(shift % (uint64_t)BITWISE_WORD_BITS);
    int i = 0;
    uint32_t carry = 0U;
    uint32_t low_mask = (bit_shift == 0) ? 0U : ((1U << bit_shift) - 1U);
    if (had_remainder != NULL) *had_remainder = 0;
    if (value->d.sign == 0) return bigint_new_zero();
    if (!bigint_abs_to_bitwise_words(value, &words, &count)) return NULL;
    if (word_shift >= count) {
        if (had_remainder != NULL) {
            for (i = 0; i < count; ++i) {
                if (words[i] != 0U) {
                    *had_remainder = 1;
                    break;
                }
            }
        }
        free(words);
        return bigint_new_zero();
    }
    shifted_count = count - word_shift;
    shifted = (uint32_t *)xcalloc((size_t)shifted_count, sizeof(uint32_t));
    if (had_remainder != NULL) {
        for (i = 0; i < word_shift; ++i) {
            if (words[i] != 0U) {
                *had_remainder = 1;
                break;
            }
        }
    }
    if (bit_shift == 0) {
        for (i = 0; i < shifted_count; ++i) shifted[i] = words[i + word_shift];
    } else {
        carry = 0U;
        for (i = count - 1; i >= word_shift; --i) {
            uint32_t cur = words[i];
            uint32_t next_carry = cur & low_mask;
            shifted[i - word_shift] = ((cur >> bit_shift) |
                                      ((carry << (BITWISE_WORD_BITS - bit_shift)) & BITWISE_WORD_MASK)) &
                                      BITWISE_WORD_MASK;
            carry = next_carry;
        }
        if (had_remainder != NULL && carry != 0U) *had_remainder = 1;
    }
    bitwise_words_normalize(shifted, &shifted_count);
    out = bigint_from_bitwise_words_positive(shifted, shifted_count);
    free(words);
    free(shifted);
    return out;
}

typedef enum {
    LOGIC_OP_CLR = 0,
    LOGIC_OP_SET = 1,
    LOGIC_OP_1 = 2,
    LOGIC_OP_2 = 3,
    LOGIC_OP_C1 = 4,
    LOGIC_OP_C2 = 5,
    LOGIC_OP_AND = 6,
    LOGIC_OP_IOR = 7,
    LOGIC_OP_XOR = 8,
    LOGIC_OP_EQV = 9,
    LOGIC_OP_NAND = 10,
    LOGIC_OP_NOR = 11,
    LOGIC_OP_ANDC1 = 12,
    LOGIC_OP_ANDC2 = 13,
    LOGIC_OP_ORC1 = 14,
    LOGIC_OP_ORC2 = 15
} LogicalIntegerOpKind;

static uint32_t apply_logical_word_op(LogicalIntegerOpKind op, uint32_t left, uint32_t right) {
    switch (op) {
        case LOGIC_OP_CLR:   return 0U;
        case LOGIC_OP_SET:   return BITWISE_WORD_MASK;
        case LOGIC_OP_1:     return left;
        case LOGIC_OP_2:     return right;
        case LOGIC_OP_C1:    return (~left) & BITWISE_WORD_MASK;
        case LOGIC_OP_C2:    return (~right) & BITWISE_WORD_MASK;
        case LOGIC_OP_AND:   return left & right;
        case LOGIC_OP_IOR:   return left | right;
        case LOGIC_OP_XOR:   return left ^ right;
        case LOGIC_OP_EQV:   return (~(left ^ right)) & BITWISE_WORD_MASK;
        case LOGIC_OP_NAND:  return (~(left & right)) & BITWISE_WORD_MASK;
        case LOGIC_OP_NOR:   return (~(left | right)) & BITWISE_WORD_MASK;
        case LOGIC_OP_ANDC1: return ((~left) & right) & BITWISE_WORD_MASK;
        case LOGIC_OP_ANDC2: return (left & (~right)) & BITWISE_WORD_MASK;
        case LOGIC_OP_ORC1:  return ((~left) | right) & BITWISE_WORD_MASK;
        case LOGIC_OP_ORC2:  return (left | (~right)) & BITWISE_WORD_MASK;
        default:             return 0U;
    }
}

static BigInt *bigint_logical_binary(LogicalIntegerOpKind op, const BigInt *left, const BigInt *right) {
    uint64_t bit_length = bigint_integer_length_u64(left);
    uint64_t right_length = bigint_integer_length_u64(right);
    uint32_t *left_words = NULL;
    uint32_t *right_words = NULL;
    uint32_t *result_words = NULL;
    BigInt *out = NULL;
    int word_count = 0;
    int i = 0;
    if (right_length > bit_length) bit_length = right_length;
    word_count = (int)((bit_length + 1U + (uint64_t)BITWISE_WORD_BITS - 1U) / (uint64_t)BITWISE_WORD_BITS);
    if (word_count <= 0) word_count = 1;
    if (!bigint_to_twos_complement_words(left, word_count, &left_words) ||
        !bigint_to_twos_complement_words(right, word_count, &right_words)) {
        free(left_words);
        free(right_words);
        return NULL;
    }
    result_words = (uint32_t *)xmalloc((size_t)word_count * sizeof(uint32_t));
    for (i = 0; i < word_count; ++i) {
        result_words[i] = apply_logical_word_op(op, left_words[i], right_words[i]) & BITWISE_WORD_MASK;
    }
    out = bigint_from_twos_complement_words(result_words, word_count);
    free(left_words);
    free(right_words);
    free(result_words);
    return out;
}

static BigInt *bigint_logical_not(const BigInt *value) {
    uint64_t bit_length = bigint_integer_length_u64(value);
    uint32_t *words = NULL;
    BigInt *out = NULL;
    int word_count = (int)((bit_length + 1U + (uint64_t)BITWISE_WORD_BITS - 1U) / (uint64_t)BITWISE_WORD_BITS);
    int i = 0;
    if (word_count <= 0) word_count = 1;
    if (!bigint_to_twos_complement_words(value, word_count, &words)) return NULL;
    for (i = 0; i < word_count; ++i) words[i] = (~words[i]) & BITWISE_WORD_MASK;
    out = bigint_from_twos_complement_words(words, word_count);
    free(words);
    return out;
}

static int bigint_fits_exact_ieee53(const BigInt *v) {
    char *s;
    const char *abs;
    size_t len;
    int ok;
    if (v->d.sign == 0) return 1;
    s = bigint_to_string(v);
    abs = (s[0] == '-') ? s + 1 : s;
    len = strlen(abs);
    ok = (len < 16U) || (len == 16U && strcmp(abs, "9007199254740991") <= 0);
    free(s);
    return ok;
}

static Value *value_new(ValueType type) {
    Value *v = (Value *)xcalloc(1U, sizeof(Value));
    v->type = type;
    return v;
}

static Value *make_symbol_value(const char *s);

static int value_vector_total_size(Value *v);

static void value_set_array_metadata(Value *v, int total_size, int has_fill_pointer, int fill_pointer, int adjustable) {
    v->array_total_size = total_size;
    if (v->type == VALUE_VECTOR || v->type == VALUE_STRING) {
        if (v->array_rank <= 0) v->array_rank = 1;
    } else {
        v->array_rank = 0;
    }
    v->has_fill_pointer = has_fill_pointer;
    v->fill_pointer = fill_pointer;
    v->adjustable = adjustable;
}

static void value_reset_array_dimensions(Value *v) {
    if (v->array_dims != NULL) free(v->array_dims);
    v->array_dims = NULL;
    if (v->type == VALUE_VECTOR || v->type == VALUE_STRING) v->array_rank = 1;
    else v->array_rank = 0;
}

static void value_set_array_dimensions(Value *v, const int *dims, int rank) {
    int i;
    value_reset_array_dimensions(v);
    if (v->type != VALUE_VECTOR) return;
    if (rank <= 1) {
        v->array_rank = rank;
        return;
    }
    v->array_rank = rank;
    v->array_dims = (int *)xmalloc((size_t)rank * sizeof(int));
    for (i = 0; i < rank; ++i) v->array_dims[i] = dims[i];
}

static void value_set_vector_element_type(Value *v, Value *element_type_spec) {
    if (v == NULL || v->type != VALUE_VECTOR) return;
    if (element_type_spec == NULL || element_type_spec->type == VALUE_NIL) {
        element_type_spec = make_symbol_value("t");
    }
    v->array_element_type_spec = element_type_spec;
}

static Value *value_vector_element_type_spec(Value *v) {
    if (v == NULL || v->type != VALUE_VECTOR) return make_symbol_value("t");
    if (v->array_element_type_spec != NULL) return v->array_element_type_spec;
    if (v->displaced_to != NULL && v->displaced_to->type == VALUE_VECTOR) {
        return value_vector_element_type_spec(v->displaced_to);
    }
    return make_symbol_value("t");
}

static int value_is_bit_value(Value *v) {
    int64_t i64 = 0;
    return v != NULL &&
           v->type == VALUE_INT &&
           bigint_to_i64_checked(v->as.bigint, &i64) &&
           (i64 == 0 || i64 == 1);
}

static int value_is_byte_value(Value *v) {
    int64_t i64 = 0;
    return v != NULL &&
           v->type == VALUE_INT &&
           bigint_to_i64_checked(v->as.bigint, &i64) &&
           i64 >= 0 &&
           i64 <= 255;
}

static int value_vector_has_bit_element_type(Value *v) {
    return v != NULL &&
           v->type == VALUE_VECTOR &&
           builtin_type_symbol_named(value_vector_element_type_spec(v), "bit");
}

static int type_spec_is_unsigned_byte_8(Value *spec) {
    ValueArray items;
    int64_t size = 0;
    if (spec == NULL) return 0;
    if (!type_spec_to_array(spec, &items) || items.count != 2 || !builtin_type_symbol_named(items.items[0], "unsigned-byte")) {
        return 0;
    }
    if (items.items[1]->type != VALUE_INT || !bigint_to_i64_checked(items.items[1]->as.bigint, &size) || size != 8) {
        return 0;
    }
    return 1;
}

static int type_spec_is_unsigned_byte_1(Value *spec) {
    ValueArray items;
    int64_t size = 0;
    if (spec == NULL) return 0;
    if (!type_spec_to_array(spec, &items) || items.count != 2 || !builtin_type_symbol_named(items.items[0], "unsigned-byte")) {
        return 0;
    }
    if (items.items[1]->type != VALUE_INT || !bigint_to_i64_checked(items.items[1]->as.bigint, &size) || size != 1) {
        return 0;
    }
    return 1;
}

static int value_vector_has_unsigned_byte_8_element_type(Value *v) {
    return v != NULL &&
           v->type == VALUE_VECTOR &&
           type_spec_is_unsigned_byte_8(value_vector_element_type_spec(v));
}

static int value_vector_has_general_t_element_type(Value *v) {
    return v != NULL &&
           v->type == VALUE_VECTOR &&
           builtin_type_symbol_named(value_vector_element_type_spec(v), "t");
}

static int value_array_rank(Value *v) {
    if (v->type == VALUE_STRING) return 1;
    if (v->type != VALUE_VECTOR) return 0;
    return (v->array_rank >= 0) ? v->array_rank : 1;
}

static int value_array_dimension_at(Value *v, int axis) {
    int rank = value_array_rank(v);
    if (axis < 0 || axis >= rank) return -1;
    if (v->type == VALUE_STRING || rank <= 1 || v->array_dims == NULL) {
        return (axis == 0) ? ((v->type == VALUE_STRING) ? v->array_total_size : value_vector_total_size(v)) : -1;
    }
    return v->array_dims[axis];
}

static int value_is_vector_rank1(Value *v) {
    return v->type == VALUE_STRING || (v->type == VALUE_VECTOR && value_array_rank(v) == 1);
}

static int value_vector_total_size(Value *v) {
    if (v->type != VALUE_VECTOR) return 0;
    return (v->array_total_size >= 0) ? v->array_total_size : v->as.array.count;
}

static int value_vector_sequence_length(Value *v) {
    if (v->type != VALUE_VECTOR) return 0;
    return v->has_fill_pointer ? v->fill_pointer : v->as.array.count;
}

static int value_string_total_size(Value *v) {
    if (v->type != VALUE_STRING) return 0;
    return (v->array_total_size >= 0) ? v->array_total_size : (int)strlen(v->as.str);
}

static int value_string_sequence_length(Value *v) {
    int total = 0;
    if (v->type != VALUE_STRING) return 0;
    total = value_string_total_size(v);
    if (!v->has_fill_pointer) return total;
    if (v->fill_pointer < 0) return 0;
    if (v->fill_pointer > total) return total;
    return v->fill_pointer;
}

static char *copy_text_slice(const char *start, size_t len);

static int string_storage_read_char(Value *v, int index, int *out_ch) {
    if (v->type != VALUE_STRING) return 0;
    if (index < 0 || index >= value_string_total_size(v)) return 0;
    if (v->displaced_to != NULL) {
        if (v->displaced_to->type != VALUE_STRING) return 0;
        return string_storage_read_char(v->displaced_to, index + v->displaced_index_offset, out_ch);
    }
    if (v->as.str == NULL) return 0;
    *out_ch = (unsigned char)v->as.str[index];
    return 1;
}

static int string_storage_write_char(Value *v, int index, int ch) {
    if (v->type != VALUE_STRING) return 0;
    if (index < 0 || index >= value_string_total_size(v)) return 0;
    if ((ch & 0xFF) == 0) return 0;
    if (v->displaced_to != NULL) {
        if (v->displaced_to->type != VALUE_STRING) return 0;
        return string_storage_write_char(v->displaced_to, index + v->displaced_index_offset, ch);
    }
    if (v->as.str == NULL) return 0;
    v->as.str[index] = (char)(ch & 0xFF);
    return 1;
}

static char *value_string_copy_range(Value *v, int start, int len) {
    char *buf = NULL;
    int i = 0;
    if (v->type != VALUE_STRING) return NULL;
    if (start < 0) start = 0;
    if (len < 0) len = 0;
    if (start > value_string_total_size(v)) start = value_string_total_size(v);
    if (len > value_string_total_size(v) - start) len = value_string_total_size(v) - start;
    buf = (char *)xmalloc((size_t)len + 1U);
    for (i = 0; i < len; ++i) {
        int ch = 0;
        if (!string_storage_read_char(v, start + i, &ch)) {
            free(buf);
            return NULL;
        }
        buf[i] = (char)(ch & 0xFF);
    }
    buf[len] = '\0';
    return buf;
}

static char *value_string_copy_text(Value *v, int use_sequence_length) {
    int len = use_sequence_length ? value_string_sequence_length(v) : value_string_total_size(v);
    return value_string_copy_range(v, 0, len);
}

static int value_vector_is_displaced(Value *v) {
    return v->type == VALUE_VECTOR && v->displaced_to != NULL;
}

static int value_is_simple_bit_array(Value *v) {
    return v != NULL &&
           v->type == VALUE_VECTOR &&
           !v->has_fill_pointer &&
           !v->adjustable &&
           !value_vector_is_displaced(v) &&
           value_vector_has_bit_element_type(v);
}

