static int array_row_major_write(Value *array, int index, Value *new_value, Value **out, char *err, size_t errsz);
static int sequence_length_any(Value *seq, int *out_len, char *err, size_t errsz);
static int sequence_set_element_any(Value *seq, int index, Value *new_value, const char *who, char *err, size_t errsz);
static int expand_type_specifier_fully(Interp *it, Env *env, Value *spec, Value **out, char *err, size_t errsz);
static int proper_form_to_array(Value *form, ValueArray *out);
static int value_is_keyword(Value *v);
static int value_equal_impl(Value *a, Value *b);
