static Value *make_int_value(BigInt *big) {
    Value *v = value_new(VALUE_INT);
    v->as.bigint = big;
    return v;
}

static Value *make_float_value(double x) {
    Value *v = value_new(VALUE_FLOAT);
    v->as.flt = x;
    return v;
}

static Value *make_ratio_value(BigInt *numerator, BigInt *denominator);

static Value *make_char_value(int ch) {
    Value *v = value_new(VALUE_CHAR);
    v->as.ch = ch & 0x1FFFFF;
    return v;
}

static Value *make_string_value_sized_with_metadata(const char *s, int total_size, int has_fill_pointer, int fill_pointer, int adjustable) {
    Value *v = value_new(VALUE_STRING);
    if (total_size < 0) total_size = 0;
    v->as.str = (char *)xmalloc((size_t)total_size + 1U);
    if (total_size > 0) memcpy(v->as.str, s, (size_t)total_size);
    v->as.str[total_size] = '\0';
    if (fill_pointer < 0) fill_pointer = 0;
    if (fill_pointer > total_size) fill_pointer = total_size;
    value_set_array_metadata(v,
                             total_size,
                             has_fill_pointer,
                             has_fill_pointer ? fill_pointer : total_size,
                             adjustable);
    return v;
}

static Value *make_displaced_string(Value *target,
                                    int offset,
                                    int len,
                                    int has_fill_pointer,
                                    int fill_pointer,
                                    int adjustable) {
    Value *v = value_new(VALUE_STRING);
    if (fill_pointer < 0) fill_pointer = 0;
    if (fill_pointer > len) fill_pointer = len;
    value_set_array_metadata(v, len, has_fill_pointer, has_fill_pointer ? fill_pointer : len, adjustable);
    v->as.str = NULL;
    v->displaced_to = target;
    v->displaced_index_offset = offset;
    return v;
}

static Value *make_string_value_with_metadata(const char *s, int has_fill_pointer, int fill_pointer, int adjustable) {
    int len = (int)strlen(s);
    Value *v = make_string_value_sized_with_metadata(s, len, has_fill_pointer, fill_pointer, adjustable);
    return v;
}

static Value *make_string_value(const char *s) {
    return make_string_value_with_metadata(s, 0, (int)strlen(s), 0);
}

