static void env_set(Env *env, const char *name, Value *value) {
    env_set_value(env, name, value);
}

static void env_define(Env *env, const char *name, Value *value) {
    env_define_value(env, name, value);
}

static int env_lookup(Env *env, const char *name, Value **out) {
    return env_lookup_value(env, name, out);
}

static int env_lookup_any(Env *env, const char *name, Value **out) {
    if (env_lookup_value(env, name, out)) return 1;
    return env_lookup_function(env, name, out);
}

static int env_lookup_lexical(Env *env, const char *name, Value **out) {
    Env *cur = env;
    while (cur != NULL && cur->parent != NULL) {
        if (binding_lookup(cur->bindings, cur->count, name, out)) return 1;
        cur = cur->parent;
    }
    return 0;
}

static int env_lookup_lexical_symbol(Env *env, Value *symbol, Value **out) {
    Env *cur = env;
    while (cur != NULL && cur->parent != NULL) {
        if (binding_lookup_symbol(cur->bindings, cur->count, symbol, out)) return 1;
        cur = cur->parent;
    }
    return 0;
}

typedef enum {
    SYMBOL_REF_NONE = 0,
    SYMBOL_REF_LEXICAL_VALUE = 1,
    SYMBOL_REF_SYMBOL_MACRO = 2
} SymbolRefKind;

static int env_lookup_symbol_reference(Env *env, const char *name, Value **out, SymbolRefKind *kind) {
    Env *cur = env;
    while (cur != NULL) {
        if (cur->parent != NULL && binding_lookup(cur->bindings, cur->count, name, out)) {
            if (kind != NULL) *kind = SYMBOL_REF_LEXICAL_VALUE;
            return 1;
        }
        if (binding_lookup(cur->sbindings, cur->scount, name, out)) {
            if (kind != NULL) *kind = SYMBOL_REF_SYMBOL_MACRO;
            return 1;
        }
        cur = cur->parent;
    }
    return 0;
}

static int env_lookup_symbol_reference_symbol(Env *env, Value *symbol, Value **out, SymbolRefKind *kind) {
    Env *cur = env;
    while (cur != NULL) {
        if (cur->parent != NULL && binding_lookup_symbol(cur->bindings, cur->count, symbol, out)) {
            if (kind != NULL) *kind = SYMBOL_REF_LEXICAL_VALUE;
            return 1;
        }
        if (binding_lookup_symbol(cur->sbindings, cur->scount, symbol, out)) {
            if (kind != NULL) *kind = SYMBOL_REF_SYMBOL_MACRO;
            return 1;
        }
        cur = cur->parent;
    }
    return 0;
}

static int env_lookup_symbol_macro(Env *env, const char *name, Value **out) {
    SymbolRefKind kind = SYMBOL_REF_NONE;
    if (!env_lookup_symbol_reference(env, name, out, &kind)) return 0;
    return kind == SYMBOL_REF_SYMBOL_MACRO;
}

static int env_lookup_symbol_macro_symbol(Env *env, Value *symbol, Value **out) {
    SymbolRefKind kind = SYMBOL_REF_NONE;
    if (!env_lookup_symbol_reference_symbol(env, symbol, out, &kind)) return 0;
    return kind == SYMBOL_REF_SYMBOL_MACRO;
}

static Env *env_root(Env *env) {
    while (env != NULL && env->parent != NULL) env = env->parent;
    return env;
}

