static Value *make_defsetf_long_descriptor(Value *expander, Value *store_vars) {
    ValueArray items;
    value_array_init(&items);
    value_array_push(&items, make_symbol_value("%defsetf-long"));
    value_array_push(&items, expander);
    value_array_push(&items, store_vars);
    return make_vector_value(&items);
}

static int defsetf_descriptor_short_updater_symbol(Value *descriptor, Value **out) {
    if (descriptor == NULL) return 0;
    if (descriptor->type != VALUE_SYMBOL) return 0;
    if (out != NULL) *out = descriptor;
    return 1;
}

static int defsetf_descriptor_long_parts(Value *descriptor, Value **expander_out, Value **store_vars_out) {
    const char *marker = NULL;
    if (descriptor == NULL || descriptor->type != VALUE_VECTOR || descriptor->as.array.count != 3) return 0;
    if (!symbol_name(descriptor->as.array.items[0], &marker) || !str_ieq(marker, "%defsetf-long")) return 0;
    if (expander_out != NULL) *expander_out = descriptor->as.array.items[1];
    if (store_vars_out != NULL) *store_vars_out = descriptor->as.array.items[2];
    return 1;
}

