                    int close_atsign = 0;
                    int special_params_ready = 0;
                    int special_spare = 0;
                    int special_line_width = 72;
                    int mincol = 0;
                    int colinc = 1;
                    int minpad = 0;
                    int padchar = ' ';
                    char **segment_texts = NULL;
                    FormatPrefixParams special_params;
                    int produced_segments = 0;
                    int escaped = 0;
                    int seg = 0;
                    special_params.count = 0;
