static Value *basic_loop_make_not_form(Value *form);
static Value *basic_loop_make_and_form(Value *left, Value *right);

static Value *basic_loop_make_guarded_form(Value *base_guard_form, Value *test_form) {
    if (base_guard_form == NULL) return test_form;
    return basic_loop_make_and_form(base_guard_form, test_form);
}

static Value *basic_loop_make_guarded_not_form(Value *base_guard_form, Value *test_form) {
    Value *not_form = basic_loop_make_not_form(test_form);
    if (base_guard_form == NULL) return not_form;
    return basic_loop_make_and_form(base_guard_form, not_form);
}

static int basic_loop_consume_optional_accumulation_type_spec(Value *form,
                                                              int *idx,
                                                              BasicLoopStepKind kind,
                                                              const char *who,
                                                              char *err,
                                                              size_t errsz) {
    const char *marker = NULL;
    if (*idx >= form->as.array.count) return 1;
    if (kind == BASIC_LOOP_STEP_COLLECT ||
        kind == BASIC_LOOP_STEP_APPEND ||
        kind == BASIC_LOOP_STEP_NCONC) {
        if (symbol_name(form->as.array.items[*idx], &marker) &&
            (str_ieq(marker, "of-type") || basic_loop_is_simple_loop_type_name(marker))) {
            snprintf(err, errsz, "loop %s does not accept a type specifier", who);
            return 0;
        }
        return 1;
    }
    if (symbol_name(form->as.array.items[*idx], &marker)) {
        if (str_ieq(marker, "of-type")) {
            ++(*idx);
            if (*idx >= form->as.array.count) {
                snprintf(err, errsz, "loop %s expects a type specifier after of-type", who);
                return 0;
            }
            ++(*idx);
            return 1;
        }
        if (basic_loop_is_simple_loop_type_name(marker)) {
            ++(*idx);
            return 1;
        }
    }
    return 1;
}

static int basic_loop_parse_conditional_clause(Value *form,
                                               int *idx,
                                               BasicLoopStepArray *steps,
                                               Value *guard_form,
                                               int guard_truthy,
                                                int *anonymous_accumulation_mask,
                                                int *saw_any_accumulation,
                                               int *saw_predicate_termination,
                                               char *err,
                                               size_t errsz);

typedef enum {
    BASIC_LOOP_BIND_INITIAL = 0,
    BASIC_LOOP_BIND_UPDATE = 1
} BasicLoopBindMode;

static int basic_loop_bind_pattern_value(Interp *it,
                                         Env *env,
                                         DynamicFrame *dynamic,
                                         Value *pattern,
                                         Value *value,
                                         BasicLoopBindMode mode,
                                         char *err,
                                         size_t errsz) {
    if (pattern == NULL || pattern->type == VALUE_NIL) return 1;
    if (pattern->type == VALUE_SYMBOL) {
        if (!reject_constant_binding_target(pattern, "loop destructuring variable", err, errsz)) return 0;
        if (mode == BASIC_LOOP_BIND_UPDATE) {
            env_set_variable_symbol(it, env, pattern, value);
        } else {
            bind_local_variable_symbol(it, env, dynamic, pattern, value);
        }
        return 1;
    }
    if (pattern->type == VALUE_LIST) {
        ValueArray items;
        Value *tail = NULL;
        int proper = 0;
        int i;
        if (!destructuring_value_to_array_tail(it, value, &items, &tail, &proper, err, errsz)) return 0;
        (void)tail;
        (void)proper;
        for (i = 0; i < pattern->as.array.count; ++i) {
            Value *next_value = (i < items.count) ? items.items[i] : it->nil;
            if (!basic_loop_bind_pattern_value(it,
                                               env,
                                               dynamic,
                                               pattern->as.array.items[i],
                                               next_value,
                                               mode,
                                               err,
                                               errsz)) {
                return 0;
            }
        }
        return 1;
    }
    if (pattern->type == VALUE_CONS) {
        ValueArray items;
        Value *tail = NULL;
        int proper = 0;
        Value *rest_value = NULL;
        if (!destructuring_value_to_array_tail(it, value, &items, &tail, &proper, err, errsz)) return 0;
        (void)proper;
        if (!basic_loop_bind_pattern_value(it,
                                           env,
                                           dynamic,
                                           pattern->as.cons.car,
                                           (items.count > 0) ? items.items[0] : it->nil,
                                           mode,
                                           err,
                                           errsz)) {
            return 0;
        }
        rest_value = destructuring_remaining_value(it, &items, 1, tail);
        if (!basic_loop_bind_pattern_value(it,
                                           env,
                                           dynamic,
                                           pattern->as.cons.cdr,
                                           rest_value,
                                           mode,
                                           err,
                                           errsz)) {
            return 0;
        }
        return 1;
    }
    snprintf(err, errsz, "%s must be a symbol or destructuring list", "loop destructuring pattern");
    return 0;
}

static int basic_loop_validate_binding_pattern(Value *pattern, const char *who, char *err, size_t errsz) {
    if (pattern == NULL || pattern->type == VALUE_NIL) return 1;
    if (pattern->type == VALUE_SYMBOL) return reject_constant_binding_target(pattern, who, err, errsz);
    if (pattern->type == VALUE_LIST) {
        for (int i = 0; i < pattern->as.array.count; ++i) {
            if (!basic_loop_validate_binding_pattern(pattern->as.array.items[i], who, err, errsz)) return 0;
        }
        return 1;
    }
    if (pattern->type == VALUE_CONS) {
        if (!basic_loop_validate_binding_pattern(pattern->as.cons.car, who, err, errsz)) return 0;
        if (!basic_loop_validate_binding_pattern(pattern->as.cons.cdr, who, err, errsz)) return 0;
        return 1;
    }
    snprintf(err, errsz, "%s must be a symbol or destructuring list", who);
    return 0;
}

static int basic_loop_register_step_constraints(BasicLoopStepKind step_kind,
                                                Value *into_symbol,
                                                int *anonymous_accumulation_mask,
                                                int *saw_any_accumulation,
                                                int *saw_predicate_termination,
                                                char *err,
                                                size_t errsz) {
    if (step_kind == BASIC_LOOP_STEP_THEREIS ||
        step_kind == BASIC_LOOP_STEP_ALWAYS ||
        step_kind == BASIC_LOOP_STEP_NEVER) {
        if (*saw_predicate_termination) {
            snprintf(err, errsz, "loop currently supports only one thereis/always/never clause");
            return 0;
        }
        if (*anonymous_accumulation_mask) {
            snprintf(err, errsz, "loop currently does not mix thereis/always/never with accumulation clauses that are not INTO");
            return 0;
        }
        *saw_predicate_termination = 1;
        return 1;
    }
    if (basic_loop_is_accumulation_step(step_kind)) {
        if (*saw_predicate_termination && into_symbol == NULL) {
            snprintf(err, errsz, "loop currently does not mix accumulation clauses that are not INTO with thereis/always/never");
            return 0;
        }
        *saw_any_accumulation = 1;
        if (into_symbol == NULL) {
            int group = basic_loop_anonymous_accumulation_group(step_kind);
            *anonymous_accumulation_mask |= (1 << group);
        }
    }
    return 1;
}

static int basic_loop_parse_hash_using_clause(Value *form, int *idx, BasicLoopIterSpec *iter, char *err, size_t errsz) {
    const char *marker = NULL;
    const char *var_name = NULL;
    ValueArray items;
    if (*idx >= form->as.array.count || !symbol_name(form->as.array.items[*idx], &marker) || !str_ieq(marker, "using")) {
        return 1;
    }
    ++(*idx);
    if (*idx >= form->as.array.count || !type_spec_to_array(form->as.array.items[*idx], &items) || items.count != 2 || !symbol_name(items.items[0], &marker)) {
        snprintf(err, errsz, "loop using currently expects (hash-value var) or (hash-key var)");
        return 0;
    }
    if (!reject_constant_binding_target(items.items[1], "loop using variable", err, errsz)) return 0;
    if (!symbol_name(items.items[1], &var_name)) {
        snprintf(err, errsz, "loop using variable must be a symbol");
        return 0;
    }
    if ((iter->kind == BASIC_LOOP_ITER_HASH_KEYS && (str_ieq(marker, "hash-value") || str_ieq(marker, "hash-values"))) ||
        (iter->kind == BASIC_LOOP_ITER_HASH_VALUES && (str_ieq(marker, "hash-key") || str_ieq(marker, "hash-keys")))) {
        iter->using_kind = (iter->kind == BASIC_LOOP_ITER_HASH_KEYS) ? BASIC_LOOP_HASH_BIND_VALUE : BASIC_LOOP_HASH_BIND_KEY;
        iter->using_var_symbol = items.items[1];
        ++(*idx);
        return 1;
    }
    snprintf(err, errsz, "loop using currently supports only the companion hash-key/hash-value binding");
    return 0;
}

static int basic_loop_parse_range_clause(Value *form, int *idx, BasicLoopIterSpec *iter, char *err, size_t errsz) {
    const char *marker = NULL;
    int saw_range = 0;
    while (*idx < form->as.array.count &&
           symbol_name(form->as.array.items[*idx], &marker) &&
           basic_loop_is_range_marker_name(marker)) {
        saw_range = 1;
        if (str_ieq(marker, "from") || str_ieq(marker, "upfrom")) {
            ++(*idx);
            if (*idx >= form->as.array.count) {
                snprintf(err, errsz, "loop for ... from expects a start form");
                return 0;
            }
            iter->kind = BASIC_LOOP_ITER_RANGE;
            iter->have_start = 1;
            iter->descending = 0;
            iter->start_form = form->as.array.items[*idx];
            ++(*idx);
            continue;
        }
        if (str_ieq(marker, "downfrom")) {
            ++(*idx);
            if (*idx >= form->as.array.count) {
                snprintf(err, errsz, "loop for ... downfrom expects a start form");
                return 0;
            }
            iter->kind = BASIC_LOOP_ITER_RANGE;
            iter->have_start = 1;
            iter->descending = 1;
            iter->start_form = form->as.array.items[*idx];
            ++(*idx);
            continue;
        }
        if (str_ieq(marker, "to") || str_ieq(marker, "upto")) {
            ++(*idx);
            if (*idx >= form->as.array.count) {
                snprintf(err, errsz, "loop range to/upto expects an end form");
                return 0;
            }
            iter->kind = BASIC_LOOP_ITER_RANGE;
            iter->have_end = 1;
            iter->bound_kind = iter->descending ? BASIC_LOOP_RANGE_DOWNTO : BASIC_LOOP_RANGE_TO;
            iter->end_form = form->as.array.items[*idx];
            ++(*idx);
            continue;
        }
        if (str_ieq(marker, "below")) {
            ++(*idx);
            if (*idx >= form->as.array.count) {
                snprintf(err, errsz, "loop below expects an end form");
                return 0;
            }
            if (iter->descending) {
                snprintf(err, errsz, "loop cannot combine downfrom with below");
                return 0;
            }
            iter->kind = BASIC_LOOP_ITER_RANGE;
            iter->have_end = 1;
            iter->bound_kind = BASIC_LOOP_RANGE_BELOW;
            iter->end_form = form->as.array.items[*idx];
            ++(*idx);
            continue;
        }
        if (str_ieq(marker, "downto")) {
            ++(*idx);
            if (*idx >= form->as.array.count) {
                snprintf(err, errsz, "loop downto expects an end form");
                return 0;
            }
            iter->kind = BASIC_LOOP_ITER_RANGE;
            iter->have_end = 1;
            iter->descending = 1;
            iter->bound_kind = BASIC_LOOP_RANGE_DOWNTO;
            iter->end_form = form->as.array.items[*idx];
            ++(*idx);
            continue;
        }
        if (str_ieq(marker, "above")) {
            ++(*idx);
            if (*idx >= form->as.array.count) {
                snprintf(err, errsz, "loop above expects an end form");
                return 0;
            }
            iter->kind = BASIC_LOOP_ITER_RANGE;
            iter->have_end = 1;
            iter->descending = 1;
            iter->bound_kind = BASIC_LOOP_RANGE_ABOVE;
            iter->end_form = form->as.array.items[*idx];
            ++(*idx);
            continue;
        }
        ++(*idx);
        if (*idx >= form->as.array.count) {
            snprintf(err, errsz, "loop by expects a step form");
            return 0;
        }
        iter->kind = BASIC_LOOP_ITER_RANGE;
        iter->step_form = form->as.array.items[*idx];
        ++(*idx);
    }
    if (!saw_range) {
        snprintf(err, errsz, "loop for/as currently supports in, on, across, being each hash-key/hash-value/symbol/present-symbol/external-symbol/element(s), and arithmetic clauses");
        return 0;
    }
    if (!iter->have_start) {
        if (iter->descending) {
            snprintf(err, errsz, "loop descending arithmetic clauses currently require downfrom");
            return 0;
        }
        iter->have_start = 1;
        iter->start_form = make_int_value(bigint_new_zero());
    }
    if (iter->bound_kind == BASIC_LOOP_RANGE_NONE && iter->have_end) {
        iter->bound_kind = iter->descending ? BASIC_LOOP_RANGE_DOWNTO : BASIC_LOOP_RANGE_TO;
    }
    if (iter->step_form == NULL) iter->step_form = make_int_value(bigint_from_i64(1));
    return 1;
}

static int basic_loop_parse_for_subclause(Value *form, int *idx, BasicLoopIterSpec *iter, char *err, size_t errsz) {
    const char *marker = NULL;
    if (*idx >= form->as.array.count) {
        snprintf(err, errsz, "loop for/as expects a variable or destructuring pattern");
        return 0;
    }
    iter->pattern = form->as.array.items[*idx];
    if (!basic_loop_validate_binding_pattern(iter->pattern, "loop variable", err, errsz)) return 0;
    if (iter->pattern->type == VALUE_SYMBOL) {
        iter->var_symbol = iter->pattern;
    }
    ++(*idx);
    if (*idx < form->as.array.count) {
        if (symbol_name(form->as.array.items[*idx], &marker) && str_ieq(marker, "of-type")) {
            ++(*idx);
            if (*idx >= form->as.array.count) {
                snprintf(err, errsz, "loop of-type expects a type specifier");
                return 0;
            }
            ++(*idx);
        } else if (!(symbol_name(form->as.array.items[*idx], &marker) &&
                     basic_loop_is_iteration_marker_name(marker))) {
            ++(*idx);
        }
    }
    if (*idx >= form->as.array.count || !symbol_name(form->as.array.items[*idx], &marker)) {
        snprintf(err, errsz, "loop expects an iteration clause after the loop variable");
        return 0;
    }
    if (str_ieq(marker, "in")) {
        ++(*idx);
        if (*idx >= form->as.array.count) {
            snprintf(err, errsz, "loop for ... in expects a list form");
            return 0;
        }
        iter->kind = BASIC_LOOP_ITER_IN;
        iter->source_form = form->as.array.items[*idx];
        ++(*idx);
        if (*idx < form->as.array.count &&
            symbol_name(form->as.array.items[*idx], &marker) &&
            str_ieq(marker, "by")) {
            ++(*idx);
            if (*idx >= form->as.array.count) {
                snprintf(err, errsz, "loop for ... in by expects a step function form");
                return 0;
            }
            iter->step_form = form->as.array.items[*idx];
            ++(*idx);
        }
        return 1;
    }
    if (str_ieq(marker, "on")) {
        ++(*idx);
        if (*idx >= form->as.array.count) {
            snprintf(err, errsz, "loop for ... on expects a list form");
            return 0;
        }
        iter->kind = BASIC_LOOP_ITER_ON;
        iter->source_form = form->as.array.items[*idx];
        ++(*idx);
        if (*idx < form->as.array.count &&
            symbol_name(form->as.array.items[*idx], &marker) &&
            str_ieq(marker, "by")) {
            ++(*idx);
            if (*idx >= form->as.array.count) {
                snprintf(err, errsz, "loop for ... on by expects a step function form");
                return 0;
            }
            iter->step_form = form->as.array.items[*idx];
            ++(*idx);
        }
        return 1;
    }
    if (str_ieq(marker, "across")) {
        ++(*idx);
        if (*idx >= form->as.array.count) {
            snprintf(err, errsz, "loop for ... across expects a vector or string form");
            return 0;
        }
        iter->kind = BASIC_LOOP_ITER_ACROSS;
        iter->source_form = form->as.array.items[*idx];
        ++(*idx);
        return 1;
    }
    if (str_ieq(marker, "being")) {
        ++(*idx);
        if (*idx >= form->as.array.count || !symbol_name(form->as.array.items[*idx], &marker) ||
            (!str_ieq(marker, "each") && !str_ieq(marker, "the"))) {
            snprintf(err, errsz, "loop being currently expects each/the hash-key, hash-value, symbol, present-symbol, external-symbol, or element(s)");
            return 0;
        }
        ++(*idx);
        if (*idx >= form->as.array.count || !symbol_name(form->as.array.items[*idx], &marker)) {
            snprintf(err, errsz, "loop being currently expects hash-key, hash-value, symbol, present-symbol, external-symbol, or element(s)");
            return 0;
        }
        if (str_ieq(marker, "hash-key") || str_ieq(marker, "hash-keys")) {
            iter->kind = BASIC_LOOP_ITER_HASH_KEYS;
        } else if (str_ieq(marker, "hash-value") || str_ieq(marker, "hash-values")) {
            iter->kind = BASIC_LOOP_ITER_HASH_VALUES;
        } else if (str_ieq(marker, "symbol") || str_ieq(marker, "symbols")) {
            iter->kind = BASIC_LOOP_ITER_PACKAGE_SYMBOLS;
        } else if (str_ieq(marker, "present-symbol") || str_ieq(marker, "present-symbols")) {
            iter->kind = BASIC_LOOP_ITER_PACKAGE_PRESENT_SYMBOLS;
        } else if (str_ieq(marker, "external-symbol") || str_ieq(marker, "external-symbols")) {
            iter->kind = BASIC_LOOP_ITER_PACKAGE_EXTERNAL_SYMBOLS;
        } else if (str_ieq(marker, "element") || str_ieq(marker, "elements")) {
            iter->kind = BASIC_LOOP_ITER_BEING_ELEMENTS;
        } else {
            snprintf(err, errsz, "loop being currently supports only hash-key/hash-value/symbol/present-symbol/external-symbol/element(s) iteration");
            return 0;
        }
        ++(*idx);
        if (iter->kind == BASIC_LOOP_ITER_PACKAGE_SYMBOLS ||
            iter->kind == BASIC_LOOP_ITER_PACKAGE_PRESENT_SYMBOLS ||
            iter->kind == BASIC_LOOP_ITER_PACKAGE_EXTERNAL_SYMBOLS) {
            if (*idx >= form->as.array.count) {
                iter->source_form = NULL;
                return 1;
            }
            if (symbol_name(form->as.array.items[*idx], &marker) &&
                (str_ieq(marker, "of") || str_ieq(marker, "in"))) {
                ++(*idx);
                if (*idx >= form->as.array.count) {
                    snprintf(err, errsz, "loop being iteration expects a source form");
                    return 0;
                }
                iter->source_form = form->as.array.items[*idx];
                ++(*idx);
                return 1;
            }
            if (symbol_name(form->as.array.items[*idx], &marker) &&
                (basic_loop_is_conditional_boundary_name(marker) || basic_loop_is_top_level_clause_name(marker))) {
                iter->source_form = NULL;
                return 1;
            }
            snprintf(err, errsz, "loop being iteration expects an optional of/in package designator or a following clause");
            return 0;
        }
        if (*idx >= form->as.array.count || !symbol_name(form->as.array.items[*idx], &marker) ||
            (!str_ieq(marker, "of") && !str_ieq(marker, "in"))) {
            snprintf(err, errsz, "loop being iteration expects of/in followed by a source form");
            return 0;
        }
        ++(*idx);
        if (*idx >= form->as.array.count) {
            snprintf(err, errsz, "loop being iteration expects a source form");
            return 0;
        }
        iter->source_form = form->as.array.items[*idx];
        ++(*idx);
        if ((iter->kind == BASIC_LOOP_ITER_HASH_KEYS || iter->kind == BASIC_LOOP_ITER_HASH_VALUES) &&
            !basic_loop_parse_hash_using_clause(form, idx, iter, err, errsz)) return 0;
        return 1;
    }
    if (str_ieq(marker, "=")) {
        ++(*idx);
        if (*idx >= form->as.array.count) {
            snprintf(err, errsz, "loop for ... = expects an initial form");
            return 0;
        }
        iter->kind = BASIC_LOOP_ITER_EQUALS_THEN;
        iter->start_form = form->as.array.items[*idx];
        ++(*idx);
        if (*idx < form->as.array.count &&
            symbol_name(form->as.array.items[*idx], &marker) &&
            str_ieq(marker, "then")) {
            ++(*idx);
            if (*idx >= form->as.array.count) {
                snprintf(err, errsz, "loop then expects a form");
                return 0;
            }
            iter->step_form = form->as.array.items[*idx];
            ++(*idx);
        }
        return 1;
    }
    return basic_loop_parse_range_clause(form, idx, iter, err, errsz);
}

static int basic_loop_parse_for_clause(Value *form, int *idx, BasicLoopSpec *spec, char *err, size_t errsz) {
    const char *marker = NULL;
    BasicLoopIterSpec iter;
    BasicLoopForClause clause;
    ++(*idx);
    basic_loop_for_clause_init(&clause);
    basic_loop_iter_spec_init(&iter);
    if (!basic_loop_parse_for_subclause(form, idx, &iter, err, errsz)) return 0;
    clause.primary_iter = iter;
    while (*idx < form->as.array.count &&
           symbol_name(form->as.array.items[*idx], &marker) &&
           str_ieq(marker, "and")) {
        ++(*idx);
        basic_loop_iter_spec_init(&iter);
        if (!basic_loop_parse_for_subclause(form, idx, &iter, err, errsz)) return 0;
        basic_loop_iter_spec_array_push(&clause.and_iters, &iter);
    }
    basic_loop_for_clause_array_push(&spec->for_clauses, &clause);
    return 1;
}

static int basic_loop_parse_with_clause(Interp *it, Value *form, int *idx, BasicLoopSpec *spec, char *err, size_t errsz) {
    const char *marker = NULL;
    basic_loop_with_array_push_group(&spec->with_bindings);
    ++(*idx);
    for (;;) {
        Value *pattern = NULL;
        Value *init_form = NULL;
        Value *type_spec = NULL;
        if (*idx >= form->as.array.count) {
            snprintf(err, errsz, "loop with expects a variable name or destructuring pattern");
            return 0;
        }
        pattern = form->as.array.items[*idx];
        if (!basic_loop_validate_binding_pattern(pattern, "loop with variable", err, errsz)) return 0;
        ++(*idx);
        if (*idx < form->as.array.count && symbol_name(form->as.array.items[*idx], &marker) && str_ieq(marker, "of-type")) {
            ++(*idx);
            if (*idx >= form->as.array.count) {
                snprintf(err, errsz, "loop with of-type expects a type specifier");
                return 0;
            }
            type_spec = form->as.array.items[*idx];
            ++(*idx);
        } else if (*idx < form->as.array.count &&
                   !(symbol_name(form->as.array.items[*idx], &marker) &&
                     (str_ieq(marker, "=") ||
                      str_ieq(marker, "and") ||
                      basic_loop_is_top_level_clause_name(marker)))) {
            type_spec = form->as.array.items[*idx];
            ++(*idx);
        }
        if (*idx < form->as.array.count && symbol_name(form->as.array.items[*idx], &marker) && str_ieq(marker, "=")) {
            ++(*idx);
            if (*idx >= form->as.array.count) {
                snprintf(err, errsz, "loop with = expects an initializer form");
                return 0;
            }
            init_form = form->as.array.items[*idx];
            ++(*idx);
        }
        if (init_form == NULL) {
            init_form = basic_loop_default_with_init_form(it, pattern, type_spec);
        }
        basic_loop_with_array_push(&spec->with_bindings, pattern, init_form);
        if (*idx < form->as.array.count && symbol_name(form->as.array.items[*idx], &marker) && str_ieq(marker, "and")) {
            ++(*idx);
            continue;
        }
        break;
    }
    return 1;
}

static Value *basic_loop_into_initial_value(Interp *it, BasicLoopStepKind kind) {
    if (kind == BASIC_LOOP_STEP_SUM || kind == BASIC_LOOP_STEP_COUNT) return make_int_value(bigint_new_zero());
    (void)it;
    return it->nil;
}

static int basic_loop_apply_with_bindings(Interp *it, Env *env, DynamicFrame *dynamic, const BasicLoopSpec *spec, char *err, size_t errsz) {
    int group = 0;
    for (group = 0; group < spec->with_bindings.group_count; ++group) {
        int start = spec->with_bindings.group_starts[group];
        int end = (group + 1 < spec->with_bindings.group_count) ? spec->with_bindings.group_starts[group + 1] : spec->with_bindings.count;
        ValueArray values;
        int i;
        value_array_init(&values);
        for (i = start; i < end; ++i) {
            Value *value = it->nil;
            if (spec->with_bindings.items[i].init_form != NULL &&
                !eval(it, env, spec->with_bindings.items[i].init_form, &value, err, errsz)) {
                return 0;
            }
            value_array_push(&values, value);
        }
        for (i = start; i < end; ++i) {
            if (!basic_loop_bind_pattern_value(it,
                                               env,
                                               dynamic,
                                               spec->with_bindings.items[i].pattern,
                                               values.items[i - start],
                                               BASIC_LOOP_BIND_INITIAL,
                                               err,
                                               errsz)) {
                return 0;
            }
        }
    }
    return 1;
}

static int basic_loop_lookup_local(Interp *it, Env *env, Value *symbol, Value **out, int *is_bound) {
    if (symbol != NULL && env_symbol_is_special(env, symbol)) return symbol_value_lookup_symbol(it, env, symbol, out, is_bound);
    if (is_bound != NULL) *is_bound = 0;
    if (symbol != NULL && env_lookup_value_symbol(env, symbol, out)) {
        if (is_bound != NULL) *is_bound = 1;
        return 1;
    }
    return 0;
}

static Value *basic_loop_make_not_form(Value *form) {
    return make_form_from2(make_symbol_value("not"), form);
}

static Value *basic_loop_make_and_form(Value *left, Value *right) {
    return make_form_from3(make_symbol_value("and"), left, right);
}

static Value *basic_loop_make_conditional_guard_form(const char *marker, Value *test_form) {
    if (str_ieq(marker, "unless")) return basic_loop_make_not_form(test_form);
    return test_form;
}

static int basic_loop_form_is_it(Value *form) {
    const char *marker = NULL;
    return form != NULL &&
           form->type == VALUE_SYMBOL &&
           symbol_name(form, &marker) &&
           str_ieq(marker, "it");
}

static int basic_loop_form_is_loop_finish(Value *form) {
    ValueArray items;
    const char *marker = NULL;
    if (!proper_form_to_array(form, &items) || items.count != 1) return 0;
    return symbol_name(items.items[0], &marker) && str_ieq(marker, "loop-finish");
}

static int basic_loop_parse_guarded_action_clause(Value *form,
                                                  int *idx,
                                                  BasicLoopStepArray *steps,
                                                  Value *guard_form,
                                                  int guard_truthy,
                                                   int *anonymous_accumulation_mask,
                                                  int *saw_any_accumulation,
                                                  int *saw_predicate_termination,
                                                  char *err,
                                                  size_t errsz) {
    const char *marker = NULL;
    const char *clause_name = NULL;
    Value *into_symbol = NULL;
    BasicLoopStepKind step_kind = BASIC_LOOP_STEP_DO;
    Value *acc_form = NULL;
    if (*idx >= form->as.array.count || !symbol_name(form->as.array.items[*idx], &marker) || !basic_loop_is_conditional_action_clause_name(marker)) {
        snprintf(err, errsz, "loop conditional clauses currently support only action clauses");
        return 0;
    }
    clause_name = marker;
    if (str_ieq(marker, "do") || str_ieq(marker, "doing")) {
        int saw_form = 0;
        ++(*idx);
        while (*idx < form->as.array.count) {
            const char *next_clause = NULL;
            if (symbol_name(form->as.array.items[*idx], &next_clause) &&
                (basic_loop_is_conditional_boundary_name(next_clause) || basic_loop_is_top_level_clause_name(next_clause))) {
                break;
            }
            basic_loop_step_array_push_guarded_into(steps,
                                                    basic_loop_form_is_loop_finish(form->as.array.items[*idx]) ? BASIC_LOOP_STEP_FINISH : BASIC_LOOP_STEP_DO,
                                                    form->as.array.items[*idx],
                                                    NULL,
                                                    guard_form,
                                                    guard_truthy);
            ++(*idx);
            saw_form = 1;
        }
        if (!saw_form) {
            snprintf(err, errsz, "loop do expects at least one body form");
            return 0;
        }
        return 1;
    }
    if (str_ieq(marker, "return")) {
        ++(*idx);
        if (*idx >= form->as.array.count) {
            snprintf(err, errsz, "loop return expects a form");
            return 0;
        }
        basic_loop_step_array_push_guarded_into(steps, BASIC_LOOP_STEP_RETURN, form->as.array.items[*idx], NULL, guard_form, guard_truthy);
        ++(*idx);
        return 1;
    }
    if (str_ieq(marker, "append") || str_ieq(marker, "appending")) step_kind = BASIC_LOOP_STEP_APPEND;
    else if (str_ieq(marker, "nconc") || str_ieq(marker, "nconcing")) step_kind = BASIC_LOOP_STEP_NCONC;
    else if (str_ieq(marker, "sum") || str_ieq(marker, "summing")) step_kind = BASIC_LOOP_STEP_SUM;
    else if (str_ieq(marker, "count") || str_ieq(marker, "counting")) step_kind = BASIC_LOOP_STEP_COUNT;
    else if (str_ieq(marker, "maximize") || str_ieq(marker, "maximizing")) step_kind = BASIC_LOOP_STEP_MAXIMIZE;
    else if (str_ieq(marker, "minimize") || str_ieq(marker, "minimizing")) step_kind = BASIC_LOOP_STEP_MINIMIZE;
    else if (str_ieq(marker, "thereis")) step_kind = BASIC_LOOP_STEP_THEREIS;
    else if (str_ieq(marker, "always")) step_kind = BASIC_LOOP_STEP_ALWAYS;
    else if (str_ieq(marker, "never")) step_kind = BASIC_LOOP_STEP_NEVER;
    else step_kind = BASIC_LOOP_STEP_COLLECT;
    ++(*idx);
    if (*idx >= form->as.array.count) {
        snprintf(err, errsz, "loop %s expects a form", marker);
        return 0;
    }
    acc_form = form->as.array.items[*idx];
    ++(*idx);
    if (basic_loop_is_accumulation_step(step_kind) &&
        *idx < form->as.array.count &&
        symbol_name(form->as.array.items[*idx], &marker) &&
        str_ieq(marker, "into")) {
        ++(*idx);
        if (*idx >= form->as.array.count || !symbol_name(form->as.array.items[*idx], &marker)) {
            snprintf(err, errsz, "loop into expects a variable name");
            return 0;
        }
        if (!reject_constant_binding_target(form->as.array.items[*idx], "loop into variable", err, errsz)) return 0;
        into_symbol = form->as.array.items[*idx];
        ++(*idx);
    }
    if (!basic_loop_consume_optional_accumulation_type_spec(form, idx, step_kind, clause_name, err, errsz)) return 0;
    if (!basic_loop_register_step_constraints(step_kind,
                                              into_symbol,
                                                      anonymous_accumulation_mask,
                                              saw_any_accumulation,
                                              saw_predicate_termination,
                                              err,
                                              errsz)) return 0;
    basic_loop_step_array_push_guarded_into(steps, step_kind, acc_form, into_symbol, guard_form, guard_truthy);
    return 1;
}

static int basic_loop_parse_conditional_branch(Value *form,
                                               int *idx,
                                               BasicLoopStepArray *steps,
                                               Value *guard_form,
                                               int guard_truthy,
                                                int *anonymous_accumulation_mask,
                                                int *saw_any_accumulation,
                                               int *saw_predicate_termination,
                                               char *err,
                                               size_t errsz) {
    int parsed_any = 0;
    while (*idx < form->as.array.count) {
        const char *marker = NULL;
        if (symbol_name(form->as.array.items[*idx], &marker) && basic_loop_is_conditional_boundary_name(marker)) break;
        if (symbol_name(form->as.array.items[*idx], &marker) && basic_loop_is_conditional_marker_name(marker)) {
            if (!basic_loop_parse_conditional_clause(form,
                                                     idx,
                                                     steps,
                                                     guard_form,
                                                     guard_truthy,
                                                      anonymous_accumulation_mask,
                                                     saw_any_accumulation,
                                                     saw_predicate_termination,
                                                     err,
                                                     errsz)) {
                return 0;
            }
        } else {
            if (basic_loop_form_is_loop_finish(form->as.array.items[*idx])) {
                basic_loop_step_array_push_guarded_into(steps, BASIC_LOOP_STEP_FINISH,
                                                        form->as.array.items[*idx], NULL,
                                                        guard_form, guard_truthy);
                ++(*idx);
                parsed_any = 1;
                if (*idx < form->as.array.count &&
                    symbol_name(form->as.array.items[*idx], &marker) &&
                    str_ieq(marker, "and")) {
                    ++(*idx);
                    continue;
                }
                break;
            }
            if (!basic_loop_parse_guarded_action_clause(form,
                                                        idx,
                                                        steps,
                                                        guard_form,
                                                        guard_truthy,
                                                         anonymous_accumulation_mask,
                                                         saw_any_accumulation,
                                                        saw_predicate_termination,
                                                        err,
                                                        errsz)) {
                if (!parsed_any) return 0;
                break;
            }
        }
        parsed_any = 1;
        if (*idx < form->as.array.count &&
            symbol_name(form->as.array.items[*idx], &marker) &&
            str_ieq(marker, "and")) {
            ++(*idx);
            continue;
        }
        break;
    }
    if (!parsed_any) {
        snprintf(err, errsz, "loop if/when/unless expects at least one selectable clause");
        return 0;
    }
    return 1;
}

static int basic_loop_parse_conditional_clause(Value *form,
                                               int *idx,
                                               BasicLoopStepArray *steps,
                                               Value *guard_form,
                                               int guard_truthy,
                                                int *anonymous_accumulation_mask,
                                                int *saw_any_accumulation,
                                               int *saw_predicate_termination,
                                               char *err,
                                               size_t errsz) {
    const char *marker = NULL;
    Value *test_form = NULL;
    Value *effective_test = NULL;
    Value *then_guard = NULL;
    Value *else_guard = NULL;
    if (*idx >= form->as.array.count || !symbol_name(form->as.array.items[*idx], &marker) || !basic_loop_is_conditional_marker_name(marker)) {
        snprintf(err, errsz, "loop conditional clauses currently expect an if, when, or unless keyword");
        return 0;
    }
    ++(*idx);
    if (*idx >= form->as.array.count) {
        snprintf(err, errsz, "loop %s expects a test form", marker);
        return 0;
    }
    test_form = form->as.array.items[*idx];
    ++(*idx);
    effective_test = basic_loop_make_conditional_guard_form(marker, test_form);
    then_guard = basic_loop_make_guarded_form(guard_form, effective_test);
    if (!basic_loop_parse_conditional_branch(form,
                                             idx,
                                             steps,
                                             then_guard,
                                             guard_truthy,
                                             anonymous_accumulation_mask,
                                             saw_any_accumulation,
                                             saw_predicate_termination,
                                             err,
                                             errsz)) {
        return 0;
    }
    if (*idx < form->as.array.count &&
        symbol_name(form->as.array.items[*idx], &marker) &&
        str_ieq(marker, "else")) {
        ++(*idx);
        else_guard = basic_loop_make_guarded_not_form(guard_form, effective_test);
        if (*idx < form->as.array.count &&
            symbol_name(form->as.array.items[*idx], &marker) &&
            basic_loop_is_conditional_marker_name(marker)) {
            if (!basic_loop_parse_conditional_clause(form,
                                                     idx,
                                                     steps,
                                                     else_guard,
                                                     guard_truthy,
                                                      anonymous_accumulation_mask,
                                                     saw_any_accumulation,
                                                     saw_predicate_termination,
                                                     err,
                                                     errsz)) {
                return 0;
            }
        } else {
            if (!basic_loop_parse_conditional_branch(form,
                                                     idx,
                                                     steps,
                                                     else_guard,
                                                     guard_truthy,
                                                      anonymous_accumulation_mask,
                                                     saw_any_accumulation,
                                                     saw_predicate_termination,
                                                     err,
                                                     errsz)) {
                return 0;
            }
        }
    }
    if (*idx < form->as.array.count &&
        symbol_name(form->as.array.items[*idx], &marker) &&
        str_ieq(marker, "end")) {
        ++(*idx);
    }
    return 1;
}

static int basic_loop_coerce_proper_runtime_list(Interp *it, Value *list, const char *who, Value **out, char *err, size_t errsz) {
    Value *runtime = NULL;
    ValueArray ignored;
    if (!value_is_list_like(list)) {
        snprintf(err, errsz, "%s expects a proper list", who);
        return 0;
    }
    runtime = (list->type == VALUE_LIST) ? runtime_list_from_array(it->nil, &list->as.array) : list;
    if (!proper_list_to_array(runtime, &ignored, err, errsz)) {
        snprintf(err, errsz, "%s expects a proper list", who);
        return 0;
    }
    *out = runtime;
    return 1;
}

static int basic_loop_append_list_piece(Interp *it, Value **acc, Value *piece, int destructive, char *err, size_t errsz) {
    Value *runtime = NULL;
    Value *tail = NULL;
    if (!basic_loop_coerce_proper_runtime_list(it, piece, "loop append/nconc", &runtime, err, errsz)) return 0;
    if (!destructive) runtime = copy_list_value(it, runtime);
    if (runtime->type == VALUE_NIL) return 1;
    if ((*acc)->type == VALUE_NIL) {
        *acc = runtime;
        return 1;
    }
    tail = *acc;
    while (tail->type == VALUE_CONS && tail->as.cons.cdr->type == VALUE_CONS) tail = tail->as.cons.cdr;
    if (tail->type != VALUE_CONS || tail->as.cons.cdr->type != VALUE_NIL) {
        snprintf(err, errsz, "loop internal list accumulator is not a proper list");
        return 0;
    }
    tail->as.cons.cdr = runtime;
    return 1;
}

static int basic_loop_runtime_init_iterator(Interp *it, Env *env, const BasicLoopIterSpec *iter, BasicLoopIterRuntime *rt, char *err, size_t errsz) {
    Value *value = NULL;
    Num step = num_make_big(bigint_new_zero());
    Num zero = num_make_big(bigint_new_zero());
    int cmp = 0;
    basic_loop_iter_runtime_init(rt);
    if (iter->kind == BASIC_LOOP_ITER_NONE) return 1;
    if (iter->kind == BASIC_LOOP_ITER_IN || iter->kind == BASIC_LOOP_ITER_ON) {
        if (!eval(it, env, iter->source_form, &value, err, errsz)) return 0;
        if (!basic_loop_coerce_proper_runtime_list(it, value, (iter->kind == BASIC_LOOP_ITER_IN) ? "loop for ... in" : "loop for ... on", &rt->list_cursor, err, errsz)) return 0;
        if (iter->step_form != NULL) {
            if (!eval(it, env, iter->step_form, &rt->step_value, err, errsz)) return 0;
        } else {
            rt->step_value = common_lisp_runtime_symbol_or_fallback(it, "cdr");
        }
        return resolve_function_designator(env, rt->step_value, &rt->step_value, err, errsz);
    }
    if (iter->kind == BASIC_LOOP_ITER_HASH_KEYS || iter->kind == BASIC_LOOP_ITER_HASH_VALUES) {
        if (!eval(it, env, iter->source_form, &value, err, errsz)) return 0;
        if (value->type != VALUE_HASH_TABLE) {
            snprintf(err, errsz, "loop hash iteration expects a hash-table");
            return 0;
        }
        rt->hash_table = value;
        rt->hash_index = 0;
        return 1;
    }
    if (iter->kind == BASIC_LOOP_ITER_PACKAGE_SYMBOLS ||
        iter->kind == BASIC_LOOP_ITER_PACKAGE_PRESENT_SYMBOLS ||
        iter->kind == BASIC_LOOP_ITER_PACKAGE_EXTERNAL_SYMBOLS) {
        Value *pkg = NULL;
        int include_internal = 0;
        int include_external = 0;
        int include_inherited = 0;
        if (iter->source_form != NULL) {
            if (!eval(it, env, iter->source_form, &value, err, errsz)) return 0;
            if (!resolve_package_designator(it, env, value, "loop package iteration", &pkg, err, errsz)) return 0;
        } else {
            pkg = current_package_runtime(it, env);
            if (pkg == NULL) {
                snprintf(err, errsz, "loop package iteration could not resolve a current package");
                return 0;
            }
        }
        if (iter->kind == BASIC_LOOP_ITER_PACKAGE_SYMBOLS) {
            include_internal = 1;
            include_external = 1;
            include_inherited = 1;
        } else if (iter->kind == BASIC_LOOP_ITER_PACKAGE_PRESENT_SYMBOLS) {
            include_internal = 1;
            include_external = 1;
        } else {
            include_external = 1;
        }
        return collect_symbols_in_package(pkg,
                                          include_internal,
                                          include_external,
                                          include_inherited,
                                          &rt->seq_items,
                                          err,
                                          errsz);
    }
    if (iter->kind == BASIC_LOOP_ITER_ACROSS) {
        if (!eval(it, env, iter->source_form, &value, err, errsz)) return 0;
        if (value->type != VALUE_VECTOR && value->type != VALUE_STRING) {
            snprintf(err, errsz, "loop for ... across expects a vector or string");
            return 0;
        }
        if (!sequence_to_array(value, &rt->seq_items, err, errsz)) return 0;
        return 1;
    }
    if (iter->kind == BASIC_LOOP_ITER_BEING_ELEMENTS) {
        if (!eval(it, env, iter->source_form, &value, err, errsz)) return 0;
        if (!sequence_to_array(value, &rt->seq_items, err, errsz)) return 0;
        return 1;
    }
    if (iter->kind == BASIC_LOOP_ITER_EQUALS_THEN) {
        if (!eval(it, env, iter->start_form, &value, err, errsz)) return 0;
        rt->current_value = value;
        return 1;
    }
    if (!eval(it, env, iter->start_form, &value, err, errsz) || !num_from_value(value, &rt->range_current, err, errsz)) return 0;
    if (iter->have_end) {
        if (!eval(it, env, iter->end_form, &value, err, errsz) || !num_from_value(value, &rt->range_end, err, errsz)) return 0;
    }
    if (!eval(it, env, iter->step_form, &value, err, errsz) || !num_from_value(value, &step, err, errsz)) return 0;
    if (!num_cmp(step, zero, &cmp)) {
        snprintf(err, errsz, "loop by expects a numeric step");
        return 0;
    }
    if (cmp == 0) {
        snprintf(err, errsz, "loop by step must be non-zero");
        return 0;
    }
    if (cmp < 0) {
        snprintf(err, errsz, "loop by currently expects a positive step");
        return 0;
    }
    rt->range_step = step;
    return 1;
}

static int basic_loop_iterator_active(const BasicLoopIterSpec *iter, BasicLoopIterRuntime *rt, int *active, char *err, size_t errsz) {
    int cmp = 0;
    *active = 1;
    if (iter->kind == BASIC_LOOP_ITER_NONE) return 1;
    if (iter->kind == BASIC_LOOP_ITER_IN || iter->kind == BASIC_LOOP_ITER_ON) {
        *active = (rt->list_cursor != NULL && rt->list_cursor->type == VALUE_CONS);
        return 1;
    }
    if (iter->kind == BASIC_LOOP_ITER_HASH_KEYS || iter->kind == BASIC_LOOP_ITER_HASH_VALUES) {
        *active = rt->hash_table != NULL && rt->hash_index < rt->hash_table->as.hash_table.count;
        return 1;
    }
    if (iter->kind == BASIC_LOOP_ITER_PACKAGE_SYMBOLS ||
        iter->kind == BASIC_LOOP_ITER_PACKAGE_PRESENT_SYMBOLS ||
        iter->kind == BASIC_LOOP_ITER_PACKAGE_EXTERNAL_SYMBOLS) {
        *active = rt->seq_index < rt->seq_items.count;
        return 1;
    }
    if (iter->kind == BASIC_LOOP_ITER_ACROSS ||
        iter->kind == BASIC_LOOP_ITER_BEING_ELEMENTS) {
        *active = rt->seq_index < rt->seq_items.count;
        return 1;
    }
    if (iter->kind == BASIC_LOOP_ITER_EQUALS_THEN) return 1;
    if (!iter->have_end) return 1;
    if (!num_cmp(rt->range_current, rt->range_end, &cmp)) {
        snprintf(err, errsz, "loop range comparison failed");
        return 0;
    }
    if (iter->bound_kind == BASIC_LOOP_RANGE_BELOW) {
        *active = (cmp < 0);
    } else if (iter->bound_kind == BASIC_LOOP_RANGE_ABOVE) {
        *active = (cmp > 0);
    } else if (iter->descending) {
        *active = (cmp >= 0);
    } else {
        *active = (cmp <= 0);
    }
    return 1;
}

static int basic_loop_bind_iteration_variable(Interp *it, Env *env, const BasicLoopIterSpec *iter, BasicLoopIterRuntime *rt, char *err, size_t errsz) {
    Value *bound = NULL;
    if (iter->kind == BASIC_LOOP_ITER_NONE || iter->pattern == NULL) return 1;
    if (iter->kind == BASIC_LOOP_ITER_IN) {
        bound = (rt->list_cursor != NULL && rt->list_cursor->type == VALUE_CONS) ? rt->list_cursor->as.cons.car : it->nil;
    } else if (iter->kind == BASIC_LOOP_ITER_ON) {
        bound = (rt->list_cursor != NULL) ? rt->list_cursor : it->nil;
    } else if (iter->kind == BASIC_LOOP_ITER_HASH_KEYS) {
        bound = (rt->hash_table != NULL && rt->hash_index < rt->hash_table->as.hash_table.count)
                    ? rt->hash_table->as.hash_table.entries[rt->hash_index].key
                    : it->nil;
    } else if (iter->kind == BASIC_LOOP_ITER_HASH_VALUES) {
        bound = (rt->hash_table != NULL && rt->hash_index < rt->hash_table->as.hash_table.count)
                    ? rt->hash_table->as.hash_table.entries[rt->hash_index].value
                    : it->nil;
    } else if (iter->kind == BASIC_LOOP_ITER_PACKAGE_SYMBOLS ||
               iter->kind == BASIC_LOOP_ITER_PACKAGE_PRESENT_SYMBOLS ||
               iter->kind == BASIC_LOOP_ITER_PACKAGE_EXTERNAL_SYMBOLS) {
        bound = (rt->seq_index >= 0 && rt->seq_index < rt->seq_items.count) ? rt->seq_items.items[rt->seq_index] : it->nil;
    } else if (iter->kind == BASIC_LOOP_ITER_ACROSS ||
               iter->kind == BASIC_LOOP_ITER_BEING_ELEMENTS) {
        bound = (rt->seq_index >= 0 && rt->seq_index < rt->seq_items.count) ? rt->seq_items.items[rt->seq_index] : it->nil;
    } else if (iter->kind == BASIC_LOOP_ITER_EQUALS_THEN) {
        bound = rt->current_value;
    } else {
        bound = num_to_value_checked(rt->range_current, err, errsz);
        if (bound == NULL) return 0;
    }
    if (!basic_loop_bind_pattern_value(it, env, NULL, iter->pattern, bound, BASIC_LOOP_BIND_UPDATE, err, errsz)) return 0;
    if (iter->using_var_symbol != NULL) {
        Value *using_value = it->nil;
        if (rt->hash_table != NULL && rt->hash_index < rt->hash_table->as.hash_table.count) {
            using_value = (iter->using_kind == BASIC_LOOP_HASH_BIND_KEY)
                              ? rt->hash_table->as.hash_table.entries[rt->hash_index].key
                              : rt->hash_table->as.hash_table.entries[rt->hash_index].value;
        }
        env_set_variable_symbol(it, env, iter->using_var_symbol, using_value);
    }
    return 1;
}

static int basic_loop_advance_iterator(Interp *it, Env *env, const BasicLoopIterSpec *iter, BasicLoopIterRuntime *rt, char *err, size_t errsz) {
    Value *next_value = NULL;
    if (iter->kind == BASIC_LOOP_ITER_IN || iter->kind == BASIC_LOOP_ITER_ON) {
        if (rt->list_cursor != NULL && rt->list_cursor->type == VALUE_CONS) {
            if (!call_unary_function(it, env, rt->step_value, rt->list_cursor, &next_value, err, errsz)) return 0;
            if (!basic_loop_coerce_proper_runtime_list(it, next_value, "loop list by stepper", &rt->list_cursor, err, errsz)) return 0;
        }
        return 1;
    }
    if (iter->kind == BASIC_LOOP_ITER_ACROSS ||
        iter->kind == BASIC_LOOP_ITER_BEING_ELEMENTS) {
        ++rt->seq_index;
        return 1;
    }
    if (iter->kind == BASIC_LOOP_ITER_PACKAGE_SYMBOLS ||
        iter->kind == BASIC_LOOP_ITER_PACKAGE_PRESENT_SYMBOLS ||
        iter->kind == BASIC_LOOP_ITER_PACKAGE_EXTERNAL_SYMBOLS) {
        ++rt->seq_index;
        return 1;
    }
    if (iter->kind == BASIC_LOOP_ITER_HASH_KEYS || iter->kind == BASIC_LOOP_ITER_HASH_VALUES) {
        ++rt->hash_index;
        return 1;
    }
    if (iter->kind == BASIC_LOOP_ITER_EQUALS_THEN) {
        Value *step = (iter->step_form != NULL) ? iter->step_form : iter->start_form;
        if (!eval(it, env, step, &next_value, err, errsz)) return 0;
        rt->current_value = next_value;
        return 1;
    }
    if (iter->kind == BASIC_LOOP_ITER_RANGE) {
        rt->range_current = iter->descending ? num_sub(rt->range_current, rt->range_step) : num_add(rt->range_current, rt->range_step);
    }
    return 1;
}

static int basic_loop_bind_clause_placeholders(Interp *it, Env *env, DynamicFrame *dynamic, const BasicLoopForClause *clause, char *err, size_t errsz) {
    if (clause->primary_iter.pattern != NULL &&
        !basic_loop_bind_pattern_value(it, env, dynamic, clause->primary_iter.pattern, it->nil, BASIC_LOOP_BIND_INITIAL, err, errsz)) {
        return 0;
    }
    if (clause->primary_iter.using_var_symbol != NULL) bind_local_variable_symbol(it, env, dynamic, clause->primary_iter.using_var_symbol, it->nil);
    for (int i = 0; i < clause->and_iters.count; ++i) {
        if (clause->and_iters.items[i].pattern != NULL &&
            !basic_loop_bind_pattern_value(it,
                                           env,
                                           dynamic,
                                           clause->and_iters.items[i].pattern,
                                           it->nil,
                                           BASIC_LOOP_BIND_INITIAL,
                                           err,
                                           errsz)) {
            return 0;
        }
        if (clause->and_iters.items[i].using_var_symbol != NULL) bind_local_variable_symbol(it, env, dynamic, clause->and_iters.items[i].using_var_symbol, it->nil);
    }
    return 1;
}

static int basic_loop_clause_init_runtime(Interp *it, Env *env, const BasicLoopForClause *clause, BasicLoopForRuntime *rt, char *err, size_t errsz) {
    if (!basic_loop_runtime_init_iterator(it, env, &clause->primary_iter, &rt->primary_iter, err, errsz)) return 0;
    for (int i = 0; i < clause->and_iters.count; ++i) {
        if (!basic_loop_runtime_init_iterator(it, env, &clause->and_iters.items[i], &rt->and_iters[i], err, errsz)) return 0;
    }
    return 1;
}

static int basic_loop_clause_active(const BasicLoopForClause *clause, BasicLoopForRuntime *rt, int *active, char *err, size_t errsz) {
    int iter_active = 1;
    if (!basic_loop_iterator_active(&clause->primary_iter, &rt->primary_iter, active, err, errsz)) return 0;
    for (int i = 0; *active && i < clause->and_iters.count; ++i) {
        if (!basic_loop_iterator_active(&clause->and_iters.items[i], &rt->and_iters[i], &iter_active, err, errsz)) return 0;
        if (!iter_active) *active = 0;
    }
    return 1;
}

static int basic_loop_bind_clause_values(Interp *it, Env *env, const BasicLoopForClause *clause, BasicLoopForRuntime *rt, char *err, size_t errsz) {
    if (!basic_loop_bind_iteration_variable(it, env, &clause->primary_iter, &rt->primary_iter, err, errsz)) return 0;
    for (int i = 0; i < clause->and_iters.count; ++i) {
        if (!basic_loop_bind_iteration_variable(it, env, &clause->and_iters.items[i], &rt->and_iters[i], err, errsz)) return 0;
    }
    return 1;
}

static int basic_loop_advance_clause(Interp *it, Env *env, const BasicLoopForClause *clause, BasicLoopForRuntime *rt, char *err, size_t errsz) {
    if (!basic_loop_advance_iterator(it, env, &clause->primary_iter, &rt->primary_iter, err, errsz)) return 0;
    for (int i = 0; i < clause->and_iters.count; ++i) {
        if (!basic_loop_advance_iterator(it, env, &clause->and_iters.items[i], &rt->and_iters[i], err, errsz)) return 0;
    }
    return 1;
}

static int execute_basic_loop(Interp *it, Env *env, const BasicLoopSpec *spec, const BasicLoopStepArray *steps, Value **out, char *err, size_t errsz) {
    Env *block_env = NULL;
    Env *child = NULL;
    DynamicFrame dynamic;
    BlockFrame named_frame;
    BlockFrame frame;
    BasicLoopRuntime rt;
    BasicLoopStepKind predicate_kind = BASIC_LOOP_STEP_DO;
    Value *anon_extreme = it->nil;
    int have_anon_extreme = 0;
    Value *list_acc = it->nil;
    Num sum_acc = num_make_big(bigint_new_zero());
    Value *cached_guard_form = NULL;
    Value *cached_guard_value = NULL;
    Value *ignored = it->nil;
    Value *normal_result = it->nil;
    int have_named = (spec->named_block_name != NULL);
    int named_jumped = 0;
    int jumped = 0;
    int active = 1;
    int i;
    int accumulation_mask = 0;
    int j;
    int saw_predicate_termination = 0;
    int have_result_override = 0;
    if (have_named) {
        block_env = env_new(env);
        block_env->active_model = env->active_model;
        block_env->block_name = spec->named_block_name;
        child = env_new(block_env);
    } else {
        child = env_new(env);
    }
    child->active_model = env->active_model;
    child->block_name = it->nil;
    dynamic_frame_init(&dynamic, it->dynamic);
    it->dynamic = &dynamic;
    if (!basic_loop_apply_with_bindings(it, child, &dynamic, spec, err, errsz)) {
        it->dynamic = dynamic.prev;
        dynamic_frame_dispose(&dynamic);
        return 0;
    }
    basic_loop_runtime_init(&rt, spec);
    if (spec->have_repeat) {
        Value *repeat_value = NULL;
        if (!eval(it, env, spec->repeat_form, &repeat_value, err, errsz) ||
            !value_to_loop_count(it, repeat_value, "loop repeat", &rt.repeat_remaining, err, errsz)) {
            it->dynamic = dynamic.prev;
            dynamic_frame_dispose(&dynamic);
            return 0;
        }
        if (rt.repeat_remaining < 0) rt.repeat_remaining = 0;
    }
    for (j = 0; j < spec->for_clauses.count; ++j) {
        if (!basic_loop_clause_init_runtime(it, child, &spec->for_clauses.items[j], &rt.clauses[j], err, errsz)) {
            it->dynamic = dynamic.prev;
            dynamic_frame_dispose(&dynamic);
            return 0;
        }
        if (!basic_loop_bind_clause_placeholders(it, child, &dynamic, &spec->for_clauses.items[j], err, errsz)) {
            it->dynamic = dynamic.prev;
            dynamic_frame_dispose(&dynamic);
            return 0;
        }
        if (!basic_loop_bind_clause_values(it, child, &spec->for_clauses.items[j], &rt.clauses[j], err, errsz)) {
            it->dynamic = dynamic.prev;
            dynamic_frame_dispose(&dynamic);
            return 0;
        }
    }
    for (i = 0; i < steps->count; ++i) {
        if (steps->items[i].into_symbol != NULL && !binding_lookup_symbol(child->bindings, child->count, steps->items[i].into_symbol, NULL)) {
            bind_local_variable_symbol(it, child, &dynamic, steps->items[i].into_symbol, basic_loop_into_initial_value(it, steps->items[i].kind));
        }
        if (steps->items[i].into_symbol == NULL && basic_loop_is_accumulation_step(steps->items[i].kind)) {
            accumulation_mask |= (1 << basic_loop_anonymous_accumulation_group(steps->items[i].kind));
        }
        if (!saw_predicate_termination &&
            (steps->items[i].kind == BASIC_LOOP_STEP_THEREIS ||
             steps->items[i].kind == BASIC_LOOP_STEP_ALWAYS ||
             steps->items[i].kind == BASIC_LOOP_STEP_NEVER)) {
            saw_predicate_termination = 1;
            predicate_kind = steps->items[i].kind;
        }
    }
    if (have_named) {
        named_frame.prev = it->blocks;
        named_frame.env = block_env;
        named_frame.saved_dynamic = dynamic.prev;
        named_frame.saved_tagbodies = it->tagbodies;
        named_frame.saved_catches = it->catches;
        named_frame.saved_handlers = it->handlers;
        named_frame.saved_restarts = it->restarts;
        named_frame.saved_condition_restart_assocs = it->condition_restart_assocs;
    frame.saved_condition_restart_assocs = it->condition_restart_assocs;
        named_frame.value = it->nil;
        it->blocks = &named_frame;
        named_jumped = setjmp(named_frame.buf);
        if (named_jumped != 0) {
            *out = named_frame.value;
            it->blocks = named_frame.prev;
            interp_restore_block_escape_state(it, &named_frame);
            dynamic_frame_dispose(&dynamic);
            return 1;
        }
    }
    frame.prev = it->blocks;
    frame.env = child;
    frame.saved_dynamic = dynamic.prev;
    frame.saved_tagbodies = it->tagbodies;
    frame.saved_catches = it->catches;
    frame.saved_handlers = it->handlers;
    frame.saved_restarts = it->restarts;
    frame.saved_condition_restart_assocs = it->condition_restart_assocs;
    frame.value = it->nil;
    it->blocks = &frame;
    jumped = setjmp(frame.buf);
    if (jumped == 0) {
        for (i = 0; i < spec->initially_forms.count; ++i) {
            if (!eval(it, child, spec->initially_forms.items[i], &ignored, err, errsz)) {
                it->blocks = frame.prev;
                interp_restore_block_escape_state(it, &frame);
                if (have_named) {
                    it->blocks = named_frame.prev;
                    interp_restore_block_escape_state(it, &named_frame);
                }
                dynamic_frame_dispose(&dynamic);
                return 0;
            }
        }
        for (;;) {
            if (spec->have_repeat) {
                if (rt.repeat_remaining <= 0) break;
                --rt.repeat_remaining;
            }
            active = 1;
            for (j = 0; active && j < spec->for_clauses.count; ++j) {
                if (!basic_loop_clause_active(&spec->for_clauses.items[j], &rt.clauses[j], &active, err, errsz)) {
                    it->blocks = frame.prev;
                    interp_restore_block_escape_state(it, &frame);
                    dynamic_frame_dispose(&dynamic);
                    return 0;
                }
            }
            if (!active) break;
            for (j = 0; j < spec->for_clauses.count; ++j) {
                if (!basic_loop_bind_clause_values(it, child, &spec->for_clauses.items[j], &rt.clauses[j], err, errsz)) {
                    it->blocks = frame.prev;
                    interp_restore_block_escape_state(it, &frame);
                    dynamic_frame_dispose(&dynamic);
                    return 0;
                }
            }
            cached_guard_form = NULL;
            cached_guard_value = NULL;
            for (i = 0; i < steps->count; ++i) {
                Value *step_value = NULL;
                Value *guard_value = NULL;
                Num step_num;
                if (steps->items[i].guard_form != NULL) {
                    if (steps->items[i].guard_form != cached_guard_form) {
                        if (!eval(it, child, steps->items[i].guard_form, &guard_value, err, errsz)) {
                            it->blocks = frame.prev;
                            interp_restore_block_escape_state(it, &frame);
                            dynamic_frame_dispose(&dynamic);
                            return 0;
                        }
                        cached_guard_form = steps->items[i].guard_form;
                        cached_guard_value = guard_value;
                    } else {
                        guard_value = cached_guard_value;
                    }
                    if (value_is_truthy(guard_value) != steps->items[i].guard_truthy) continue;
                }
                switch (steps->items[i].kind) {
                    case BASIC_LOOP_STEP_WHILE:
                        if (!eval(it, child, steps->items[i].form, &step_value, err, errsz)) {
                            it->blocks = frame.prev;
                            interp_restore_block_escape_state(it, &frame);
                            dynamic_frame_dispose(&dynamic);
                            return 0;
                        }
                        if (!value_is_truthy(step_value)) goto basic_loop_done;
                        break;
                    case BASIC_LOOP_STEP_UNTIL:
                        if (!eval(it, child, steps->items[i].form, &step_value, err, errsz)) {
                            it->blocks = frame.prev;
                            interp_restore_block_escape_state(it, &frame);
                            dynamic_frame_dispose(&dynamic);
                            return 0;
                        }
                        if (value_is_truthy(step_value)) goto basic_loop_done;
                        break;
                    case BASIC_LOOP_STEP_DO:
                        if (steps->items[i].guard_form != NULL && basic_loop_form_is_it(steps->items[i].form)) {
                            ignored = guard_value;
                        } else {
                            if (!eval(it, child, steps->items[i].form, &ignored, err, errsz)) {
                                it->blocks = frame.prev;
                                interp_restore_block_escape_state(it, &frame);
                                dynamic_frame_dispose(&dynamic);
                                return 0;
                            }
                        }
                        break;
                    case BASIC_LOOP_STEP_COLLECT:
                        if (steps->items[i].guard_form != NULL && basic_loop_form_is_it(steps->items[i].form)) {
                            step_value = guard_value;
                        } else {
                            if (!eval(it, child, steps->items[i].form, &step_value, err, errsz)) {
                                it->blocks = frame.prev;
                                interp_restore_block_escape_state(it, &frame);
                                dynamic_frame_dispose(&dynamic);
                                return 0;
                            }
                        }
                        if (steps->items[i].into_symbol != NULL) {
                            Value *cur = NULL;
                            int is_bound = 0;
                            Value *piece = make_cons_value(step_value, it->nil);
                            if (!basic_loop_lookup_local(it, child, steps->items[i].into_symbol, &cur, &is_bound) || !is_bound) cur = it->nil;
                            if (!basic_loop_append_list_piece(it, &cur, piece, 1, err, errsz)) {
                                it->blocks = frame.prev;
                                interp_restore_block_escape_state(it, &frame);
                                dynamic_frame_dispose(&dynamic);
                                return 0;
                            }
                            env_set_variable_symbol(it, child, steps->items[i].into_symbol, cur);
                        } else {
                            Value *piece = make_cons_value(step_value, it->nil);
                            if (!basic_loop_append_list_piece(it, &list_acc, piece, 1, err, errsz)) {
                                it->blocks = frame.prev;
                                interp_restore_block_escape_state(it, &frame);
                                dynamic_frame_dispose(&dynamic);
                                return 0;
                            }
                        }
                        break;
                    case BASIC_LOOP_STEP_APPEND:
                        if (steps->items[i].guard_form != NULL && basic_loop_form_is_it(steps->items[i].form)) {
                            step_value = guard_value;
                        } else {
                            if (!eval(it, child, steps->items[i].form, &step_value, err, errsz)) {
                                it->blocks = frame.prev;
                                interp_restore_block_escape_state(it, &frame);
                                dynamic_frame_dispose(&dynamic);
                                return 0;
                            }
                        }
                        if (steps->items[i].into_symbol != NULL) {
                            Value *cur = NULL;
                            int is_bound = 0;
                            if (!basic_loop_lookup_local(it, child, steps->items[i].into_symbol, &cur, &is_bound) || !is_bound) cur = it->nil;
                            if (!basic_loop_append_list_piece(it, &cur, step_value, 0, err, errsz)) {
                                it->blocks = frame.prev;
                                interp_restore_block_escape_state(it, &frame);
                                dynamic_frame_dispose(&dynamic);
                                return 0;
                            }
                            env_set_variable_symbol(it, child, steps->items[i].into_symbol, cur);
                        } else if (!basic_loop_append_list_piece(it, &list_acc, step_value, 0, err, errsz)) {
                            it->blocks = frame.prev;
                            interp_restore_block_escape_state(it, &frame);
                            dynamic_frame_dispose(&dynamic);
                            return 0;
                        }
                        break;
                    case BASIC_LOOP_STEP_NCONC:
                        if (steps->items[i].guard_form != NULL && basic_loop_form_is_it(steps->items[i].form)) {
                            step_value = guard_value;
                        } else {
                            if (!eval(it, child, steps->items[i].form, &step_value, err, errsz)) {
                                it->blocks = frame.prev;
                                interp_restore_block_escape_state(it, &frame);
                                dynamic_frame_dispose(&dynamic);
                                return 0;
                            }
                        }
                        if (steps->items[i].into_symbol != NULL) {
                            Value *cur = NULL;
                            int is_bound = 0;
                            if (!basic_loop_lookup_local(it, child, steps->items[i].into_symbol, &cur, &is_bound) || !is_bound) cur = it->nil;
                            if (!basic_loop_append_list_piece(it, &cur, step_value, 1, err, errsz)) {
                                it->blocks = frame.prev;
                                interp_restore_block_escape_state(it, &frame);
                                dynamic_frame_dispose(&dynamic);
                                return 0;
                            }
                            env_set_variable_symbol(it, child, steps->items[i].into_symbol, cur);
                        } else if (!basic_loop_append_list_piece(it, &list_acc, step_value, 1, err, errsz)) {
                            it->blocks = frame.prev;
                            interp_restore_block_escape_state(it, &frame);
                            dynamic_frame_dispose(&dynamic);
                            return 0;
                        }
                        break;
                    case BASIC_LOOP_STEP_SUM:
                        if (steps->items[i].guard_form != NULL && basic_loop_form_is_it(steps->items[i].form)) {
                            step_value = guard_value;
                            if (!num_from_value(step_value, &step_num, err, errsz)) {
                                it->blocks = frame.prev;
                                interp_restore_block_escape_state(it, &frame);
                                dynamic_frame_dispose(&dynamic);
                                return 0;
                            }
                        } else {
                            if (!eval(it, child, steps->items[i].form, &step_value, err, errsz) ||
                                !num_from_value(step_value, &step_num, err, errsz)) {
                                it->blocks = frame.prev;
                                interp_restore_block_escape_state(it, &frame);
                                dynamic_frame_dispose(&dynamic);
                                return 0;
                            }
                        }
                        if (steps->items[i].into_symbol != NULL) {
                            Value *cur = NULL;
                            Num cur_num;
                            int is_bound = 0;
                            if (!basic_loop_lookup_local(it, child, steps->items[i].into_symbol, &cur, &is_bound) || !is_bound) cur = make_int_value(bigint_new_zero());
                            if (!num_from_value(cur, &cur_num, err, errsz)) {
                                it->blocks = frame.prev;
                                interp_restore_block_escape_state(it, &frame);
                                dynamic_frame_dispose(&dynamic);
                                return 0;
                            }
                            cur_num = num_add(cur_num, step_num);
                            cur = num_to_value_checked(cur_num, err, errsz);
                            if (cur == NULL) {
                                it->blocks = frame.prev;
                                interp_restore_block_escape_state(it, &frame);
                                dynamic_frame_dispose(&dynamic);
                                return 0;
                            }
                            env_set_variable_symbol(it, child, steps->items[i].into_symbol, cur);
                        } else {
                            sum_acc = num_add(sum_acc, step_num);
                        }
                        break;
                    case BASIC_LOOP_STEP_COUNT:
                        if (steps->items[i].guard_form != NULL && basic_loop_form_is_it(steps->items[i].form)) {
                            step_value = guard_value;
                        } else {
                            if (!eval(it, child, steps->items[i].form, &step_value, err, errsz)) {
                                it->blocks = frame.prev;
                                interp_restore_block_escape_state(it, &frame);
                                dynamic_frame_dispose(&dynamic);
                                return 0;
                            }
                        }
                        if (steps->items[i].into_symbol != NULL) {
                            Value *cur = NULL;
                            Num cur_num;
                            int is_bound = 0;
                            if (!basic_loop_lookup_local(it, child, steps->items[i].into_symbol, &cur, &is_bound) || !is_bound) cur = make_int_value(bigint_new_zero());
                            if (!num_from_value(cur, &cur_num, err, errsz)) {
                                it->blocks = frame.prev;
                                interp_restore_block_escape_state(it, &frame);
                                dynamic_frame_dispose(&dynamic);
                                return 0;
                            }
                            if (value_is_truthy(step_value)) cur_num = num_add(cur_num, num_make_big(bigint_from_i64(1)));
                            cur = num_to_value_checked(cur_num, err, errsz);
                            if (cur == NULL) {
                                it->blocks = frame.prev;
                                interp_restore_block_escape_state(it, &frame);
                                dynamic_frame_dispose(&dynamic);
                                return 0;
                            }
                            env_set_variable_symbol(it, child, steps->items[i].into_symbol, cur);
                        } else if (value_is_truthy(step_value)) {
                            sum_acc = num_add(sum_acc, num_make_big(bigint_from_i64(1)));
                        }
                        break;
                    case BASIC_LOOP_STEP_MAXIMIZE:
                    case BASIC_LOOP_STEP_MINIMIZE: {
                        Value *cur = NULL;
                        Value *best = NULL;
                        Num cur_num;
                        Num best_num;
                        int cmp = 0;
                        int is_bound = 0;
                        if (steps->items[i].guard_form != NULL && basic_loop_form_is_it(steps->items[i].form)) {
                            step_value = guard_value;
                            if (!num_from_value(step_value, &cur_num, err, errsz)) {
                                it->blocks = frame.prev;
                                interp_restore_block_escape_state(it, &frame);
                                dynamic_frame_dispose(&dynamic);
                                return 0;
                            }
                        } else {
                            if (!eval(it, child, steps->items[i].form, &step_value, err, errsz) ||
                                !num_from_value(step_value, &cur_num, err, errsz)) {
                                it->blocks = frame.prev;
                                interp_restore_block_escape_state(it, &frame);
                                dynamic_frame_dispose(&dynamic);
                                return 0;
                            }
                        }
                        if (steps->items[i].into_symbol != NULL) {
                            if (!basic_loop_lookup_local(it, child, steps->items[i].into_symbol, &best, &is_bound) || !is_bound || best->type == VALUE_NIL) {
                                env_set_variable_symbol(it, child, steps->items[i].into_symbol, step_value);
                                break;
                            }
                            if (!num_from_value(best, &best_num, err, errsz) || !num_cmp(cur_num, best_num, &cmp)) {
                                it->blocks = frame.prev;
                                interp_restore_block_escape_state(it, &frame);
                                dynamic_frame_dispose(&dynamic);
                                return 0;
                            }
                            if ((steps->items[i].kind == BASIC_LOOP_STEP_MAXIMIZE && cmp > 0) ||
                                (steps->items[i].kind == BASIC_LOOP_STEP_MINIMIZE && cmp < 0)) {
                                env_set_variable_symbol(it, child, steps->items[i].into_symbol, step_value);
                            }
                        } else if (!have_anon_extreme) {
                            anon_extreme = step_value;
                            have_anon_extreme = 1;
                        } else {
                            if (!num_from_value(anon_extreme, &best_num, err, errsz) || !num_cmp(cur_num, best_num, &cmp)) {
                                it->blocks = frame.prev;
                                interp_restore_block_escape_state(it, &frame);
                                dynamic_frame_dispose(&dynamic);
                                return 0;
                            }
                            if ((steps->items[i].kind == BASIC_LOOP_STEP_MAXIMIZE && cmp > 0) ||
                                (steps->items[i].kind == BASIC_LOOP_STEP_MINIMIZE && cmp < 0)) {
                                anon_extreme = step_value;
                            }
                        }
                        break;
                    }
                    case BASIC_LOOP_STEP_FINISH:
                        goto basic_loop_done;
                    case BASIC_LOOP_STEP_RETURN:
                        if (steps->items[i].guard_form != NULL && basic_loop_form_is_it(steps->items[i].form)) {
                            *out = guard_value;
                        } else {
                            if (!eval(it, child, steps->items[i].form, out, err, errsz)) {
                                it->blocks = frame.prev;
                                interp_restore_block_escape_state(it, &frame);
                                dynamic_frame_dispose(&dynamic);
                                return 0;
                            }
                        }
                        goto basic_loop_finished;
                    case BASIC_LOOP_STEP_THEREIS:
                        if (steps->items[i].guard_form != NULL && basic_loop_form_is_it(steps->items[i].form)) {
                            step_value = guard_value;
                        } else {
                            if (!eval(it, child, steps->items[i].form, &step_value, err, errsz)) {
                                it->blocks = frame.prev;
                                interp_restore_block_escape_state(it, &frame);
                                if (have_named) {
                                    it->blocks = named_frame.prev;
                                    interp_restore_block_escape_state(it, &named_frame);
                                }
                                dynamic_frame_dispose(&dynamic);
                                return 0;
                            }
                        }
                        if (value_is_truthy(step_value)) {
                            normal_result = step_value;
                            have_result_override = 1;
                            *out = normal_result;
                            goto basic_loop_finished;
                        }
                        break;
                    case BASIC_LOOP_STEP_ALWAYS:
                        if (steps->items[i].guard_form != NULL && basic_loop_form_is_it(steps->items[i].form)) {
                            step_value = guard_value;
                        } else {
                            if (!eval(it, child, steps->items[i].form, &step_value, err, errsz)) {
                                it->blocks = frame.prev;
                                interp_restore_block_escape_state(it, &frame);
                                if (have_named) {
                                    it->blocks = named_frame.prev;
                                    interp_restore_block_escape_state(it, &named_frame);
                                }
                                dynamic_frame_dispose(&dynamic);
                                return 0;
                            }
                        }
                        if (!value_is_truthy(step_value)) {
                            normal_result = it->nil;
                            have_result_override = 1;
                            *out = normal_result;
                            goto basic_loop_finished;
                        }
                        break;
                    case BASIC_LOOP_STEP_NEVER:
                        if (steps->items[i].guard_form != NULL && basic_loop_form_is_it(steps->items[i].form)) {
                            step_value = guard_value;
                        } else {
                            if (!eval(it, child, steps->items[i].form, &step_value, err, errsz)) {
                                it->blocks = frame.prev;
                                interp_restore_block_escape_state(it, &frame);
                                if (have_named) {
                                    it->blocks = named_frame.prev;
                                    interp_restore_block_escape_state(it, &named_frame);
                                }
                                dynamic_frame_dispose(&dynamic);
                                return 0;
                            }
                        }
                        if (value_is_truthy(step_value)) {
                            normal_result = it->nil;
                            have_result_override = 1;
                            *out = normal_result;
                            goto basic_loop_finished;
                        }
                        break;
                    default:
                        break;
                }
            }
            for (j = 0; j < spec->for_clauses.count; ++j) {
                if (!basic_loop_advance_clause(it, child, &spec->for_clauses.items[j], &rt.clauses[j], err, errsz) ||
                    !basic_loop_bind_clause_values(it, child, &spec->for_clauses.items[j], &rt.clauses[j], err, errsz)) {
                    it->blocks = frame.prev;
                    interp_restore_block_escape_state(it, &frame);
                    if (have_named) {
                        it->blocks = named_frame.prev;
                        interp_restore_block_escape_state(it, &named_frame);
                    }
                    dynamic_frame_dispose(&dynamic);
                    return 0;
                }
            }
        }
basic_loop_done:
        if (saw_predicate_termination && !have_result_override) {
            normal_result = (predicate_kind == BASIC_LOOP_STEP_THEREIS) ? it->nil : it->true_value;
            have_result_override = 1;
        }
        if (have_result_override) {
            *out = normal_result;
        } else if (!accumulation_mask) {
            *out = it->nil;
        } else {
            ValueArray accum_results;
            value_array_init(&accum_results);
            if (accumulation_mask & (1 << 1)) {
                if (list_acc != NULL) value_array_push(&accum_results, list_acc);
            }
            if (accumulation_mask & (1 << 2)) {
                Value *v = num_to_value_checked(sum_acc, err, errsz);
                if (v == NULL) {
                    value_array_dispose(&accum_results);
                    it->blocks = frame.prev;
                    interp_restore_block_escape_state(it, &frame);
                    dynamic_frame_dispose(&dynamic);
                    return 0;
                }
                value_array_push(&accum_results, v);
            }
            if (accumulation_mask & (1 << 3)) {
                value_array_push(&accum_results, (have_anon_extreme ? anon_extreme : it->nil));
            }
            if (accum_results.count > 0) {
                *out = accum_results.items[0];
                interp_set_values(it, &accum_results);
            } else {
                *out = it->nil;
            }
            value_array_dispose(&accum_results);
        }
        for (i = 0; i < spec->finally_forms.count; ++i) {
            if (!eval(it, child, spec->finally_forms.items[i], &ignored, err, errsz)) {
                it->blocks = frame.prev;
                interp_restore_block_escape_state(it, &frame);
                if (have_named) {
                    it->blocks = named_frame.prev;
                    interp_restore_block_escape_state(it, &named_frame);
                }
                dynamic_frame_dispose(&dynamic);
                return 0;
            }
        }
        if (spec->finally_return_form != NULL) {
            if (!eval(it, child, spec->finally_return_form, out, err, errsz)) {
                it->blocks = frame.prev;
                interp_restore_block_escape_state(it, &frame);
                if (have_named) {
                    it->blocks = named_frame.prev;
                    interp_restore_block_escape_state(it, &named_frame);
                }
                dynamic_frame_dispose(&dynamic);
                return 0;
            }
        }
    } else {
        *out = frame.value;
    }
basic_loop_finished:
    it->blocks = frame.prev;
    interp_restore_block_escape_state(it, &frame);
    if (have_named) {
        it->blocks = named_frame.prev;
        interp_restore_block_escape_state(it, &named_frame);
    }
    dynamic_frame_dispose(&dynamic);
    return 1;
}

static int special_loop(Interp *it, Env *env, Value *form, Value **out, char *err, size_t errsz) {
    BasicLoopSpec spec;
    BasicLoopStepArray steps;
    const char *marker = NULL;
    int anonymous_accumulation_mask = 0;
    int saw_any_accumulation = 0;
    int saw_predicate_termination = 0;
    int idx = 1;
    basic_loop_spec_init(&spec);
    basic_loop_step_array_init(&steps);
    if (form->as.array.count <= 1) {
        return execute_basic_loop(it, env, &spec, &steps, out, err, errsz);
    }
    if (!symbol_name(form->as.array.items[idx], &marker) || !basic_loop_is_top_level_clause_name(marker)) {
        while (idx < form->as.array.count) {
            basic_loop_step_array_push(&steps,
                                       basic_loop_form_is_loop_finish(form->as.array.items[idx]) ? BASIC_LOOP_STEP_FINISH : BASIC_LOOP_STEP_DO,
                                       form->as.array.items[idx]);
            ++idx;
        }
        return execute_basic_loop(it, env, &spec, &steps, out, err, errsz);
    }
    while (idx < form->as.array.count) {
        if (!symbol_name(form->as.array.items[idx], &marker)) {
            /* Handle raw forms that are conditional clauses (when/unless/if)
               appearing inside do bodies in method bodies */
            {
                ValueArray hdr; const char *hdr_name = NULL;
                value_array_init(&hdr);
                if ((form->as.array.items[idx]->type == VALUE_CONS || form->as.array.items[idx]->type == VALUE_LIST) &&
                    proper_form_to_array(form->as.array.items[idx], &hdr) && hdr.count > 0 &&
                    symbol_name(hdr.items[0], &hdr_name) &&
                    basic_loop_is_conditional_marker_name(hdr_name)) {
                    value_array_dispose(&hdr);
                    if (!basic_loop_parse_conditional_clause(form, &idx, &steps, NULL, 1,
                                                              &anonymous_accumulation_mask,
                                                              &saw_any_accumulation,
                                                              &saw_predicate_termination,
                                                              err, errsz)) return 0;
                    continue;
                }
                value_array_dispose(&hdr);
            }
            snprintf(err, errsz, "loop expected a clause keyword, got a raw form");
            return 0;
        }
        if (!basic_loop_is_top_level_clause_name(marker)) {
            snprintf(err, errsz, "loop clause '%s' is not recognized in the current ANSI subset", marker);
            return 0;
        }
        if (!basic_loop_is_supported_clause_name(marker)) {
            snprintf(err, errsz, "loop clause '%s' is ANSI but not implemented yet", marker);
            return 0;
        }
        if (str_ieq(marker, "named")) {
            Value *name = NULL;
            ++idx;
            if (spec.named_block_name != NULL) {
                snprintf(err, errsz, "loop currently supports only one named clause");
                return 0;
            }
            if (idx >= form->as.array.count) {
                snprintf(err, errsz, "loop named expects a symbol");
                return 0;
            }
            name = form->as.array.items[idx];
            if (name->type != VALUE_SYMBOL) {
                snprintf(err, errsz, "loop named expects a symbol");
                return 0;
            }
            if (!reject_constant_binding_target(name, "loop name", err, errsz)) return 0;
            spec.named_block_name = name;
            ++idx;
            continue;
        }
        if (str_ieq(marker, "with")) {
            if (steps.count > 0) {
                snprintf(err, errsz, "loop with must appear before main clauses");
                return 0;
            }
            if (!basic_loop_parse_with_clause(it, form, &idx, &spec, err, errsz)) return 0;
            continue;
        }
        if (str_ieq(marker, "for") || str_ieq(marker, "as")) {
            if (steps.count > 0) {
                snprintf(err, errsz, "loop for/as must appear before termination and action clauses");
                return 0;
            }
            if (!basic_loop_parse_for_clause(form, &idx, &spec, err, errsz)) return 0;
            continue;
        }
        if (str_ieq(marker, "initially") || str_ieq(marker, "finally")) {
            ValueArray *target = str_ieq(marker, "initially") ? &spec.initially_forms : &spec.finally_forms;
            const char *submarker = NULL;
            ++idx;
            if (idx >= form->as.array.count) {
                snprintf(err, errsz, "loop %s expects at least one form", marker);
                return 0;
            }
            if (str_ieq(marker, "finally") &&
                symbol_name(form->as.array.items[idx], &submarker) &&
                str_ieq(submarker, "return")) {
                ++idx;
                if (idx >= form->as.array.count) {
                    snprintf(err, errsz, "loop finally return expects a form");
                    return 0;
                }
                spec.finally_return_form = form->as.array.items[idx];
                ++idx;
                continue;
            }
            while (idx < form->as.array.count) {
                const char *next_clause = NULL;
                if (symbol_name(form->as.array.items[idx], &next_clause) && basic_loop_is_top_level_clause_name(next_clause)) break;
                value_array_push(target, form->as.array.items[idx]);
                ++idx;
            }
            if (target->count <= 0) {
                snprintf(err, errsz, "loop %s expects at least one form", marker);
                return 0;
            }
            continue;
        }
        if (str_ieq(marker, "repeat")) {
            ++idx;
            if (idx >= form->as.array.count) {
                snprintf(err, errsz, "loop repeat expects a count form");
                return 0;
            }
            spec.have_repeat = 1;
            spec.repeat_form = form->as.array.items[idx];
            ++idx;
            continue;
        }
        if (str_ieq(marker, "while") || str_ieq(marker, "until")) {
            BasicLoopStepKind test_kind = str_ieq(marker, "while") ? BASIC_LOOP_STEP_WHILE : BASIC_LOOP_STEP_UNTIL;
            ++idx;
            if (idx >= form->as.array.count) {
                snprintf(err, errsz, "loop %s expects a test form", marker);
                return 0;
            }
            basic_loop_step_array_push(&steps, test_kind, form->as.array.items[idx]);
            ++idx;
            continue;
        }
        if (basic_loop_is_conditional_marker_name(marker)) {
            if (!basic_loop_parse_conditional_clause(form,
                                                     &idx,
                                                     &steps,
                                                     NULL,
                                                     1,
                                                     &anonymous_accumulation_mask,
                                                     &saw_any_accumulation,
                                                     &saw_predicate_termination,
                                                     err,
                                                     errsz)) return 0;
            continue;
        }
        if (str_ieq(marker, "thereis") || str_ieq(marker, "always") || str_ieq(marker, "never")) {
            BasicLoopStepKind test_kind = BASIC_LOOP_STEP_THEREIS;
            if (str_ieq(marker, "always")) test_kind = BASIC_LOOP_STEP_ALWAYS;
            else if (str_ieq(marker, "never")) test_kind = BASIC_LOOP_STEP_NEVER;
            ++idx;
            if (idx >= form->as.array.count) {
                snprintf(err, errsz, "loop %s expects a test form", marker);
                return 0;
            }
            if (saw_predicate_termination) {
                snprintf(err, errsz, "loop currently supports only one thereis/always/never clause");
                return 0;
            }
            if (!basic_loop_register_step_constraints(test_kind,
                                                      NULL,
                                                       &anonymous_accumulation_mask,
                                                      &saw_any_accumulation,
                                                      &saw_predicate_termination,
                                                      err,
                                                      errsz)) return 0;
            basic_loop_step_array_push(&steps, test_kind, form->as.array.items[idx]);
            ++idx;
            continue;
        }
        if (str_ieq(marker, "do") || str_ieq(marker, "doing")) {
            ++idx;
            if (idx >= form->as.array.count) {
                snprintf(err, errsz, "loop do expects at least one body form");
                return 0;
            }
            while (idx < form->as.array.count) {
                const char *next_clause = NULL;
                if (symbol_name(form->as.array.items[idx], &next_clause) && basic_loop_is_top_level_clause_name(next_clause)) break;
                /* Also handle conditional clauses (when/unless/if) inside do body.
                   Process them inline by extracting the test and body from the nested form. */
                {
                    ValueArray hdr; const char *hdr_name = NULL;
                    value_array_init(&hdr);
                    if ((form->as.array.items[idx]->type == VALUE_CONS || form->as.array.items[idx]->type == VALUE_LIST) &&
                        proper_form_to_array(form->as.array.items[idx], &hdr) && hdr.count > 1 &&
                        symbol_name(hdr.items[0], &hdr_name) &&
                        basic_loop_is_conditional_marker_name(hdr_name)) {
                        Value *test_form = hdr.items[1];
                        Value *effective_test = basic_loop_make_conditional_guard_form(hdr_name, test_form);
                        int bi;
                        for (bi = 2; bi < hdr.count; bi++) {
                            basic_loop_step_array_push_guarded_into(&steps, BASIC_LOOP_STEP_DO,
                                                                     hdr.items[bi], NULL,
                                                                     effective_test, 1);
                        }
                        value_array_dispose(&hdr);
                        ++idx;
                        continue;
                    }
                    value_array_dispose(&hdr);
                }
                basic_loop_step_array_push(&steps,
                                           basic_loop_form_is_loop_finish(form->as.array.items[idx]) ? BASIC_LOOP_STEP_FINISH : BASIC_LOOP_STEP_DO,
                                           form->as.array.items[idx]);
                ++idx;
            }
            continue;
        }
        if (str_ieq(marker, "return")) {
            ++idx;
            if (idx >= form->as.array.count) {
                snprintf(err, errsz, "loop return expects a form");
                return 0;
            }
            basic_loop_step_array_push(&steps, BASIC_LOOP_STEP_RETURN, form->as.array.items[idx]);
            ++idx;
            continue;
        }
        {
            BasicLoopStepKind step_kind = BASIC_LOOP_STEP_COLLECT;
            Value *into_symbol = NULL;
            Value *acc_form = NULL;
            const char *clause_name = marker;
            if (str_ieq(marker, "append") || str_ieq(marker, "appending")) step_kind = BASIC_LOOP_STEP_APPEND;
            else if (str_ieq(marker, "nconc") || str_ieq(marker, "nconcing")) step_kind = BASIC_LOOP_STEP_NCONC;
            else if (str_ieq(marker, "sum") || str_ieq(marker, "summing")) step_kind = BASIC_LOOP_STEP_SUM;
            else if (str_ieq(marker, "count") || str_ieq(marker, "counting")) step_kind = BASIC_LOOP_STEP_COUNT;
            else if (str_ieq(marker, "maximize") || str_ieq(marker, "maximizing")) step_kind = BASIC_LOOP_STEP_MAXIMIZE;
            else if (str_ieq(marker, "minimize") || str_ieq(marker, "minimizing")) step_kind = BASIC_LOOP_STEP_MINIMIZE;
            ++idx;
            if (idx >= form->as.array.count) {
                snprintf(err, errsz, "loop %s expects a form", marker);
                return 0;
            }
            acc_form = form->as.array.items[idx];
            ++idx;
            if (idx < form->as.array.count && symbol_name(form->as.array.items[idx], &marker) && str_ieq(marker, "into")) {
                ++idx;
                if (idx >= form->as.array.count || !symbol_name(form->as.array.items[idx], &marker)) {
                    snprintf(err, errsz, "loop into expects a variable name");
                    return 0;
                }
                if (!reject_constant_binding_target(form->as.array.items[idx], "loop into variable", err, errsz)) return 0;
                into_symbol = form->as.array.items[idx];
                ++idx;
            }
            if (!basic_loop_consume_optional_accumulation_type_spec(form, &idx, step_kind, clause_name, err, errsz)) return 0;
            if (!basic_loop_register_step_constraints(step_kind,
                                                       into_symbol,
                                                       &anonymous_accumulation_mask,
                                                       &saw_any_accumulation,
                                                      &saw_predicate_termination,
                                                      err,
                                                      errsz)) return 0;
            basic_loop_step_array_push_into(&steps, step_kind, acc_form, into_symbol);
        }
    }
    if (steps.count == 0 && spec.for_clauses.count == 0 && !spec.have_repeat) {
        snprintf(err, errsz, "loop expects clauses or body forms");
        return 0;
    }
    return execute_basic_loop(it, env, &spec, &steps, out, err, errsz);
}

static int special_dotimes(Interp *it, Env *env, Value *form, Value **out, char *err, size_t errsz) {
    Value *spec = NULL;
    Value *count_value = NULL;
    Value *result_form = NULL;
    Value *ignored = it->nil;
    const char *name = NULL;
    Value *symbol = NULL;
    int count = 0;
    int i = 0;
    int body_start = 0;
    Env *child = NULL;
    DynamicFrame dynamic;
    BlockFrame frame;
    int jumped = 0;
    if (form->as.array.count < 2) {
        snprintf(err, errsz, "dotimes expects a binding spec");
        return 0;
    }
    spec = form->as.array.items[1];
    /* Normalize CONS cells to VALUE_LIST so we can use as.array access */
    if (spec->type == VALUE_CONS) {
        ValueArray na; char na_err[64];
        value_array_init(&na);
        if (sequence_to_array(spec, &na, na_err, sizeof(na_err))) {
            spec = make_list_value(&na);
            value_array_dispose(&na);
        }
    }
    if (spec->type != VALUE_LIST && spec->type != VALUE_VECTOR) {
        snprintf(err, errsz, "dotimes binding spec must be a list");
        return 0;
    }
    if (spec->as.array.count < 2 || spec->as.array.count > 3) {
        snprintf(err, errsz, "dotimes binding spec expects var, count-form, and optional result-form");
        return 0;
    }
    if (!reject_constant_binding_target(spec->as.array.items[0], "dotimes", err, errsz)) return 0;
    if (!symbol_name(spec->as.array.items[0], &name)) {
        snprintf(err, errsz, "dotimes variable must be a symbol");
        return 0;
    }
    symbol = spec->as.array.items[0];
    if (!eval(it, env, spec->as.array.items[1], &count_value, err, errsz)) return 0;
    if (!value_to_loop_count(it, count_value, "dotimes", &count, err, errsz)) return 0;
    if (count < 0) count = 0;
    result_form = (spec->as.array.count == 3) ? spec->as.array.items[2] : NULL;
    child = env_new(env);
    child->active_model = env->active_model;
    child->block_name = it->nil;
    if (!process_declare_forms_in_form(child, form, 2, &body_start, err, errsz)) return 0;
    dynamic_frame_init(&dynamic, it->dynamic);
    it->dynamic = &dynamic;
    bind_local_variable_symbol(it, child, &dynamic, symbol, make_int_value(bigint_from_i64(0)));
    frame.prev = it->blocks;
    frame.env = child;
    frame.saved_dynamic = dynamic.prev;
    frame.saved_tagbodies = it->tagbodies;
    frame.saved_catches = it->catches;
    frame.saved_handlers = it->handlers;
    frame.saved_restarts = it->restarts;
    frame.saved_condition_restart_assocs = it->condition_restart_assocs;
    frame.value = it->nil;
    it->blocks = &frame;
    jumped = setjmp(frame.buf);
    if (jumped == 0) {
        for (i = 0; i < count; ++i) {
            env_set_variable_symbol(it, child, symbol, make_int_value(bigint_from_i64(i)));
            if (body_start < form->as.array.count && !execute_tagbody_body(it, child, form, body_start, &ignored, err, errsz)) {
                it->blocks = frame.prev;
                interp_restore_block_escape_state(it, &frame);
                dynamic_frame_dispose(&dynamic);
                return 0;
            }
        }
        env_set_variable_symbol(it, child, symbol, make_int_value(bigint_from_i64(count)));
        if (result_form != NULL) {
            if (!eval(it, child, result_form, out, err, errsz)) {
                it->blocks = frame.prev;
                interp_restore_block_escape_state(it, &frame);
                dynamic_frame_dispose(&dynamic);
                return 0;
            }
        } else {
            *out = it->nil;
        }
    } else {
        *out = frame.value;
    }
    it->blocks = frame.prev;
    interp_restore_block_escape_state(it, &frame);
    dynamic_frame_dispose(&dynamic);
    return 1;
}

static int special_dolist(Interp *it, Env *env, Value *form, Value **out, char *err, size_t errsz) {
    Value *spec = NULL;
    Value *list_value = NULL;
    Value *result_form = NULL;
    Value *ignored = it->nil;
    ValueArray items;
    const char *name = NULL;
    Value *symbol = NULL;
    int i;
    int body_start = 0;
    Env *child = NULL;
    DynamicFrame dynamic;
    BlockFrame frame;
    int jumped = 0;
    if (form->as.array.count < 2) {
        snprintf(err, errsz, "dolist expects a binding spec");
        return 0;
    }
    spec = form->as.array.items[1];
    /* Normalize CONS cells to VALUE_LIST so we can use as.array access */
    if (spec->type == VALUE_CONS) {
        ValueArray na; char na_err[64];
        value_array_init(&na);
        if (sequence_to_array(spec, &na, na_err, sizeof(na_err))) {
            spec = make_list_value(&na);
            value_array_dispose(&na);
        }
    }
    if (spec->type != VALUE_LIST && spec->type != VALUE_VECTOR) {
        snprintf(err, errsz, "dolist binding spec must be a list");
        return 0;
    }
    if (spec->as.array.count < 2 || spec->as.array.count > 3) {
        snprintf(err, errsz, "dolist binding spec expects var, list-form, and optional result-form");
        return 0;
    }
    if (!reject_constant_binding_target(spec->as.array.items[0], "dolist", err, errsz)) return 0;
    if (!symbol_name(spec->as.array.items[0], &name)) {
        snprintf(err, errsz, "dolist variable must be a symbol");
        return 0;
    }
    symbol = spec->as.array.items[0];
    if (!eval(it, env, spec->as.array.items[1], &list_value, err, errsz)) return 0;
    /* Convert vectors to lists for safe iteration (BUG-024 fix) */
    if (list_value != NULL && list_value->type == VALUE_VECTOR) {
        ValueArray va; char va_err[64];
        value_array_init(&va);
        if (sequence_to_array(list_value, &va, va_err, sizeof(va_err))) {
            list_value = make_list_value(&va);
            value_array_dispose(&va);
        }
    }
    if (!value_is_list_like(list_value) || !sequence_to_array(list_value, &items, err, errsz)) {
        snprintf(err, errsz, "dolist expects list-form to evaluate to a proper list");
        return 0;
    }
    result_form = (spec->as.array.count == 3) ? spec->as.array.items[2] : NULL;
    child = env_new(env);
    child->active_model = env->active_model;
    child->block_name = it->nil;
    if (!process_declare_forms_in_form(child, form, 2, &body_start, err, errsz)) return 0;
    dynamic_frame_init(&dynamic, it->dynamic);
    it->dynamic = &dynamic;
    bind_local_variable_symbol(it, child, &dynamic, symbol, it->nil);
    frame.prev = it->blocks;
    frame.env = child;
    frame.saved_dynamic = dynamic.prev;
    frame.saved_tagbodies = it->tagbodies;
    frame.saved_catches = it->catches;
    frame.saved_handlers = it->handlers;
    frame.saved_restarts = it->restarts;
    frame.saved_condition_restart_assocs = it->condition_restart_assocs;
    frame.value = it->nil;
    it->blocks = &frame;
    jumped = setjmp(frame.buf);
    if (jumped == 0) {
        for (i = 0; i < items.count; ++i) {
            env_set_variable_symbol(it, child, symbol, items.items[i]);
            if (body_start < form->as.array.count && !execute_tagbody_body(it, child, form, body_start, &ignored, err, errsz)) {
                it->blocks = frame.prev;
                interp_restore_block_escape_state(it, &frame);
                dynamic_frame_dispose(&dynamic);
                return 0;
            }
        }
        env_set_variable_symbol(it, child, symbol, it->nil);
        if (result_form != NULL) {
            if (!eval(it, child, result_form, out, err, errsz)) {
                it->blocks = frame.prev;
                interp_restore_block_escape_state(it, &frame);
                dynamic_frame_dispose(&dynamic);
                return 0;
            }
        } else {
            *out = it->nil;
        }
    } else {
        *out = frame.value;
    }
    it->blocks = frame.prev;
    interp_restore_block_escape_state(it, &frame);
    dynamic_frame_dispose(&dynamic);
    return 1;
}

static Value *current_package_runtime(Interp *it, Env *env);

static int special_do_package_symbols(Interp *it,
                                      Env *env,
                                      Value *form,
                                      const char *who,
                                      int default_current_package,
                                      int include_internal,
                                      int include_external,
                                      int include_inherited,
                                      Value **out,
                                      char *err,
                                      size_t errsz) {
    Value *spec = NULL;
    Value *result_form = NULL;
    Value *ignored = it->nil;
    Value *pkg = NULL;
    Value *pkg_form_value = NULL;
    ValueArray items;
    ValueArray symbols;
    const char *name = NULL;
    Value *symbol = NULL;
    int i;
    int j;
    int body_start = 0;
    Env *child = NULL;
    DynamicFrame dynamic;
    BlockFrame frame;
    int jumped = 0;
    if (form->as.array.count < 2) {
        snprintf(err, errsz, "%s expects a binding spec", who);
        return 0;
    }
    spec = form->as.array.items[1];
    /* Normalize CONS cells to VALUE_LIST for defmethod body support */
    if (spec->type == VALUE_CONS) {
        ValueArray na; char na_err_spec[64];
        value_array_init(&na);
        if (sequence_to_array(spec, &na, na_err_spec, sizeof(na_err_spec))) {
            spec = make_list_value(&na);
            value_array_dispose(&na);
        }
    }
    if (spec->type != VALUE_LIST && spec->type != VALUE_VECTOR) {
        snprintf(err, errsz, "%s binding spec must be a list", who);
        return 0;
    }
    if (default_current_package) {
        if (spec->as.array.count < 1 || spec->as.array.count > 3) {
            snprintf(err, errsz, "%s binding spec expects var, optional package-form, and optional result-form", who);
            return 0;
        }
    } else if (spec->as.array.count < 1 || spec->as.array.count > 2) {
        snprintf(err, errsz, "%s binding spec expects var and optional result-form", who);
        return 0;
    }
    if (!reject_constant_binding_target(spec->as.array.items[0], who, err, errsz)) return 0;
    if (!symbol_name(spec->as.array.items[0], &name)) {
        snprintf(err, errsz, "%s variable must be a symbol", who);
        return 0;
    }
    symbol = spec->as.array.items[0];
    value_array_init(&symbols);
    if (default_current_package) {
        if (spec->as.array.count >= 2) {
            if (!eval(it, env, spec->as.array.items[1], &pkg_form_value, err, errsz)) return 0;
            if (!resolve_package_designator(it, env, pkg_form_value, who, &pkg, err, errsz)) return 0;
        } else {
            pkg = current_package_runtime(it, env);
        }
        if (!collect_symbols_in_package(pkg,
                                        include_internal,
                                        include_external,
                                        include_inherited,
                                        &items,
                                        err,
                                        errsz)) {
            return 0;
        }
        for (j = 0; j < items.count; ++j) value_array_push(&symbols, items.items[j]);
        result_form = (spec->as.array.count == 3) ? spec->as.array.items[2] : NULL;
    } else {
        for (i = 0; i < it->packages.count; ++i) {
            pkg = it->packages.items[i];
            if (!package_is_live(pkg)) continue;
            if (!collect_symbols_in_package(pkg,
                                            include_internal,
                                            include_external,
                                            include_inherited,
                                            &items,
                                            err,
                                            errsz)) {
                return 0;
            }
            for (j = 0; j < items.count; ++j) value_array_push(&symbols, items.items[j]);
        }
        result_form = (spec->as.array.count == 2) ? spec->as.array.items[1] : NULL;
    }
    child = env_new(env);
    child->active_model = env->active_model;
    child->block_name = it->nil;
    if (!process_declare_forms_in_form(child, form, 2, &body_start, err, errsz)) return 0;
    dynamic_frame_init(&dynamic, it->dynamic);
    it->dynamic = &dynamic;
    bind_local_variable_symbol(it, child, &dynamic, symbol, it->nil);
    frame.prev = it->blocks;
    frame.env = child;
    frame.saved_dynamic = dynamic.prev;
    frame.saved_tagbodies = it->tagbodies;
    frame.saved_catches = it->catches;
    frame.saved_handlers = it->handlers;
    frame.saved_restarts = it->restarts;
    frame.saved_condition_restart_assocs = it->condition_restart_assocs;
    frame.value = it->nil;
    it->blocks = &frame;
    jumped = setjmp(frame.buf);
    if (jumped == 0) {
        for (i = 0; i < symbols.count; ++i) {
            env_set_variable_symbol(it, child, symbol, symbols.items[i]);
            if (body_start < form->as.array.count && !execute_tagbody_body(it, child, form, body_start, &ignored, err, errsz)) {
                it->blocks = frame.prev;
                interp_restore_block_escape_state(it, &frame);
                dynamic_frame_dispose(&dynamic);
                return 0;
            }
        }
        env_set_variable_symbol(it, child, symbol, it->nil);
        if (result_form != NULL) {
            if (!eval(it, child, result_form, out, err, errsz)) {
                it->blocks = frame.prev;
                interp_restore_block_escape_state(it, &frame);
                dynamic_frame_dispose(&dynamic);
                return 0;
            }
        } else {
            *out = it->nil;
        }
    } else {
        *out = frame.value;
    }
    it->blocks = frame.prev;
    interp_restore_block_escape_state(it, &frame);
    dynamic_frame_dispose(&dynamic);
    return 1;
}

static int special_do_symbols(Interp *it, Env *env, Value *form, Value **out, char *err, size_t errsz) {
    return special_do_package_symbols(it, env, form, "do-symbols", 1, 1, 1, 1, out, err, errsz);
}

static int special_do_external_symbols(Interp *it, Env *env, Value *form, Value **out, char *err, size_t errsz) {
    return special_do_package_symbols(it, env, form, "do-external-symbols", 1, 0, 1, 0, out, err, errsz);
}

static int special_do_all_symbols(Interp *it, Env *env, Value *form, Value **out, char *err, size_t errsz) {
    return special_do_package_symbols(it, env, form, "do-all-symbols", 0, 1, 1, 1, out, err, errsz);
}

static int special_and_or(Interp *it, Env *env, Value *form, int want_or, Value **out, char *err, size_t errsz) {
    int i;
    Value *last = want_or ? it->nil : it->true_value;
    for (i = 1; i < form->as.array.count; ++i) {
        if (!eval(it, env, form->as.array.items[i], &last, err, errsz)) return 0;
        if (want_or) {
            if (value_is_truthy(last)) {
                *out = last;
                return 1;
            }
        } else if (!value_is_truthy(last)) {
            *out = last;
            return 1;
        }
    }
    *out = last;
    return 1;
}

static int split_body_docstring(Value *body, Value **clean_body_out, Value **doc_out, char *err, size_t errsz) {
    ValueArray items;
    ValueArray cleaned;
    int doc_index = -1;
    int i = 0;
    if (!proper_form_to_array(body, &items)) {
        snprintf(err, errsz, "function body must be a proper list");
        return 0;
    }
    while (i < items.count && form_head_symbol_named(items.items[i], "declare")) ++i;
    if (i < items.count && items.items[i]->type == VALUE_STRING) doc_index = i;
    value_array_init(&cleaned);
    for (i = 0; i < items.count; ++i) {
        if (i == doc_index) continue;
        value_array_push(&cleaned, items.items[i]);
    }
    if (doc_out != NULL) *doc_out = (doc_index >= 0) ? items.items[doc_index] : NULL;
    *clean_body_out = make_list_value(&cleaned);
    return 1;
}

static int make_user_closure_value(Value *params,
                                   Value *body,
                                   Env *env,
                                   int is_macro,
                                   Value **out,
                                   Value **doc_out,
                                   char *err,
                                   size_t errsz) {
    Value *clean_body = NULL;
    Value *doc = NULL;
    Value *closure = NULL;
    if (!split_body_docstring(body, &clean_body, &doc, err, errsz)) return 0;
    closure = make_closure_value(params, clean_body, env, is_macro);
    closure->as.closure.documentation = doc;
    if (doc_out != NULL) *doc_out = doc;
    *out = closure;
    return 1;
}

static int special_fn_like(Interp *it, Env *env, Value *form, int is_macro, Value **out, char *err, size_t errsz) {
    ValueArray items;
    ValueArray params;
    ValueArray body;
    int i;
    if (!proper_form_to_array(form, &items) || items.count < 3) {
        snprintf(err, errsz, "lambda expects params and body");
        return 0;
    }
    if (!proper_form_to_array(items.items[1], &params)) {
        snprintf(err, errsz, "function params must be a list");
        return 0;
    }
    value_array_init(&body);
    for (i = 2; i < items.count; ++i) value_array_push(&body, items.items[i]);
    if (!make_user_closure_value(make_list_value(&params), make_list_value(&body), env, is_macro, out, NULL, err, errsz)) {
        return 0;
    }
    interp_set_single_value(it, *out);
    return 1;
}

static char *concat_three_texts(const char *a, const char *b, const char *c) {
    size_t len_a = (a != NULL) ? strlen(a) : 0U;
    size_t len_b = (b != NULL) ? strlen(b) : 0U;
    size_t len_c = (c != NULL) ? strlen(c) : 0U;
    char *out = (char *)xmalloc(len_a + len_b + len_c + 1U);
    size_t at = 0U;
    if (a != NULL) {
        memcpy(out + at, a, len_a);
        at += len_a;
    }
    if (b != NULL) {
        memcpy(out + at, b, len_b);
        at += len_b;
    }
    if (c != NULL) {
        memcpy(out + at, c, len_c);
        at += len_c;
    }
    out[at] = '\0';
    return out;
}

static int defstruct_intern_generated_symbol(Interp *it,
                                             Value *package,
                                             const char *name,
                                             Value **out,
                                             char *err,
                                             size_t errsz) {
    Value *symbol = NULL;
    int status = 0;
    if (package == NULL || package->type != VALUE_PACKAGE) {
        snprintf(err, errsz, "defstruct internal package error");
        return 0;
    }
    if (!package_intern_name(it, package, name, &symbol, &status, err, errsz)) return 0;
    *out = symbol;
    return 1;
}

typedef struct DefstructOptions {
    int constructor_seen;
    int predicate_seen;
    int copier_seen;
    int conc_name_seen;
    int type_seen;
    int named_seen;
    int initial_offset_seen;
    int representation_kind;
    int printer_seen;
    int printer_kind;
    int namedp;
    int initial_offset;
    Value *representation_type_spec;
    Value *printer;
    Value *predicate_symbol;
    Value *copier_symbol;
    Value *standard_constructor_symbol;
    ValueArray constructor_specs;
    char *conc_name_prefix;
} DefstructOptions;

typedef struct DefstructParsedSlotSpec {
    Value *slot_name;
    Value *initform;
    Value *type_spec;
    int has_initform;
    int has_read_only;
    int read_only;
    int has_type;
} DefstructParsedSlotSpec;

static void defstruct_options_init(DefstructOptions *opts) {
    memset(opts, 0, sizeof(*opts));
    opts->printer_kind = STRUCT_PRINT_UNSPECIFIED;
    value_array_init(&opts->constructor_specs);
}

static void defstruct_options_dispose(DefstructOptions *opts) {
    if (opts == NULL) return;
    value_array_dispose(&opts->constructor_specs);
    free(opts->conc_name_prefix);
    opts->conc_name_prefix = NULL;
}

static void defstruct_parsed_slot_spec_init(DefstructParsedSlotSpec *spec) {
    memset(spec, 0, sizeof(*spec));
}

static int defstruct_option_to_array(Value *spec,
                                     ValueArray *items,
                                     char *err,
                                     size_t errsz) {
    if (spec->type == VALUE_SYMBOL) {
        value_array_init(items);
        value_array_push(items, spec);
        return 1;
    }
    if (!proper_form_to_array(spec, items) || items->count < 1) {
        snprintf(err, errsz, "defstruct options must be keywords or keyword option lists");
        return 0;
    }
    if (items->items[0]->type != VALUE_SYMBOL || !value_is_keyword(items->items[0])) {
        snprintf(err, errsz, "defstruct options must start with a keyword");
        return 0;
    }
    return 1;
}

static int defstruct_parse_slot_spec(Interp *it,
                                     Value *spec,
                                     DefstructParsedSlotSpec *parsed,
                                     char *err,
                                     size_t errsz) {
    ValueArray items;
    int i;
    (void)it;
    defstruct_parsed_slot_spec_init(parsed);
    if (spec->type == VALUE_SYMBOL) {
        parsed->slot_name = spec;
        return 1;
    }
    if (!proper_form_to_array(spec, &items) || items.count < 1) {
        snprintf(err, errsz, "defstruct slot spec must be a symbol or (name [initform] option*)");
        return 0;
    }
    if (items.items[0]->type != VALUE_SYMBOL) {
        snprintf(err, errsz, "defstruct slot name must be a symbol");
        return 0;
    }
    parsed->slot_name = items.items[0];
    parsed->initform = (items.count >= 2) ? items.items[1] : NULL;
    parsed->has_initform = (items.count >= 2);
    if (items.count <= 2) return 1;
    if (((items.count - 2) % 2) != 0) {
        snprintf(err, errsz, "defstruct slot options must be keyword/value pairs");
        return 0;
    }
    for (i = 2; i + 1 < items.count; i += 2) {
        Value *key = items.items[i];
        Value *value = items.items[i + 1];
        if (!value_is_keyword(key)) {
            snprintf(err, errsz, "defstruct slot options must be keyword/value pairs");
            return 0;
        }
        if (keyword_matches(key, ":read-only")) {
            parsed->has_read_only = 1;
            parsed->read_only = value_is_truthy(value);
        } else if (keyword_matches(key, ":type")) {
            /* Accepted for ANSI compatibility; currently advisory only. */
            parsed->has_type = 1;
            parsed->type_spec = value;
        } else {
            snprintf(err, errsz, "defstruct slot option %s is not implemented yet", key->as.str);
            return 0;
        }
    }
    return 1;
}

static int defstruct_slot_name_seen(const ValueArray *slot_names, Value *slot_name) {
    const char *candidate = package_symbol_entry_name(slot_name);
    int i;
    for (i = 0; i < slot_names->count; ++i) {
        if (str_ieq(package_symbol_entry_name(slot_names->items[i]), candidate)) return 1;
    }
    return 0;
}

static int defstruct_parse_printer_designator(Env *env,
                                              Value *printer_form,
                                              Value **out,
                                              char *err,
                                              size_t errsz) {
    if (printer_form == NULL) {
        snprintf(err, errsz, "defstruct printer option expects a function name or lambda expression");
        return 0;
    }
    if (printer_form->type == VALUE_SYMBOL) {
        *out = printer_form;
        return 1;
    }
    if (coerce_lambda_expression_to_function(env, printer_form, out, err, errsz)) return 1;
    snprintf(err, errsz, "defstruct printer option expects a function name or lambda expression");
    return 0;
}

static Value *make_defstruct_constructor_spec(Value *name_symbol, Value *boa_lambda_list_or_nil) {
    ValueArray items;
    value_array_init(&items);
    value_array_push(&items, name_symbol);
    value_array_push(&items, boa_lambda_list_or_nil);
    return make_vector_value(&items);
}

static int defstruct_constructor_spec_parts(Value *spec,
                                            Value **name_symbol_out,
                                            Value **boa_lambda_list_or_nil_out) {
    if (spec == NULL || spec->type != VALUE_VECTOR || spec->as.array.count != 2) return 0;
    if (name_symbol_out != NULL) *name_symbol_out = spec->as.array.items[0];
    if (boa_lambda_list_or_nil_out != NULL) *boa_lambda_list_or_nil_out = spec->as.array.items[1];
    return 1;
}

static int defstruct_slot_index_for_var_symbol(const ValueArray *slot_names, Value *var_symbol) {
    const char *candidate = NULL;
    int i;
    if (var_symbol == NULL || var_symbol->type != VALUE_SYMBOL) return -1;
    candidate = package_symbol_entry_name(var_symbol);
    for (i = 0; i < slot_names->count; ++i) {
        if (str_ieq(package_symbol_entry_name(slot_names->items[i]), candidate)) return i;
    }
    return -1;
}

static Value *defstruct_param_spec_with_default(Value *spec, Value *default_init) {
    ValueArray items;
    ValueArray out;
    if (spec->type == VALUE_SYMBOL) return make_form_from2(spec, default_init);
    if (!proper_form_to_array(spec, &items) || items.count < 1 || items.count > 3) return spec;
    value_array_init(&out);
    value_array_push(&out, items.items[0]);
    value_array_push(&out, default_init);
    if (items.count == 3) value_array_push(&out, items.items[2]);
    return make_list_value(&out);
}

static Value *defstruct_make_constructor_function(Interp *it,
                                                  Env *env,
                                                  Value *type_name,
                                                  const ValueArray *slot_names,
                                                  const ValueArray *slot_initforms) {
    ValueArray params;
    ValueArray body_items;
    ValueArray call_args;
    int i;
    value_array_init(&params);
    value_array_push(&params, make_symbol_value("&key"));
    for (i = 0; i < slot_names->count; ++i) {
        Value *initform = (slot_initforms->items[i] != NULL) ? slot_initforms->items[i] : defstruct_default_unbound_initform(it);
        value_array_push(&params, make_form_from2(slot_names->items[i], initform));
    }
    value_array_init(&call_args);
    value_array_push(&call_args, make_runtime_quote_form(it, type_name));
    for (i = 0; i < slot_names->count; ++i) value_array_push(&call_args, slot_names->items[i]);
    value_array_init(&body_items);
    value_array_push(&body_items,
                     make_runtime_form_with_head(it,
                                                 common_lisp_runtime_symbol_or_fallback(it, "%make-struct-instance"),
                                                 &call_args));
    return make_closure_value(make_list_value(&params), make_list_value(&body_items), env, 0);
}

static int defstruct_make_boa_constructor_function(Interp *it,
                                                   Env *env,
                                                   Value *type_name,
                                                   Value *constructor_symbol,
                                                   Value *boa_lambda_list,
                                                   const ValueArray *slot_names,
                                                   const ValueArray *slot_initforms,
                                                   Value **out,
                                                   char *err,
                                                   size_t errsz) {
    enum {
        DEFSTRUCT_BOA_REQUIRED = 0,
        DEFSTRUCT_BOA_OPTIONAL = 1,
        DEFSTRUCT_BOA_REST_NAME = 2,
        DEFSTRUCT_BOA_POST_REST = 3,
        DEFSTRUCT_BOA_KEY = 4,
        DEFSTRUCT_BOA_AUX = 5
    };
    ValueArray boa_items;
    ValueArray params;
    ValueArray slot_exprs;
    ValueArray body_items;
    ValueArray call_args;
    int state = DEFSTRUCT_BOA_REQUIRED;
    int i;
    if (!proper_form_to_array(boa_lambda_list, &boa_items)) {
        snprintf(err, errsz, "defstruct BOA constructor %s requires a proper lambda list", package_symbol_entry_name(constructor_symbol));
        return 0;
    }
    value_array_init(&params);
    value_array_init(&slot_exprs);
    for (i = 0; i < slot_initforms->count; ++i) value_array_push(&slot_exprs, slot_initforms->items[i]);
    for (i = 0; i < boa_items.count; ++i) {
        Value *item = boa_items.items[i];
        const char *marker = NULL;
        if (symbol_name(item, &marker) && marker[0] == '&') {
            if (str_ieq(marker, "&optional")) {
                if (state != DEFSTRUCT_BOA_REQUIRED) {
                    snprintf(err, errsz, "defstruct BOA constructor %s has invalid &optional placement", package_symbol_entry_name(constructor_symbol));
                    return 0;
                }
                state = DEFSTRUCT_BOA_OPTIONAL;
                value_array_push(&params, item);
                continue;
            }
            if (str_ieq(marker, "&rest") || str_ieq(marker, "&body")) {
                if (state == DEFSTRUCT_BOA_REST_NAME || state == DEFSTRUCT_BOA_POST_REST || state == DEFSTRUCT_BOA_AUX) {
                    snprintf(err, errsz, "defstruct BOA constructor %s has invalid %s placement", package_symbol_entry_name(constructor_symbol), marker);
                    return 0;
                }
                state = DEFSTRUCT_BOA_REST_NAME;
                value_array_push(&params, item);
                continue;
            }
            if (str_ieq(marker, "&key")) {
                if (state == DEFSTRUCT_BOA_REST_NAME || state == DEFSTRUCT_BOA_AUX || state == DEFSTRUCT_BOA_KEY) {
                    snprintf(err, errsz, "defstruct BOA constructor %s has invalid &key placement", package_symbol_entry_name(constructor_symbol));
                    return 0;
                }
                state = DEFSTRUCT_BOA_KEY;
                value_array_push(&params, item);
                continue;
            }
            if (str_ieq(marker, "&allow-other-keys")) {
                if (state != DEFSTRUCT_BOA_KEY) {
                    snprintf(err, errsz, "defstruct BOA constructor %s uses &allow-other-keys outside of &key", package_symbol_entry_name(constructor_symbol));
                    return 0;
                }
                value_array_push(&params, item);
                continue;
            }
            if (str_ieq(marker, "&aux")) {
                if (state == DEFSTRUCT_BOA_REST_NAME) {
                    snprintf(err, errsz, "defstruct BOA constructor %s is missing a parameter after &rest", package_symbol_entry_name(constructor_symbol));
                    return 0;
                }
                state = DEFSTRUCT_BOA_AUX;
                value_array_push(&params, item);
                continue;
            }
            snprintf(err, errsz, "defstruct BOA constructor %s does not support lambda list marker '%s'", package_symbol_entry_name(constructor_symbol), marker);
            return 0;
        }
        if (state == DEFSTRUCT_BOA_POST_REST) {
            snprintf(err, errsz, "defstruct BOA constructor %s only permits &key or &aux after &rest", package_symbol_entry_name(constructor_symbol));
            return 0;
        }
        if (state == DEFSTRUCT_BOA_REST_NAME) {
            int slot_index = -1;
            if (!reject_constant_binding_target(item, "defstruct BOA &rest parameter", err, errsz)) return 0;
            if (item->type != VALUE_SYMBOL) {
                snprintf(err, errsz, "defstruct BOA constructor %s expects a symbol after &rest", package_symbol_entry_name(constructor_symbol));
                return 0;
            }
            slot_index = defstruct_slot_index_for_var_symbol(slot_names, item);
            if (slot_index >= 0) slot_exprs.items[slot_index] = item;
            value_array_push(&params, item);
            state = DEFSTRUCT_BOA_POST_REST;
            continue;
        }
        if (state == DEFSTRUCT_BOA_REQUIRED) {
            int slot_index = -1;
            if (!reject_constant_binding_target(item, "defstruct BOA parameter", err, errsz)) return 0;
            if (item->type != VALUE_SYMBOL) {
                snprintf(err, errsz, "defstruct BOA constructor %s required parameters must be symbols", package_symbol_entry_name(constructor_symbol));
                return 0;
            }
            slot_index = defstruct_slot_index_for_var_symbol(slot_names, item);
            if (slot_index >= 0) slot_exprs.items[slot_index] = item;
            value_array_push(&params, item);
            continue;
        }
        if (state == DEFSTRUCT_BOA_OPTIONAL) {
            const char *name = NULL;
            const char *suppliedp = NULL;
            Value *initform = NULL;
            Value *var_symbol = NULL;
            int slot_index = -1;
            if (!parse_optional_param_spec(item, &name, &initform, &suppliedp, err, errsz)) return 0;
            (void)name;
            (void)suppliedp;
            var_symbol = optional_param_symbol_or_null(item);
            slot_index = defstruct_slot_index_for_var_symbol(slot_names, var_symbol);
            if (slot_index >= 0) {
                slot_exprs.items[slot_index] = var_symbol;
                if (initform == NULL) {
                    value_array_push(&params, defstruct_param_spec_with_default(item, slot_initforms->items[slot_index]));
                    continue;
                }
            }
            value_array_push(&params, item);
            continue;
        }
        if (state == DEFSTRUCT_BOA_KEY) {
            char *keyword_name = NULL;
            const char *name = NULL;
            const char *suppliedp = NULL;
            Value *initform = NULL;
            Value *var_symbol = NULL;
            int slot_index = -1;
            if (!parse_key_param_spec(item, &keyword_name, &name, &initform, &suppliedp, err, errsz)) {
                free(keyword_name);
                return 0;
            }
            free(keyword_name);
            (void)name;
            (void)suppliedp;
            var_symbol = key_param_symbol_or_null(item);
            slot_index = defstruct_slot_index_for_var_symbol(slot_names, var_symbol);
            if (slot_index >= 0) {
                slot_exprs.items[slot_index] = var_symbol;
                if (initform == NULL) {
                    value_array_push(&params, defstruct_param_spec_with_default(item, slot_initforms->items[slot_index]));
                    continue;
                }
            }
            value_array_push(&params, item);
            continue;
        }
        {
            const char *name = NULL;
            Value *initform = NULL;
            Value *var_symbol = NULL;
            int slot_index = -1;
            if (!parse_aux_param_spec(item, &name, &initform, err, errsz)) return 0;
            (void)name;
            (void)initform;
            var_symbol = aux_param_symbol_or_null(item);
            slot_index = defstruct_slot_index_for_var_symbol(slot_names, var_symbol);
            if (slot_index >= 0) slot_exprs.items[slot_index] = var_symbol;
            value_array_push(&params, item);
        }
    }
    if (state == DEFSTRUCT_BOA_REST_NAME) {
        snprintf(err, errsz, "defstruct BOA constructor %s is missing a parameter after &rest", package_symbol_entry_name(constructor_symbol));
        return 0;
    }
    value_array_init(&call_args);
    value_array_push(&call_args, make_runtime_quote_form(it, type_name));
    for (i = 0; i < slot_exprs.count; ++i) value_array_push(&call_args, slot_exprs.items[i]);
    value_array_init(&body_items);
    value_array_push(&body_items,
                     make_runtime_form_with_head(it,
                                                 common_lisp_runtime_symbol_or_fallback(it, "%make-struct-instance"),
                                                 &call_args));
    *out = make_closure_value(make_list_value(&params), make_list_value(&body_items), env, 0);
    return 1;
}

static Value *defstruct_make_predicate_function(Interp *it, Env *env, Value *type_name) {
    Value *object_symbol = make_generated_uninterned_symbol(it, "struct-object");
    ValueArray params;
    ValueArray body_items;
    ValueArray call_args;
    value_array_init(&params);
    value_array_push(&params, object_symbol);
    value_array_init(&call_args);
    value_array_push(&call_args, make_runtime_quote_form(it, type_name));
    value_array_push(&call_args, object_symbol);
    value_array_init(&body_items);
    value_array_push(&body_items,
                     make_runtime_form_with_head(it,
                                                 common_lisp_runtime_symbol_or_fallback(it, "%struct-type-p"),
                                                 &call_args));
    return make_closure_value(make_list_value(&params), make_list_value(&body_items), env, 0);
}

static Value *defstruct_make_accessor_function(Interp *it, Env *env, Value *type_name, int index) {
    Value *object_symbol = make_generated_uninterned_symbol(it, "struct-object");
    ValueArray params;
    ValueArray body_items;
    ValueArray call_args;
    value_array_init(&params);
    value_array_push(&params, object_symbol);
    value_array_init(&call_args);
    value_array_push(&call_args, make_runtime_quote_form(it, type_name));
    value_array_push(&call_args, make_int_value(bigint_from_i64(index)));
    value_array_push(&call_args, object_symbol);
    value_array_init(&body_items);
    value_array_push(&body_items,
                     make_runtime_form_with_head(it,
                                                 common_lisp_runtime_symbol_or_fallback(it, "%struct-ref"),
                                                 &call_args));
    return make_closure_value(make_list_value(&params), make_list_value(&body_items), env, 0);
}

static Value *defstruct_make_updater_function(Interp *it, Env *env, Value *type_name, int index) {
    Value *object_symbol = make_generated_uninterned_symbol(it, "struct-object");
    Value *new_value_symbol = make_generated_uninterned_symbol(it, "struct-value");
    ValueArray params;
    ValueArray body_items;
    ValueArray call_args;
    value_array_init(&params);
    value_array_push(&params, object_symbol);
    value_array_push(&params, new_value_symbol);
    value_array_init(&call_args);
    value_array_push(&call_args, make_runtime_quote_form(it, type_name));
    value_array_push(&call_args, make_int_value(bigint_from_i64(index)));
    value_array_push(&call_args, object_symbol);
    value_array_push(&call_args, new_value_symbol);
    value_array_init(&body_items);
    value_array_push(&body_items,
                     make_runtime_form_with_head(it,
                                                 common_lisp_runtime_symbol_or_fallback(it, "%struct-set"),
                                                 &call_args));
    return make_closure_value(make_list_value(&params), make_list_value(&body_items), env, 0);
}

static Value *defstruct_make_copier_function(Interp *it, Env *env, Value *type_name) {
    Value *object_symbol = make_generated_uninterned_symbol(it, "struct-object");
    ValueArray params;
    ValueArray body_items;
    ValueArray call_args;
    value_array_init(&params);
    value_array_push(&params, object_symbol);
    value_array_init(&call_args);
    value_array_push(&call_args, make_runtime_quote_form(it, type_name));
    value_array_push(&call_args, object_symbol);
    value_array_init(&body_items);
    value_array_push(&body_items,
                     make_runtime_form_with_head(it,
                                                 common_lisp_runtime_symbol_or_fallback(it, "%copy-struct-instance"),
                                                 &call_args));
    return make_closure_value(make_list_value(&params), make_list_value(&body_items), env, 0);
}

static int special_defstruct(Interp *it, Env *env, Value *form, Value **out, char *err, size_t errsz) {
    Value *name_spec = NULL;
    ValueArray name_and_options;
    Value *name_symbol = NULL;
    Value *doc = NULL;
    Value *current_package = NULL;
    Value *descriptor = NULL;
    Value *included_descriptor = NULL;
    Value *included_type = NULL;
    Value *included_slot_names_value = NULL;
    Value *included_slot_initforms_value = NULL;
    Value *included_slot_read_only_flags_value = NULL;
    Value *included_conc_name_prefix_value = NULL;
    Value *included_slot_positions_value = NULL;
    Value *included_slot_type_specs_value = NULL;
    ValueArray include_override_specs;
    Value *default_constructor_symbol = NULL;
    Value *default_predicate_symbol = NULL;
    Value *default_copier_symbol = NULL;
    Value *constructor_fn = NULL;
    Value *predicate_fn = NULL;
    Value *copier_fn = NULL;
    ValueArray slot_names;
    ValueArray slot_initforms;
    ValueArray slot_read_only_flags;
    ValueArray slot_type_specs;
    DefstructOptions options;
    int body_start = 2;
    int have_name_options = 0;
    int included_slot_count = 0;
    int included_representation_kind = STRUCT_REPR_HEAP;
    int included_minimum_size = 0;
    char *included_accessor_prefix = NULL;
    int i;
    if (form->as.array.count < 2) {
        snprintf(err, errsz, "defstruct expects a structure name and optional slots");
        return 0;
    }
    current_package = current_package_runtime(it, env);
    if (current_package == NULL) {
        snprintf(err, errsz, "defstruct could not determine the current package");
        return 0;
    }
    name_spec = form->as.array.items[1];
    if (name_spec->type == VALUE_SYMBOL) {
        name_symbol = name_spec;
    } else {
        if (!proper_form_to_array(name_spec, &name_and_options) || name_and_options.count < 1) {
            snprintf(err, errsz, "defstruct name-and-options must be a symbol or a non-empty list");
            return 0;
        }
        if (name_and_options.items[0]->type != VALUE_SYMBOL) {
            snprintf(err, errsz, "defstruct name-and-options must start with a structure name symbol");
            return 0;
        }
        name_symbol = name_and_options.items[0];
        have_name_options = 1;
    }
    if (value_is_self_evaluating_constant_form(name_symbol, NULL)) {
        snprintf(err, errsz, "defstruct cannot use constant '%s' as a structure name", package_symbol_entry_name(name_symbol));
        return 0;
    }
    if (special_operator_symbol_p(it, name_symbol)) {
        snprintf(err, errsz, "defstruct cannot target special operator '%s'", package_symbol_entry_name(name_symbol));
        return 0;
    }
    {
        char *constructor_name = concat_three_texts("make-", package_symbol_entry_name(name_symbol), "");
        char *predicate_name = concat_three_texts(package_symbol_entry_name(name_symbol), "-p", "");
        char *copier_name = concat_three_texts("copy-", package_symbol_entry_name(name_symbol), "");
        if (!defstruct_intern_generated_symbol(it, current_package, constructor_name, &default_constructor_symbol, err, errsz) ||
            !defstruct_intern_generated_symbol(it, current_package, predicate_name, &default_predicate_symbol, err, errsz) ||
            !defstruct_intern_generated_symbol(it, current_package, copier_name, &default_copier_symbol, err, errsz)) {
            free(constructor_name);
            free(predicate_name);
            free(copier_name);
            return 0;
        }
        free(constructor_name);
        free(predicate_name);
        free(copier_name);
    }
    defstruct_options_init(&options);
    value_array_init(&include_override_specs);
    options.predicate_symbol = default_predicate_symbol;
    options.copier_symbol = default_copier_symbol;
    options.conc_name_prefix = concat_three_texts(package_symbol_entry_name(name_symbol), "-", "");
    included_type = it->nil;
    if (have_name_options) {
        for (i = 1; i < name_and_options.count; ++i) {
            ValueArray option_items;
            Value *head = NULL;
            if (!defstruct_option_to_array(name_and_options.items[i], &option_items, err, errsz)) {
                defstruct_options_dispose(&options);
                return 0;
            }
            head = option_items.items[0];
            if (keyword_matches(head, ":constructor")) {
                Value *constructor_symbol = NULL;
                Value *constructor_lambda_list = it->nil;
                options.constructor_seen = 1;
                if (option_items.count == 1) {
                    constructor_symbol = default_constructor_symbol;
                } else if (option_items.count == 2) {
                    if (option_items.items[1] != it->nil) {
                        if (option_items.items[1]->type != VALUE_SYMBOL) {
                            defstruct_options_dispose(&options);
                            snprintf(err, errsz, "defstruct :constructor expects a symbol, nil, or no argument");
                            return 0;
                        }
                        constructor_symbol = option_items.items[1];
                    }
                } else if (option_items.count == 3) {
                    if (option_items.items[1]->type != VALUE_SYMBOL) {
                        defstruct_options_dispose(&options);
                        snprintf(err, errsz, "defstruct BOA constructor name must be a symbol");
                        return 0;
                    }
                    constructor_symbol = option_items.items[1];
                    constructor_lambda_list = option_items.items[2];
                } else {
                    defstruct_options_dispose(&options);
                    snprintf(err, errsz, "defstruct :constructor expects at most two arguments");
                    return 0;
                }
                if (constructor_symbol != NULL) {
                    if (constructor_lambda_list == it->nil && options.standard_constructor_symbol == NULL) {
                        options.standard_constructor_symbol = constructor_symbol;
                    }
                    value_array_push(&options.constructor_specs,
                                     make_defstruct_constructor_spec(constructor_symbol, constructor_lambda_list));
                }
            } else if (keyword_matches(head, ":predicate")) {
                if (options.predicate_seen) {
                    defstruct_options_dispose(&options);
                    snprintf(err, errsz, "defstruct supports at most one :predicate option");
                    return 0;
                }
                options.predicate_seen = 1;
                if (option_items.count == 1) {
                    options.predicate_symbol = default_predicate_symbol;
                } else if (option_items.count == 2) {
                    if (option_items.items[1] == it->nil) {
                        options.predicate_symbol = NULL;
                    } else if (option_items.items[1]->type == VALUE_SYMBOL) {
                        options.predicate_symbol = option_items.items[1];
                    } else {
                        defstruct_options_dispose(&options);
                        snprintf(err, errsz, "defstruct :predicate expects a symbol, nil, or no argument");
                        return 0;
                    }
                } else {
                    defstruct_options_dispose(&options);
                    snprintf(err, errsz, "defstruct :predicate expects at most one argument");
                    return 0;
                }
            } else if (keyword_matches(head, ":copier")) {
                if (options.copier_seen) {
                    defstruct_options_dispose(&options);
                    snprintf(err, errsz, "defstruct supports at most one :copier option");
                    return 0;
                }
                options.copier_seen = 1;
                if (option_items.count == 1) {
                    options.copier_symbol = default_copier_symbol;
                } else if (option_items.count == 2) {
                    if (option_items.items[1] == it->nil) {
                        options.copier_symbol = NULL;
                    } else if (option_items.items[1]->type == VALUE_SYMBOL) {
                        options.copier_symbol = option_items.items[1];
                    } else {
                        defstruct_options_dispose(&options);
                        snprintf(err, errsz, "defstruct :copier expects a symbol, nil, or no argument");
                        return 0;
                    }
                } else {
                    defstruct_options_dispose(&options);
                    snprintf(err, errsz, "defstruct :copier expects at most one argument");
                    return 0;
                }
            } else if (keyword_matches(head, ":conc-name")) {
                char *text = NULL;
                if (options.conc_name_seen) {
                    defstruct_options_dispose(&options);
                    snprintf(err, errsz, "defstruct supports at most one :conc-name option");
                    return 0;
                }
                options.conc_name_seen = 1;
                free(options.conc_name_prefix);
                options.conc_name_prefix = NULL;
                if (option_items.count == 1 || option_items.items[1] == it->nil) {
                    options.conc_name_prefix = xstrdup_c("");
                } else if (option_items.count == 2) {
                    if (!value_to_string_designator_text(option_items.items[1], "defstruct :conc-name", &text, err, errsz)) {
                        defstruct_options_dispose(&options);
                        return 0;
                    }
                    options.conc_name_prefix = text;
                } else {
                    defstruct_options_dispose(&options);
                    snprintf(err, errsz, "defstruct :conc-name expects at most one argument");
                    return 0;
                }
            } else if (keyword_matches(head, ":include")) {
                if (included_type != it->nil) {
                    defstruct_options_dispose(&options);
                    snprintf(err, errsz, "defstruct supports at most one :include option");
                    return 0;
                }
                if (option_items.count < 2 || option_items.items[1]->type != VALUE_SYMBOL) {
                    defstruct_options_dispose(&options);
                    snprintf(err, errsz, "defstruct :include expects an included structure name");
                    return 0;
                }
                if (value_eq_impl(option_items.items[1], name_symbol)) {
                    defstruct_options_dispose(&options);
                    snprintf(err, errsz, "defstruct cannot include itself");
                    return 0;
                }
                if (!struct_descriptor_lookup(it, env, option_items.items[1], &included_descriptor) ||
                    !struct_descriptor_parts(included_descriptor,
                                             &included_slot_names_value,
                                             NULL,
                                             NULL,
                                             &included_slot_initforms_value,
                                             &included_slot_read_only_flags_value,
                                             &included_conc_name_prefix_value)) {
                    defstruct_options_dispose(&options);
                    snprintf(err, errsz, "defstruct :include expects an existing structure name");
                    return 0;
                }
                if (!struct_descriptor_representation_info(included_descriptor, &included_representation_kind, NULL, NULL) ||
                    !struct_descriptor_layout_info(included_descriptor,
                                                   &included_slot_positions_value,
                                                   &included_minimum_size,
                                                   NULL)) {
                    defstruct_options_dispose(&options);
                    snprintf(err, errsz, "defstruct internal included structure descriptor error");
                    return 0;
                }
                for (int j = 2; j < option_items.count; ++j) value_array_push(&include_override_specs, option_items.items[j]);
                included_type = option_items.items[1];
            } else if (keyword_matches(head, ":type")) {
                ValueArray type_items;
                Value *upgraded = NULL;
                if (options.type_seen) {
                    defstruct_options_dispose(&options);
                    snprintf(err, errsz, "defstruct supports at most one :type option");
                    return 0;
                }
                if (option_items.count != 2) {
                    defstruct_options_dispose(&options);
                    snprintf(err, errsz, "defstruct :type expects exactly one type argument");
                    return 0;
                }
                options.type_seen = 1;
                if (builtin_type_symbol_named(option_items.items[1], "list")) {
                    options.representation_kind = STRUCT_REPR_LIST;
                    options.representation_type_spec = it->nil;
                } else if (builtin_type_symbol_named(option_items.items[1], "vector")) {
                    options.representation_kind = STRUCT_REPR_VECTOR;
                    options.representation_type_spec = common_lisp_runtime_symbol_or_fallback(it, "t");
                } else if (proper_form_to_array(option_items.items[1], &type_items) &&
                           type_items.count == 2 &&
                           builtin_type_symbol_named(type_items.items[0], "vector")) {
                    Value *element_type = builtin_type_symbol_named(type_items.items[1], "*")
                        ? common_lisp_runtime_symbol_or_fallback(it, "t")
                        : type_items.items[1];
                    upgraded = upgraded_array_element_type_value(it, env, element_type);
                    if (builtin_type_symbol_named(upgraded, "bit") ||
                        builtin_type_symbol_named(upgraded, "character") ||
                        builtin_type_symbol_named(upgraded, "base-char")) {
                        if (builtin_type_symbol_named(upgraded, "character") ||
                            builtin_type_symbol_named(upgraded, "base-char")) {
                            options.representation_kind = STRUCT_REPR_STRING;
                            options.representation_type_spec = element_type;
                            continue;
                        }
                        options.representation_kind = STRUCT_REPR_VECTOR;
                        options.representation_type_spec = element_type;
                        continue;
                    }
                    options.representation_kind = STRUCT_REPR_VECTOR;
                    options.representation_type_spec = element_type;
                } else {
                    defstruct_options_dispose(&options);
                    snprintf(err, errsz, "defstruct :type currently supports only list, vector, or (vector element-type)");
                    return 0;
                }
            } else if (keyword_matches(head, ":named")) {
                if (options.named_seen) {
                    defstruct_options_dispose(&options);
                    snprintf(err, errsz, "defstruct supports at most one :named option");
                    return 0;
                }
                if (option_items.count != 1) {
                    defstruct_options_dispose(&options);
                    snprintf(err, errsz, "defstruct :named does not take arguments");
                    return 0;
                }
                options.named_seen = 1;
                options.namedp = 1;
            } else if (keyword_matches(head, ":print-function") ||
                       keyword_matches(head, ":print-object")) {
                int printer_kind = keyword_matches(head, ":print-function")
                    ? STRUCT_PRINT_FUNCTION
                    : STRUCT_PRINT_OBJECT;
                if (options.printer_seen) {
                    defstruct_options_dispose(&options);
                    snprintf(err, errsz, "defstruct supports at most one printer option");
                    return 0;
                }
                if (option_items.count > 2) {
                    defstruct_options_dispose(&options);
                    snprintf(err, errsz, "defstruct %s expects at most one printer name", head->as.str);
                    return 0;
                }
                options.printer_seen = 1;
                if (option_items.count == 1) {
                    options.printer_kind = STRUCT_PRINT_DEFAULT;
                    options.printer = it->nil;
                } else {
                    if (!defstruct_parse_printer_designator(env,
                                                            option_items.items[1],
                                                            &options.printer,
                                                            err,
                                                            errsz)) {
                        defstruct_options_dispose(&options);
                        return 0;
                    }
                    options.printer_kind = printer_kind;
                }
            } else if (keyword_matches(head, ":initial-offset")) {
                int64_t offset_i64 = 0;
                if (options.initial_offset_seen) {
                    defstruct_options_dispose(&options);
                    snprintf(err, errsz, "defstruct supports at most one :initial-offset option");
                    return 0;
                }
                if (option_items.count != 2 ||
                    option_items.items[1]->type != VALUE_INT ||
                    !bigint_to_i64_checked(option_items.items[1]->as.bigint, &offset_i64) ||
                    offset_i64 < 0) {
                    defstruct_options_dispose(&options);
                    snprintf(err, errsz, "defstruct :initial-offset expects one non-negative fixnum argument");
                    return 0;
                }
                options.initial_offset_seen = 1;
                options.initial_offset = (int)offset_i64;
            } else {
                defstruct_options_dispose(&options);
                snprintf(err, errsz, "unsupported defstruct option %s", head->as.str);
                return 0;
            }
        }
    }
    if (options.initial_offset_seen && options.representation_kind == STRUCT_REPR_HEAP) {
        defstruct_options_dispose(&options);
        snprintf(err, errsz, "defstruct :initial-offset requires :type");
        return 0;
    }
    if (options.printer_seen && options.representation_kind != STRUCT_REPR_HEAP) {
        defstruct_options_dispose(&options);
        snprintf(err, errsz, "defstruct printer options may be used only when :type is not supplied");
        return 0;
    }
    if (included_type != it->nil && options.representation_kind != included_representation_kind) {
        defstruct_options_dispose(&options);
        snprintf(err, errsz, "defstruct :include requires the same representation type as the included structure");
        return 0;
    }
    if (included_type != it->nil && (options.representation_kind == STRUCT_REPR_VECTOR || options.representation_kind == STRUCT_REPR_STRING)) {
        Value *included_vector_element_type = NULL;
        Value *expected_upgraded = NULL;
        Value *included_upgraded = NULL;
        if (!struct_descriptor_vector_element_type_spec(it, included_descriptor, &included_vector_element_type)) {
            defstruct_options_dispose(&options);
            snprintf(err, errsz, "defstruct internal included structure descriptor error");
            return 0;
        }
        if (options.representation_kind == STRUCT_REPR_VECTOR) {
            expected_upgraded = upgraded_array_element_type_value(it,
                                                                  env,
                                                                  (options.representation_type_spec != NULL)
                                                                      ? options.representation_type_spec
                                                                      : common_lisp_runtime_symbol_or_fallback(it, "t"));
            included_upgraded = upgraded_array_element_type_value(it, env, included_vector_element_type);
            if (!value_equal_impl(expected_upgraded, included_upgraded)) {
                defstruct_options_dispose(&options);
                snprintf(err, errsz, "defstruct :include requires compatible vector element representations");
                return 0;
            }
        }
    }
    if (options.representation_kind == STRUCT_REPR_STRING && options.namedp) {
        defstruct_options_dispose(&options);
        snprintf(err, errsz, "defstruct :named is not supported for string-based :type representations");
        return 0;
    }
    if (options.representation_kind != STRUCT_REPR_HEAP && !options.namedp) {
        if (!options.predicate_seen) {
            options.predicate_symbol = NULL;
        } else if (options.predicate_symbol != NULL) {
            defstruct_options_dispose(&options);
            snprintf(err, errsz, "defstruct :predicate requires the structure to be named when :type is supplied");
            return 0;
        }
    }
    if (options.representation_kind == STRUCT_REPR_VECTOR && options.namedp) {
        int match = 0;
        Value *repr_type = (options.representation_type_spec != NULL)
            ? options.representation_type_spec
            : common_lisp_runtime_symbol_or_fallback(it, "t");
        if (!value_matches_type_spec(it, env, name_symbol, repr_type, &match, err, errsz)) {
            defstruct_options_dispose(&options);
            return 0;
        }
        if (!match) {
            defstruct_options_dispose(&options);
            snprintf(err, errsz, "defstruct :named requires the structure name symbol to fit the vector element-type");
            return 0;
        }
    }
    if (!options.constructor_seen) {
        options.standard_constructor_symbol = default_constructor_symbol;
        value_array_push(&options.constructor_specs, make_defstruct_constructor_spec(default_constructor_symbol, it->nil));
    }
    value_array_init(&slot_names);
    value_array_init(&slot_initforms);
    value_array_init(&slot_read_only_flags);
    value_array_init(&slot_type_specs);
    if (included_type != it->nil) {
        ValueArray included_slot_names;
        ValueArray included_slot_initforms;
        ValueArray included_slot_read_only_flags;
        ValueArray included_slot_type_specs;
        ValueArray included_slot_names_copy;
        ValueArray included_slot_initforms_copy;
        ValueArray included_slot_read_only_flags_copy;
        ValueArray included_slot_type_specs_copy;
        if (!proper_form_to_array(included_slot_names_value, &included_slot_names) ||
            !proper_form_to_array(included_slot_initforms_value, &included_slot_initforms) ||
            !proper_form_to_array(included_slot_read_only_flags_value, &included_slot_read_only_flags) ||
            !struct_descriptor_slot_type_specs(it, included_descriptor, &included_slot_type_specs_value) ||
            !proper_form_to_array(included_slot_type_specs_value, &included_slot_type_specs) ||
            included_slot_names.count != included_slot_initforms.count ||
            included_slot_names.count != included_slot_read_only_flags.count ||
            included_slot_names.count != included_slot_type_specs.count) {
            defstruct_options_dispose(&options);
            snprintf(err, errsz, "defstruct internal included structure descriptor error");
            return 0;
        }
        value_array_copy(&included_slot_names_copy, &included_slot_names);
        value_array_copy(&included_slot_initforms_copy, &included_slot_initforms);
        value_array_copy(&included_slot_read_only_flags_copy, &included_slot_read_only_flags);
        value_array_copy(&included_slot_type_specs_copy, &included_slot_type_specs);
        for (i = 0; i < include_override_specs.count; ++i) {
            DefstructParsedSlotSpec override_spec;
            int matched = 0;
            int j;
            if (!defstruct_parse_slot_spec(it, include_override_specs.items[i], &override_spec, err, errsz)) {
                free(included_accessor_prefix);
                defstruct_options_dispose(&options);
                return 0;
            }
            for (j = 0; j < included_slot_names_copy.count; ++j) {
                if (value_eq_impl(included_slot_names_copy.items[j], override_spec.slot_name)) {
                    matched = 1;
                    included_slot_initforms_copy.items[j] = override_spec.has_initform
                        ? override_spec.initform
                        : defstruct_default_unbound_initform(it);
                    if (override_spec.has_read_only) {
                        if (value_is_truthy(included_slot_read_only_flags_copy.items[j]) && !override_spec.read_only) {
                            free(included_accessor_prefix);
                            defstruct_options_dispose(&options);
                            snprintf(err,
                                     errsz,
                                     "defstruct :include cannot make inherited read-only slot '%s' writable",
                                     package_symbol_entry_name(override_spec.slot_name));
                            return 0;
                        }
                        if (override_spec.read_only) included_slot_read_only_flags_copy.items[j] = it->true_value;
                    }
                    if (override_spec.has_type) {
                        int known = 0;
                        int subtype = 0;
                        if (!subtypep_type_specs(it,
                                                 env,
                                                 override_spec.type_spec,
                                                 included_slot_type_specs_copy.items[j],
                                                 &known,
                                                 &subtype,
                                                 err,
                                                 errsz)) {
                            free(included_accessor_prefix);
                            defstruct_options_dispose(&options);
                            return 0;
                        }
                        if (!known || !subtype) {
                            free(included_accessor_prefix);
                            defstruct_options_dispose(&options);
                            snprintf(err,
                                     errsz,
                                     "defstruct :include slot override '%s' must use a :type that is a subtype of the inherited slot type",
                                     package_symbol_entry_name(override_spec.slot_name));
                            return 0;
                        }
                        included_slot_type_specs_copy.items[j] = override_spec.type_spec;
                    }
                    break;
                }
            }
            if (!matched) {
                free(included_accessor_prefix);
                defstruct_options_dispose(&options);
                snprintf(err,
                         errsz,
                         "defstruct :include slot override '%s' does not name an inherited slot",
                         package_symbol_entry_name(override_spec.slot_name));
                return 0;
            }
        }
        included_slot_count = included_slot_names_copy.count;
        if (!value_to_string_designator_text(included_conc_name_prefix_value,
                                             "defstruct internal included structure conc-name",
                                             &included_accessor_prefix,
                                             err,
                                             errsz)) {
            defstruct_options_dispose(&options);
            return 0;
        }
        for (i = 0; i < included_slot_names_copy.count; ++i) {
            value_array_push(&slot_names, included_slot_names_copy.items[i]);
            value_array_push(&slot_initforms, included_slot_initforms_copy.items[i]);
            value_array_push(&slot_read_only_flags, included_slot_read_only_flags_copy.items[i]);
            value_array_push(&slot_type_specs, included_slot_type_specs_copy.items[i]);
        }
    }
    if (body_start < form->as.array.count && form->as.array.items[body_start]->type == VALUE_STRING) {
        doc = form->as.array.items[body_start];
        ++body_start;
    }
    for (i = body_start; i < form->as.array.count; ++i) {
        DefstructParsedSlotSpec parsed_slot;
        if (!defstruct_parse_slot_spec(it, form->as.array.items[i], &parsed_slot, err, errsz)) {
            free(included_accessor_prefix);
            defstruct_options_dispose(&options);
            return 0;
        }
        if (defstruct_slot_name_seen(&slot_names, parsed_slot.slot_name)) {
            free(included_accessor_prefix);
            defstruct_options_dispose(&options);
            snprintf(err, errsz, "defstruct slot name '%s' appears more than once", package_symbol_entry_name(parsed_slot.slot_name));
            return 0;
        }
        value_array_push(&slot_names, parsed_slot.slot_name);
        value_array_push(&slot_initforms,
                         (parsed_slot.initform != NULL) ? parsed_slot.initform : defstruct_default_unbound_initform(it));
        value_array_push(&slot_read_only_flags, parsed_slot.read_only ? it->true_value : it->nil);
        value_array_push(&slot_type_specs,
                         parsed_slot.has_type ? parsed_slot.type_spec : common_lisp_runtime_symbol_or_fallback(it, "t"));
    }
    {
        ValueArray slot_positions;
        int minimum_size = 0;
        int name_position = 0;
        int own_slot_base = 0;
        value_array_init(&slot_positions);
        if (options.representation_kind == STRUCT_REPR_HEAP) {
            for (i = 0; i < slot_names.count; ++i) {
                value_array_push(&slot_positions, make_int_value(bigint_from_i64((int64_t)i)));
            }
            minimum_size = slot_names.count;
            name_position = 0;
        } else {
            if (included_type != it->nil) {
                ValueArray included_slot_positions;
                if (!proper_form_to_array(included_slot_positions_value, &included_slot_positions)) {
                    free(included_accessor_prefix);
                    defstruct_options_dispose(&options);
                    snprintf(err, errsz, "defstruct internal included structure descriptor error");
                    return 0;
                }
                for (i = 0; i < included_slot_positions.count; ++i) {
                    value_array_push(&slot_positions, included_slot_positions.items[i]);
                }
                own_slot_base = included_minimum_size + options.initial_offset + (options.namedp ? 1 : 0);
                name_position = options.namedp ? (included_minimum_size + options.initial_offset) : -1;
                minimum_size = own_slot_base + (slot_names.count - included_slot_count);
                for (i = included_slot_count; i < slot_names.count; ++i) {
                    value_array_push(&slot_positions,
                                     make_int_value(bigint_from_i64((int64_t)(own_slot_base + (i - included_slot_count)))));
                }
            } else {
                own_slot_base = options.initial_offset + (options.namedp ? 1 : 0);
                name_position = options.namedp ? options.initial_offset : -1;
                minimum_size = own_slot_base + slot_names.count;
                for (i = 0; i < slot_names.count; ++i) {
                    value_array_push(&slot_positions,
                                     make_int_value(bigint_from_i64((int64_t)(own_slot_base + i))));
                }
            }
        }
        descriptor = make_struct_descriptor(make_list_value(&slot_names),
                                            (options.standard_constructor_symbol != NULL &&
                                             options.representation_kind == STRUCT_REPR_HEAP)
                                                ? options.standard_constructor_symbol
                                                : it->nil,
                                            included_type,
                                            make_list_value(&slot_initforms),
                                            make_list_value(&slot_read_only_flags),
                                            make_string_value(options.conc_name_prefix),
                                            options.representation_kind,
                                            (options.representation_kind == STRUCT_REPR_HEAP) ? 1 : options.namedp,
                                            options.initial_offset,
                                            make_list_value(&slot_positions),
                                            minimum_size,
                                            name_position,
                                            make_list_value(&slot_type_specs),
                                            (options.representation_kind == STRUCT_REPR_VECTOR && options.representation_type_spec != NULL)
                                                ? options.representation_type_spec
                                                : it->nil,
                                            options.printer_kind,
                                            (options.printer != NULL) ? options.printer : it->nil);
    }
    struct_descriptor_set(it, env, name_symbol, descriptor);
    if (options.constructor_specs.count > 0) {
        Value *keyword_constructor_fn = NULL;
        for (i = 0; i < options.constructor_specs.count; ++i) {
            Value *constructor_symbol = NULL;
            Value *constructor_lambda_list = NULL;
            if (!defstruct_constructor_spec_parts(options.constructor_specs.items[i],
                                                  &constructor_symbol,
                                                  &constructor_lambda_list)) {
                free(included_accessor_prefix);
                defstruct_options_dispose(&options);
                snprintf(err, errsz, "defstruct internal constructor descriptor error");
                return 0;
            }
            if (constructor_lambda_list == it->nil) {
                if (keyword_constructor_fn == NULL) {
                    keyword_constructor_fn = defstruct_make_constructor_function(it, env, name_symbol, &slot_names, &slot_initforms);
                }
                constructor_fn = keyword_constructor_fn;
            } else if (!defstruct_make_boa_constructor_function(it,
                                                                env,
                                                                name_symbol,
                                                                constructor_symbol,
                                                                constructor_lambda_list,
                                                                &slot_names,
                                                                &slot_initforms,
                                                                &constructor_fn,
                                                                err,
                                                                errsz)) {
                free(included_accessor_prefix);
                defstruct_options_dispose(&options);
                return 0;
            }
            global_function_set_symbol(env, constructor_symbol, constructor_fn);
        }
    }
    if (options.predicate_symbol != NULL) {
        predicate_fn = defstruct_make_predicate_function(it, env, name_symbol);
        global_function_set_symbol(env, options.predicate_symbol, predicate_fn);
    }
    if (options.copier_symbol != NULL) {
        copier_fn = defstruct_make_copier_function(it, env, name_symbol);
        global_function_set_symbol(env, options.copier_symbol, copier_fn);
    }
    for (i = 0; i < slot_names.count; ++i) {
        char *accessor_name = concat_three_texts(options.conc_name_prefix, package_symbol_entry_name(slot_names.items[i]), "");
        char *included_accessor_name = NULL;
        Value *accessor_symbol = NULL;
        Value *accessor_fn = NULL;
        Value *updater_symbol = make_generated_uninterned_symbol(it, "struct-setf");
        Value *updater_fn = NULL;
        if (i < included_slot_count && included_accessor_prefix != NULL) {
            included_accessor_name = concat_three_texts(included_accessor_prefix,
                                                        package_symbol_entry_name(slot_names.items[i]),
                                                        "");
            if (strcmp(accessor_name, included_accessor_name) == 0) {
                free(included_accessor_name);
                free(accessor_name);
                continue;
            }
            free(included_accessor_name);
        }
        if (!defstruct_intern_generated_symbol(it, current_package, accessor_name, &accessor_symbol, err, errsz)) {
            free(accessor_name);
            free(included_accessor_prefix);
            defstruct_options_dispose(&options);
            return 0;
        }
        free(accessor_name);
        accessor_fn = defstruct_make_accessor_function(it, env, name_symbol, i);
        global_function_set_symbol(env, accessor_symbol, accessor_fn);
        if (value_is_truthy(slot_read_only_flags.items[i])) {
            global_setf_function_unbind_symbol(env, accessor_symbol);
        } else {
            updater_fn = defstruct_make_updater_function(it, env, name_symbol, i);
            global_function_set_symbol(env, updater_symbol, updater_fn);
            global_setf_function_set_symbol(env, accessor_symbol, updater_symbol);
        }
    }
    if (doc != NULL) global_type_doc_set_symbol(env, name_symbol, doc);
    else global_type_doc_unbind_symbol(env, name_symbol);
    free(included_accessor_prefix);
    value_array_dispose(&include_override_specs);
    defstruct_options_dispose(&options);
    *out = name_symbol;
    interp_set_single_value(it, *out);
    return 1;
}

#ifdef LISPY_HAVE_PYTHON
static int builtin_py_register_callback(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz);
#endif

static int special_defn_like(Interp *it, Env *env, Value *form, int is_macro, Value **out, char *err, size_t errsz) {
    const char *name = NULL;
    Value *name_symbol = NULL;
    Value *fn = NULL;
    Value *doc = NULL;
    ValueArray arr;
    if (form->as.array.count < 4) {
        snprintf(err, errsz, "%s expects name, params and body", is_macro ? "defmacro" : "defun");
        return 0;
    }
    name_symbol = form->as.array.items[1];
    if (!symbol_name(name_symbol, &name)) {
        snprintf(err, errsz, "%s name must be a symbol", is_macro ? "defmacro" : "defun");
        return 0;
    }
    if (special_operator_symbol_p(it, name_symbol)) {
        snprintf(err, errsz, "%s cannot target special operator '%s'", is_macro ? "defmacro" : "defun", name);
        return 0;
    }
    value_array_init(&arr);
    value_array_push(&arr, make_symbol_value("lambda"));
    value_array_push(&arr, form->as.array.items[2]);
    {
        int i;
        ValueArray block_body;
        value_array_init(&block_body);
        value_array_push(&block_body, make_symbol_value("block"));
        value_array_push(&block_body, name_symbol);
        for (i = 3; i < form->as.array.count; ++i)
            value_array_push(&block_body, form->as.array.items[i]);
        value_array_push(&arr, make_list_value(&block_body));
    }
    if (!special_fn_like(it, env, make_list_value(&arr), is_macro, &fn, err, errsz)) return 0;
    env_define_function_symbol(env, name_symbol, fn);
#ifdef LISPY_HAVE_PYTHON
    {
        ValueArray cb_args;
        memset(&cb_args, 0, sizeof(cb_args));
        cb_args.items = &name_symbol;
        cb_args.count = 1;
        Value *ignored = NULL;
        char cb_err[256];
        builtin_py_register_callback(it, env, &cb_args, &ignored, cb_err, sizeof(cb_err));
    }
#endif
    doc = (fn->type == VALUE_CLOSURE) ? fn->as.closure.documentation : NULL;
    if (doc != NULL) {
        global_function_doc_set_symbol(env, name_symbol, doc);
    } else {
        global_function_doc_unbind_symbol(env, name_symbol);
    }
    *out = name_symbol;
    interp_set_single_value(it, *out);
    return 1;
}

static int special_defsetf(Interp *it, Env *env, Value *form, Value **out, char *err, size_t errsz) {
    const char *access_name = NULL;
    const char *update_name = NULL;
    Value *access_symbol = NULL;
    Value *update_symbol = NULL;
    Value *doc = NULL;
    access_symbol = form->as.array.items[1];
    if (form->as.array.count >= 4 &&
        (form->as.array.items[2]->type == VALUE_LIST || form->as.array.items[2]->type == VALUE_NIL)) {
        Value *lambda_list = NULL;
        Value *store_vars = NULL;
        ValueArray store_names;
        ValueArray wrapped;
        ValueArray block_items;
        Value *expander = NULL;
        Value *body_form = NULL;
        int body_start = 4;
        int i;
        if (!symbol_name(form->as.array.items[1], &access_name)) {
            snprintf(err, errsz, "defsetf accessor name must be a symbol");
            return 0;
        }
        if (value_is_self_evaluating_constant_form(form->as.array.items[1], NULL)) {
            snprintf(err, errsz, "defsetf cannot use self-evaluating constant name '%s'", access_name);
            return 0;
        }
        if (special_operator_symbol_p(it, form->as.array.items[1])) {
            snprintf(err, errsz, "defsetf cannot target special operator '%s'", access_name);
            return 0;
        }
        lambda_list = form->as.array.items[2];
        store_vars = form->as.array.items[3];
        if (lambda_list->type != VALUE_LIST) {
            snprintf(err, errsz, "defsetf long form lambda list must be a list");
            return 0;
        }
        for (i = 0; i < lambda_list->as.array.count; ++i) {
            const char *marker = NULL;
            if (!symbol_name(lambda_list->as.array.items[i], &marker)) continue;
            if (str_ieq(marker, "&aux")) {
                snprintf(err, errsz, "defsetf lambda list does not permit &aux");
                return 0;
            }
        }
        if (!defsetf_store_vars_to_array(store_vars, &store_names, err, errsz)) return 0;
        if (form->as.array.count == 5 && form->as.array.items[4]->type == VALUE_STRING) {
            snprintf(err, errsz, "defsetf long form requires at least one body form");
            return 0;
        }
        while (body_start < form->as.array.count && form_head_symbol_named(form->as.array.items[body_start], "declare")) {
            ++body_start;
        }
        if (body_start < form->as.array.count && form->as.array.items[body_start]->type == VALUE_STRING) ++body_start;
        if (body_start >= form->as.array.count) {
            snprintf(err, errsz, "defsetf long form requires at least one body form");
            return 0;
        }
        value_array_init(&block_items);
        value_array_push(&block_items, make_symbol_value("block"));
        value_array_push(&block_items, access_symbol);
        for (i = 4; i < form->as.array.count; ++i) {
            if (i == body_start - 1 && form->as.array.items[i]->type == VALUE_STRING) continue;
            value_array_push(&block_items, form->as.array.items[i]);
        }
        body_form = make_list_value(&block_items);
        value_array_init(&wrapped);
        value_array_push(&wrapped, body_form);
        expander = make_closure_value(lambda_list, make_list_value(&wrapped), env, 0);
        if (body_start > 4 && form->as.array.items[body_start - 1]->type == VALUE_STRING) {
            global_setf_doc_set_symbol(env, access_symbol, form->as.array.items[body_start - 1]);
        } else {
            global_setf_doc_unbind_symbol(env, access_symbol);
        }
        global_setf_function_set_symbol(env, access_symbol, make_defsetf_long_descriptor(expander, store_vars));
        *out = form->as.array.items[1];
        interp_set_single_value(it, *out);
        return 1;
    }
    if (form->as.array.count != 3 && form->as.array.count != 4) {
        snprintf(err, errsz, "defsetf expects accessor name, updater name, and optional docstring");
        return 0;
    }
    if (!symbol_name(form->as.array.items[1], &access_name)) {
        snprintf(err, errsz, "defsetf accessor name must be a symbol");
        return 0;
    }
    if (!symbol_name(form->as.array.items[2], &update_name)) {
        snprintf(err, errsz, "defsetf updater name must be a symbol");
        return 0;
    }
    update_symbol = form->as.array.items[2];
    if (value_is_self_evaluating_constant_form(form->as.array.items[1], NULL)) {
        snprintf(err, errsz, "defsetf cannot use self-evaluating constant name '%s'", access_name);
        return 0;
    }
    if (value_is_self_evaluating_constant_form(form->as.array.items[2], NULL)) {
        snprintf(err, errsz, "defsetf updater cannot be the constant '%s'", update_name);
        return 0;
    }
    if (special_operator_symbol_p(it, form->as.array.items[1])) {
        snprintf(err, errsz, "defsetf cannot target special operator '%s'", access_name);
        return 0;
    }
    if (special_operator_symbol_p(it, form->as.array.items[2])) {
        snprintf(err, errsz, "defsetf updater cannot be special operator '%s'", update_name);
        return 0;
    }
    if (form->as.array.count == 4) {
        doc = form->as.array.items[3];
        if (doc->type != VALUE_STRING) {
            snprintf(err, errsz, "defsetf short form optional docstring must be a string");
            return 0;
        }
    }
    global_setf_function_set_symbol(env, access_symbol, update_symbol);
    if (doc != NULL) {
        global_setf_doc_set_symbol(env, access_symbol, doc);
    } else {
        global_setf_doc_unbind_symbol(env, access_symbol);
    }
    *out = form->as.array.items[1];
    interp_set_single_value(it, *out);
    return 1;
}

static int special_define_setf_expander(Interp *it, Env *env, Value *form, Value **out, char *err, size_t errsz) {
    const char *access_name = NULL;
    Value *access_symbol = NULL;
    Value *lambda_list = NULL;
    Value *expander = NULL;
    Value *body_form = NULL;
    ValueArray wrapped;
    ValueArray block_items;
    int body_start = 3;
    int i;
    if (form->as.array.count < 4) {
        snprintf(err, errsz, "define-setf-expander expects name, lambda-list, and body");
        return 0;
    }
    if (!symbol_name(form->as.array.items[1], &access_name)) {
        snprintf(err, errsz, "define-setf-expander name must be a symbol");
        return 0;
    }
    access_symbol = form->as.array.items[1];
    if (value_is_self_evaluating_constant_form(form->as.array.items[1], NULL)) {
        snprintf(err, errsz, "define-setf-expander cannot use self-evaluating constant name '%s'", access_name);
        return 0;
    }
    if (special_operator_symbol_p(it, form->as.array.items[1])) {
        snprintf(err, errsz, "define-setf-expander cannot target special operator '%s'", access_name);
        return 0;
    }
    lambda_list = form->as.array.items[2];
    if (lambda_list->type != VALUE_LIST) {
        snprintf(err, errsz, "define-setf-expander lambda list must be a list");
        return 0;
    }
    if (form->as.array.count == 4 && form->as.array.items[3]->type == VALUE_STRING) {
        snprintf(err, errsz, "define-setf-expander requires at least one body form");
        return 0;
    }
    while (body_start < form->as.array.count && form_head_symbol_named(form->as.array.items[body_start], "declare")) {
        ++body_start;
    }
    if (body_start < form->as.array.count && form->as.array.items[body_start]->type == VALUE_STRING) ++body_start;
    if (body_start >= form->as.array.count) {
        snprintf(err, errsz, "define-setf-expander requires at least one body form");
        return 0;
    }
    value_array_init(&block_items);
    value_array_push(&block_items, make_symbol_value("block"));
    value_array_push(&block_items, access_symbol);
    for (i = 3; i < form->as.array.count; ++i) {
        if (i == body_start - 1 && form->as.array.items[i]->type == VALUE_STRING) continue;
        value_array_push(&block_items, form->as.array.items[i]);
    }
    body_form = make_list_value(&block_items);
    value_array_init(&wrapped);
    value_array_push(&wrapped, body_form);
    expander = make_closure_value(lambda_list, make_list_value(&wrapped), env, 1);
    global_setf_function_set_symbol(env, access_symbol, make_setf_expander_descriptor(expander));
    if (body_start > 3 && form->as.array.items[body_start - 1]->type == VALUE_STRING) {
        global_setf_doc_set_symbol(env, access_symbol, form->as.array.items[body_start - 1]);
    } else {
        global_setf_doc_unbind_symbol(env, access_symbol);
    }
    *out = form->as.array.items[1];
    interp_set_single_value(it, *out);
    return 1;
}

static int special_define_modify_macro(Interp *it, Env *env, Value *form, Value **out, char *err, size_t errsz) {
    const char *name = NULL;
    const char *updater_name = NULL;
    Value *name_symbol = NULL;
    Value *updater_symbol = NULL;
    Value *lambda_list = NULL;
    Value *updater = NULL;
    Value *existing = NULL;
    Value *place_param = NULL;
    Value *macro = NULL;
    Value *body_form = NULL;
    ValueArray lambda_items;
    ValueArray params;
    ValueArray helper_rest;
    ValueArray block_items;
    ValueArray wrapped;
    if (form->as.array.count != 4 && form->as.array.count != 5) {
        snprintf(err, errsz, "define-modify-macro expects name, lambda-list, function, and optional docstring");
        return 0;
    }
    name_symbol = form->as.array.items[1];
    if (!symbol_name(name_symbol, &name)) {
        snprintf(err, errsz, "define-modify-macro name must be a symbol");
        return 0;
    }
    if (value_is_self_evaluating_constant_form(name_symbol, NULL)) {
        snprintf(err, errsz, "define-modify-macro cannot use self-evaluating constant name '%s'", name);
        return 0;
    }
    if (special_operator_symbol_p(it, name_symbol)) {
        snprintf(err, errsz, "define-modify-macro cannot target special operator '%s'", name);
        return 0;
    }
    lambda_list = form->as.array.items[2];
    if (!validate_define_modify_macro_lambda_list(lambda_list, err, errsz)) return 0;
    if (!proper_form_to_array(lambda_list, &lambda_items)) {
        snprintf(err, errsz, "define-modify-macro lambda list must be a list");
        return 0;
    }
    updater = form->as.array.items[3];
    updater_symbol = updater;
    if (!symbol_name(updater_symbol, &updater_name)) {
        snprintf(err, errsz, "define-modify-macro function must be a symbol");
        return 0;
    }
    if (value_is_self_evaluating_constant_form(updater_symbol, NULL)) {
        snprintf(err, errsz, "define-modify-macro function cannot be the constant '%s'", updater_name);
        return 0;
    }
    if (special_operator_symbol_p(it, updater_symbol)) {
        snprintf(err, errsz, "define-modify-macro function cannot be special operator '%s'", updater_name);
        return 0;
    }
    if (env_lookup_function_symbol(env, updater_symbol, &existing) &&
        existing->type == VALUE_CLOSURE &&
        existing->as.closure.is_macro) {
        snprintf(err, errsz, "define-modify-macro function cannot be macro '%s'", updater_name);
        return 0;
    }
    if (form->as.array.count == 5 && form->as.array.items[4]->type != VALUE_STRING) {
        snprintf(err, errsz, "define-modify-macro optional docstring must be a string");
        return 0;
    }
    place_param = make_setf_expansion_temp(it, "modify-place");
    value_array_init(&params);
    value_array_push(&params, place_param);
    {
        int i;
        for (i = 0; i < lambda_items.count; ++i) value_array_push(&params, lambda_items.items[i]);
    }
    value_array_init(&helper_rest);
    value_array_push(&helper_rest, make_runtime_quote_form(it, updater));
    value_array_push(&helper_rest, make_runtime_quote_form(it, lambda_list));
    value_array_push(&helper_rest, place_param);
    value_array_init(&block_items);
    value_array_push(&block_items, make_symbol_value("block"));
    value_array_push(&block_items, make_symbol_value(name));
    value_array_push(&block_items, make_runtime_form_with_head(it, make_symbol_value("%define-modify-macro-expand"), &helper_rest));
    body_form = make_list_value(&block_items);
    value_array_init(&wrapped);
    value_array_push(&wrapped, body_form);
    macro = make_closure_value(make_list_value(&params), make_list_value(&wrapped), env, 1);
    env_define_function_symbol(env, name_symbol, macro);
    if (form->as.array.count == 5) {
        global_setf_doc_set_symbol(env, name_symbol, form->as.array.items[4]);
    } else {
        global_setf_doc_unbind_symbol(env, name_symbol);
    }
    *out = name_symbol;
    interp_set_single_value(it, *out);
    return 1;
}

static int special_define_compiler_macro(Interp *it, Env *env, Value *form, Value **out, char *err, size_t errsz) {
    const char *name = NULL;
    Value *name_symbol = NULL;
    Value *fn = NULL;
    ValueArray arr;
    int i;
    if (form->as.array.count < 4) {
        snprintf(err, errsz, "define-compiler-macro expects name, lambda-list, and body");
        return 0;
    }
    name_symbol = form->as.array.items[1];
    if (!symbol_name(name_symbol, &name)) {
        snprintf(err, errsz, "define-compiler-macro name must be a symbol");
        return 0;
    }
    if (value_is_self_evaluating_constant_form(name_symbol, NULL)) {
        snprintf(err, errsz, "define-compiler-macro cannot use self-evaluating constant name '%s'", name);
        return 0;
    }
    if (special_operator_symbol_p(it, name_symbol)) {
        snprintf(err, errsz, "define-compiler-macro cannot target special operator '%s'", name);
        return 0;
    }
    if (form->as.array.items[2]->type != VALUE_LIST) {
        snprintf(err, errsz, "define-compiler-macro lambda list must be a list");
        return 0;
    }
    value_array_init(&arr);
    value_array_push(&arr, make_symbol_value("lambda"));
    value_array_push(&arr, form->as.array.items[2]);
    for (i = 3; i < form->as.array.count; ++i) value_array_push(&arr, form->as.array.items[i]);
    if (!special_fn_like(it, env, make_list_value(&arr), 1, &fn, err, errsz)) return 0;
    global_compiler_macro_set_symbol(env, name_symbol, fn);
    *out = name_symbol;
    interp_set_single_value(it, *out);
    return 1;
}

static int special_deftype(Interp *it, Env *env, Value *form, Value **out, char *err, size_t errsz) {
    const char *name = NULL;
    Value *name_symbol = NULL;
    Value *expander = NULL;
    Value *doc = NULL;
    ValueArray arr;
    if (form->as.array.count < 4) {
        snprintf(err, errsz, "deftype expects name, lambda-list, and body");
        return 0;
    }
    name_symbol = form->as.array.items[1];
    if (!symbol_name(name_symbol, &name)) {
        snprintf(err, errsz, "deftype name must be a symbol");
        return 0;
    }
    if (value_is_self_evaluating_constant_form(name_symbol, NULL)) {
        snprintf(err, errsz, "deftype cannot use self-evaluating constant name '%s'", name);
        return 0;
    }
    value_array_init(&arr);
    value_array_push(&arr, make_symbol_value("lambda"));
    value_array_push(&arr, form->as.array.items[2]);
    {
        int i;
        for (i = 3; i < form->as.array.count; ++i) value_array_push(&arr, form->as.array.items[i]);
    }
    if (!special_fn_like(it, env, make_list_value(&arr), 1, &expander, err, errsz)) return 0;
    global_type_expander_set_symbol(env, name_symbol, expander);
    doc = (expander->type == VALUE_CLOSURE) ? expander->as.closure.documentation : NULL;
    if (doc != NULL) {
        global_type_doc_set_symbol(env, name_symbol, doc);
    } else {
        global_type_doc_unbind_symbol(env, name_symbol);
    }
    *out = name_symbol;
    interp_set_single_value(it, *out);
    return 1;
}

static int special_function(Interp *it, Env *env, Value *form, Value **out, char *err, size_t errsz) {
    Value *arg;
    if (form->as.array.count != 2) {
        snprintf(err, errsz, "function expects exactly one argument");
        return 0;
    }
    arg = form->as.array.items[1];
    if (arg->type == VALUE_SYMBOL) {
        if (!env_lookup_function_symbol(env, arg, out)) {
            snprintf(err, errsz, "undefined function '%s'", arg->as.str);
            return 0;
        }
    } else {
        ValueArray items;
        const char *head = NULL;
        if (proper_form_to_array(arg, &items) && items.count > 0 && symbol_name(items.items[0], &head) &&
            str_ieq(head, "lambda")) {
            return special_fn_like(it, env, arg, 0, out, err, errsz);
        }
        snprintf(err, errsz, "function expects a symbol or lambda form");
        return 0;
    }
    if ((*out)->type == VALUE_CLOSURE && (*out)->as.closure.is_macro) {
        snprintf(err, errsz, "'%s' names a macro, not a function", arg->as.str);
        return 0;
    }
    if ((*out)->type != VALUE_BUILTIN && (*out)->type != VALUE_CLOSURE) {
        snprintf(err, errsz, "value named '%s' is not callable", arg->as.str);
        return 0;
    }
    interp_set_single_value(it, *out);
    return 1;
}

static int expand_macro_form(Interp *it, Env *env, Value *macro, Value *form, Value **out, char *err, size_t errsz) {
    Env *call_env;
    DynamicFrame dynamic;
    ValueArray items;
    ValueArray args;
    int i;
    int body_start = 0;
    if (macro->type != VALUE_CLOSURE || !macro->as.closure.is_macro) {
        snprintf(err, errsz, "value is not a macro");
        return 0;
    }
    call_env = env_new(macro->as.closure.env);
    call_env->active_model = env->active_model;
    if (!process_declare_forms_in_body(call_env, macro->as.closure.body, &body_start, err, errsz)) return 0;
    if (!proper_form_to_array(form, &items)) {
        snprintf(err, errsz, "macro call must be a proper list");
        return 0;
    }
    value_array_init(&args);
    for (i = 1; i < items.count; ++i) value_array_push(&args, items.items[i]);
    dynamic_frame_init(&dynamic, it->dynamic);
    it->dynamic = &dynamic;
    if (!bind_macro_like_params(it,
                                call_env,
                                &dynamic,
                                macro->as.closure.params,
                                form,
                                make_environment_value(env),
                                &args,
                                err,
                                errsz)) {
        it->dynamic = dynamic.prev;
        dynamic_frame_dispose(&dynamic);
        return 0;
    }
    if (!eval_sequence_range(it, call_env, macro->as.closure.body, body_start, out, err, errsz)) {
        it->dynamic = dynamic.prev;
        dynamic_frame_dispose(&dynamic);
        return 0;
    }
    it->dynamic = dynamic.prev;
    dynamic_frame_dispose(&dynamic);
    return 1;
}

static int macroexpand_form_in_env(Interp *it,
                                   Env *env,
                                   Value *cur,
                                   int one_step,
                                   Value **out,
                                   char *err,
                                   size_t errsz) {
    int depth = 0;
    for (;;) {
        ValueArray items;
        Value *macro = NULL;
        Value *next = NULL;
        if (depth >= 64) {
            snprintf(err, errsz, "macro expansion exceeded the implementation limit");
            return 0;
        }
        if (cur->type == VALUE_SYMBOL &&
            !env_symbol_is_special(env, cur) &&
            env_lookup_symbol_macro_symbol(env, cur, &next)) {
            cur = next;
            ++depth;
            if (one_step) break;
            continue;
        }
        if (!proper_form_to_array(cur, &items) || items.count <= 0 || items.items[0]->type != VALUE_SYMBOL) break;
        if (!env_lookup_function_symbol(env, items.items[0], &macro)) break;
        if (macro->type != VALUE_CLOSURE || !macro->as.closure.is_macro) break;
        if (!expand_macro_form(it, env, macro, cur, &next, err, errsz)) return 0;
        cur = next;
        ++depth;
        if (one_step) break;
    }
    *out = cur;
    return 1;
}

static int special_macroexpand_like(Interp *it, Env *env, Value *form, int one_step, Value **out, char *err, size_t errsz) {
    Value *cur = NULL;
    Value *env_value = NULL;
    Env *macro_env = env;
    const char *who = one_step ? "macroexpand-1" : "macroexpand";
    if (form->as.array.count != 2 && form->as.array.count != 3) {
        snprintf(err, errsz, "%s expects a form and optional environment", who);
        return 0;
    }
    if (!eval(it, env, form->as.array.items[1], &cur, err, errsz)) return 0;
    if (form->as.array.count == 3) {
        if (!eval(it, env, form->as.array.items[2], &env_value, err, errsz)) return 0;
        if (!resolve_environment_argument(env, env_value, who, &macro_env, err, errsz)) return 0;
    }
    if (!macroexpand_form_in_env(it, macro_env, cur, one_step, out, err, errsz)) return 0;
    interp_set_single_value(it, *out);
    return 1;
}

static int special_with_hash_table_iterator(Interp *it, Env *env, Value *form, Value **out, char *err, size_t errsz) {
    ValueArray binding;
    ValueArray params;
    ValueArray helper_args;
    ValueArray helper_body;
    ValueArray body;
    Value *table = NULL;
    Value *body_list = NULL;
    Value *macro_form = NULL;
    Value *macro_body = NULL;
    Value *macro_fn = NULL;
    Value *table_symbol = NULL;
    Value *index_symbol = NULL;
    Env *child = NULL;
    const char *name = NULL;
    int body_start = 0;
    if (form->as.array.count < 3) {
        snprintf(err, errsz, "with-hash-table-iterator expects a binding spec and body");
        return 0;
    }
    if (!proper_form_to_array(form->as.array.items[1], &binding) || binding.count != 2) {
        snprintf(err, errsz, "with-hash-table-iterator expects a binding spec of the form (name hash-table)");
        return 0;
    }
    if (!reject_constant_binding_target(binding.items[0], "with-hash-table-iterator name", err, errsz)) return 0;
    if (!symbol_name(binding.items[0], &name)) {
        snprintf(err, errsz, "with-hash-table-iterator name must be a symbol");
        return 0;
    }
    if (!eval(it, env, binding.items[1], &table, err, errsz)) return 0;
    if (table->type != VALUE_HASH_TABLE) {
        snprintf(err, errsz, "with-hash-table-iterator expects a hash-table");
        return 0;
    }
    child = env_new(env);
    child->active_model = env->active_model;
    table_symbol = make_generated_uninterned_symbol(it, "hti-table");
    index_symbol = make_generated_uninterned_symbol(it, "hti-index");
    env_define_value_symbol(child, table_symbol, table);
    env_define_value_symbol(child, index_symbol, make_int_value(bigint_from_i64(0)));

    value_array_init(&params);
    value_array_init(&helper_args);
    value_array_push(&helper_args, make_symbol_value("%hash-table-iterator-next-form"));
    value_array_push(&helper_args, make_quote_form(index_symbol));
    value_array_push(&helper_args, make_quote_form(table_symbol));
    macro_form = make_list_value(&helper_args);

    value_array_init(&helper_body);
    value_array_push(&helper_body, macro_form);
    macro_body = make_list_value(&helper_body);
    macro_fn = make_closure_value(make_list_value(&params), macro_body, child, 1);
    env_define_function_symbol(child, binding.items[0], macro_fn);

    value_array_init(&body);
    for (int i = 2; i < form->as.array.count; ++i) value_array_push(&body, form->as.array.items[i]);
    body_list = make_list_value(&body);
    if (!process_declare_forms_in_body(child, body_list, &body_start, err, errsz)) return 0;
    if (!eval_sequence_range(it, child, body_list, body_start, out, err, errsz)) return 0;
    return 1;
}

static int parse_package_iterator_symbol_types(ValueArray *binding,
                                               const char *who,
                                               int *include_internal,
                                               int *include_external,
                                               int *include_inherited,
                                               char *err,
                                               size_t errsz) {
    int i;
    if (include_internal != NULL) *include_internal = 0;
    if (include_external != NULL) *include_external = 0;
    if (include_inherited != NULL) *include_inherited = 0;
    if (binding == NULL || binding->count < 3) {
        snprintf(err, errsz, "%s expects at least one symbol type", who);
        return 0;
    }
    for (i = 2; i < binding->count; ++i) {
        const char *name = NULL;
        if (!symbol_name(binding->items[i], &name)) {
            snprintf(err, errsz, "%s symbol type must be a symbol", who);
            return 0;
        }
        if (str_ieq(name, ":internal")) {
            if (include_internal != NULL) *include_internal = 1;
        } else if (str_ieq(name, ":external")) {
            if (include_external != NULL) *include_external = 1;
        } else if (str_ieq(name, ":inherited")) {
            if (include_inherited != NULL) *include_inherited = 1;
        } else {
            snprintf(err, errsz, "%s does not recognize symbol type '%s'", who, name);
            return 0;
        }
    }
    return 1;
}

static int special_with_package_iterator(Interp *it, Env *env, Value *form, Value **out, char *err, size_t errsz) {
    ValueArray binding;
    ValueArray params;
    ValueArray helper_args;
    ValueArray helper_body;
    ValueArray body;
    ValueArray packages;
    ValueArray snapshot;
    ValueArray entries;
    Value *package_list = NULL;
    Value *body_list = NULL;
    Value *entries_vector = NULL;
    Value *macro_form = NULL;
    Value *macro_body = NULL;
    Value *macro_fn = NULL;
    Value *entries_symbol = NULL;
    Value *index_symbol = NULL;
    Env *child = NULL;
    const char *name = NULL;
    int include_internal = 0;
    int include_external = 0;
    int include_inherited = 0;
    int body_start = 0;
    int i;
    int j;
    if (form->as.array.count < 2) {
        snprintf(err, errsz, "with-package-iterator expects a binding spec");
        return 0;
    }
    if (!proper_form_to_array(form->as.array.items[1], &binding) || binding.count < 3) {
        snprintf(err, errsz, "with-package-iterator expects a binding spec of the form (name package-list-form symbol-type+)");
        return 0;
    }
    if (!reject_constant_binding_target(binding.items[0], "with-package-iterator name", err, errsz)) return 0;
    if (!symbol_name(binding.items[0], &name)) {
        snprintf(err, errsz, "with-package-iterator name must be a symbol");
        return 0;
    }
    if (!parse_package_iterator_symbol_types(&binding,
                                             "with-package-iterator",
                                             &include_internal,
                                             &include_external,
                                             &include_inherited,
                                             err,
                                             errsz)) {
        return 0;
    }
    if (!eval(it, env, binding.items[1], &package_list, err, errsz)) return 0;
    if (!parse_package_designator_list(it, env, package_list, "with-package-iterator", &packages, err, errsz)) return 0;
    value_array_init(&snapshot);
    for (i = 0; i < packages.count; ++i) {
        if (!collect_package_iterator_entries(it,
                                              packages.items[i],
                                              include_internal,
                                              include_external,
                                              include_inherited,
                                              &entries,
                                              err,
                                              errsz)) {
            return 0;
        }
        for (j = 0; j < entries.count; ++j) value_array_push(&snapshot, entries.items[j]);
    }
    entries_vector = make_vector_value(&snapshot);

    child = env_new(env);
    child->active_model = env->active_model;
    entries_symbol = make_generated_uninterned_symbol(it, "pkg-iter-entries");
    index_symbol = make_generated_uninterned_symbol(it, "pkg-iter-index");
    env_define_value_symbol(child, entries_symbol, entries_vector);
    env_define_value_symbol(child, index_symbol, make_int_value(bigint_from_i64(0)));

    value_array_init(&params);
    value_array_init(&helper_args);
    value_array_push(&helper_args, make_symbol_value("%package-iterator-next-form"));
    value_array_push(&helper_args, make_quote_form(index_symbol));
    value_array_push(&helper_args, make_quote_form(entries_symbol));
    macro_form = make_list_value(&helper_args);

    value_array_init(&helper_body);
    value_array_push(&helper_body, macro_form);
    macro_body = make_list_value(&helper_body);
    macro_fn = make_closure_value(make_list_value(&params), macro_body, child, 1);
    env_define_function_symbol(child, binding.items[0], macro_fn);

    value_array_init(&body);
    for (i = 2; i < form->as.array.count; ++i) value_array_push(&body, form->as.array.items[i]);
    body_list = make_list_value(&body);
    if (!process_declare_forms_in_body(child, body_list, &body_start, err, errsz)) return 0;
    if (!eval_sequence_range(it, child, body_list, body_start, out, err, errsz)) return 0;
    return 1;
}

static int special_with_output_to_string(Interp *it, Env *env, Value *form, Value **out, char *err, size_t errsz) {
    UnwindFrame frame;
    ValueArray binding;
    ValueArray body;
    ValueArray cleanups;
    Value *body_list = NULL;
    Value *stream = NULL;
    Value *stream_symbol = NULL;
    Value *target_string = NULL;
    Value *element_type = NULL;
    Value *body_result = it->nil;
    Env *child = NULL;
    const char *name = NULL;
    int body_start = 0;
    int idx = 1;
    int body_ok = 0;
    char body_err[1024];
    char *text = NULL;
    Value *target_string_value = NULL;
    Value *element_type_value = NULL;
    if (form->as.array.count < 2) {
        snprintf(err, errsz, "with-output-to-string expects a binding spec");
        return 0;
    }
    if (!proper_form_to_array(form->as.array.items[1], &binding) || binding.count < 1) {
        snprintf(err, errsz, "with-output-to-string expects a binding spec of the form (var &optional string &key element-type)");
        return 0;
    }
    if (!reject_constant_binding_target(binding.items[0], "with-output-to-string variable", err, errsz)) return 0;
    if (!symbol_name(binding.items[0], &name)) {
        snprintf(err, errsz, "with-output-to-string variable must be a symbol");
        return 0;
    }
    if (idx < binding.count && !value_is_keyword(binding.items[idx])) {
        target_string = binding.items[idx];
        ++idx;
    }
    while (idx < binding.count) {
        Value *key = binding.items[idx];
        if (!value_is_keyword(key) || idx + 1 >= binding.count) {
            snprintf(err, errsz, "with-output-to-string binding keywords must appear in keyword/value pairs");
            return 0;
        }
        if (keyword_matches(key, ":element-type")) {
            element_type = binding.items[idx + 1];
        } else {
            snprintf(err, errsz, "unsupported with-output-to-string keyword '%s'", key->as.str);
            return 0;
        }
        idx += 2;
    }
    if (target_string != NULL) {
        if (!eval(it, env, target_string, &target_string_value, err, errsz)) return 0;
    }
    if (element_type != NULL) {
        if (!eval(it, env, element_type, &element_type_value, err, errsz)) return 0;
    }
    if (target_string_value != NULL && target_string_value->type != VALUE_NIL) {
        if (target_string_value->type != VALUE_STRING || !target_string_value->has_fill_pointer) {
            snprintf(err, errsz, "with-output-to-string target string must be a string with a fill pointer");
            return 0;
        }
    }
    if (!validate_string_output_stream_element_type(element_type_value, "with-output-to-string", err, errsz)) return 0;
    stream = make_string_output_stream_value(string_output_stream_element_type_kind(element_type_value));
    child = env_new(env);
    child->active_model = env->active_model;
    env_define_value_symbol(child, binding.items[0], stream);
    stream_symbol = make_generated_uninterned_symbol(it, "wots-stream");
    env_define_value_symbol(child, stream_symbol, stream);
    value_array_init(&cleanups);
    value_array_push(&cleanups, make_form_from2(make_symbol_value("close"), stream_symbol));
    frame.prev = it->unwinds;
    frame.env = child;
    frame.cleanup = make_list_value(&cleanups);
    frame.saved_blocks = it->blocks;
    frame.saved_dynamic = it->dynamic;
    frame.saved_tagbodies = it->tagbodies;
    frame.saved_catches = it->catches;
    frame.saved_handlers = it->handlers;
    frame.saved_restarts = it->restarts;
    frame.saved_condition_restart_assocs = it->condition_restart_assocs;
    it->unwinds = &frame;
    value_array_init(&body);
    for (int i = 2; i < form->as.array.count; ++i) value_array_push(&body, form->as.array.items[i]);
    body_list = make_list_value(&body);
    body_err[0] = '\0';
    body_ok = process_declare_forms_in_body(child, body_list, &body_start, err, errsz) &&
              eval_sequence_range(it, child, body_list, body_start, &body_result, err, errsz);
    if (!body_ok) snprintf(body_err, sizeof(body_err), "%s", err);
    if (!run_unwind_cleanup_frame(it, &frame, err, errsz)) return 0;
    if (!body_ok) {
        snprintf(err, errsz, "%s", body_err);
        return 0;
    }
    text = string_output_stream_take_text(stream);
    if (target_string_value != NULL && target_string_value->type == VALUE_STRING) {
        int text_len = (int)strlen(text);
        int start = target_string_value->fill_pointer;
        int total = value_string_total_size(target_string_value);
        int i = 0;
        if (start > total || text_len > total - start) {
            free(text);
            snprintf(err, errsz, "with-output-to-string target string does not have enough room past its fill pointer");
            return 0;
        }
        for (i = 0; i < text_len; ++i) {
            if (!string_storage_write_char(target_string_value, start + i, (unsigned char)text[i])) {
                free(text);
                snprintf(err, errsz, "with-output-to-string target string does not have enough room past its fill pointer");
                return 0;
            }
        }
        target_string_value->fill_pointer = start + text_len;
        *out = target_string_value;
    } else {
        *out = make_string_value(text);
    }
    free(text);
    interp_set_single_value(it, *out);
    return 1;
}

