static Value *pprint_logical_block_stream_state_symbol(Interp *it) {
    static Value *symbol = NULL;
    if (symbol == NULL) symbol = make_generated_uninterned_symbol(it, "pprint-logical-block-stream");
    return symbol;
}

static Value *portable_type_of_value(Interp *it, Value *value);

static int special_print_unreadable_object(Interp *it, Env *env, Value *form, Value **out, char *err, size_t errsz) {
    ValueArray binding;
    ValueArray body;
    Value *object_expr = NULL;
    Value *stream_expr = NULL;
    Value *type_expr = NULL;
    Value *identity_expr = NULL;
    Value *object_value = NULL;
    Value *stream_value = NULL;
    Value *stream = NULL;
    Value *type_value = NULL;
    Value *identity_value = NULL;
    Value *type_of_object = NULL;
    Value *body_list = NULL;
    Value *body_result = it->nil;
    Value *condition = NULL;
    Env *child = NULL;
    int body_start = 0;
    int idx = 2;
    int any_previous = 0;
    int body_ok = 0;
    int body_has_forms = 0;
    char *type_text = NULL;
    char *message_text = NULL;
    char body_err[1024];
    char identity_text[64];
    if (form->as.array.count < 2) {
        snprintf(err, errsz, "print-unreadable-object expects a binding spec");
        return 0;
    }
    if (!proper_form_to_array(form->as.array.items[1], &binding) || binding.count < 2) {
        snprintf(err, errsz, "print-unreadable-object expects a binding spec of the form (object stream &key type identity)");
        return 0;
    }
    object_expr = binding.items[0];
    stream_expr = binding.items[1];
    while (idx < binding.count) {
        Value *key = binding.items[idx];
        Value *val = NULL;
        if (!value_is_keyword(key) || idx + 1 >= binding.count) {
            snprintf(err, errsz, "print-unreadable-object binding keywords must appear in keyword/value pairs");
            return 0;
        }
        val = binding.items[idx + 1];
        if (keyword_matches(key, ":type")) {
            type_expr = val;
        } else if (keyword_matches(key, ":identity")) {
            identity_expr = val;
        } else {
            snprintf(err, errsz, "unsupported print-unreadable-object keyword '%s'", key->as.str);
            return 0;
        }
        idx += 2;
    }
    if (!eval(it, env, object_expr, &object_value, err, errsz)) return 0;
    if (!eval(it, env, stream_expr, &stream_value, err, errsz)) return 0;
    if (!resolve_output_stream_designator(it, stream_value, "print-unreadable-object", &stream, err, errsz)) return 0;
    if (type_expr != NULL && !eval(it, env, type_expr, &type_value, err, errsz)) return 0;
    if (identity_expr != NULL && !eval(it, env, identity_expr, &identity_value, err, errsz)) return 0;
    if (runtime_special_truthy(it, env, "*print-readably*")) {
        if (!condition_make_instance(it,
                                     common_lisp_runtime_symbol_or_fallback(it, "print-not-readable"),
                                     it->nil,
                                     it->nil,
                                     NULL,
                                     NULL,
                                     object_value,
                                     &condition,
                                     err,
                                     errsz)) {
            return 0;
        }
        if (!condition_invoke_handlers(it, env, condition, err, errsz)) return 0;
        if (!condition_render_message_text(it, env, condition, &message_text, err, errsz)) return 0;
        it->pending_condition = condition;
        snprintf(err, errsz, "%s", (message_text != NULL && message_text[0] != '\0') ? message_text : "print-not-readable");
        free(message_text);
        return 0;
    }
    value_array_init(&body);
    for (int i = 2; i < form->as.array.count; ++i) value_array_push(&body, form->as.array.items[i]);
    body_list = make_list_value(&body);
    body_err[0] = '\0';
    child = env_new(env);
    if (child == NULL) {
        free(type_text);
        value_array_dispose(&body);
        snprintf(err, errsz, "print-unreadable-object could not allocate body environment");
        return 0;
    }
    child->active_model = env->active_model;
    if (!process_declare_forms_in_body(child, body_list, &body_start, err, errsz)) {
        free(type_text);
        value_array_dispose(&body);
        return 0;
    }
    body_has_forms = (body_start < body.count);
    output_stream_write_text(it, stream, "#<");
    if (type_value != NULL && value_is_truthy(type_value)) {
        type_of_object = portable_type_of_value(it, object_value);
        type_text = value_to_string_repr(it, type_of_object);
        output_stream_write_text(it, stream, (type_text != NULL) ? type_text : "<type>");
        any_previous = 1;
    }
    if (body_has_forms) {
        if (any_previous) output_stream_write_char(it, stream, ' ');
        body_ok = eval_sequence_range(it, child, body_list, body_start, &body_result, err, errsz);
        if (!body_ok) snprintf(body_err, sizeof(body_err), "%s", err);
        if (!body_ok) {
            snprintf(err, errsz, "%s", body_err);
            free(type_text);
            value_array_dispose(&body);
            return 0;
        }
        (void)body_result;
        any_previous = 1;
    }
    (void)body_result;
    if (identity_value != NULL && value_is_truthy(identity_value)) {
        if (any_previous) output_stream_write_char(it, stream, ' ');
        snprintf(identity_text, sizeof(identity_text), "%p", (void *)object_value);
        output_stream_write_text(it, stream, identity_text);
        any_previous = 1;
    }
    output_stream_write_char(it, stream, '>');
    free(type_text);
    value_array_dispose(&body);
    *out = it->nil;
    interp_set_single_value(it, *out);
    return 1;
}

static int special_pprint_logical_block(Interp *it, Env *env, Value *form, Value **out, char *err, size_t errsz) {
    UnwindFrame frame;
    ValueArray binding;
    ValueArray body;
    ValueArray cleanups;
    Value *body_list = NULL;
    Value *outer_stream_value = NULL;
    Value *outer_stream = NULL;
    Value *capture_stream = NULL;
    Value *stream_symbol = NULL;
    Value *block_name_value = NULL;
    Value *object_expr = NULL;
    Value *object_value = NULL;
    Value *body_result = it->nil;
    Value *prefix_value = NULL;
    Value *per_line_prefix_value = NULL;
    Value *suffix_value = NULL;
    char *prefix_text = NULL;
    char *per_line_prefix_text = NULL;
    char *suffix_text = NULL;
    char *text = NULL;
    Env *child = NULL;
    Env *block_env = NULL;
    const char *name = NULL;
    int body_start = 0;
    int idx = 1;
    int body_ok = 0;
    char body_err[1024];
    if (form->as.array.count < 3) {
        snprintf(err, errsz, "pprint-logical-block expects a binding spec and body");
        return 0;
    }
    if (!proper_form_to_array(form->as.array.items[1], &binding) || binding.count < 1) {
        snprintf(err, errsz, "pprint-logical-block expects a binding spec of the form (stream object &key prefix per-line-prefix suffix)");
        return 0;
    }
    if (!reject_constant_binding_target(binding.items[0], "pprint-logical-block stream", err, errsz)) return 0;
    if (!symbol_name(binding.items[0], &name)) {
        snprintf(err, errsz, "pprint-logical-block stream must be a symbol");
        return 0;
    }
    (void)name;
    if (!eval(it, env, binding.items[0], &outer_stream_value, err, errsz)) return 0;
    if (!resolve_output_stream_designator(it, outer_stream_value, "pprint-logical-block", &outer_stream, err, errsz)) return 0;
    if (idx < binding.count && !value_is_keyword(binding.items[idx])) {
        object_expr = binding.items[idx];
        ++idx;
    }
    while (idx < binding.count) {
        Value *key = binding.items[idx];
        Value *val = NULL;
        if (!value_is_keyword(key) || idx + 1 >= binding.count) {
            snprintf(err, errsz, "pprint-logical-block binding keywords must appear in keyword/value pairs");
            return 0;
        }
        val = binding.items[idx + 1];
        if (keyword_matches(key, ":prefix")) {
            prefix_value = val;
        } else if (keyword_matches(key, ":per-line-prefix")) {
            per_line_prefix_value = val;
        } else if (keyword_matches(key, ":suffix")) {
            suffix_value = val;
        } else {
            snprintf(err, errsz, "unsupported pprint-logical-block keyword '%s'", key->as.str);
            return 0;
        }
        idx += 2;
    }
    if (object_expr != NULL) {
        if (!eval(it, env, object_expr, &object_value, err, errsz)) return 0;
    }
    if (object_value == NULL) object_value = it->nil;
    if (prefix_value != NULL && prefix_value->type != VALUE_NIL) {
        if (!value_to_string_designator_text(prefix_value, "pprint-logical-block :prefix", &prefix_text, err, errsz)) return 0;
    } else {
        prefix_text = xstrdup_c("");
    }
    if (per_line_prefix_value != NULL && per_line_prefix_value->type != VALUE_NIL) {
        if (!value_to_string_designator_text(per_line_prefix_value, "pprint-logical-block :per-line-prefix", &per_line_prefix_text, err, errsz)) {
            free(prefix_text);
            return 0;
        }
    }
    if (suffix_value != NULL && suffix_value->type != VALUE_NIL) {
        if (!value_to_string_designator_text(suffix_value, "pprint-logical-block :suffix", &suffix_text, err, errsz)) {
            free(prefix_text);
            free(per_line_prefix_text);
            return 0;
        }
    } else {
        suffix_text = xstrdup_c("");
    }
    if (!value_is_list_like(object_value) && object_value->type != VALUE_NIL) {
        char *object_text = NULL;
        if (!format_render_argument_text(it, env, object_value, 1, -1, &object_text, err, errsz)) {
            free(prefix_text);
            free(per_line_prefix_text);
            free(suffix_text);
            return 0;
        }
        output_stream_write_text(it, outer_stream, object_text);
        free(object_text);
        free(prefix_text);
        free(per_line_prefix_text);
        free(suffix_text);
        *out = it->nil;
        interp_set_single_value(it, *out);
        return 1;
    }
    capture_stream = make_string_output_stream_value(STRING_STREAM_ELEMENT_CHARACTER);
    output_stream_set_pretty_context_depth(it, capture_stream, runtime_special_truthy(it, env, "*print-pretty*") ? 1 : 0);
    if (prefix_text[0] != '\0') {
        output_stream_write_text(it, capture_stream, prefix_text);
        capture_stream->as.string_output_stream.pretty_block_column = capture_stream->as.string_output_stream.current_column;
        capture_stream->as.string_output_stream.pretty_indent_column = capture_stream->as.string_output_stream.current_column;
    }
    child = env_new(env);
    child->active_model = env->active_model;
    env_define_value_symbol(child, binding.items[0], capture_stream);
    stream_symbol = make_generated_uninterned_symbol(it, "pprint-logical-block-stream");
    env_define_value_symbol(child, stream_symbol, capture_stream);
    env_define_value_symbol(child, pprint_logical_block_stream_state_symbol(it), capture_stream);
    block_name_value = make_generated_uninterned_symbol(it, "pprint-logical-block-exit");
    env_define_value_symbol(child, pprint_logical_block_object_state_symbol(it), object_value);
    env_define_value_symbol(child, pprint_logical_block_index_state_symbol(it), make_int_value(bigint_from_i64(0)));
    env_define_value_symbol(child, pprint_logical_block_name_state_symbol(it), block_name_value);
    block_env = env_new(child);
    block_env->active_model = child->active_model;
    block_env->block_name = block_name_value;
    value_array_init(&cleanups);
    value_array_push(&cleanups, make_form_from2(make_symbol_value("close"), stream_symbol));
    frame.prev = it->unwinds;
    frame.env = block_env;
    frame.cleanup = make_list_value(&cleanups);
    frame.saved_blocks = it->blocks;
    frame.saved_dynamic = it->dynamic;
    frame.saved_tagbodies = it->tagbodies;
    frame.saved_catches = it->catches;
    frame.saved_handlers = it->handlers;
    frame.saved_restarts = it->restarts;
    frame.saved_condition_restart_assocs = it->condition_restart_assocs;
    it->unwinds = &frame;
    value_array_init(&body);
    for (int i = 2; i < form->as.array.count; ++i) value_array_push(&body, form->as.array.items[i]);
    body_list = make_list_value(&body);
    body_err[0] = '\0';
    if (process_declare_forms_in_body(block_env, body_list, &body_start, err, errsz)) {
        ValueArray body_exec;
        value_array_init(&body_exec);
        for (int i = body_start; i < body.count; ++i) value_array_push(&body_exec, body.items[i]);
        body_list = make_list_value(&body_exec);
        value_array_dispose(&body_exec);
        body_ok = eval_block_body(it, block_env, body_list, &body_result, err, errsz);
    }
    if (!body_ok) snprintf(body_err, sizeof(body_err), "%s", err);
    if (!run_unwind_cleanup_frame(it, &frame, err, errsz)) {
        free(prefix_text);
        free(per_line_prefix_text);
        free(suffix_text);
        return 0;
    }
    if (!body_ok) {
        free(prefix_text);
        free(per_line_prefix_text);
        free(suffix_text);
        snprintf(err, errsz, "%s", body_err);
        return 0;
    }
    text = string_output_stream_take_text(capture_stream);
    format_write_logical_block_text(it, outer_stream, "", text, suffix_text, per_line_prefix_text);
    free(text);
    free(prefix_text);
    free(per_line_prefix_text);
    free(suffix_text);
    (void)object_value;
    *out = body_result;
    interp_set_single_value(it, *out);
    return 1;
}

static int pprint_logical_block_sequence_length(Value *object) {
    if (object == NULL || object->type == VALUE_NIL) return 0;
    if (object->type == VALUE_LIST) return object->as.array.count;
    if (object->type == VALUE_VECTOR) {
        if (value_array_rank(object) != 1) return -1;
        return value_vector_sequence_length(object);
    }
    if (object->type == VALUE_STRING) return value_string_sequence_length(object);
    return -1;
}

static int pprint_logical_block_print_length_limit(Interp *it, Env *env, int *out_limit, int *out_has_limit, char *err, size_t errsz) {
    Value *length_value = NULL;
    int is_bound = 0;
    int limit = -1;
    if (out_limit != NULL) *out_limit = -1;
    if (out_has_limit != NULL) *out_has_limit = 0;
    if (!symbol_value_lookup_runtime_special(it, env, "*print-length*", &length_value, &is_bound)) return 1;
    if (!is_bound) return 1;
    if (!value_to_optional_nonnegative(length_value, "*print-length*", &limit, err, errsz)) return 0;
    if (limit >= 0) {
        if (out_limit != NULL) *out_limit = limit;
        if (out_has_limit != NULL) *out_has_limit = 1;
    }
    return 1;
}

static int pprint_logical_block_emit_length_abbreviation(Interp *it, Env *env, Value *block_name, Value **out, char *err, size_t errsz) {
    Value *stream = NULL;
    if (!env_lookup_value_symbol(env, pprint_logical_block_stream_state_symbol(it), &stream)) {
        snprintf(err, errsz, "pprint-logical-block stream state is unavailable");
        return 0;
    }
    output_stream_write_text(it, stream, "...");
    return special_return_from_named(it, env, block_name, NULL, out, err, errsz);
}

static int pprint_logical_block_sequence_item(Interp *it,
                                              Value *object,
                                              int index,
                                              Value **out,
                                              char *err,
                                              size_t errsz) {
    int ch = 0;
    if (object == NULL || out == NULL) {
        snprintf(err, errsz, "pprint-logical-block sequence state is unavailable");
        return 0;
    }
    if (object->type == VALUE_LIST) {
        if (index < 0 || index >= object->as.array.count) {
            snprintf(err, errsz, "pprint-pop called after logical block exhausted");
            return 0;
        }
        *out = object->as.array.items[index];
        return 1;
    }
    if (object->type == VALUE_VECTOR) {
        if (value_array_rank(object) != 1) {
            snprintf(err, errsz, "pprint-pop sequence state expects a one-dimensional vector");
            return 0;
        }
        if (!array_row_major_read(object, index, out, err, errsz)) return 0;
        return 1;
    }
    if (object->type == VALUE_STRING) {
        if (index < 0 || index >= value_string_sequence_length(object)) {
            snprintf(err, errsz, "pprint-pop called after logical block exhausted");
            return 0;
        }
        if (!string_storage_read_char(object, index, &ch)) {
            snprintf(err, errsz, "pprint-pop sequence state expects a string");
            return 0;
        }
        *out = make_char_value(ch);
        return 1;
    }
    if (object->type == VALUE_NIL) {
        snprintf(err, errsz, "pprint-pop called after logical block exhausted");
        return 0;
    }
    snprintf(err, errsz, "pprint-logical-block sequence state expects a list, vector, or string");
    return 0;
}

static int pprint_logical_block_is_exhausted(Interp *it, Env *env, Value **out_object, Value **out_cursor, Value **out_block_name, int *out_index, char *err, size_t errsz) {
    Value *object = NULL;
    Value *cursor = NULL;
    Value *index_value = NULL;
    Value *block_name = NULL;
    int index = 0;
    if (out_object != NULL) *out_object = NULL;
    if (out_cursor != NULL) *out_cursor = NULL;
    if (out_block_name != NULL) *out_block_name = NULL;
    if (out_index != NULL) *out_index = 0;
    if (!env_lookup_value_symbol(env, pprint_logical_block_object_state_symbol(it), &object)) {
        snprintf(err, errsz, "pprint-logical-block object state is unavailable");
        return 0;
    }
    if (!env_lookup_value_symbol(env, pprint_logical_block_name_state_symbol(it), &block_name)) {
        snprintf(err, errsz, "pprint-logical-block block name state is unavailable");
        return 0;
    }
    if (object->type == VALUE_LIST || object->type == VALUE_VECTOR || object->type == VALUE_STRING) {
        int length = pprint_logical_block_sequence_length(object);
        if (length < 0) {
            snprintf(err, errsz, "pprint-logical-block sequence state is unavailable");
            return 0;
        }
        if (!env_lookup_value_symbol(env, pprint_logical_block_index_state_symbol(it), &index_value)) {
            snprintf(err, errsz, "pprint-logical-block index state is unavailable");
            return 0;
        }
        if (!value_to_non_negative_index(it, index_value, "pprint-pop", &index, err, errsz)) return 0;
        if (out_index != NULL) *out_index = index;
        if (out_object != NULL) *out_object = object;
        if (out_block_name != NULL) *out_block_name = block_name;
        return (index >= length);
    }
    if (object->type == VALUE_NIL) {
        if (out_object != NULL) *out_object = object;
        if (out_block_name != NULL) *out_block_name = block_name;
        return 1;
    }
    if (out_object != NULL) *out_object = object;
    if (out_cursor != NULL) *out_cursor = object;
    if (out_block_name != NULL) *out_block_name = block_name;
    return 0;
}

static int special_pprint_pop(Interp *it, Env *env, Value *form, Value **out, char *err, size_t errsz) {
    Value *object = NULL;
    Value *index_value = NULL;
    Value *item = NULL;
    Value *block_name = NULL;
    int index = 0;
    int length = -1;
    int has_length = 0;
    if (form->as.array.count != 1) {
        snprintf(err, errsz, "pprint-pop expects no arguments");
        return 0;
    }
    if (!env_lookup_value_symbol(env, pprint_logical_block_object_state_symbol(it), &object)) {
        snprintf(err, errsz, "pprint-logical-block object state is unavailable");
        return 0;
    }
    if (!env_lookup_value_symbol(env, pprint_logical_block_name_state_symbol(it), &block_name)) {
        snprintf(err, errsz, "pprint-logical-block block name state is unavailable");
        return 0;
    }
    if (object == NULL) {
        snprintf(err, errsz, "pprint-pop can only be used inside pprint-logical-block");
        return 0;
    }
    if (object->type == VALUE_NIL) {
        if (!env_lookup_value_symbol(env, pprint_logical_block_index_state_symbol(it), &index_value)) {
            snprintf(err, errsz, "pprint-logical-block index state is unavailable");
            return 0;
        }
        if (!value_to_non_negative_index(it, index_value, "pprint-pop", &index, err, errsz)) return 0;
        if (!pprint_logical_block_print_length_limit(it, env, &length, &has_length, err, errsz)) return 0;
        if (has_length && index >= length) {
            return pprint_logical_block_emit_length_abbreviation(it, env, block_name, out, err, errsz);
        }
        env_set_variable_symbol(it, env, pprint_logical_block_index_state_symbol(it), make_int_value(bigint_from_i64((int64_t)(index + 1))));
        *out = it->nil;
        interp_set_single_value(it, *out);
        return 1;
    }
    if (!env_lookup_value_symbol(env, pprint_logical_block_index_state_symbol(it), &index_value)) {
        snprintf(err, errsz, "pprint-logical-block state is unavailable");
        return 0;
    }
    if (!value_to_non_negative_index(it, index_value, "pprint-pop", &index, err, errsz)) return 0;
    if (!pprint_logical_block_print_length_limit(it, env, &length, &has_length, err, errsz)) return 0;
    if (has_length && index >= length) {
        return pprint_logical_block_emit_length_abbreviation(it, env, block_name, out, err, errsz);
    }
    if (object->type == VALUE_LIST || object->type == VALUE_VECTOR || object->type == VALUE_STRING) {
        int sequence_length = pprint_logical_block_sequence_length(object);
        if (sequence_length < 0) {
            snprintf(err, errsz, "pprint-pop sequence state is unavailable");
            return 0;
        }
        if (index >= sequence_length) {
            snprintf(err, errsz, "pprint-pop called after logical block exhausted");
            return 0;
        }
        if (!pprint_logical_block_sequence_item(it, object, index, &item, err, errsz)) return 0;
        env_set_variable_symbol(it, env, pprint_logical_block_index_state_symbol(it), make_int_value(bigint_from_i64((int64_t)(index + 1))));
        *out = item;
        interp_set_single_value(it, *out);
        return 1;
    }
    if (object->type == VALUE_CONS) {
        *out = object->as.cons.car;
        env_set_variable_symbol(it, env, pprint_logical_block_object_state_symbol(it), object->as.cons.cdr);
    } else {
        *out = object;
        env_set_variable_symbol(it, env, pprint_logical_block_object_state_symbol(it), it->nil);
    }
    interp_set_single_value(it, *out);
    return 1;
}

static int special_pprint_exit_if_list_exhausted(Interp *it, Env *env, Value *form, Value **out, char *err, size_t errsz) {
    Value *object = NULL;
    Value *block_name = NULL;
    int index = 0;
    int exhausted = 0;
    if (form->as.array.count != 1) {
        snprintf(err, errsz, "pprint-exit-if-list-exhausted expects no arguments");
        return 0;
    }
    err[0] = '\0';
    exhausted = pprint_logical_block_is_exhausted(it, env, &object, NULL, &block_name, &index, err, errsz);
    if (err[0] != '\0') return 0;
    if (!exhausted) {
        *out = it->nil;
        interp_set_single_value(it, *out);
        return 1;
    }
    if (block_name == NULL) {
        snprintf(err, errsz, "pprint-exit-if-list-exhausted can only be used inside pprint-logical-block");
        return 0;
    }
    return special_return_from_named(it, env, block_name, NULL, out, err, errsz);
}

static int special_with_input_from_string(Interp *it, Env *env, Value *form, Value **out, char *err, size_t errsz) {
    UnwindFrame frame;
    ValueArray binding;
    ValueArray body;
    ValueArray cleanups;
    ValueArray body_values;
    Value *source = NULL;
    Value *body_list = NULL;
    Value *stream = NULL;
    Value *stream_symbol = NULL;
    Value *start_value = NULL;
    Value *end_value = NULL;
    Value *index_place = NULL;
    Value *body_result = it->nil;
    Value *ignored = it->nil;
    Env *child = NULL;
    const char *name = NULL;
    int idx = 2;
    int start = 0;
    int end = 0;
    int body_start = 0;
    int body_ok = 0;
    int index_ok = 1;
    char body_err[1024];
    char index_err[1024];
    if (form->as.array.count < 3) {
        snprintf(err, errsz, "with-input-from-string expects a binding spec and body");
        return 0;
    }
    if (!proper_form_to_array(form->as.array.items[1], &binding) || binding.count < 2) {
        snprintf(err, errsz, "with-input-from-string expects a binding spec of the form (var string-form &key index start end)");
        return 0;
    }
    if (!reject_constant_binding_target(binding.items[0], "with-input-from-string variable", err, errsz)) return 0;
    if (!symbol_name(binding.items[0], &name)) {
        snprintf(err, errsz, "with-input-from-string variable must be a symbol");
        return 0;
    }
    if (!eval(it, env, binding.items[1], &source, err, errsz)) return 0;
    if (source->type != VALUE_STRING) {
        snprintf(err, errsz, "with-input-from-string expects string-form to evaluate to a string");
        return 0;
    }
    while (idx < binding.count) {
        Value *key = binding.items[idx];
        Value *val = NULL;
        if (!value_is_keyword(key) || idx + 1 >= binding.count) {
            snprintf(err, errsz, "with-input-from-string binding keywords must appear in keyword/value pairs");
            return 0;
        }
        val = binding.items[idx + 1];
        if (keyword_matches(key, ":start")) {
            if (!eval(it, env, val, &start_value, err, errsz)) return 0;
        } else if (keyword_matches(key, ":end")) {
            if (!eval(it, env, val, &end_value, err, errsz)) return 0;
        } else if (keyword_matches(key, ":index")) {
            index_place = val;
        } else {
            snprintf(err, errsz, "unsupported with-input-from-string keyword '%s'", key->as.str);
            return 0;
        }
        idx += 2;
    }
    if (!parse_string_bounds(it, source, start_value, end_value, "with-input-from-string", &start, &end, err, errsz)) return 0;
    {
        char *source_text = value_string_copy_text(source, 1);
        stream = make_string_input_stream_value(source_text, start, end);
        free(source_text);
    }
    child = env_new(env);
    child->active_model = env->active_model;
    env_define_value_symbol(child, binding.items[0], stream);
    stream_symbol = make_generated_uninterned_symbol(it, "wifs-stream");
    env_define_value_symbol(child, stream_symbol, stream);
    value_array_init(&cleanups);
    value_array_push(&cleanups, make_form_from2(make_symbol_value("close"), stream_symbol));
    frame.prev = it->unwinds;
    frame.env = child;
    frame.cleanup = make_list_value(&cleanups);
    frame.saved_blocks = it->blocks;
    frame.saved_dynamic = it->dynamic;
    frame.saved_tagbodies = it->tagbodies;
    frame.saved_catches = it->catches;
    frame.saved_handlers = it->handlers;
    frame.saved_restarts = it->restarts;
    frame.saved_condition_restart_assocs = it->condition_restart_assocs;
    it->unwinds = &frame;
    value_array_init(&body);
    for (int i = 2; i < form->as.array.count; ++i) value_array_push(&body, form->as.array.items[i]);
    body_list = make_list_value(&body);
    body_err[0] = '\0';
    index_err[0] = '\0';
    body_ok = process_declare_forms_in_body(child, body_list, &body_start, err, errsz) &&
              eval_sequence_range(it, child, body_list, body_start, &body_result, err, errsz);
    if (body_ok) interp_copy_values(it, &body_values);
    else snprintf(body_err, sizeof(body_err), "%s", err);
    if (body_ok && index_place != NULL) {
        PlaceRef *index_ref = NULL;
        Value *index_value = make_int_value(bigint_from_i64((int64_t)stream->as.string_input_stream.pos));
        index_ok = resolve_place_ref(it, env, index_place, &index_ref, err, errsz) &&
                   place_ref_write(it, env, index_ref, index_value, &ignored, err, errsz);
        if (index_ref != NULL) place_ref_free(index_ref);
        if (!index_ok) snprintf(index_err, sizeof(index_err), "%s", err);
    }
    if (!run_unwind_cleanup_frame(it, &frame, err, errsz)) return 0;
    if (!body_ok) {
        snprintf(err, errsz, "%s", body_err);
        return 0;
    }
    if (!index_ok) {
        snprintf(err, errsz, "%s", index_err);
        return 0;
    }
    interp_set_values(it, &body_values);
    *out = body_result;
    return 1;
}

