static int builtin_append(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    ValueArray arr;
    int i, j;
    (void)it; (void)env;
    value_array_init(&arr);
    for (i = 0; i < args->count; ++i) {
        ValueArray items;
        if (!sequence_to_array(args->items[i], &items, err, errsz)) {
            snprintf(err, errsz, "append expects list/vector arguments");
            return 0;
        }
        for (j = 0; j < items.count; ++j) value_array_push(&arr, items.items[j]);
    }
    *out = runtime_list_from_array(it->nil, &arr);
    return 1;
}

static int builtin_nconc(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    int i;
    (void)it; (void)env;
    if (args->count == 0) { *out = it->nil; return 1; }
    for (i = 0; i < args->count; ++i) {
        if (!value_is_list_like(args->items[i]) && args->items[i]->type != VALUE_NIL) {
            snprintf(err, errsz, "nconc expects list arguments");
            return 0;
        }
    }
    *out = args->items[0];
    for (i = 1; i < args->count; ++i) {
        Value *tail = *out;
        if (tail->type == VALUE_NIL) {
            *out = args->items[i];
            continue;
        }
        while (tail->type == VALUE_CONS && tail->as.cons.cdr->type == VALUE_CONS) {
            tail = tail->as.cons.cdr;
        }
        if (tail->type == VALUE_CONS) {
            tail->as.cons.cdr = args->items[i];
        }
    }
    return 1;
}

static int builtin_revappend(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    ValueArray rev_items;
    ValueArray tail_items;
    ValueArray all_items;
    int i;
    (void)it; (void)env;
    if (args->count != 2) {
        snprintf(err, errsz, "revappend expects a list and a tail");
        return 0;
    }
    if (!sequence_to_array(args->items[0], &rev_items, err, errsz)) {
        snprintf(err, errsz, "revappend expects a list");
        return 0;
    }
    value_array_init(&all_items);
    for (i = rev_items.count - 1; i >= 0; --i) value_array_push(&all_items, rev_items.items[i]);
    if (!sequence_to_array(args->items[1], &tail_items, err, errsz)) {
        value_array_dispose(&all_items);
        snprintf(err, errsz, "revappend expects a list for tail");
        return 0;
    }
    for (i = 0; i < tail_items.count; ++i) value_array_push(&all_items, tail_items.items[i]);
    *out = runtime_list_from_array(it->nil, &all_items);
    value_array_dispose(&all_items);
    return 1;
}

static int builtin_nreconc(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    ValueArray rev_items;
    ValueArray tail_items;
    ValueArray all_items;
    int i;
    (void)it; (void)env;
    if (args->count != 2) {
        snprintf(err, errsz, "nreconc expects a list and a tail");
        return 0;
    }
    if (!sequence_to_array(args->items[0], &rev_items, err, errsz)) {
        snprintf(err, errsz, "nreconc expects a list");
        return 0;
    }
    value_array_init(&all_items);
    for (i = rev_items.count - 1; i >= 0; --i) value_array_push(&all_items, rev_items.items[i]);
    if (!sequence_to_array(args->items[1], &tail_items, err, errsz)) {
        value_array_dispose(&all_items);
        snprintf(err, errsz, "nreconc expects a list for tail");
        return 0;
    }
    for (i = 0; i < tail_items.count; ++i) value_array_push(&all_items, tail_items.items[i]);
    *out = runtime_list_from_array(it->nil, &all_items);
    value_array_dispose(&all_items);
    return 1;
}

static int builtin_first(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    (void)env;
    if (args->count != 1 || !value_is_sequence(args->items[0])) {
        snprintf(err, errsz, "first expects one list/vector");
        return 0;
    }
    if (args->items[0]->type == VALUE_NIL) {
        *out = it->nil;
        return 1;
    }
    return sequence_first(args->items[0], out, err, errsz);
}

static int builtin_second(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    Value *v;
    (void)env;
    if (args->count != 1) {
        snprintf(err, errsz, "second expects exactly one argument");
        return 0;
    }
    v = args->items[0];
    if (v->type == VALUE_NIL) {
        *out = it->nil;
        return 1;
    }
    if (v->type == VALUE_LIST) {
        if (v->as.array.count < 2) {
            *out = it->nil;
            return 1;
        }
        *out = v->as.array.items[1];
        return 1;
    }
    if (v->type == VALUE_CONS) {
        Value *cdr = v->as.cons.cdr;
        if (cdr->type == VALUE_NIL) {
            *out = it->nil;
            return 1;
        }
        if (cdr->type == VALUE_CONS) {
            *out = cdr->as.cons.car;
            return 1;
        }
        if (cdr->type == VALUE_LIST) {
            if (cdr->as.array.count < 1) {
                *out = it->nil;
                return 1;
            }
            *out = cdr->as.array.items[0];
            return 1;
        }
    }
    snprintf(err, errsz, "second expects a proper list");
    return 0;
}

static int builtin_rest(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    (void)it; (void)env;
    if (args->count != 1 || !value_is_sequence(args->items[0])) {
        snprintf(err, errsz, "rest expects one list/vector");
        return 0;
    }
    return sequence_rest(it->nil, args->items[0], out, err, errsz);
}

