static int builtin_length(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    int n = 0;
    (void)it; (void)env;
    if (args->count != 1) {
        snprintf(err, errsz, "length expects exactly one sequence");
        return 0;
    }
    if (args->items[0]->type == VALUE_STRING) {
        *out = make_int_value(bigint_from_i64((int64_t)value_string_sequence_length(args->items[0])));
        return 1;
    }
    if (!value_is_sequence(args->items[0])) {
        snprintf(err, errsz, "length expects one list/vector/string");
        return 0;
    }
    if (!sequence_length(args->items[0], &n, err, errsz)) return 0;
    *out = make_int_value(bigint_from_i64(n));
    return 1;
}

static int builtin_nth(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    Num idx_num;
    double d = 0.0;
    (void)env;
    if (args->count != 2 || !value_is_sequence(args->items[1])) {
        snprintf(err, errsz, "nth expects index and sequence");
        return 0;
    }
    if (!value_to_num(it, args->items[0], &idx_num, err, errsz)) return 0;
    if (!num_to_double_checked(idx_num, &d) || floor(d) != d || d < 0.0) {
        snprintf(err, errsz, "nth index out of range");
        return 0;
    }
    return sequence_nth(args->items[1], (int)d, out, err, errsz);
}

static int builtin_nthcdr(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    Num idx_num;
    double d = 0.0;
    int n = 0;
    int i;
    Value *list = NULL;
    (void)env;
    if (args->count != 2) {
        snprintf(err, errsz, "nthcdr expects index and list");
        return 0;
    }
    if (!value_to_num(it, args->items[0], &idx_num, err, errsz)) return 0;
    if (!num_to_double_checked(idx_num, &d) || floor(d) != d || d < 0.0) {
        snprintf(err, errsz, "nthcdr index out of range");
        return 0;
    }
    n = (int)d;
    list = args->items[1];
    if (list->type == VALUE_NIL) {
        *out = it->nil;
        return 1;
    }
    if (!value_is_list_like(list)) {
        snprintf(err, errsz, "nthcdr expects a list");
        return 0;
    }
    for (i = 0; i < n; ++i) {
        if (list->type != VALUE_CONS) {
            *out = it->nil;
            return 1;
        }
        list = list->as.cons.cdr;
    }
    *out = list;
    return 1;
}

static int builtin_aref(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    ValueArray subscripts;
    int index = 0;
    int i;
    (void)env;
    if (args->count < 1) {
        snprintf(err, errsz, "aref expects an array and the required subscripts");
        return 0;
    }
    value_array_init(&subscripts);
    for (i = 1; i < args->count; ++i) value_array_push(&subscripts, args->items[i]);
    if (!array_compute_row_major_index_values(it, args->items[0], &subscripts, "aref", 1, &index, NULL, err, errsz)) return 0;
    return array_row_major_read(args->items[0], index, out, err, errsz);
}

static int builtin_elt(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    Num idx_num;
    double d = 0.0;
    (void)env;
    if (args->count != 2) {
        snprintf(err, errsz, "elt expects sequence and index");
        return 0;
    }
    if (!value_to_num(it, args->items[1], &idx_num, err, errsz)) return 0;
    if (!num_to_double_checked(idx_num, &d) || floor(d) != d || d < 0.0) {
        snprintf(err, errsz, "elt index out of range");
        return 0;
    }
    if (args->items[0]->type == VALUE_STRING) {
        int ch = 0;
        if ((int)d < 0 || (int)d >= value_string_sequence_length(args->items[0]) ||
            !string_storage_read_char(args->items[0], (int)d, &ch)) {
            snprintf(err, errsz, "string index out of range");
            return 0;
        }
        *out = make_char_value(ch);
        return 1;
    }
    if (!value_is_sequence(args->items[0])) {
        snprintf(err, errsz, "elt expects sequence and index");
        return 0;
    }
    return sequence_nth(args->items[0], (int)d, out, err, errsz);
}

static int builtin_svref(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    int index = 0;
    (void)env;
    if (args->count != 2 || args->items[0]->type != VALUE_VECTOR || value_array_rank(args->items[0]) != 1) {
        snprintf(err, errsz, "svref expects vector and index");
        return 0;
    }
    if (!value_to_non_negative_index(it, args->items[1], "svref", &index, err, errsz)) return 0;
    if (index >= value_vector_total_size(args->items[0])) {
        snprintf(err, errsz, "svref index out of range");
        return 0;
    }
    return array_row_major_read(args->items[0], index, out, err, errsz);
}

static Value *upgraded_array_element_type_value(Interp *it, Env *env, Value *spec) {
    int known = 0;
    int result = 0;
    char tmp_err[128];
    if (spec->type == VALUE_NIL) return common_lisp_runtime_symbol_or_fallback(it, "t");
    if (spec->type == VALUE_SYMBOL) {
        if (builtin_type_symbol_named(spec, "character")) return common_lisp_runtime_symbol_or_fallback(it, "character");
        if (builtin_type_symbol_named(spec, "base-char")) return common_lisp_runtime_symbol_or_fallback(it, "base-char");
        if (builtin_type_symbol_named(spec, "standard-char")) return common_lisp_runtime_symbol_or_fallback(it, "character");
        if (builtin_type_symbol_named(spec, "bit")) return common_lisp_runtime_symbol_or_fallback(it, "bit");
        if (builtin_type_symbol_named(spec, "t")) return common_lisp_runtime_symbol_or_fallback(it, "t");
    }
    if (type_spec_is_unsigned_byte_1(spec)) {
        return common_lisp_runtime_symbol_or_fallback(it, "bit");
    }
    if (type_spec_is_unsigned_byte_8(spec)) {
        return make_unsigned_byte_8_type_spec(it);
    }
    if (subtypep_type_specs(it, env, spec, common_lisp_runtime_symbol_or_fallback(it, "bit"), &known, &result, tmp_err, sizeof(tmp_err)) && known && result) {
        return common_lisp_runtime_symbol_or_fallback(it, "bit");
    }
    if (subtypep_type_specs(it, env, spec, common_lisp_runtime_symbol_or_fallback(it, "character"), &known, &result, tmp_err, sizeof(tmp_err)) && known && result) {
        return common_lisp_runtime_symbol_or_fallback(it, "character");
    }
    return common_lisp_runtime_symbol_or_fallback(it, "t");
}

