static int value_to_bit_int_checked(Value *value, int *out_bit) {
    int64_t i64 = 0;
    if (!value_is_bit_value(value) || !bigint_to_i64_checked(value->as.bigint, &i64)) return 0;
    *out_bit = (int)i64;
    return 1;
}

static int value_to_byte_int_checked(Value *value, int *out_byte) {
    int64_t i64 = 0;
    if (!value_is_byte_value(value) || !bigint_to_i64_checked(value->as.bigint, &i64)) return 0;
    *out_byte = (int)i64;
    return 1;
}

static int bit_arrays_same_dimensions(Value *a, Value *b) {
    int rank = 0;
    int i = 0;
    if (a == NULL || b == NULL) return 0;
    if (a->type != VALUE_VECTOR || b->type != VALUE_VECTOR) return 0;
    rank = value_array_rank(a);
    if (rank != value_array_rank(b)) return 0;
    for (i = 0; i < rank; ++i) {
        if (value_array_dimension_at(a, i) != value_array_dimension_at(b, i)) return 0;
    }
    return 1;
}

static Value *make_simple_bit_array_like(Value *source) {
    ValueArray items;
    Value *result = NULL;
    int rank = 0;
    int total = 0;
    int *dims = NULL;
    int i = 0;
    value_array_init(&items);
    total = value_vector_total_size(source);
    for (i = 0; i < total; ++i) value_array_push(&items, make_int_value(bigint_new_zero()));
    result = make_vector_value_typed(&items, make_symbol_value("bit"));
    rank = value_array_rank(source);
    if (rank > 1) {
        dims = (int *)xmalloc((size_t)rank * sizeof(int));
        for (i = 0; i < rank; ++i) dims[i] = value_array_dimension_at(source, i);
        value_set_array_dimensions(result, dims, rank);
        free(dims);
    } else {
        value_set_array_dimensions(result, NULL, rank);
    }
    return result;
}

static int builtin_bit_common(Interp *it,
                              const ValueArray *args,
                              const char *who,
                              int require_simple,
                              Value **out,
                              char *err,
                              size_t errsz) {
    ValueArray subscripts;
    int index = 0;
    int i = 0;
    if (args->count < 1) {
        snprintf(err,
                 errsz,
                 "%s expects a %sbit array and the required subscripts",
                 who,
                 require_simple ? "simple " : "");
        return 0;
    }
    if (args->items[0]->type != VALUE_VECTOR ||
        !value_vector_has_bit_element_type(args->items[0]) ||
        (require_simple && !value_is_simple_bit_array(args->items[0]))) {
        snprintf(err,
                 errsz,
                 "%s expects a %sbit array and the required subscripts",
                 who,
                 require_simple ? "simple " : "");
        return 0;
    }
    value_array_init(&subscripts);
    for (i = 1; i < args->count; ++i) value_array_push(&subscripts, args->items[i]);
    if (!array_compute_row_major_index_values(it,
                                              args->items[0],
                                              &subscripts,
                                              who,
                                              1,
                                              &index,
                                              NULL,
                                              err,
                                              errsz)) {
        return 0;
    }
    return array_row_major_read(args->items[0], index, out, err, errsz);
}

static int bit_array_read_bit(Value *array, int index, int *out_bit, const char *who, char *err, size_t errsz) {
    Value *value = NULL;
    if (!array_row_major_read(array, index, &value, err, errsz)) return 0;
    if (!value_to_bit_int_checked(value, out_bit)) {
        snprintf(err, errsz, "%s encountered a non-bit element in a bit array", who);
        return 0;
    }
    return 1;
}

static int resolve_bit_array_result(Value *source,
                                    Value *opt_result,
                                    const char *who,
                                    Value **out,
                                    char *err,
                                    size_t errsz) {
    if (opt_result == NULL || opt_result->type == VALUE_NIL) {
        *out = make_simple_bit_array_like(source);
        return 1;
    }
    if (symbol_is_common_lisp_t_symbol(opt_result)) {
        *out = source;
        return 1;
    }
    if (opt_result->type != VALUE_VECTOR || !value_vector_has_bit_element_type(opt_result)) {
        snprintf(err, errsz, "%s expects result-bit-array to be a bit array", who);
        return 0;
    }
    if (!bit_arrays_same_dimensions(source, opt_result)) {
        snprintf(err, errsz, "%s expects result-bit-array to have the same dimensions", who);
        return 0;
    }
    *out = opt_result;
    return 1;
}

typedef enum {
    BIT_ARRAY_OP_AND = 0,
    BIT_ARRAY_OP_IOR = 1,
    BIT_ARRAY_OP_XOR = 2,
    BIT_ARRAY_OP_EQV = 3,
    BIT_ARRAY_OP_NAND = 4,
    BIT_ARRAY_OP_NOR = 5,
    BIT_ARRAY_OP_ANDC1 = 6,
    BIT_ARRAY_OP_ANDC2 = 7,
    BIT_ARRAY_OP_ORC1 = 8,
    BIT_ARRAY_OP_ORC2 = 9,
    BIT_ARRAY_OP_NOT = 10
} BitArrayOpKind;

static int apply_bit_array_op(BitArrayOpKind op, int left, int right) {
    switch (op) {
        case BIT_ARRAY_OP_AND:   return left & right;
        case BIT_ARRAY_OP_IOR:   return left | right;
        case BIT_ARRAY_OP_XOR:   return left ^ right;
        case BIT_ARRAY_OP_EQV:   return !(left ^ right);
        case BIT_ARRAY_OP_NAND:  return !(left & right);
        case BIT_ARRAY_OP_NOR:   return !(left | right);
        case BIT_ARRAY_OP_ANDC1: return (!left) & right;
        case BIT_ARRAY_OP_ANDC2: return left & (!right);
        case BIT_ARRAY_OP_ORC1:  return (!left) | right;
        case BIT_ARRAY_OP_ORC2:  return left | (!right);
        case BIT_ARRAY_OP_NOT:   return !left;
        default:                 return 0;
    }
}

static int builtin_bit_array_unary_op(Interp *it,
                                      const ValueArray *args,
                                      const char *who,
                                      BitArrayOpKind op,
                                      Value **out,
                                      char *err,
                                      size_t errsz) {
    Value *source = NULL;
    Value *result = NULL;
    int total = 0;
    int *bits = NULL;
    int i = 0;
    (void)it;
    if (args->count != 1 && args->count != 2) {
        snprintf(err, errsz, "%s expects a bit array and optional result-bit-array", who);
        return 0;
    }
    source = args->items[0];
    if (source->type != VALUE_VECTOR || !value_vector_has_bit_element_type(source)) {
        snprintf(err, errsz, "%s expects a bit array and optional result-bit-array", who);
        return 0;
    }
    if (!resolve_bit_array_result(source,
                                  (args->count == 2) ? args->items[1] : NULL,
                                  who,
                                  &result,
                                  err,
                                  errsz)) {
        return 0;
    }
    total = value_vector_total_size(source);
    bits = (int *)xmalloc((size_t)(total > 0 ? total : 1) * sizeof(int));
    for (i = 0; i < total; ++i) {
        int bit = 0;
        if (!bit_array_read_bit(source, i, &bit, who, err, errsz)) {
            free(bits);
            return 0;
        }
        bits[i] = apply_bit_array_op(op, bit, 0);
    }
    for (i = 0; i < total; ++i) {
        Value *ignored = NULL;
        if (!array_row_major_write(result,
                                   i,
                                   make_int_value(bigint_from_i64(bits[i] ? 1 : 0)),
                                   &ignored,
                                   err,
                                   errsz)) {
            free(bits);
            return 0;
        }
    }
    free(bits);
    *out = result;
    return 1;
}

static int builtin_bit_array_binary_op(Interp *it,
                                       const ValueArray *args,
                                       const char *who,
                                       BitArrayOpKind op,
                                       Value **out,
                                       char *err,
                                       size_t errsz) {
    Value *left = NULL;
    Value *right = NULL;
    Value *result = NULL;
    int total = 0;
    int *bits = NULL;
    int i = 0;
    (void)it;
    if (args->count != 2 && args->count != 3) {
        snprintf(err, errsz, "%s expects two bit arrays and optional result-bit-array", who);
        return 0;
    }
    left = args->items[0];
    right = args->items[1];
    if (left->type != VALUE_VECTOR || !value_vector_has_bit_element_type(left) ||
        right->type != VALUE_VECTOR || !value_vector_has_bit_element_type(right)) {
        snprintf(err, errsz, "%s expects two bit arrays and optional result-bit-array", who);
        return 0;
    }
    if (!bit_arrays_same_dimensions(left, right)) {
        snprintf(err, errsz, "%s expects bit arrays with the same dimensions", who);
        return 0;
    }
    if (!resolve_bit_array_result(left,
                                  (args->count == 3) ? args->items[2] : NULL,
                                  who,
                                  &result,
                                  err,
                                  errsz)) {
        return 0;
    }
    total = value_vector_total_size(left);
    bits = (int *)xmalloc((size_t)(total > 0 ? total : 1) * sizeof(int));
    for (i = 0; i < total; ++i) {
        int left_bit = 0;
        int right_bit = 0;
        if (!bit_array_read_bit(left, i, &left_bit, who, err, errsz) ||
            !bit_array_read_bit(right, i, &right_bit, who, err, errsz)) {
            free(bits);
            return 0;
        }
        bits[i] = apply_bit_array_op(op, left_bit, right_bit);
    }
    for (i = 0; i < total; ++i) {
        Value *ignored = NULL;
        if (!array_row_major_write(result,
                                   i,
                                   make_int_value(bigint_from_i64(bits[i] ? 1 : 0)),
                                   &ignored,
                                   err,
                                   errsz)) {
            free(bits);
            return 0;
        }
    }
    free(bits);
    *out = result;
    return 1;
}

