static int builtin_simple_string_p(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    (void)env;
    if (args->count != 1) {
        snprintf(err, errsz, "simple-string-p expects exactly one argument");
        return 0;
    }
    *out = (args->items[0]->type == VALUE_STRING && !args->items[0]->has_fill_pointer &&
            !args->items[0]->adjustable && args->items[0]->displaced_to == NULL) ? it->true_value : it->false_value;
    return 1;
}

static int builtin_array_element_type(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    (void)env;
    if (args->count != 1) {
        snprintf(err, errsz, "array-element-type expects exactly one array");
        return 0;
    }
    if (args->items[0]->type == VALUE_STRING) {
        *out = common_lisp_runtime_symbol_or_fallback(it, "base-char");
        return 1;
    }
    if (args->items[0]->type == VALUE_VECTOR) {
        Value *elem = array_actual_element_type_value(args->items[0]);
        if (elem == NULL) {
            *out = common_lisp_runtime_symbol_or_fallback(it, "t");
        } else if (elem->type == VALUE_SYMBOL) {
            *out = common_lisp_runtime_symbol_or_fallback(it, package_symbol_entry_name(elem));
        } else {
            *out = elem;
        }
        return 1;
    }
    snprintf(err, errsz, "array-element-type expects a string or vector");
    (void)it;
    return 0;
}

static int builtin_upgraded_array_element_type(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    (void)env;
    if (args->count != 1 && args->count != 2) {
        snprintf(err, errsz, "upgraded-array-element-type expects a type specifier and optional environment");
        return 0;
    }
    *out = upgraded_array_element_type_value(it, env, args->items[0]);
    return 1;
}

static int value_array_length(Value *value, int *out_len, char *err, size_t errsz) {
    if (value->type == VALUE_STRING) {
        if (out_len != NULL) *out_len = value->array_total_size;
        return 1;
    }
    if (value->type == VALUE_VECTOR) {
        if (out_len != NULL) *out_len = value_vector_total_size(value);
        return 1;
    }
    snprintf(err, errsz, "expected an array");
    return 0;
}

static int parse_array_dimensions(Interp *it, Value *dims, const char *who, int **out_dims, int *out_rank, int *out_total, char *err, size_t errsz) {
    ValueArray items;
    int *parsed = NULL;
    int rank = 0;
    int total = 1;
    int dim = 0;
    int i;
    *out_dims = NULL;
    *out_rank = 0;
    *out_total = 0;
    if (value_to_non_negative_index(it, dims, who, &dim, err, errsz)) {
        parsed = (int *)xmalloc(sizeof(int));
        parsed[0] = dim;
        *out_dims = parsed;
        *out_rank = 1;
        *out_total = dim;
        return 1;
    }
    if (dims->type != VALUE_VECTOR && !value_is_proper_list(dims)) {
        snprintf(err, errsz, "%s expects an integer or a dimensions list", who);
        return 0;
    }
    value_array_init(&items);
    if (!sequence_to_array(dims, &items, err, errsz)) {
        snprintf(err, errsz, "%s expects an integer or a dimensions list", who);
        return 0;
    }
    if (items.count == 0) {
        *out_dims = NULL;
        *out_rank = 0;
        *out_total = 1;
        return 1;
    }
    parsed = (int *)xmalloc((size_t)items.count * sizeof(int));
    rank = items.count;
    total = 1;
    for (i = 0; i < items.count; ++i) {
        if (!value_to_non_negative_index(it, items.items[i], who, &dim, err, errsz)) {
            free(parsed);
            return 0;
        }
        if (dim > 0 && total > INT_MAX / dim) {
            free(parsed);
            snprintf(err, errsz, "%s dimensions exceed the implementation limit", who);
            return 0;
        }
        parsed[i] = dim;
        total *= dim;
    }
    *out_dims = parsed;
    *out_rank = rank;
    *out_total = total;
    return 1;
}

static int parse_array_rank1_length(Interp *it, Value *dims, const char *who, int *out_len, char *err, size_t errsz) {
    int *parsed = NULL;
    int rank = 0;
    int total = 0;
    if (!parse_array_dimensions(it, dims, who, &parsed, &rank, &total, err, errsz)) return 0;
    if (rank != 1) {
        free(parsed);
        snprintf(err, errsz, "%s currently supports only rank-1 arrays", who);
        return 0;
    }
    *out_len = parsed[0];
    free(parsed);
    return 1;
}

static int array_build_dimensions_list(Interp *it, Value *array, Value **out, char *err, size_t errsz) {
    ValueArray dims;
    int rank = 0;
    int i;
    if (array->type != VALUE_VECTOR && array->type != VALUE_STRING) {
        snprintf(err, errsz, "expected an array");
        return 0;
    }
    rank = value_array_rank(array);
    value_array_init(&dims);
    for (i = 0; i < rank; ++i) {
        value_array_push(&dims, make_int_value(bigint_from_i64(value_array_dimension_at(array, i))));
    }
    *out = runtime_list_from_array(it->nil, &dims);
    return 1;
}

static int array_compute_row_major_index_values(Interp *it,
                                                Value *array,
                                                const ValueArray *subscripts,
                                                const char *who,
                                                int report_oob,
                                                int *out_index,
                                                int *out_in_bounds,
                                                char *err,
                                                size_t errsz) {
    int rank = 0;
    int index = 0;
    int i;
    if (out_in_bounds != NULL) *out_in_bounds = 0;
    if (array->type != VALUE_VECTOR && array->type != VALUE_STRING) {
        snprintf(err, errsz, "%s expects an array", who);
        return 0;
    }
    rank = value_array_rank(array);
    if (subscripts->count != rank) {
        snprintf(err, errsz, "%s expects %d subscript%s for this array", who, rank, (rank == 1) ? "" : "s");
        return 0;
    }
    for (i = 0; i < rank; ++i) {
        int sub = 0;
        int dim = value_array_dimension_at(array, i);
        if (!value_to_non_negative_index(it, subscripts->items[i], who, &sub, err, errsz)) return 0;
        if (sub < 0 || sub >= dim) {
            if (report_oob) {
                snprintf(err, errsz, "%s subscript out of range", who);
                return 0;
            }
            if (out_index != NULL) *out_index = 0;
            if (out_in_bounds != NULL) *out_in_bounds = 0;
            return 1;
        }
        index = (i == 0) ? sub : (index * dim + sub);
    }
    if (out_index != NULL) *out_index = index;
    if (out_in_bounds != NULL) *out_in_bounds = 1;
    return 1;
}

static int make_array_string_from_contents(Interp *it,
                                           const ValueArray *items,
                                           int len,
                                           int has_fill_pointer,
                                           int fill_pointer,
                                           int adjustable,
                                           Value **out,
                                           char *err,
                                           size_t errsz) {
    char *buf = NULL;
    int i;
    int ch = 0;
    (void)it;
    if (items->count != len) {
        snprintf(err, errsz, "make-array initial contents length does not match dimensions");
        return 0;
    }
    buf = (char *)xmalloc((size_t)len + 1U);
    for (i = 0; i < len; ++i) {
        if (!value_to_char_code_compat(items->items[i], &ch)) {
            free(buf);
            snprintf(err, errsz, "make-array expects character initial contents for string arrays");
            return 0;
        }
        if (ch == 0) {
            free(buf);
            snprintf(err, errsz, "make-array does not support NUL characters in the current string representation");
            return 0;
        }
        buf[i] = (char)(ch & 0xFF);
    }
    buf[len] = '\0';
    *out = make_string_value_sized_with_metadata(buf, len, has_fill_pointer, fill_pointer, adjustable);
    free(buf);
    return 1;
}

static int value_array_matches_vector_element_type(const ValueArray *items,
                                                   Value *element_type_spec,
                                                   const char *who,
                                                   char *err,
                                                   size_t errsz) {
    int i;
    if (element_type_spec == NULL) return 1;
    if (builtin_type_symbol_named(element_type_spec, "bit")) {
        for (i = 0; i < items->count; ++i) {
            if (!value_is_bit_value(items->items[i])) {
                snprintf(err, errsz, "%s expects bit elements for bit vectors", who);
                return 0;
            }
        }
        return 1;
    }
    if (type_spec_is_unsigned_byte_8(element_type_spec)) {
        for (i = 0; i < items->count; ++i) {
            if (!value_is_byte_value(items->items[i])) {
                snprintf(err, errsz, "%s expects byte elements for unsigned-byte 8 vectors", who);
                return 0;
            }
        }
        return 1;
    }
    return 1;
}

static Value *default_vector_initial_element(Interp *it, Value *element_type_spec) {
    if (element_type_spec != NULL &&
        (builtin_type_symbol_named(element_type_spec, "bit") || type_spec_is_unsigned_byte_8(element_type_spec))) {
        return make_int_value(bigint_new_zero());
    }
    return it->nil;
}

static int flatten_array_initial_contents(Value *contents,
                                          const int *dims,
                                          int rank,
                                          ValueArray *flat,
                                          char *err,
                                          size_t errsz) {
    ValueArray items;
    int i;
    if (rank == 0) {
        value_array_push(flat, contents);
        return 1;
    }
    if (!sequence_to_array(contents, &items, err, errsz)) {
        snprintf(err, errsz, "make-array expects nested initial contents matching dimensions");
        return 0;
    }
    if (items.count != dims[0]) {
        snprintf(err, errsz, "make-array initial contents do not match dimensions");
        return 0;
    }
    if (rank == 1) {
        for (i = 0; i < items.count; ++i) value_array_push(flat, items.items[i]);
        return 1;
    }
    for (i = 0; i < items.count; ++i) {
        if (!flatten_array_initial_contents(items.items[i], dims + 1, rank - 1, flat, err, errsz)) return 0;
    }
    return 1;
}

static int parse_array_literal_contents_recursive(Value *contents,
                                                  int *dims,
                                                  int rank,
                                                  int axis,
                                                  ValueArray *flat,
                                                  char *err,
                                                  size_t errsz) {
    ValueArray items;
    int i;
    if (rank == 0) {
        value_array_push(flat, contents);
        return 1;
    }
    if (!sequence_to_array(contents, &items, err, errsz)) {
        snprintf(err, errsz, "array literal expects nested initial contents matching dimensions");
        return 0;
    }
    if (dims != NULL) {
        if (dims[axis] < 0) {
            dims[axis] = items.count;
        } else if (dims[axis] != items.count) {
            snprintf(err, errsz, "array literal initial contents do not match dimensions");
            return 0;
        }
    }
    if (rank == 1) {
        for (i = 0; i < items.count; ++i) value_array_push(flat, items.items[i]);
        return 1;
    }
    if (items.count == 0) {
        if (dims != NULL) {
            for (i = axis + 1; i < axis + rank; ++i) {
                if (dims[i] < 0) dims[i] = 0;
            }
        }
        return 1;
    }
    for (i = 0; i < items.count; ++i) {
        if (!parse_array_literal_contents_recursive(items.items[i], dims, rank - 1, axis + 1, flat, err, errsz)) return 0;
    }
    return 1;
}

static int make_array_rank1_result(Interp *it,
                                   int len,
                                   int want_string,
                                   Value *vector_element_type_spec,
                                   int adjustable,
                                   int has_fill_pointer,
                                   int fill_pointer,
                                   int saw_initial_element,
                                   Value *initial_element,
                                   int saw_initial_contents,
                                   Value *initial_contents,
                                   Value **out,
                                   char *err,
                                   size_t errsz) {
    ValueArray items;
    int i;
    int fill = ' ';
    int want_bit_vector = (!want_string &&
                           vector_element_type_spec != NULL &&
                           builtin_type_symbol_named(vector_element_type_spec, "bit"));
    if (saw_initial_element && saw_initial_contents) {
        snprintf(err, errsz, "make-array does not allow both :initial-element and :initial-contents");
        return 0;
    }
    if (saw_initial_contents) {
        value_array_init(&items);
        if (!sequence_to_array(initial_contents, &items, err, errsz)) {
            snprintf(err, errsz, "make-array expects rank-1 initial contents");
            return 0;
        }
        if (want_string) {
            return make_array_string_from_contents(it,
                                                  &items,
                                                  len,
                                                  has_fill_pointer,
                                                  fill_pointer,
                                                  adjustable,
                                                  out,
                                                  err,
                                                  errsz);
        }
        if (items.count != len) {
            snprintf(err, errsz, "make-array initial contents length does not match dimensions");
            return 0;
        }
        if (!value_array_matches_vector_element_type(&items, vector_element_type_spec, "make-array", err, errsz)) {
            return 0;
        }
        *out = make_vector_with_fill_pointer_typed(&items,
                                                   has_fill_pointer,
                                                   fill_pointer,
                                                   adjustable,
                                                   vector_element_type_spec);
        return 1;
    }
    if (want_string) {
        if (saw_initial_element) {
            if (!value_to_char_code_compat(initial_element, &fill)) {
                snprintf(err, errsz, "make-array expects :initial-element to be a character for string arrays");
                return 0;
            }
        }
        if (fill == 0) {
            snprintf(err, errsz, "make-array does not support NUL characters in the current string representation");
            return 0;
        }
        {
            char *buf = (char *)xmalloc((size_t)len + 1U);
            for (i = 0; i < len; ++i) buf[i] = (char)(fill & 0xFF);
            buf[len] = '\0';
            *out = make_string_value_sized_with_metadata(buf, len, has_fill_pointer, fill_pointer, adjustable);
            free(buf);
            return 1;
        }
    }
    value_array_init(&items);
    if (want_bit_vector && saw_initial_element && !value_is_bit_value(initial_element)) {
        snprintf(err, errsz, "make-array expects :initial-element to be a bit for bit vectors");
        return 0;
    }
    if (type_spec_is_unsigned_byte_8(vector_element_type_spec) &&
        saw_initial_element &&
        !value_is_byte_value(initial_element)) {
        snprintf(err, errsz, "make-array expects :initial-element to be a byte for unsigned-byte 8 vectors");
        return 0;
    }
    for (i = 0; i < len; ++i) {
        value_array_push(&items, saw_initial_element ? initial_element : default_vector_initial_element(it, vector_element_type_spec));
    }
    *out = make_vector_with_fill_pointer_typed(&items,
                                               has_fill_pointer,
                                               fill_pointer,
                                               adjustable,
                                               vector_element_type_spec);
    return 1;
}

static int make_array_rank0_result(Interp *it,
                                   Value *vector_element_type_spec,
                                   int adjustable,
                                   int saw_initial_element,
                                   Value *initial_element,
                                   int saw_initial_contents,
                                   Value *initial_contents,
                                   Value **out,
                                   char *err,
                                   size_t errsz) {
    ValueArray items;
    Value *value = default_vector_initial_element(it, vector_element_type_spec);
    if (saw_initial_element && saw_initial_contents) {
        snprintf(err, errsz, "make-array does not allow both :initial-element and :initial-contents");
        return 0;
    }
    if (saw_initial_contents) value = initial_contents;
    else if (saw_initial_element) value = initial_element;
    if (vector_element_type_spec != NULL) {
        if (builtin_type_symbol_named(vector_element_type_spec, "bit") && !value_is_bit_value(value)) {
            snprintf(err, errsz, "make-array expects bit contents for bit vectors");
            return 0;
        }
        if (type_spec_is_unsigned_byte_8(vector_element_type_spec) && !value_is_byte_value(value)) {
            snprintf(err, errsz, "make-array expects byte contents for unsigned-byte 8 vectors");
            return 0;
        }
    }
    value_array_init(&items);
    value_array_push(&items, value);
    *out = make_vector_value_typed(&items, vector_element_type_spec);
    (*out)->adjustable = adjustable;
    value_set_array_dimensions(*out, NULL, 0);
    return 1;
}

static int make_array_multidimensional_result(Interp *it,
                                              const int *dims,
                                              int rank,
                                              int total_size,
                                              Value *vector_element_type_spec,
                                              int saw_initial_element,
                                              Value *initial_element,
                                              int saw_initial_contents,
                                              Value *initial_contents,
                                              Value **out,
                                              char *err,
                                              size_t errsz) {
    ValueArray items;
    int i;
    if (saw_initial_element && saw_initial_contents) {
        snprintf(err, errsz, "make-array does not allow both :initial-element and :initial-contents");
        return 0;
    }
    value_array_init(&items);
    if (saw_initial_contents) {
        if (!flatten_array_initial_contents(initial_contents, dims, rank, &items, err, errsz)) return 0;
        if (items.count != total_size) {
            snprintf(err, errsz, "make-array initial contents do not match dimensions");
            return 0;
        }
        if (!value_array_matches_vector_element_type(&items, vector_element_type_spec, "make-array", err, errsz)) {
            return 0;
        }
    } else {
        if (vector_element_type_spec != NULL) {
            if (builtin_type_symbol_named(vector_element_type_spec, "bit") &&
                saw_initial_element &&
                !value_is_bit_value(initial_element)) {
                snprintf(err, errsz, "make-array expects :initial-element to be a bit for bit arrays");
                return 0;
            }
            if (type_spec_is_unsigned_byte_8(vector_element_type_spec) &&
                saw_initial_element &&
                !value_is_byte_value(initial_element)) {
                snprintf(err, errsz, "make-array expects :initial-element to be a byte for unsigned-byte 8 arrays");
                return 0;
            }
        }
        for (i = 0; i < total_size; ++i) {
            value_array_push(&items,
                             saw_initial_element ? initial_element : default_vector_initial_element(it, vector_element_type_spec));
        }
    }
    *out = make_vector_value_typed(&items, vector_element_type_spec);
    value_set_array_dimensions(*out, dims, rank);
    return 1;
}

static int builtin_make_array(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    int *dims = NULL;
    int rank = 0;
    int total_size = 0;
    int i = 0;
    int adjustable = 0;
    int saw_element_type = 0;
    int saw_initial_element = 0;
    int saw_initial_contents = 0;
    int has_fill_pointer = 0;
    int fill_pointer = 0;
    Value *displaced_to = it->nil;
    int displaced_index_offset = 0;
    Value *element_type = make_symbol_value("t");
    Value *initial_element = it->nil;
    Value *initial_contents = NULL;
    int want_string = 0;
    Value *vector_element_type_spec = make_symbol_value("t");
    (void)env;
    if (args->count < 1 || ((args->count - 1) % 2) != 0) {
        snprintf(err, errsz, "make-array expects dimensions and optional keyword/value pairs");
        return 0;
    }
    if (!parse_array_dimensions(it, args->items[0], "make-array", &dims, &rank, &total_size, err, errsz)) return 0;
    for (i = 1; i < args->count; i += 2) {
        Value *key = args->items[i];
        Value *val = args->items[i + 1];
        if (!value_is_keyword(key)) {
            free(dims);
            snprintf(err, errsz, "make-array expected a keyword argument, got %s", value_type_name(key));
            return 0;
        }
        if (keyword_matches(key, ":element-type")) {
            element_type = val;
            saw_element_type = 1;
        } else if (keyword_matches(key, ":initial-element")) {
            initial_element = val;
            saw_initial_element = 1;
        } else if (keyword_matches(key, ":initial-contents")) {
            initial_contents = val;
            saw_initial_contents = 1;
        } else if (keyword_matches(key, ":adjustable")) {
            adjustable = value_is_truthy(val);
        } else if (keyword_matches(key, ":fill-pointer")) {
            if (val->type == VALUE_NIL) {
                has_fill_pointer = 0;
            } else if (symbol_is_common_lisp_t_symbol(val)) {
                has_fill_pointer = 1;
                fill_pointer = total_size;
            } else {
                if (!value_to_non_negative_index(it, val, "make-array", &fill_pointer, err, errsz)) {
                    free(dims);
                    return 0;
                }
                if (fill_pointer > total_size) {
                    free(dims);
                    snprintf(err, errsz, "make-array fill pointer out of range");
                    return 0;
                }
                has_fill_pointer = 1;
            }
        } else if (keyword_matches(key, ":displaced-to")) {
            displaced_to = val;
        } else if (keyword_matches(key, ":displaced-index-offset")) {
            if (val->type != VALUE_NIL && !value_to_non_negative_index(it, val, "make-array", &displaced_index_offset, err, errsz)) {
                free(dims);
                return 0;
            }
        } else {
            free(dims);
            snprintf(err, errsz, "make-array does not support the %s keyword", key->as.str);
            return 0;
        }
    }
    if (saw_element_type) {
        Value *upgraded = upgraded_array_element_type_value(it, env, element_type);
        want_string = (upgraded->type == VALUE_SYMBOL &&
                       (str_ieq(upgraded->as.str, "character") || str_ieq(upgraded->as.str, "base-char")));
        if (!want_string) vector_element_type_spec = upgraded;
    }
    if (rank != 1 && want_string) {
        free(dims);
        snprintf(err, errsz, "make-array currently supports character element-type arrays only for rank-1 strings");
        return 0;
    }
    if (rank > 1) {
        if (adjustable) {
            free(dims);
            snprintf(err, errsz, "make-array currently supports adjustable arrays only for rank-1 arrays");
            return 0;
        }
        if (has_fill_pointer) {
            free(dims);
            snprintf(err, errsz, "make-array currently supports fill pointers only for rank-1 general vectors");
            return 0;
        }
    }
    if (rank == 0 && has_fill_pointer) {
        free(dims);
        snprintf(err, errsz, "make-array currently supports fill pointers only for rank-1 general vectors");
        return 0;
    }
    if (displaced_to->type != VALUE_NIL) {
        if (want_string) {
            if (displaced_to->type != VALUE_STRING) {
                free(dims);
                snprintf(err, errsz, "make-array displaced-to currently expects a string for string arrays");
                return 0;
            }
        } else if (displaced_to->type != VALUE_VECTOR) {
            free(dims);
            snprintf(err, errsz, "make-array displaced-to currently expects a general vector");
            return 0;
        }
        if (!want_string &&
            !value_equal_impl(array_actual_element_type_value(displaced_to), vector_element_type_spec)) {
            free(dims);
            snprintf(err, errsz, "make-array currently requires element-type compatible with the displaced vector target");
            return 0;
        }
        if (saw_initial_element || saw_initial_contents) {
            free(dims);
            snprintf(err, errsz, "make-array does not allow initial contents for displaced arrays");
            return 0;
        }
        if ((want_string &&
             (displaced_index_offset > value_string_total_size(displaced_to) ||
              total_size > value_string_total_size(displaced_to) - displaced_index_offset)) ||
            (!want_string &&
             (displaced_index_offset > value_vector_total_size(displaced_to) ||
              total_size > value_vector_total_size(displaced_to) - displaced_index_offset))) {
            free(dims);
            snprintf(err, errsz, "make-array displaced array bounds exceed target array");
            return 0;
        }
        if (want_string) {
            *out = make_displaced_string(displaced_to,
                                         displaced_index_offset,
                                         total_size,
                                         has_fill_pointer,
                                         has_fill_pointer ? fill_pointer : total_size,
                                         adjustable);
        } else {
            *out = make_displaced_vector_typed(displaced_to,
                                               displaced_index_offset,
                                               dims,
                                               rank,
                                               total_size,
                                               has_fill_pointer,
                                               has_fill_pointer ? fill_pointer : total_size,
                                               adjustable,
                                               vector_element_type_spec);
        }
        free(dims);
        return 1;
    }
    if (rank == 0) {
        int ok = make_array_rank0_result(it,
                                         vector_element_type_spec,
                                         adjustable,
                                         saw_initial_element,
                                         initial_element,
                                         saw_initial_contents,
                                         initial_contents,
                                         out,
                                         err,
                                         errsz);
        free(dims);
        return ok;
    }
    if (rank == 1) {
        int ok = make_array_rank1_result(it,
                                         dims[0],
                                         want_string,
                                         vector_element_type_spec,
                                         adjustable,
                                         has_fill_pointer,
                                         fill_pointer,
                                         saw_initial_element,
                                         initial_element,
                                         saw_initial_contents,
                                         initial_contents,
                                         out,
                                         err,
                                         errsz);
        free(dims);
        return ok;
    }
    {
        int ok = make_array_multidimensional_result(it,
                                                    dims,
                                                    rank,
                                                    total_size,
                                                    vector_element_type_spec,
                                                    saw_initial_element,
                                                    initial_element,
                                                    saw_initial_contents,
                                                    initial_contents,
                                                    out,
                                                    err,
                                                    errsz);
        free(dims);
        return ok;
    }
}

static int builtin_array_rank(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    int ignored = 0;
    (void)env;
    if (args->count != 1) {
        snprintf(err, errsz, "array-rank expects exactly one array");
        return 0;
    }
    if (!value_array_length(args->items[0], &ignored, err, errsz)) {
        snprintf(err, errsz, "array-rank expects an array");
        return 0;
    }
    *out = make_int_value(bigint_from_i64(value_array_rank(args->items[0])));
    (void)it;
    return 1;
}

static int builtin_array_dimensions(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    (void)env;
    if (args->count != 1) {
        snprintf(err, errsz, "array-dimensions expects exactly one array");
        return 0;
    }
    if (!value_array_length(args->items[0], NULL, err, errsz)) {
        snprintf(err, errsz, "array-dimensions expects an array");
        return 0;
    }
    return array_build_dimensions_list(it, args->items[0], out, err, errsz);
}

static int builtin_array_total_size(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    int len = 0;
    (void)env;
    if (args->count != 1) {
        snprintf(err, errsz, "array-total-size expects exactly one array");
        return 0;
    }
    if (!value_array_length(args->items[0], &len, err, errsz)) {
        snprintf(err, errsz, "array-total-size expects an array");
        return 0;
    }
    *out = make_int_value(bigint_from_i64(len));
    (void)it;
    return 1;
}

static int builtin_array_row_major_index(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    ValueArray subscripts;
    int index = 0;
    int i;
    (void)env;
    if (args->count < 1) {
        snprintf(err, errsz, "array-row-major-index expects an array and the required subscripts");
        return 0;
    }
    if (!value_array_length(args->items[0], NULL, err, errsz)) {
        snprintf(err, errsz, "array-row-major-index expects an array");
        return 0;
    }
    value_array_init(&subscripts);
    for (i = 1; i < args->count; ++i) value_array_push(&subscripts, args->items[i]);
    if (!array_compute_row_major_index_values(it, args->items[0], &subscripts, "array-row-major-index", 1, &index, NULL, err, errsz)) return 0;
    *out = make_int_value(bigint_from_i64(index));
    return 1;
}

static int builtin_row_major_aref(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    int index = 0;
    (void)env;
    if (args->count != 2) {
        snprintf(err, errsz, "row-major-aref expects array and index");
        return 0;
    }
    if (!value_to_non_negative_index(it, args->items[1], "row-major-aref", &index, err, errsz)) return 0;
    return array_row_major_read(args->items[0], index, out, err, errsz);
}

static int builtin_array_displacement(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    int ignored = 0;
    ValueArray values;
    (void)env;
    if (args->count != 1) {
        snprintf(err, errsz, "array-displacement expects exactly one array");
        return 0;
    }
    if (!value_array_length(args->items[0], &ignored, err, errsz)) {
        snprintf(err, errsz, "array-displacement expects an array");
        return 0;
    }
    value_array_init(&values);
    if ((args->items[0]->type == VALUE_VECTOR || args->items[0]->type == VALUE_STRING) &&
        args->items[0]->displaced_to != NULL) {
        value_array_push(&values, args->items[0]->displaced_to);
        value_array_push(&values, make_int_value(bigint_from_i64(args->items[0]->displaced_index_offset)));
        interp_set_values(it, &values);
        *out = args->items[0]->displaced_to;
        return 1;
    }
    value_array_push(&values, it->nil);
    value_array_push(&values, make_int_value(bigint_new_zero()));
    interp_set_values(it, &values);
    *out = it->nil;
    return 1;
}

static int builtin_array_dimension(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    Num axis_num;
    double axis = 0.0;
    int axis_int = 0;
    (void)env;
    if (args->count != 2) {
        snprintf(err, errsz, "array-dimension expects array and axis-number");
        return 0;
    }
    if (!value_array_length(args->items[0], NULL, err, errsz)) {
        snprintf(err, errsz, "array-dimension expects an array");
        return 0;
    }
    if (!value_to_num(it, args->items[1], &axis_num, err, errsz)) return 0;
    if (!num_to_double_checked(axis_num, &axis) || floor(axis) != axis || axis < 0.0) {
        snprintf(err, errsz, "array-dimension axis out of range");
        return 0;
    }
    axis_int = (int)axis;
    if (axis_int >= value_array_rank(args->items[0])) {
        snprintf(err, errsz, "array-dimension axis out of range");
        return 0;
    }
    *out = make_int_value(bigint_from_i64(value_array_dimension_at(args->items[0], axis_int)));
    return 1;
}

static int builtin_adjustable_array_p(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    int ignored = 0;
    (void)env;
    if (args->count != 1) {
        snprintf(err, errsz, "adjustable-array-p expects exactly one array");
        return 0;
    }
    if (!value_array_length(args->items[0], &ignored, err, errsz)) {
        snprintf(err, errsz, "adjustable-array-p expects an array");
        return 0;
    }
    *out = ((args->items[0]->type == VALUE_VECTOR || args->items[0]->type == VALUE_STRING) &&
            args->items[0]->adjustable) ? it->true_value : it->false_value;
    return 1;
}

static int materialize_displaced_vector_storage(Value *vec, char *err, size_t errsz) {
    int total = 0;
    int i = 0;
    Value **items = NULL;
    Value *item = NULL;
    if (vec->type != VALUE_VECTOR) {
        snprintf(err, errsz, "adjust-array currently expects a general vector");
        return 0;
    }
    if (vec->displaced_to == NULL) return 1;
    total = value_vector_total_size(vec);
    items = (total > 0) ? (Value **)xmalloc((size_t)total * sizeof(Value *)) : NULL;
    for (i = 0; i < total; ++i) {
        if (!array_row_major_read(vec, i, &item, err, errsz)) {
            if (items != NULL) free(items);
            return 0;
        }
        items[i] = item;
    }
    if (vec->array_element_type_spec == NULL &&
        vec->displaced_to != NULL &&
        vec->displaced_to->type == VALUE_VECTOR) {
        vec->array_element_type_spec = value_vector_element_type_spec(vec->displaced_to);
    }
    vec->as.array.items = items;
    vec->as.array.cap = total;
    vec->as.array.count = vec->has_fill_pointer ? vec->fill_pointer : total;
    vec->displaced_to = NULL;
    vec->displaced_index_offset = 0;
    return 1;
}

static int materialize_displaced_string_storage(Value *str, char *err, size_t errsz) {
    char *text = NULL;
    if (str->type != VALUE_STRING) {
        snprintf(err, errsz, "adjust-array currently expects a string");
        return 0;
    }
    if (str->displaced_to == NULL) return 1;
    text = value_string_copy_text(str, 0);
    if (text == NULL) {
        snprintf(err, errsz, "adjust-array currently expects a string");
        return 0;
    }
    str->as.str = text;
    str->displaced_to = NULL;
    str->displaced_index_offset = 0;
    return 1;
}

static int adjust_vector_storage(Value *vec, int new_total, Value *fill, char *err, size_t errsz) {
    int old_total = 0;
    int i = 0;
    Value **new_items = NULL;
    if (vec->type != VALUE_VECTOR) {
        snprintf(err, errsz, "adjust-array currently expects a general vector");
        return 0;
    }
    if (vec->displaced_to != NULL) {
        if (!materialize_displaced_vector_storage(vec, err, errsz)) return 0;
    }
    if (new_total < 0) {
        snprintf(err, errsz, "adjust-array dimensions out of range");
        return 0;
    }
    old_total = value_vector_total_size(vec);
    new_items = (new_total > 0) ? (Value **)xrealloc(vec->as.array.items, (size_t)new_total * sizeof(Value *)) : NULL;
    vec->as.array.items = new_items;
    for (i = old_total; i < new_total; ++i) vec->as.array.items[i] = fill;
    vec->array_total_size = new_total;
    vec->as.array.cap = new_total;
    if (!vec->has_fill_pointer) {
        vec->as.array.count = new_total;
        vec->fill_pointer = new_total;
    } else {
        if (vec->fill_pointer > new_total) vec->fill_pointer = new_total;
        vec->as.array.count = vec->fill_pointer;
    }
    return 1;
}

static int adjust_string_storage(Value *str, int new_total, int fill_ch, char *err, size_t errsz) {
    int old_total = 0;
    int i = 0;
    char *new_text = NULL;
    if (str->type != VALUE_STRING) {
        snprintf(err, errsz, "adjust-array currently expects a string");
        return 0;
    }
    if (str->displaced_to != NULL) {
        if (!materialize_displaced_string_storage(str, err, errsz)) return 0;
    }
    if (new_total < 0) {
        snprintf(err, errsz, "adjust-array dimensions out of range");
        return 0;
    }
    if (fill_ch == 0) {
        snprintf(err, errsz, "adjust-array does not support NUL characters in the current string representation");
        return 0;
    }
    old_total = str->array_total_size;
    new_text = (char *)xrealloc(str->as.str, (size_t)new_total + 1U);
    str->as.str = new_text;
    for (i = old_total; i < new_total; ++i) str->as.str[i] = (char)(fill_ch & 0xFF);
    str->as.str[new_total] = '\0';
    str->array_total_size = new_total;
    if (!str->has_fill_pointer) str->fill_pointer = new_total;
    else if (str->fill_pointer > new_total) str->fill_pointer = new_total;
    return 1;
}

static int parse_adjust_array_dimensions(Interp *it,
                                         Value *array,
                                         Value *dims_form,
                                         int **out_dims,
                                         int *out_rank,
                                         int *out_total,
                                         char *err,
                                         size_t errsz) {
    if (array->type == VALUE_STRING) {
        int len = 0;
        int *dims = NULL;
        if (!parse_array_rank1_length(it, dims_form, "adjust-array", &len, err, errsz)) return 0;
        dims = (int *)xmalloc(sizeof(int));
        dims[0] = len;
        *out_dims = dims;
        *out_rank = 1;
        *out_total = len;
        return 1;
    }
    return parse_array_dimensions(it, dims_form, "adjust-array", out_dims, out_rank, out_total, err, errsz);
}

static Value *make_vector_value_with_dimensions(const ValueArray *items, const int *dims, int rank, int adjustable) {
    Value *v = make_vector_value(items);
    v->adjustable = adjustable;
    value_set_array_dimensions(v, dims, rank);
    return v;
}

static Value *make_vector_value_with_dimensions_typed(const ValueArray *items,
                                                      const int *dims,
                                                      int rank,
                                                      int adjustable,
                                                      Value *element_type_spec) {
    Value *v = make_vector_value_typed(items, element_type_spec);
    v->adjustable = adjustable;
    value_set_array_dimensions(v, dims, rank);
    return v;
}

static int builtin_adjust_array(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    int *new_dims = NULL;
    int new_rank = 0;
    int new_total = 0;
    int i = 0;
    int adjustable_override = -1;
    int fill_pointer_override = -1;
    int use_initial_element = 0;
    int use_initial_contents = 0;
    int saw_displaced_to = 0;
    int saw_displaced_offset = 0;
    Value *initial_element = it->nil;
    Value *initial_contents = NULL;
    Value *array = NULL;
    Value *res = NULL;
    Value *displaced_to = NULL;
    int displaced_index_offset = 0;
    int result_adjustable = 0;
    int result_has_fill_pointer = 0;
    int result_fill_pointer = 0;
    int want_string = 0;
    int string_fill = ' ';
    Value *result_vector_element_type_spec = NULL;
    (void)env;
    if (args->count < 2 || ((args->count - 2) % 2) != 0) {
        snprintf(err, errsz, "adjust-array expects array, dimensions, and optional keyword/value pairs");
        return 0;
    }
    array = args->items[0];
    if (array->type != VALUE_VECTOR && array->type != VALUE_STRING) {
        snprintf(err, errsz, "adjust-array currently supports only general vectors and strings");
        return 0;
    }
    want_string = (array->type == VALUE_STRING);
    result_vector_element_type_spec = want_string ? NULL : array_actual_element_type_value(array);
    if (!parse_adjust_array_dimensions(it, array, args->items[1], &new_dims, &new_rank, &new_total, err, errsz)) return 0;
    displaced_to = (array->displaced_to != NULL) ? array->displaced_to : it->nil;
    displaced_index_offset = (array->displaced_to != NULL) ? array->displaced_index_offset : 0;
    for (i = 2; i < args->count; i += 2) {
        Value *key = args->items[i];
        Value *val = args->items[i + 1];
        if (!value_is_keyword(key)) {
            free(new_dims);
            snprintf(err, errsz, "adjust-array expected a keyword argument, got %s", value_type_name(key));
            return 0;
        }
        if (keyword_matches(key, ":element-type")) {
            Value *upgraded = upgraded_array_element_type_value(it, env, val);
            if (want_string) {
                if (upgraded->type != VALUE_SYMBOL ||
                    (!str_ieq(upgraded->as.str, "character") && !str_ieq(upgraded->as.str, "base-char"))) {
                    free(new_dims);
                    snprintf(err, errsz, "adjust-array currently supports only character-compatible element-type for strings");
                    return 0;
                }
            } else if (!value_equal_impl(upgraded, array_actual_element_type_value(array))) {
                free(new_dims);
                snprintf(err, errsz, "adjust-array currently requires :element-type compatible with the existing vector representation");
                return 0;
            } else {
                result_vector_element_type_spec = upgraded;
            }
        } else if (keyword_matches(key, ":initial-element")) {
            if (want_string && !value_to_char_code_compat(val, &string_fill)) {
                free(new_dims);
                snprintf(err, errsz, "adjust-array expects :initial-element to be a character for string arrays");
                return 0;
            }
            if (!want_string &&
                result_vector_element_type_spec != NULL &&
                builtin_type_symbol_named(result_vector_element_type_spec, "bit") &&
                !value_is_bit_value(val)) {
                free(new_dims);
                snprintf(err, errsz, "adjust-array expects :initial-element to be a bit for bit vectors");
                return 0;
            }
            if (!want_string &&
                result_vector_element_type_spec != NULL &&
                type_spec_is_unsigned_byte_8(result_vector_element_type_spec) &&
                !value_is_byte_value(val)) {
                free(new_dims);
                snprintf(err, errsz, "adjust-array expects :initial-element to be a byte for unsigned-byte 8 vectors");
                return 0;
            }
            initial_element = val;
            use_initial_element = 1;
        } else if (keyword_matches(key, ":initial-contents")) {
            initial_contents = val;
            use_initial_contents = 1;
        } else if (keyword_matches(key, ":fill-pointer")) {
            if (!array->has_fill_pointer && value_is_truthy(val)) {
                free(new_dims);
                snprintf(err, errsz, "adjust-array cannot add a fill pointer to an array that has none");
                return 0;
            } else if (val->type == VALUE_NIL) {
                fill_pointer_override = -1;
            } else if (symbol_is_common_lisp_t_symbol(val)) {
                fill_pointer_override = new_total;
            } else {
                if (!value_to_non_negative_index(it, val, "adjust-array", &fill_pointer_override, err, errsz)) {
                    free(new_dims);
                    return 0;
                }
                if (fill_pointer_override > new_total) {
                    free(new_dims);
                    snprintf(err, errsz, "adjust-array fill pointer out of range");
                    return 0;
                }
            }
        } else if (keyword_matches(key, ":adjustable")) {
            adjustable_override = value_is_truthy(val) ? 1 : 0;
        } else if (keyword_matches(key, ":displaced-to")) {
            saw_displaced_to = 1;
            displaced_index_offset = 0;
            displaced_to = val;
        } else if (keyword_matches(key, ":displaced-index-offset")) {
            saw_displaced_offset = 1;
            if (val->type == VALUE_NIL) {
                displaced_index_offset = 0;
            } else {
                if (!value_to_non_negative_index(it, val, "adjust-array", &displaced_index_offset, err, errsz)) {
                    free(new_dims);
                    return 0;
                }
            }
        } else {
            free(new_dims);
            snprintf(err, errsz, "adjust-array does not support the %s keyword", key->as.str);
            return 0;
        }
    }
    if (use_initial_element && use_initial_contents) {
        free(new_dims);
        snprintf(err, errsz, "adjust-array does not allow both :initial-element and :initial-contents");
        return 0;
    }
    result_adjustable = (adjustable_override >= 0) ? adjustable_override : array->adjustable;
    result_has_fill_pointer = array->has_fill_pointer;
    result_fill_pointer = array->has_fill_pointer ? array->fill_pointer : new_total;
    if (result_has_fill_pointer) {
        if (fill_pointer_override >= 0) result_fill_pointer = fill_pointer_override;
        else if (result_fill_pointer > new_total) result_fill_pointer = new_total;
    }
    if (displaced_to == it->nil && displaced_index_offset != 0) {
        free(new_dims);
        snprintf(err, errsz, "adjust-array displaced-index-offset requires a displaced-to target");
        return 0;
    }
    if (new_rank > 1 && result_has_fill_pointer) {
        free(new_dims);
        snprintf(err, errsz, "adjust-array currently supports fill pointers only for rank-1 arrays");
        return 0;
    }
    if (displaced_to != it->nil) {
        if (use_initial_element || use_initial_contents) {
            free(new_dims);
            snprintf(err, errsz, "adjust-array does not allow initial contents for displaced arrays");
            return 0;
        }
        if (want_string) {
            if (displaced_to->type != VALUE_STRING) {
                free(new_dims);
                snprintf(err, errsz, "adjust-array displaced-to currently expects a string for string arrays");
                return 0;
            }
        } else if (displaced_to->type != VALUE_VECTOR) {
            free(new_dims);
            snprintf(err, errsz, "adjust-array displaced-to currently expects a general vector");
            return 0;
        } else if (!value_equal_impl(array_actual_element_type_value(displaced_to), result_vector_element_type_spec)) {
            free(new_dims);
            snprintf(err, errsz, "adjust-array currently requires element-type compatible with the displaced vector target");
            return 0;
        }
        if ((want_string &&
             (displaced_index_offset > value_string_total_size(displaced_to) ||
              new_total > value_string_total_size(displaced_to) - displaced_index_offset)) ||
            (!want_string &&
             (displaced_index_offset > value_vector_total_size(displaced_to) ||
              new_total > value_vector_total_size(displaced_to) - displaced_index_offset))) {
            free(new_dims);
            snprintf(err, errsz, "adjust-array displaced array bounds exceed target array");
            return 0;
        }
        if (want_string) {
            res = make_displaced_string(displaced_to,
                                        displaced_index_offset,
                                        new_total,
                                        result_has_fill_pointer,
                                        result_has_fill_pointer ? result_fill_pointer : new_total,
                                        result_adjustable);
        } else {
            res = make_displaced_vector_typed(displaced_to,
                                              displaced_index_offset,
                                              new_dims,
                                              new_rank,
                                              new_total,
                                              result_has_fill_pointer,
                                              result_has_fill_pointer ? result_fill_pointer : new_total,
                                              result_adjustable,
                                              result_vector_element_type_spec);
        }
        free(new_dims);
        *out = res;
        return 1;
    }
    if (use_initial_contents) {
        if (want_string || new_rank == 1) {
            int ok = make_array_rank1_result(it,
                                             new_total,
                                             want_string,
                                             result_vector_element_type_spec,
                                             result_adjustable,
                                             result_has_fill_pointer,
                                             result_fill_pointer,
                                             0,
                                             it->nil,
                                             1,
                                             initial_contents,
                                             out,
                                             err,
                                             errsz);
            free(new_dims);
            return ok;
        }
        {
            int ok = make_array_multidimensional_result(it,
                                                        new_dims,
                                                        new_rank,
                                                        new_total,
                                                        result_vector_element_type_spec,
                                                        0,
                                                        it->nil,
                                                        1,
                                                        initial_contents,
                                                        out,
                                                        err,
                                                        errsz);
            if (ok) (*out)->adjustable = result_adjustable;
            free(new_dims);
            return ok;
        }
    }
    if (want_string) {
        if (array->adjustable) {
            if (!adjust_string_storage(array, new_total, use_initial_element ? string_fill : ' ', err, errsz)) {
                free(new_dims);
                return 0;
            }
            array->adjustable = result_adjustable;
            array->has_fill_pointer = result_has_fill_pointer;
            array->fill_pointer = result_has_fill_pointer ? result_fill_pointer : new_total;
            value_set_array_dimensions(array, new_dims, new_rank);
            free(new_dims);
            *out = array;
            return 1;
        }
        {
            int old_total = array->array_total_size;
            int preserve = (old_total < new_total) ? old_total : new_total;
            char *buf = (char *)xmalloc((size_t)new_total + 1U);
            for (i = 0; i < preserve; ++i) {
                int ch = 0;
                if (!string_storage_read_char(array, i, &ch)) {
                    free(buf);
                    free(new_dims);
                    snprintf(err, errsz, "adjust-array currently expects a string");
                    return 0;
                }
                buf[i] = (char)(ch & 0xFF);
            }
            for (i = preserve; i < new_total; ++i) buf[i] = (char)((use_initial_element ? string_fill : ' ') & 0xFF);
            buf[new_total] = '\0';
            res = make_string_value_sized_with_metadata(buf,
                                                        new_total,
                                                        result_has_fill_pointer,
                                                        result_fill_pointer,
                                                        result_adjustable);
            free(buf);
            free(new_dims);
            *out = res;
            return 1;
        }
    }
    if (array->adjustable && array->displaced_to == NULL && !use_initial_contents) {
        if (!adjust_vector_storage(array,
                                   new_total,
                                   use_initial_element ? initial_element : default_vector_initial_element(it, result_vector_element_type_spec),
                                   err,
                                   errsz)) {
            free(new_dims);
            return 0;
        }
        array->adjustable = result_adjustable;
        array->has_fill_pointer = result_has_fill_pointer;
        if (array->has_fill_pointer) {
            array->fill_pointer = result_fill_pointer;
            array->as.array.count = result_fill_pointer;
        } else {
            array->fill_pointer = new_total;
            array->as.array.count = new_total;
        }
        value_set_vector_element_type(array, result_vector_element_type_spec);
        value_set_array_dimensions(array, new_dims, new_rank);
        free(new_dims);
        *out = array;
        return 1;
    }
    {
        ValueArray arr;
        int old_total = value_vector_total_size(array);
        int preserve = (old_total < new_total) ? old_total : new_total;
        value_array_init(&arr);
        for (i = 0; i < preserve; ++i) {
            Value *item = NULL;
            if (!array_row_major_read(array, i, &item, err, errsz)) {
                free(new_dims);
                return 0;
            }
            value_array_push(&arr, item);
        }
        for (i = preserve; i < new_total; ++i) {
            value_array_push(&arr,
                             use_initial_element ? initial_element : default_vector_initial_element(it, result_vector_element_type_spec));
        }
        if (new_rank == 1) {
            res = make_vector_with_fill_pointer_typed(&arr,
                                                      result_has_fill_pointer,
                                                      result_has_fill_pointer ? result_fill_pointer : new_total,
                                                      result_adjustable,
                                                      result_vector_element_type_spec);
        } else {
            res = make_vector_value_with_dimensions_typed(&arr,
                                                          new_dims,
                                                          new_rank,
                                                          result_adjustable,
                                                          result_vector_element_type_spec);
        }
        free(new_dims);
        *out = res;
        return 1;
    }
}

static int builtin_array_in_bounds_p(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    ValueArray subscripts;
    int in_bounds = 0;
    int i;
    (void)env;
    if (args->count < 1) {
        snprintf(err, errsz, "array-in-bounds-p expects an array and the required subscripts");
        return 0;
    }
    if (!value_array_length(args->items[0], NULL, err, errsz)) {
        snprintf(err, errsz, "array-in-bounds-p expects an array");
        return 0;
    }
    value_array_init(&subscripts);
    for (i = 1; i < args->count; ++i) value_array_push(&subscripts, args->items[i]);
    if (!array_compute_row_major_index_values(it, args->items[0], &subscripts, "array-in-bounds-p", 0, NULL, &in_bounds, err, errsz)) return 0;
    *out = in_bounds ? it->true_value : it->false_value;
    return 1;
}

static int builtin_array_has_fill_pointer_p(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    int ignored = 0;
    (void)env;
    if (args->count != 1) {
        snprintf(err, errsz, "array-has-fill-pointer-p expects exactly one array");
        return 0;
    }
    if (!value_array_length(args->items[0], &ignored, err, errsz)) {
        snprintf(err, errsz, "array-has-fill-pointer-p expects an array");
        return 0;
    }
    *out = ((args->items[0]->type == VALUE_VECTOR || args->items[0]->type == VALUE_STRING) &&
            args->items[0]->has_fill_pointer) ? it->true_value : it->false_value;
    return 1;
}

static int builtin_fill_pointer(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    int ignored = 0;
    (void)env;
    if (args->count != 1) {
        snprintf(err, errsz, "fill-pointer expects exactly one array");
        return 0;
    }
    if (!value_array_length(args->items[0], &ignored, err, errsz)) {
        snprintf(err, errsz, "fill-pointer expects an array");
        return 0;
    }
    if ((args->items[0]->type == VALUE_VECTOR || args->items[0]->type == VALUE_STRING) &&
        args->items[0]->has_fill_pointer) {
        *out = make_int_value(bigint_from_i64(args->items[0]->fill_pointer));
        return 1;
    }
    snprintf(err, errsz, "fill-pointer expects an array with a fill pointer");
    return 0;
}

static int builtin_vector_push(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    Value *vec = NULL;
    int index = 0;
    (void)env;
    if (args->count != 2 || (args->items[1]->type != VALUE_VECTOR && args->items[1]->type != VALUE_STRING)) {
        snprintf(err, errsz, "vector-push expects item and vector");
        return 0;
    }
    vec = args->items[1];
    if (!vec->has_fill_pointer) {
        snprintf(err, errsz, "vector-push expects a vector with a fill pointer");
        return 0;
    }
    index = vec->fill_pointer;
    if (index >= ((vec->type == VALUE_STRING) ? value_string_total_size(vec) : value_vector_total_size(vec))) {
        *out = it->nil;
        return 1;
    }
    if (vec->type == VALUE_STRING) {
        int ch = 0;
        if (!value_to_char_code_compat(args->items[0], &ch)) {
            snprintf(err, errsz, "vector-push expects a character for string vectors");
            return 0;
        }
        if (ch == 0) {
            snprintf(err, errsz, "vector-push does not support NUL characters in the current string representation");
            return 0;
        }
        if (!string_storage_write_char(vec, index, ch)) {
            snprintf(err, errsz, "array index out of range");
            return 0;
        }
    } else {
        Value *ignored = NULL;
        if (!array_row_major_write(vec, index, args->items[0], &ignored, err, errsz)) return 0;
        vec->as.array.count = index + 1;
    }
    vec->fill_pointer = index + 1;
    *out = make_int_value(bigint_from_i64(index));
    return 1;
}

static int builtin_vector_push_extend(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    Value *vec = NULL;
    int index = 0;
    int extension = 0;
    int old_total = 0;
    int new_total = 0;
    (void)env;
    if (args->count != 2 && args->count != 3) {
        snprintf(err, errsz, "vector-push-extend expects item, vector, and optional extension");
        return 0;
    }
    if (args->items[1]->type != VALUE_VECTOR && args->items[1]->type != VALUE_STRING) {
        snprintf(err, errsz, "vector-push-extend expects item and vector");
        return 0;
    }
    vec = args->items[1];
    if (!vec->has_fill_pointer) {
        snprintf(err, errsz, "vector-push-extend expects a vector with a fill pointer");
        return 0;
    }
    if (args->count == 3) {
        if (!value_to_non_negative_index(it, args->items[2], "vector-push-extend", &extension, err, errsz)) return 0;
    }
    index = vec->fill_pointer;
    old_total = (vec->type == VALUE_STRING) ? value_string_total_size(vec) : value_vector_total_size(vec);
    if (index >= old_total) {
        if (!vec->adjustable) {
            snprintf(err, errsz, "vector-push-extend expects an adjustable vector when extension is needed");
            return 0;
        }
        new_total = old_total + ((args->count == 3) ? extension : ((old_total > 0) ? old_total : 1));
        if (new_total <= old_total) new_total = old_total + 1;
        if (vec->type == VALUE_STRING) {
            if (!adjust_string_storage(vec, new_total, ' ', err, errsz)) return 0;
        } else if (!adjust_vector_storage(vec,
                                          new_total,
                                          default_vector_initial_element(it, array_actual_element_type_value(vec)),
                                          err,
                                          errsz)) {
            return 0;
        }
    }
    if (vec->type == VALUE_STRING) {
        int ch = 0;
        if (!value_to_char_code_compat(args->items[0], &ch)) {
            snprintf(err, errsz, "vector-push-extend expects a character for string vectors");
            return 0;
        }
        if (ch == 0) {
            snprintf(err, errsz, "vector-push-extend does not support NUL characters in the current string representation");
            return 0;
        }
        if (!string_storage_write_char(vec, index, ch)) {
            snprintf(err, errsz, "array index out of range");
            return 0;
        }
    } else {
        Value *ignored = NULL;
        if (!array_row_major_write(vec, index, args->items[0], &ignored, err, errsz)) return 0;
        vec->as.array.count = index + 1;
    }
    vec->fill_pointer = index + 1;
    *out = make_int_value(bigint_from_i64(index));
    return 1;
}

static int builtin_vector_pop(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    Value *vec = NULL;
    int index = 0;
    (void)env;
    if (args->count != 1 || (args->items[0]->type != VALUE_VECTOR && args->items[0]->type != VALUE_STRING)) {
        snprintf(err, errsz, "vector-pop expects exactly one vector");
        return 0;
    }
    vec = args->items[0];
    if (!vec->has_fill_pointer) {
        snprintf(err, errsz, "vector-pop expects a vector with a fill pointer");
        return 0;
    }
    if (vec->fill_pointer <= 0) {
        snprintf(err, errsz, "vector-pop expects a non-empty vector");
        return 0;
    }
    index = vec->fill_pointer - 1;
    if (vec->type == VALUE_STRING) {
        int ch = 0;
        if (!string_storage_read_char(vec, index, &ch)) {
            snprintf(err, errsz, "vector-pop expects a non-empty vector");
            return 0;
        }
        vec->fill_pointer = index;
        *out = make_char_value(ch);
    } else {
        Value *item = NULL;
        if (!array_row_major_read(vec, index, &item, err, errsz)) return 0;
        vec->fill_pointer = index;
        vec->as.array.count = index;
        *out = item;
    }
    return 1;
}

