static int value_numeric_zero_any_p(Value *v) {
    if (v == NULL) return 0;
    if (v->type == VALUE_FLOAT) return v->as.flt == 0.0;
    if (v->type == VALUE_INT) return bigint_is_zero(v->as.bigint);
    if (v->type == VALUE_RATIO) return bigint_is_zero(v->as.ratio.numerator);
    if (v->type == VALUE_COMPLEX) {
        return value_numeric_zero_any_p(v->as.complex.realpart) &&
               value_numeric_zero_any_p(v->as.complex.imagpart);
    }
    return 0;
}

