static int builtin_integer_parity_predicate(Interp *it,
                                            Env *env,
                                            const ValueArray *args,
                                            Value **out,
                                            const char *name,
                                            int want_odd,
                                            char *err,
                                            size_t errsz) {
    (void)env;
    if (args->count != 1) {
        snprintf(err, errsz, "%s expects exactly one argument", name);
        return 0;
    }
    if (args->items[0]->type != VALUE_INT) {
        snprintf(err, errsz, "%s expects an integer", name);
        return 0;
    }
    if (bigint_is_zero(args->items[0]->as.bigint)) {
        *out = want_odd ? it->false_value : it->true_value;
        return 1;
    }
    *out = (((args->items[0]->as.bigint->d.digits[0] & 1U) != 0U) == want_odd) ? it->true_value : it->false_value;
    return 1;
}

