static int parse_integer_from_substring(const char *text,
                                        int start,
                                        int end,
                                        int radix,
                                        int junk_allowed,
                                        Value **out_value,
                                        int *out_pos,
                                        char *err,
                                        size_t errsz) {
    int pos = start;
    int digit_start;
    int sign = 1;
    BigInt *acc = bigint_new_zero();
    while (pos < end && isspace((unsigned char)text[pos])) ++pos;
    digit_start = pos;
    if (pos < end && (text[pos] == '+' || text[pos] == '-')) {
        if (text[pos] == '-') sign = -1;
        ++pos;
    }
    if (pos >= end || digit_char_weight((unsigned char)text[pos]) < 0 || digit_char_weight((unsigned char)text[pos]) >= radix) {
        if (junk_allowed) {
            *out_value = NULL;
            *out_pos = digit_start;
            return 1;
        }
        snprintf(err, errsz, "parse-integer could not parse an integer");
        return 0;
    }
    while (pos < end) {
        int weight = digit_char_weight((unsigned char)text[pos]);
        BigInt *tmp;
        if (weight < 0 || weight >= radix) break;
        tmp = bigint_mul_small(acc, (uint32_t)radix);
        acc = bigint_add_small(tmp, (uint32_t)weight);
        ++pos;
    }
    while (pos < end && isspace((unsigned char)text[pos])) ++pos;
    if (!junk_allowed && pos != end) {
        snprintf(err, errsz, "parse-integer found junk after the integer");
        return 0;
    }
    if (sign < 0) acc = bigint_neg(acc);
    *out_value = make_int_value(acc);
    *out_pos = pos;
    return 1;
}

static int builtin_parse_integer(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    ParseIntegerOptions opts;
    Value *value = NULL;
    ValueArray values;
    int start = 0;
    int end = 0;
    int len = 0;
    int pos = 0;
    (void)env;
    if (args->count < 1) {
        snprintf(err, errsz, "parse-integer expects a string");
        return 0;
    }
    if (args->items[0]->type != VALUE_STRING) {
        snprintf(err, errsz, "parse-integer expects a string");
        return 0;
    }
    if (!parse_parse_integer_keyword_options(it, args, &opts, err, errsz)) return 0;
    len = value_string_sequence_length(args->items[0]);
    start = opts.start;
    end = (opts.end >= 0) ? opts.end : len;
    if (start > end || end > len) {
        snprintf(err, errsz, "parse-integer bounds out of range");
        return 0;
    }
    {
        char *text = value_string_copy_text(args->items[0], 1);
        int ok = parse_integer_from_substring(text, start, end, opts.radix, opts.junk_allowed, &value, &pos, err, errsz);
        free(text);
        if (!ok) return 0;
    }
    value_array_init(&values);
    value_array_push(&values, (value != NULL) ? value : it->nil);
    value_array_push(&values, make_int_value(bigint_from_i64(pos)));
    interp_set_values(it, &values);
    *out = interp_primary_value(it);
    return 1;
}

static int builtin_read_from_string(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    ReadFromStringOptions opts;
    Value *form = NULL;
    ValueArray values;
    int pos = 0;
    int eof = 0;
    if (args->count < 1) {
        snprintf(err, errsz, "read-from-string expects at least one string");
        return 0;
    }
    if (args->items[0]->type != VALUE_STRING) {
        snprintf(err, errsz, "read-from-string expects a string");
        return 0;
    }
    if (!parse_read_from_string_options(it, args, &opts, err, errsz)) return 0;
    {
        char *text = value_string_copy_text(args->items[0], 1);
        int ok = parse_single_form_from_string_range(it,
                                                     env,
                                                     text,
                                                     opts.start,
                                                     opts.end,
                                                     opts.preserve_whitespace,
                                                     &form,
                                                     &pos,
                                                     &eof,
                                                     err,
                                                     errsz);
        free(text);
        if (!ok) return 0;
    }
    if (eof) {
        if (opts.eof_error_p) {
            snprintf(err, errsz, "read-from-string reached EOF before reading an object");
            return 0;
        }
        value_array_init(&values);
        value_array_push(&values, opts.eof_value);
        value_array_push(&values, make_int_value(bigint_from_i64(pos)));
        interp_set_values(it, &values);
        *out = interp_primary_value(it);
        return 1;
    }
    value_array_init(&values);
    value_array_push(&values, form);
    value_array_push(&values, make_int_value(bigint_from_i64(pos)));
    interp_set_values(it, &values);
    *out = interp_primary_value(it);
    return 1;
}

static int parse_write_keyword_options(Interp *it,
                                       const ValueArray *args,
                                       int start_index,
                                       int allow_stream,
                                       const char *who,
                                       WriteKeywordOptions *opts,
                                       char *err,
                                       size_t errsz) {
    int i;
    (void)it;
    opts->escape = 1;
    opts->readably = 0;
    opts->have_escape = 0;
    opts->have_readably = 0;
    opts->pretty = 0;
    opts->have_pretty = 0;
    opts->base = 10;
    opts->have_base = 0;
    opts->radix = 0;
    opts->have_radix = 0;
    opts->case_mode = PRINT_CASE_DOWNCASE;
    opts->have_case = 0;
    opts->array = 1;
    opts->have_array = 0;
    opts->gensym = 1;
    opts->have_gensym = 0;
    opts->level = -1;
    opts->have_level = 0;
    opts->length = -1;
    opts->have_length = 0;
    opts->right_margin = -1;
    opts->have_right_margin = 0;
    opts->miser_width = -1;
    opts->have_miser_width = 0;
    opts->lines = -1;
    opts->have_lines = 0;
    opts->pprint_dispatch = NULL;
    opts->have_pprint_dispatch = 0;
    opts->stream = NULL;
    if (((args->count - start_index) % 2) != 0) {
        snprintf(err, errsz, "%s keyword arguments must appear in keyword/value pairs", who);
        return 0;
    }
    for (i = start_index; i < args->count; i += 2) {
        Value *key = args->items[i];
        Value *val = args->items[i + 1];
        if (!value_is_keyword(key)) {
            snprintf(err, errsz, "expected a keyword argument, got %s", value_type_name(key));
            return 0;
        }
        if (keyword_matches(key, ":escape")) {
            opts->escape = value_is_truthy(val);
            opts->have_escape = 1;
        } else if (keyword_matches(key, ":readably")) {
            opts->readably = value_is_truthy(val);
            opts->have_readably = 1;
        } else if (keyword_matches(key, ":pretty")) {
            opts->pretty = value_is_truthy(val);
            opts->have_pretty = 1;
        } else if (keyword_matches(key, ":base")) {
            if (!value_to_print_base(it, val, who, &opts->base, err, errsz)) return 0;
            opts->have_base = 1;
        } else if (keyword_matches(key, ":radix")) {
            opts->radix = value_is_truthy(val);
            opts->have_radix = 1;
        } else if (keyword_matches(key, ":case")) {
            if (!value_to_print_case_mode(val, who, &opts->case_mode, err, errsz)) return 0;
            opts->have_case = 1;
        } else if (keyword_matches(key, ":array")) {
            opts->array = value_is_truthy(val);
            opts->have_array = 1;
        } else if (keyword_matches(key, ":gensym")) {
            opts->gensym = value_is_truthy(val);
            opts->have_gensym = 1;
        } else if (keyword_matches(key, ":circle")) {
            opts->circle = value_is_truthy(val);
            opts->have_circle = 1;
        } else if (keyword_matches(key, ":level")) {
            char level_who[64];
            snprintf(level_who, sizeof(level_who), "%s :level", who);
            if (!value_to_optional_nonnegative(val, level_who, &opts->level, err, errsz)) return 0;
            opts->have_level = 1;
        } else if (keyword_matches(key, ":length")) {
            char length_who[64];
            snprintf(length_who, sizeof(length_who), "%s :length", who);
            if (!value_to_optional_nonnegative(val, length_who, &opts->length, err, errsz)) return 0;
            opts->have_length = 1;
        } else if (keyword_matches(key, ":right-margin")) {
            char margin_who[64];
            snprintf(margin_who, sizeof(margin_who), "%s :right-margin", who);
            if (!value_to_optional_nonnegative(val, margin_who, &opts->right_margin, err, errsz)) return 0;
            opts->have_right_margin = 1;
        } else if (keyword_matches(key, ":miser-width")) {
            char miser_who[64];
            snprintf(miser_who, sizeof(miser_who), "%s :miser-width", who);
            if (!value_to_optional_nonnegative(val, miser_who, &opts->miser_width, err, errsz)) return 0;
            opts->have_miser_width = 1;
        } else if (keyword_matches(key, ":lines")) {
            char lines_who[64];
            snprintf(lines_who, sizeof(lines_who), "%s :lines", who);
            if (!value_to_optional_nonnegative(val, lines_who, &opts->lines, err, errsz)) return 0;
            opts->have_lines = 1;
        } else if (keyword_matches(key, ":pprint-dispatch")) {
            opts->pprint_dispatch = val;
            opts->have_pprint_dispatch = 1;
        } else if (keyword_matches(key, ":stream")) {
            if (!allow_stream) {
                snprintf(err, errsz, "%s does not support the :stream keyword", who);
                return 0;
            }
            opts->stream = val;
        } else {
            snprintf(err, errsz, "unsupported %s keyword '%s'", who, key->as.str);
            return 0;
        }
    }
    if (opts->readably) {
        opts->escape = 1;
        opts->have_escape = 1;
    }
    return 1;
}

static int builtin_write(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    WriteKeywordOptions opts;
    PrintRenderOptions render;
    Value *stream = NULL;
    char *text = NULL;
    if (args->count < 1) {
        snprintf(err, errsz, "write expects at least one argument");
        return 0;
    }
    if (!parse_write_keyword_options(it, args, 1, 1, "write", &opts, err, errsz)) return 0;
    if (!resolve_output_stream_designator(it, opts.stream, "write", &stream, err, errsz)) return 0;
    if (!resolve_print_render_options(it, env, &opts, &render, err, errsz)) return 0;
    if (!render_write_text(it, env, args->items[0], &render, &text)) return 0;
    output_stream_write_text(it, stream, text);
    free(text);
    *out = args->items[0];
    return 1;
}

static int builtin_write_to_string(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    WriteKeywordOptions opts;
    PrintRenderOptions render;
    char *text = NULL;
    if (args->count < 1) {
        snprintf(err, errsz, "write-to-string expects at least one argument");
        return 0;
    }
    if (!parse_write_keyword_options(it, args, 1, 0, "write-to-string", &opts, err, errsz)) return 0;
    if (!resolve_print_render_options(it, env, &opts, &render, err, errsz)) return 0;
    if (!render_write_text(it, env, args->items[0], &render, &text)) return 0;
    *out = make_string_value(text);
    free(text);
    return 1;
}

static int builtin_format(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    Value *stream = NULL;
    Value *control = NULL;
    int return_string = 0;
    int pretty_depth = 0;
    int pushed_pretty = 0;
    char *control_text = NULL;
    char *result_text = NULL;
    if (args->count < 2) {
        snprintf(err, errsz, "format expects a destination, a control string, and optional arguments");
        return 0;
    }
    control = args->items[1];
    if (control->type != VALUE_STRING) {
        snprintf(err, errsz, "format expects a string control string");
        return 0;
    }
    if (!format_resolve_destination(it, args->items[0], &stream, &return_string, err, errsz)) return 0;
    if (runtime_special_truthy(it, env, "*print-pretty*")) {
        pretty_depth = output_stream_pretty_context_depth(it, stream);
        output_stream_set_pretty_context_depth(it, stream, pretty_depth + 1);
        pushed_pretty = 1;
    }
    control_text = value_string_copy_text(control, 1);
    if (control_text == NULL) {
        if (pushed_pretty) output_stream_set_pretty_context_depth(it, stream, pretty_depth);
        snprintf(err, errsz, "format expects a string control string");
        return 0;
    }
    if (!format_execute_control_string(it, env, stream, control_text, args, 2, err, errsz)) {
        if (pushed_pretty) output_stream_set_pretty_context_depth(it, stream, pretty_depth);
        free(control_text);
        return 0;
    }
    free(control_text);
    if (return_string) {
        result_text = string_output_stream_take_text(stream);
        if (pushed_pretty) output_stream_set_pretty_context_depth(it, stream, pretty_depth);
        *out = make_string_value(result_text);
        free(result_text);
        interp_set_single_value(it, *out);
        return 1;
    }
    if (pushed_pretty) output_stream_set_pretty_context_depth(it, stream, pretty_depth);
    *out = it->nil;
    interp_set_single_value(it, *out);
    return 1;
}

static Value *make_formatter_macro_closure(Interp *it, Env *env) {
    ValueArray macro_params;
    ValueArray params_data;
    ValueArray function_data;
    ValueArray function_form_data;
    ValueArray unquote_data;
    ValueArray apply_data;
    ValueArray lambda_data;
    ValueArray quasiquote_data;
    ValueArray macro_body;
    Value *macro_param = common_lisp_runtime_symbol_or_fallback(it, "control-string");
    Value *stream_param = common_lisp_runtime_symbol_or_fallback(it, "stream");
    Value *args_param = common_lisp_runtime_symbol_or_fallback(it, "args");
    Value *rest_keyword = common_lisp_runtime_symbol_or_fallback(it, "&rest");
    Value *lambda_sym = common_lisp_runtime_symbol_or_fallback(it, "lambda");
    Value *apply_sym = common_lisp_runtime_symbol_or_fallback(it, "apply");
    Value *function_sym = common_lisp_runtime_symbol_or_fallback(it, "function");
    Value *quasiquote_sym = common_lisp_runtime_symbol_or_fallback(it, "quasiquote");
    Value *unquote_sym = common_lisp_runtime_symbol_or_fallback(it, "unquote");
    Value *format_sym = common_lisp_runtime_symbol_or_fallback(it, "format");
    Value *macro = NULL;
    value_array_init(&macro_params);
    value_array_init(&params_data);
    value_array_init(&function_data);
    value_array_init(&function_form_data);
    value_array_init(&unquote_data);
    value_array_init(&apply_data);
    value_array_init(&lambda_data);
    value_array_init(&quasiquote_data);
    value_array_init(&macro_body);
    value_array_push(&macro_params, macro_param);
    value_array_push(&params_data, stream_param);
    value_array_push(&params_data, rest_keyword);
    value_array_push(&params_data, args_param);
    value_array_push(&function_data, function_sym);
    value_array_push(&function_data, format_sym);
    value_array_push(&unquote_data, unquote_sym);
    value_array_push(&unquote_data, macro_param);
    value_array_push(&apply_data, apply_sym);
    value_array_push(&apply_data, make_list_value(&function_data));
    value_array_push(&apply_data, stream_param);
    value_array_push(&apply_data, make_list_value(&unquote_data));
    value_array_push(&apply_data, args_param);
    value_array_push(&lambda_data, lambda_sym);
    value_array_push(&lambda_data, make_list_value(&params_data));
    value_array_push(&lambda_data, make_list_value(&apply_data));
    value_array_push(&function_form_data, function_sym);
    value_array_push(&function_form_data, make_list_value(&lambda_data));
    value_array_push(&quasiquote_data, quasiquote_sym);
    value_array_push(&quasiquote_data, make_list_value(&function_form_data));
    value_array_push(&macro_body, make_list_value(&quasiquote_data));
    macro = make_closure_value(make_list_value(&macro_params), make_list_value(&macro_body), env, 1);
    value_array_dispose(&macro_params);
    value_array_dispose(&params_data);
    value_array_dispose(&function_data);
    value_array_dispose(&function_form_data);
    value_array_dispose(&unquote_data);
    value_array_dispose(&apply_data);
    value_array_dispose(&lambda_data);
    value_array_dispose(&quasiquote_data);
    value_array_dispose(&macro_body);
    return macro;
}

static int builtin_make_condition(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    if (args->count < 1 || args->items[0]->type != VALUE_SYMBOL || !condition_type_symbol_recognized(it, args->items[0])) {
        snprintf(err, errsz, "make-condition expects a recognized condition type symbol");
        return 0;
    }
    (void)env;
    return condition_parse_make_initargs(it, args, 1, args->items[0], NULL, NULL, NULL, out, err, errsz);
}

