static int signal_control_error_no_restart(Interp *it, Env *env, const char *who, char *err, size_t errsz) {
    Value *condition = NULL;
    if (!condition_make_instance(it,
                                 common_lisp_runtime_symbol_or_fallback(it, "control-error"),
                                 it->nil,
                                 it->nil,
                                 NULL,
                                 NULL,
                                 NULL,
                                 &condition,
                                 err,
                                 errsz)) {
        return 0;
    }
    if (!condition_invoke_handlers(it, env, condition, err, errsz)) return 0;
    it->pending_condition = condition;
    snprintf(err, errsz, "%s restart is not currently active", who);
    return 0;
}

static int restart_optional_condition(Value *value, Value **out, char *err, size_t errsz) {
    if (value == NULL || value->type == VALUE_NIL) {
        if (out != NULL) *out = value;
        return 1;
    }
    if (!value_is_condition_object(NULL, value)) {
        snprintf(err, errsz, "restart condition argument must be a condition or nil");
        return 0;
    }
    if (out != NULL) *out = value;
    return 1;
}

static int builtin_compute_restarts(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    Value *condition = it->nil;
    ValueArray restarts;
    RestartFrame *frame = NULL;
    int match = 0;
    if (args->count > 1) {
        snprintf(err, errsz, "compute-restarts expects at most one optional condition");
        return 0;
    }
    if (args->count == 1 && !restart_optional_condition(args->items[0], &condition, err, errsz)) return 0;
    value_array_init(&restarts);
    for (frame = it->restarts; frame != NULL; frame = frame->prev) {
        if (!restart_matches_condition(it, env, frame, condition, &match, err, errsz)) return 0;
        if (!match) continue;
        value_array_push(&restarts, make_restart_object(it, frame->name, frame->token, frame->report_function));
    }
    *out = runtime_list_from_array(it->nil, &restarts);
    return 1;
}

static int builtin_find_restart(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    Value *condition = it->nil;
    RestartFrame *frame = NULL;
    if (args->count < 1 || args->count > 2) {
        snprintf(err, errsz, "find-restart expects a restart designator and an optional condition");
        return 0;
    }
    if (args->count == 2 && !restart_optional_condition(args->items[1], &condition, err, errsz)) return 0;
    if (args->items[0]->type == VALUE_NIL) {
        *out = it->nil;
        return 1;
    }
    if (args->items[0]->type != VALUE_SYMBOL && !restart_extract_parts(args->items[0], NULL, NULL)) {
        snprintf(err, errsz, "find-restart expects a restart object or restart name");
        return 0;
    }
    if (!find_restart_frame_by_designator(it, env, args->items[0], condition, &frame, err, errsz)) return 0;
    *out = (frame != NULL) ? make_restart_object(it, frame->name, frame->token, frame->report_function) : it->nil;
    return 1;
}

static int builtin_invoke_restart(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    RestartFrame *frame = NULL;
    ValueArray invoke_args;
    if (args->count < 1) {
        snprintf(err, errsz, "invoke-restart expects a restart designator");
        return 0;
    }
    if (!find_restart_frame_by_designator(it, env, args->items[0], it->nil, &frame, err, errsz)) return 0;
    if (frame == NULL) {
        snprintf(err, errsz, "restart is not currently active");
        return 0;
    }
    value_array_init(&invoke_args);
    for (int i = 1; i < args->count; ++i) value_array_push(&invoke_args, args->items[i]);
    return invoke_restart_frame(it, env, frame, &invoke_args, out, err, errsz);
}

static int builtin_invoke_restart_interactively(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    RestartFrame *frame = NULL;
    ValueArray interactive_args;
    ValueArray empty_args;
    Value *interactive_result = it->nil;
    int i;
    if (args->count != 1) {
        snprintf(err, errsz, "invoke-restart-interactively expects exactly one restart designator");
        return 0;
    }
    if (!find_restart_frame_by_designator(it, env, args->items[0], it->nil, &frame, err, errsz)) return 0;
    if (frame == NULL) {
        snprintf(err, errsz, "restart is not currently active");
        return 0;
    }
    value_array_init(&interactive_args);
    if (frame->interactive_function != NULL && frame->interactive_function->type != VALUE_NIL) {
        value_array_init(&empty_args);
        if (!apply_callable(it, env, frame->interactive_function, &empty_args, &interactive_result, err, errsz)) return 0;
        if (!proper_form_to_array(interactive_result, &interactive_args)) {
            snprintf(err, errsz, "restart interactive function must return a proper list of arguments");
            return 0;
        }
    }
    for (i = 0; i < interactive_args.count; ++i) {
        if (interactive_args.items[i] == NULL) {
            snprintf(err, errsz, "restart interactive function returned an invalid argument list");
            return 0;
        }
    }
    return invoke_restart_frame(it, env, frame, &interactive_args, out, err, errsz);
}

static int builtin_abort(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    RestartFrame *frame = NULL;
    Value *condition = it->nil;
    ValueArray invoke_args;
    if (args->count > 1) {
        snprintf(err, errsz, "abort expects at most one optional condition");
        return 0;
    }
    if (args->count == 1 && !restart_optional_condition(args->items[0], &condition, err, errsz)) return 0;
    if (!find_restart_frame_by_designator(it, env, common_lisp_runtime_symbol_or_fallback(it, "abort"), condition, &frame, err, errsz)) return 0;
    if (frame == NULL) return signal_control_error_no_restart(it, env, "abort", err, errsz);
    value_array_init(&invoke_args);
    return invoke_restart_frame(it, env, frame, &invoke_args, out, err, errsz);
}

static int builtin_continue(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    RestartFrame *frame = NULL;
    Value *condition = it->nil;
    ValueArray invoke_args;
    if (args->count > 1) {
        snprintf(err, errsz, "continue expects at most one optional condition");
        return 0;
    }
    if (args->count == 1 && !restart_optional_condition(args->items[0], &condition, err, errsz)) return 0;
    if (!find_restart_frame_by_designator(it, env, common_lisp_runtime_symbol_or_fallback(it, "continue"), condition, &frame, err, errsz)) return 0;
    if (frame == NULL) {
        *out = it->nil;
        interp_set_single_value(it, *out);
        return 1;
    }
    value_array_init(&invoke_args);
    return invoke_restart_frame(it, env, frame, &invoke_args, out, err, errsz);
}

