static int builtin_warn(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    Value *condition = NULL;
    char *message = NULL;
    RestartFrame frame;
    int jumped = 0;
    CompilationUnitFrame *target = NULL;
    if (!condition_designator_to_value(it, env, args, "warn", "simple-warning", &condition, err, errsz)) return 0;
    frame.prev = it->restarts;
    frame.name = common_lisp_runtime_symbol_or_fallback(it, "muffle-warning");
    frame.token = make_generated_uninterned_symbol(it, "restart");
    frame.function = it->nil;
    frame.report_function = it->nil;
    frame.associated_condition = condition;
    frame.test_function = it->nil;
    frame.interactive_function = it->nil;
    frame.invoked_arg_list = it->nil;
    frame.kind = RESTART_KIND_CERROR_CONTINUE;
    frame.saved_blocks = it->blocks;
    frame.saved_dynamic = it->dynamic;
    frame.saved_tagbodies = it->tagbodies;
    frame.saved_catches = it->catches;
    frame.saved_handlers = it->handlers;
    frame.saved_restarts = it->restarts;
    frame.saved_condition_restart_assocs = it->condition_restart_assocs;
    it->restarts = &frame;
    jumped = setjmp(frame.buf);
    if (jumped != 0) {
        interp_restore_restart_escape_state(it, &frame);
        *out = it->nil;
        interp_set_single_value(it, *out);
        return 1;
    }
    if (!condition_invoke_handlers(it, env, condition, err, errsz)) {
        it->restarts = frame.prev;
        return 0;
    }
    if (!condition_render_message_text(it, env, condition, &message, err, errsz)) {
        it->restarts = frame.prev;
        return 0;
    }
    it->restarts = frame.prev;
    target = interp_compilation_unit_warning_target(it);
    if (target != NULL) {
        strvec_push_copy(&target->warnings, (message != NULL) ? message : "warning");
        free(message);
    } else {
        if (!warning_message_emit(it, env, message, err, errsz)) {
            free(message);
            return 0;
        }
        free(message);
    }
    *out = it->nil;
    interp_set_single_value(it, *out);
    return 1;
}

static int builtin_error(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    Value *condition = NULL;
    char *message = NULL;
    if (!condition_designator_to_value(it, env, args, "error", "simple-error", &condition, err, errsz)) return 0;
    if (!condition_invoke_handlers(it, env, condition, err, errsz)) return 0;
    if (!condition_render_message_text(it, env, condition, &message, err, errsz)) return 0;
    it->pending_condition = condition;
    snprintf(err, errsz, "%s", (message != NULL && message[0] != '\0') ? message : "error");
    free(message);
    (void)out;
    return 0;
}

static int builtin_cerror(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    ValueArray condition_args;
    ValueArray report_arg_forms;
    Value *condition = NULL;
    char *message = NULL;
    RestartFrame frame;
    int jumped = 0;
    int i;
    if (args->count < 2) {
        snprintf(err, errsz, "cerror expects a continue format-control and a condition designator");
        return 0;
    }
    value_array_init(&condition_args);
    for (int i = 1; i < args->count; ++i) value_array_push(&condition_args, args->items[i]);
    if (value_is_condition_object(NULL, condition_args.items[0])) {
        condition = condition_args.items[0];
    } else if (!condition_designator_to_value(it, env, &condition_args, "cerror", "simple-error", &condition, err, errsz)) {
        return 0;
    }
    frame.prev = it->restarts;
    frame.name = common_lisp_runtime_symbol_or_fallback(it, "continue");
    frame.token = make_generated_uninterned_symbol(it, "restart");
    frame.function = it->nil;
    value_array_init(&report_arg_forms);
    for (i = 2; i < args->count; ++i) {
        value_array_push(&report_arg_forms, make_runtime_quote_form(it, args->items[i]));
    }
    frame.report_function = make_restart_report_format_function(it, env, make_runtime_quote_form(it, args->items[0]), &report_arg_forms);
    frame.associated_condition = condition;
    frame.test_function = it->nil;
    frame.interactive_function = it->nil;
    frame.invoked_arg_list = it->nil;
    frame.kind = RESTART_KIND_CERROR_CONTINUE;
    frame.saved_blocks = it->blocks;
    frame.saved_dynamic = it->dynamic;
    frame.saved_tagbodies = it->tagbodies;
    frame.saved_catches = it->catches;
    frame.saved_handlers = it->handlers;
    frame.saved_restarts = it->restarts;
    frame.saved_condition_restart_assocs = it->condition_restart_assocs;
    it->restarts = &frame;
    jumped = setjmp(frame.buf);
    if (jumped != 0) {
        interp_restore_restart_escape_state(it, &frame);
        *out = it->nil;
        interp_set_single_value(it, *out);
        return 1;
    }
    if (!condition_invoke_handlers(it, env, condition, err, errsz)) {
        it->restarts = frame.prev;
        return 0;
    }
    if (!condition_render_message_text(it, env, condition, &message, err, errsz)) {
        it->restarts = frame.prev;
        return 0;
    }
    it->restarts = frame.prev;
    it->pending_condition = condition;
    snprintf(err, errsz, "%s", (message != NULL && message[0] != '\0') ? message : "error");
    free(message);
    (void)out;
    return 0;
}

