static int builtin_get_internal_run_time(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    clock_t ticks = 0;
    double millis = 0.0;
    (void)env;
    if (args->count != 0) {
        snprintf(err, errsz, "get-internal-run-time expects no arguments");
        return 0;
    }
    ticks = clock();
    if (ticks == (clock_t)-1) {
        snprintf(err, errsz, "could not determine the current run time");
        return 0;
    }
    millis = ((double)ticks * 1000.0) / (double)CLOCKS_PER_SEC;
    if (!isfinite(millis) || millis < 0.0) {
        snprintf(err, errsz, "could not determine the current run time");
        return 0;
    }
    *out = make_int_value(bigint_from_i64((int64_t)llround(millis)));
    interp_set_single_value(it, *out);
    return 1;
}

static int builtin_get_decoded_time(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    int daylight_p = 0;
    int64_t zone_seconds = 0;
    int64_t universal_seconds = 0;
    ValueArray values;
    (void)env;
    if (args->count != 0) {
        snprintf(err, errsz, "get-decoded-time expects no arguments");
        return 0;
    }
    if (!current_time_to_universal_seconds(&universal_seconds, err, errsz)) return 0;
    if (!current_local_time_zone_seconds_from_epoch((time_t)(universal_seconds - 2208988800LL), &zone_seconds, &daylight_p, err, errsz)) return 0;
    if (!fill_decoded_time_values(it, universal_seconds, zone_seconds, daylight_p, &values, err, errsz)) return 0;
    interp_set_values(it, &values);
    *out = values.items[0];
    return 1;
}

static int builtin_decode_universal_time(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    int64_t universal_seconds = 0;
    int64_t zone_seconds = 0;
    int daylight_p = 0;
    ValueArray values;
    if (args->count != 1 && args->count != 2) {
        snprintf(err, errsz, "decode-universal-time expects a universal time and an optional time-zone");
        return 0;
    }
    if (!value_to_exact_i64(it, args->items[0], "decode-universal-time", "universal-time", &universal_seconds, err, errsz)) return 0;
    if (universal_seconds < 0) {
        snprintf(err, errsz, "decode-universal-time expects a non-negative universal time");
        return 0;
    }
    if (args->count == 2) {
        if (!value_to_time_zone_seconds(it, args->items[1], "decode-universal-time", &zone_seconds, err, errsz)) return 0;
    } else {
        if (!current_local_time_zone_seconds_from_epoch((time_t)(universal_seconds - 2208988800LL), &zone_seconds, &daylight_p, err, errsz)) return 0;
    }
    if (!fill_decoded_time_values(it, universal_seconds, zone_seconds, (args->count == 2) ? 0 : daylight_p, &values, err, errsz)) return 0;
    interp_set_values(it, &values);
    *out = values.items[0];
    return 1;
}

static int builtin_encode_universal_time(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    int64_t second = 0;
    int64_t minute = 0;
    int64_t hour = 0;
    int64_t day = 0;
    int64_t month = 0;
    int64_t year = 0;
    int64_t zone_seconds = 0;
    int64_t universal_seconds = 0;
    time_t epoch = (time_t)0;
    struct tm local_tm;
    (void)env;
    if (args->count != 6 && args->count != 7) {
        snprintf(err, errsz, "encode-universal-time expects second, minute, hour, date, month, year and an optional time-zone");
        return 0;
    }
    if (!value_to_exact_i64(it, args->items[0], "encode-universal-time", "second", &second, err, errsz)) return 0;
    if (!value_to_exact_i64(it, args->items[1], "encode-universal-time", "minute", &minute, err, errsz)) return 0;
    if (!value_to_exact_i64(it, args->items[2], "encode-universal-time", "hour", &hour, err, errsz)) return 0;
    if (!value_to_exact_i64(it, args->items[3], "encode-universal-time", "date", &day, err, errsz)) return 0;
    if (!value_to_exact_i64(it, args->items[4], "encode-universal-time", "month", &month, err, errsz)) return 0;
    if (!value_to_exact_i64(it, args->items[5], "encode-universal-time", "year", &year, err, errsz)) return 0;
    if (!validate_encoded_time_fields(second, minute, hour, day, month, year, "encode-universal-time", err, errsz)) return 0;
    if (args->count == 7) {
        if (!value_to_time_zone_seconds(it, args->items[6], "encode-universal-time", &zone_seconds, err, errsz)) return 0;
        universal_seconds = universal_seconds_from_fields_i64(year, month, day, hour, minute, second) + zone_seconds;
    } else {
        memset(&local_tm, 0, sizeof(local_tm));
        local_tm.tm_sec = (int)second;
        local_tm.tm_min = (int)minute;
        local_tm.tm_hour = (int)hour;
        local_tm.tm_mday = (int)day;
        local_tm.tm_mon = (int)month - 1;
        local_tm.tm_year = (int)year - 1900;
        local_tm.tm_isdst = -1;
        epoch = mktime(&local_tm);
        if (epoch == (time_t)-1) {
            snprintf(err, errsz, "encode-universal-time could not determine the corresponding universal time");
            return 0;
        }
        universal_seconds = (int64_t)epoch + 2208988800LL;
    }
    if (universal_seconds < 0) {
        snprintf(err, errsz, "encode-universal-time produced an invalid universal time");
        return 0;
    }
    *out = make_int_value(bigint_from_i64(universal_seconds));
    interp_set_single_value(it, *out);
    return 1;
}

static int builtin_sleep(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    double seconds = 0.0;
    uint64_t millis = 0U;
#if defined(_WIN32)
    uint64_t remaining = 0U;
#else
    struct timespec req;
    struct timespec rem;
#endif
    (void)env;
    if (args->count != 1) {
        snprintf(err, errsz, "sleep expects one non-negative real");
        return 0;
    }
    if (!value_to_double_number(it, args->items[0], "sleep", "seconds", &seconds, err, errsz)) return 0;
    if (seconds < 0.0) {
        snprintf(err, errsz, "sleep expects one non-negative real");
        return 0;
    }
    millis = (uint64_t)ceil(seconds * 1000.0);
#if defined(_WIN32)
    remaining = millis;
    while (remaining > 0U) {
        DWORD chunk = (remaining > 0xFFFFFFFFULL) ? 0xFFFFFFFFUL : (DWORD)remaining;
        Sleep(chunk);
        remaining -= (uint64_t)chunk;
    }
#else
    req.tv_sec = (time_t)(millis / 1000ULL);
    req.tv_nsec = (long)((millis % 1000ULL) * 1000000ULL);
    while (nanosleep(&req, &rem) != 0) {
        if (errno != EINTR) {
            snprintf(err, errsz, "sleep could not complete: %s", strerror(errno));
            return 0;
        }
        req = rem;
    }
#endif
    *out = it->nil;
    interp_set_single_value(it, *out);
    return 1;
}

