static int builtin_prin1(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    char *text = NULL;
    Value *stream = NULL;
    WriteKeywordOptions opts;
    PrintRenderOptions render;
    if (args->count < 1 || args->count > 2) {
        snprintf(err, errsz, "prin1 expects one argument and an optional output-stream");
        return 0;
    }
    if (args->count == 2) stream = args->items[1];
    if (!resolve_output_stream_designator(it, stream, "prin1", &stream, err, errsz)) return 0;
    memset(&opts, 0, sizeof(opts));
    opts.escape = 1;
    opts.have_escape = 1;
    if (!resolve_print_render_options(it, env, &opts, &render, err, errsz)) return 0;
    if (!render_write_text(it, env, args->items[0], &render, &text)) return 0;
    output_stream_write_text(it, stream, text);
    free(text);
    *out = args->items[0];
    return 1;
}

static int builtin_princ(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    char *text = NULL;
    Value *stream = NULL;
    WriteKeywordOptions opts;
    PrintRenderOptions render;
    if (args->count < 1 || args->count > 2) {
        snprintf(err, errsz, "princ expects one argument and an optional output-stream");
        return 0;
    }
    if (args->count == 2) stream = args->items[1];
    if (!resolve_output_stream_designator(it, stream, "princ", &stream, err, errsz)) return 0;
    memset(&opts, 0, sizeof(opts));
    opts.escape = 0;
    opts.have_escape = 1;
    if (!resolve_print_render_options(it, env, &opts, &render, err, errsz)) return 0;
    if (!render_write_text(it, env, args->items[0], &render, &text)) return 0;
    output_stream_write_text(it, stream, text);
    free(text);
    *out = args->items[0];
    return 1;
}

static int builtin_write_string_common(Interp *it,
                                       const ValueArray *args,
                                       const char *who,
                                       int append_newline,
                                       Value **out,
                                       char *err,
                                       size_t errsz) {
    Value *stream = NULL;
    Value *start_value = NULL;
    Value *end_value = NULL;
    int i;
    int start = 0;
    int end = 0;
    int len = 0;
    char *slice = NULL;
    if (args->count < 1) {
        snprintf(err, errsz, "%s expects a string", who);
        return 0;
    }
    if (args->items[0]->type != VALUE_STRING) {
        snprintf(err, errsz, "%s expects a string", who);
        return 0;
    }
    if (args->count >= 2) stream = args->items[1];
    if (args->count > 2 && (((args->count - 2) % 2) != 0)) {
        snprintf(err, errsz, "%s keyword arguments must appear in keyword/value pairs", who);
        return 0;
    }
    for (i = 2; i < args->count; i += 2) {
        Value *key = args->items[i];
        Value *val = args->items[i + 1];
        if (!value_is_keyword(key)) {
            snprintf(err, errsz, "expected a keyword argument, got %s", value_type_name(key));
            return 0;
        }
        if (keyword_matches(key, ":start")) {
            start_value = val;
        } else if (keyword_matches(key, ":end")) {
            end_value = val;
        } else {
            snprintf(err, errsz, "unsupported %s keyword '%s'", who, key->as.str);
            return 0;
        }
    }
    if (!resolve_output_stream_designator(it, stream, who, &stream, err, errsz)) return 0;
    if (!parse_string_bounds(it, args->items[0], start_value, end_value, who, &start, &end, err, errsz)) return 0;
    len = end - start;
    slice = value_string_copy_range(args->items[0], start, len);
    output_stream_write_text(it, stream, slice);
    free(slice);
    if (append_newline) output_stream_write_char(it, stream, '\n');
    *out = args->items[0];
    return 1;
}

static int builtin_write_string(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    (void)env;
    return builtin_write_string_common(it, args, "write-string", 0, out, err, errsz);
}

static int builtin_write_line(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    (void)env;
    return builtin_write_string_common(it, args, "write-line", 1, out, err, errsz);
}

static int builtin_terpri(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    Value *stream = NULL;
    (void)env;
    if (args->count > 1) {
        snprintf(err, errsz, "terpri expects an optional output-stream");
        return 0;
    }
    if (args->count == 1) stream = args->items[0];
    if (!resolve_output_stream_designator(it, stream, "terpri", &stream, err, errsz)) return 0;
    output_stream_write_char(it, stream, '\n');
    *out = it->nil;
    return 1;
}

static int builtin_fresh_line(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    Value *stream = NULL;
    (void)env;
    if (args->count > 1) {
        snprintf(err, errsz, "fresh-line expects an optional output-stream");
        return 0;
    }
    if (args->count == 1) stream = args->items[0];
    if (!resolve_output_stream_designator(it, stream, "fresh-line", &stream, err, errsz)) return 0;
    if (output_stream_at_line_start(it, stream)) {
        *out = it->nil;
        return 1;
    }
    output_stream_write_char(it, stream, '\n');
    *out = it->true_value;
    return 1;
}

static int pprint_newline_kind_from_keyword(Value *kind, PPrintNewlineKind *out_kind, char *err, size_t errsz);
static int pprint_should_emit_newline(Interp *it,
                                      Env *env,
                                      Value *stream,
                                      PPrintNewlineKind kind,
                                      int *out_emit,
                                      char *err,
                                      size_t errsz);

static int builtin_pprint_newline(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    Value *stream = NULL;
    Value *kind = NULL;
    PPrintNewlineKind newline_kind = PPRINT_NEWLINE_LINEAR;
    int emit_newline = 0;
    (void)env;
    if (args->count < 1 || args->count > 2) {
        snprintf(err, errsz, "pprint-newline expects a kind and optional output-stream");
        return 0;
    }
    kind = args->items[0];
    if (!pprint_newline_kind_from_keyword(kind, &newline_kind, err, errsz)) {
        return 0;
    }
    if (args->count == 2) stream = args->items[1];
    if (!resolve_output_stream_designator(it, stream, "pprint-newline", &stream, err, errsz)) return 0;
    if (!pprint_should_emit_newline(it, env, stream, newline_kind, &emit_newline, err, errsz)) return 0;
    if (emit_newline) {
        output_stream_write_char(it, stream, '\n');
    }
    *out = it->nil;
    return 1;
}

static int builtin_pprint_indent(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    Value *stream = NULL;
    Value *relative_to = NULL;
    double n = 0.0;
    double target = 0.0;
    int current_column = 0;
    int base_column = 0;
    int indent_column = 0;
    (void)env;
    if (args->count < 2 || args->count > 3) {
        snprintf(err, errsz, "pprint-indent expects relative-to, n, and optional output-stream");
        return 0;
    }
    relative_to = args->items[0];
    if (!value_is_keyword(relative_to) ||
        (!keyword_matches(relative_to, ":block") &&
         !keyword_matches(relative_to, ":current"))) {
        snprintf(err, errsz, "pprint-indent relative-to must be :block or :current");
        return 0;
    }
    if (!value_to_double_number(it, args->items[1], "pprint-indent", "n", &n, err, errsz)) return 0;
    if (args->count == 3) stream = args->items[2];
    if (!runtime_special_truthy(it, env, "*print-pretty*") || !output_stream_pretty_context_active(it, stream)) {
        *out = it->nil;
        return 1;
    }
    if (!resolve_output_stream_designator(it, stream, "pprint-indent", &stream, err, errsz)) return 0;
    current_column = output_stream_current_column(it, stream);
    base_column = output_stream_pretty_block_column(it, stream);
    {
        int right_margin = 0;
        int miser_mode = 0;
        if (!pprint_right_margin_value(it, env, &right_margin, err, errsz)) return 0;
        miser_mode = pprint_miser_mode_active(it, env, base_column, right_margin, err, errsz);
        if (miser_mode < 0) return 0;
        if (miser_mode) {
            *out = it->nil;
            return 1;
        }
    }
    target = keyword_matches(relative_to, ":current") ? ((double)current_column + n) : ((double)base_column + n);
    if (target < 0.0) {
        indent_column = 0;
    } else if (target > (double)INT_MAX) {
        indent_column = INT_MAX;
    } else {
        indent_column = (int)llround(target);
        if (indent_column < 0) indent_column = 0;
    }
    output_stream_set_pretty_indent_column(it, stream, indent_column);
    *out = it->nil;
    return 1;
}

static int builtin_pprint_tab(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    Value *stream = NULL;
    Value *kind = NULL;
    double colnum_d = 0.0;
    double colinc_d = 0.0;
    int current_column = 0;
    int section_column = 0;
    int colnum = 0;
    int colinc = 0;
    int spaces = 0;
    int target = 0;
    int origin = 0;
    int relative = 0;
    int section_relative = 0;
    (void)env;
    if (args->count < 3 || args->count > 4) {
        snprintf(err, errsz, "pprint-tab expects kind, colnum, colinc, and optional output-stream");
        return 0;
    }
    kind = args->items[0];
    if (!value_is_keyword(kind) ||
        (!keyword_matches(kind, ":line") &&
         !keyword_matches(kind, ":line-relative") &&
         !keyword_matches(kind, ":section") &&
         !keyword_matches(kind, ":section-relative"))) {
        snprintf(err, errsz, "pprint-tab kind must be one of :line, :line-relative, :section, or :section-relative");
        return 0;
    }
    if (!value_to_double_number(it, args->items[1], "pprint-tab", "colnum", &colnum_d, err, errsz)) return 0;
    if (!value_to_double_number(it, args->items[2], "pprint-tab", "colinc", &colinc_d, err, errsz)) return 0;
    if (args->count == 4) stream = args->items[3];
    if (!runtime_special_truthy(it, env, "*print-pretty*") || !output_stream_pretty_context_active(it, stream)) {
        *out = it->nil;
        return 1;
    }
    if (!resolve_output_stream_designator(it, stream, "pprint-tab", &stream, err, errsz)) return 0;
    output_stream_emit_pretty_indent(it, stream);
    current_column = output_stream_current_column(it, stream);
    section_column = output_stream_pretty_block_column(it, stream);
    if (colnum_d < 0.0 || colinc_d < 0.0) {
        snprintf(err, errsz, "pprint-tab expects nonnegative numeric colnum and colinc");
        return 0;
    }
    if (colnum_d > (double)INT_MAX || colinc_d > (double)INT_MAX) {
        snprintf(err, errsz, "pprint-tab colnum or colinc is too large");
        return 0;
    }
    colnum = (int)llround(colnum_d);
    colinc = (int)llround(colinc_d);
    section_relative = keyword_matches(kind, ":section") || keyword_matches(kind, ":section-relative");
    relative = keyword_matches(kind, ":line-relative") || keyword_matches(kind, ":section-relative");
    origin = section_relative ? section_column : 0;
    if (relative) {
        target = current_column + colnum;
        if (colinc > 0) {
            int rel = target - origin;
            int rem = rel % colinc;
            if (rem < 0) rem += colinc;
            if (rem != 0) target += (colinc - rem);
        }
        spaces = target - current_column;
    } else {
        target = origin + colnum;
        if (current_column < target) {
            spaces = target - current_column;
        } else if (colinc == 0) {
            spaces = 0;
        } else {
            spaces = colinc - ((current_column - target) % colinc);
            if (spaces == 0) spaces = colinc;
        }
    }
    if (spaces < 0) spaces = 0;
    format_write_spaces(it, stream, spaces);
    *out = it->nil;
    return 1;
}

typedef enum {
    PPRINT_LIST_FILL = 0,
    PPRINT_LIST_LINEAR = 1,
    PPRINT_LIST_TABULAR = 2
} PPrintListStyle;

static void pprint_write_spaces_raw(Interp *it, Value *stream, int count) {
    while (count-- > 0) output_stream_write_char_raw(it, stream, ' ');
}

static void pprint_write_newline_and_indent_raw(Interp *it, Value *stream, int indent) {
    if (indent < 0) indent = 0;
    output_stream_set_pretty_indent_column(it, stream, indent);
    output_stream_write_char_raw(it, stream, '\n');
    pprint_write_spaces_raw(it, stream, indent);
}

static int pprint_collect_list_elements(Interp *it,
                                        Value *object,
                                        ValueArray *items,
                                        Value **tail,
                                        char *err,
                                        size_t errsz) {
    Value *cur = object;
    Value *slow = object;
    Value *fast = object;
    int i = 0;
    value_array_init(items);
    if (tail != NULL) *tail = it->nil;
    for (;;) {
        if (cur == NULL) {
            if (tail != NULL) *tail = it->nil;
            return 1;
        }
        if (cur->type == VALUE_NIL) {
            if (tail != NULL) *tail = it->nil;
            return 1;
        }
        if (cur->type == VALUE_LIST) {
            for (i = 0; i < cur->as.array.count; ++i) value_array_push(items, cur->as.array.items[i]);
            if (tail != NULL) *tail = it->nil;
            return 1;
        }
        if (cur->type != VALUE_CONS) {
            if (tail != NULL) *tail = cur;
            return 1;
        }
        while (cur->type == VALUE_CONS) {
            value_array_push(items, cur->as.cons.car);
            cur = cur->as.cons.cdr;
            if (slow != NULL && slow->type == VALUE_CONS) slow = slow->as.cons.cdr;
            if (fast != NULL && fast->type == VALUE_CONS) fast = fast->as.cons.cdr;
            if (fast != NULL && fast->type == VALUE_CONS) fast = fast->as.cons.cdr;
            if (cur != NULL && cur->type == VALUE_CONS && slow == fast) {
                value_array_dispose(items);
                snprintf(err, errsz, "pprint list printer cannot handle circular lists");
                return 0;
            }
        }
    }
}

static int pprint_render_list_texts(Interp *it,
                                    Env *env,
                                    const ValueArray *items,
                                    Value *tail,
                                    const PrintRenderOptions *render,
                                    char ***out_texts,
                                    int **out_lengths,
                                    char **out_tail_text,
                                    int *out_tail_length,
                                    char *err,
                                    size_t errsz) {
    char **texts = NULL;
    int *lengths = NULL;
    char *tail_text = NULL;
    int tail_length = 0;
    int i = 0;
    if (out_texts != NULL) *out_texts = NULL;
    if (out_lengths != NULL) *out_lengths = NULL;
    if (out_tail_text != NULL) *out_tail_text = NULL;
    if (out_tail_length != NULL) *out_tail_length = 0;
    if (items->count > 0) {
        texts = (char **)xcalloc((size_t)items->count, sizeof(char *));
        lengths = (int *)xcalloc((size_t)items->count, sizeof(int));
        for (i = 0; i < items->count; ++i) {
            if (!render_write_text(it, env, items->items[i], render, &texts[i])) {
                goto fail;
            }
            lengths[i] = (int)strlen(texts[i]);
        }
    }
    if (tail != NULL && tail->type != VALUE_NIL) {
        if (!render_write_text(it, env, tail, render, &tail_text)) goto fail;
        tail_length = (int)strlen(tail_text);
    }
    if (out_texts != NULL) *out_texts = texts;
    else {
        for (i = 0; i < items->count; ++i) free(texts[i]);
        free(texts);
        texts = NULL;
    }
    if (out_lengths != NULL) *out_lengths = lengths;
    else {
        free(lengths);
        lengths = NULL;
    }
    if (out_tail_text != NULL) *out_tail_text = tail_text;
    else {
        free(tail_text);
        tail_text = NULL;
    }
    if (out_tail_length != NULL) *out_tail_length = tail_length;
    return 1;
fail:
    if (texts != NULL) {
        for (i = 0; i < items->count; ++i) free(texts[i]);
        free(texts);
    }
    free(lengths);
    free(tail_text);
    return 0;
}

static int pprint_right_margin_value(Interp *it, Env *env, int *out_margin, char *err, size_t errsz) {
    Value *margin_value = NULL;
    int is_bound = 0;
    int margin = 80;
    if (symbol_value_lookup_runtime_special(it, env, "*print-right-margin*", &margin_value, &is_bound) && is_bound) {
        if (!value_to_optional_nonnegative(margin_value, "*print-right-margin*", &margin, err, errsz)) return 0;
    }
    *out_margin = margin;
    return 1;
}

static int pprint_miser_width_value(Interp *it, Env *env, int *out_width, char *err, size_t errsz) {
    Value *miser_value = NULL;
    int is_bound = 0;
    int width = -1;
    if (symbol_value_lookup_runtime_special(it, env, "*print-miser-width*", &miser_value, &is_bound) && is_bound) {
        if (!value_to_optional_nonnegative(miser_value, "*print-miser-width*", &width, err, errsz)) return 0;
    }
    *out_width = width;
    return 1;
}

static int pprint_newline_kind_from_keyword(Value *kind, PPrintNewlineKind *out_kind, char *err, size_t errsz) {
    if (kind == NULL || !value_is_keyword(kind)) {
        snprintf(err, errsz, "pprint-newline kind must be one of :linear, :fill, :miser, or :mandatory");
        return 0;
    }
    if (keyword_matches(kind, ":linear")) {
        if (out_kind != NULL) *out_kind = PPRINT_NEWLINE_LINEAR;
        return 1;
    }
    if (keyword_matches(kind, ":miser")) {
        if (out_kind != NULL) *out_kind = PPRINT_NEWLINE_MISER;
        return 1;
    }
    if (keyword_matches(kind, ":fill")) {
        if (out_kind != NULL) *out_kind = PPRINT_NEWLINE_FILL;
        return 1;
    }
    if (keyword_matches(kind, ":mandatory")) {
        if (out_kind != NULL) *out_kind = PPRINT_NEWLINE_MANDATORY;
        return 1;
    }
    snprintf(err, errsz, "pprint-newline kind must be one of :linear, :fill, :miser, or :mandatory");
    return 0;
}

static int pprint_should_emit_newline(Interp *it,
                                      Env *env,
                                      Value *stream,
                                      PPrintNewlineKind kind,
                                      int *out_emit,
                                      char *err,
                                      size_t errsz) {
    int pretty = runtime_special_truthy(it, env, "*print-pretty*");
    int right_margin = -1;
    int current_column = 0;
    int base_column = 0;
    int miser_mode = 0;
    if (out_emit != NULL) *out_emit = 0;
    if (!pretty || !output_stream_pretty_context_active(it, stream)) {
        return 1;
    }
    if (kind == PPRINT_NEWLINE_MANDATORY) {
        if (out_emit != NULL) *out_emit = 1;
        return 1;
    }
    if (!pprint_right_margin_value(it, env, &right_margin, err, errsz)) return 0;
    current_column = output_stream_current_column(it, stream);
    if (kind == PPRINT_NEWLINE_MISER) {
        base_column = output_stream_pretty_block_column(it, stream);
        miser_mode = pprint_miser_mode_active(it, env, base_column, right_margin, err, errsz);
        if (miser_mode < 0) return 0;
        if (!miser_mode) {
            return 1;
        }
    }
    if (right_margin >= 0 && current_column >= right_margin) {
        if (out_emit != NULL) *out_emit = 1;
    }
    return 1;
}

static int pprint_miser_mode_active(Interp *it, Env *env, int base_column, int right_margin, char *err, size_t errsz) {
    int miser_width = -1;
    if (!pprint_miser_width_value(it, env, &miser_width, err, errsz)) return -1;
    if (right_margin < 0 || miser_width < 0) return 0;
    return (right_margin - base_column) <= miser_width;
}

static int pprint_emit_minimum_whitespace_list(Interp *it,
                                               Env *env,
                                               Value *stream,
                                               const ValueArray *items,
                                               Value *tail,
                                               int colon_p,
                                               char *err,
                                               size_t errsz) {
    PrintRenderOptions render;
    char **texts = NULL;
    int *lengths = NULL;
    char *tail_text = NULL;
    int tail_length = 0;
    int i = 0;
    WriteKeywordOptions opts;
    memset(&opts, 0, sizeof(opts));
    if (!resolve_print_render_options(it, env, &opts, &render, err, errsz)) return 0;
    if (!pprint_render_list_texts(it, env, items, tail, &render, &texts, &lengths, &tail_text, &tail_length, err, errsz)) {
        return 0;
    }
    if (colon_p) output_stream_write_char_raw(it, stream, '(');
    for (i = 0; i < items->count; ++i) {
        if (i > 0) output_stream_write_char_raw(it, stream, ' ');
        output_stream_write_text(it, stream, texts[i]);
    }
    if (tail_text != NULL) {
        if (items->count > 0) output_stream_write_text(it, stream, " . ");
        output_stream_write_text(it, stream, tail_text);
    }
    if (colon_p) output_stream_write_char_raw(it, stream, ')');
    for (i = 0; i < items->count; ++i) free(texts[i]);
    free(texts);
    free(lengths);
    free(tail_text);
    return 1;
}

static int pprint_emit_linear_list(Interp *it,
                                   Env *env,
                                   Value *stream,
                                   const ValueArray *items,
                                   Value *tail,
                                   int colon_p,
                                   int right_margin,
                                   char *err,
                                   size_t errsz) {
    PrintRenderOptions render;
    WriteKeywordOptions opts;
    char **texts = NULL;
    int *lengths = NULL;
    char *tail_text = NULL;
    int tail_length = 0;
    int base_indent = 0;
    int available = 0;
    int total_width = 0;
    int i = 0;
    int one_line = 0;
    int has_tail = 0;
    memset(&opts, 0, sizeof(opts));
    if (!resolve_print_render_options(it, env, &opts, &render, err, errsz)) return 0;
    if (!pprint_render_list_texts(it, env, items, tail, &render, &texts, &lengths, &tail_text, &tail_length, err, errsz)) {
        return 0;
    }
    has_tail = (tail_text != NULL);
    if (colon_p) output_stream_write_char_raw(it, stream, '(');
    base_indent = output_stream_current_column(it, stream);
    output_stream_set_pretty_indent_column(it, stream, base_indent);
    if (items->count == 0 && !has_tail) {
        if (colon_p) output_stream_write_char_raw(it, stream, ')');
        for (i = 0; i < items->count; ++i) free(texts[i]);
        free(texts);
        free(lengths);
        free(tail_text);
        return 1;
    }
    if (right_margin < 0) {
        one_line = 1;
    } else {
        available = right_margin - base_indent;
        if (available < 0) available = 0;
        total_width = 0;
        for (i = 0; i < items->count; ++i) {
            total_width += lengths[i];
            if (i > 0) total_width += 1;
        }
        if (has_tail) total_width += (items->count > 0) ? (3 + tail_length) : tail_length;
        one_line = (total_width <= available);
    }
    if (one_line) {
        for (i = 0; i < items->count; ++i) {
            if (i > 0) output_stream_write_char_raw(it, stream, ' ');
            output_stream_write_text(it, stream, texts[i]);
        }
        if (has_tail) {
            if (items->count > 0) output_stream_write_text(it, stream, " . ");
            output_stream_write_text(it, stream, tail_text);
        }
    } else {
        for (i = 0; i < items->count; ++i) {
            if (i > 0) pprint_write_newline_and_indent_raw(it, stream, base_indent);
            output_stream_write_text(it, stream, texts[i]);
        }
        if (has_tail) {
            if (items->count > 0) output_stream_write_text(it, stream, " . ");
            output_stream_write_text(it, stream, tail_text);
        }
    }
    if (colon_p) output_stream_write_char_raw(it, stream, ')');
    for (i = 0; i < items->count; ++i) free(texts[i]);
    free(texts);
    free(lengths);
    free(tail_text);
    return 1;
}

static int pprint_emit_fill_list(Interp *it,
                                 Env *env,
                                 Value *stream,
                                 const ValueArray *items,
                                 Value *tail,
                                 int colon_p,
                                 int right_margin,
                                 char *err,
                                 size_t errsz) {
    PrintRenderOptions render;
    WriteKeywordOptions opts;
    char **texts = NULL;
    int *lengths = NULL;
    char *tail_text = NULL;
    int tail_length = 0;
    int base_indent = 0;
    int i = 0;
    int has_tail = 0;
    memset(&opts, 0, sizeof(opts));
    if (!resolve_print_render_options(it, env, &opts, &render, err, errsz)) return 0;
    if (!pprint_render_list_texts(it, env, items, tail, &render, &texts, &lengths, &tail_text, &tail_length, err, errsz)) {
        return 0;
    }
    has_tail = (tail_text != NULL);
    if (colon_p) output_stream_write_char_raw(it, stream, '(');
    base_indent = output_stream_current_column(it, stream);
    output_stream_set_pretty_indent_column(it, stream, base_indent);
    if (items->count == 0 && !has_tail) {
        if (colon_p) output_stream_write_char_raw(it, stream, ')');
        for (i = 0; i < items->count; ++i) free(texts[i]);
        free(texts);
        free(lengths);
        free(tail_text);
        return 1;
    }
    if (right_margin < 0) {
        for (i = 0; i < items->count; ++i) {
            if (i > 0) output_stream_write_char_raw(it, stream, ' ');
            output_stream_write_text(it, stream, texts[i]);
        }
        if (has_tail) {
            if (items->count > 0) output_stream_write_text(it, stream, " . ");
            output_stream_write_text(it, stream, tail_text);
        }
    } else {
        int current_column = output_stream_current_column(it, stream);
        int row_has_item = 0;
        int tail_new_line = 0;
        for (i = 0; i < items->count; ++i) {
            int projected = current_column + (row_has_item ? 1 : 0) + lengths[i];
            if (row_has_item && projected > right_margin) {
                pprint_write_newline_and_indent_raw(it, stream, base_indent);
                current_column = output_stream_current_column(it, stream);
                row_has_item = 0;
            } else if (row_has_item) {
                output_stream_write_char_raw(it, stream, ' ');
                current_column = output_stream_current_column(it, stream);
            }
            output_stream_write_text(it, stream, texts[i]);
            current_column = output_stream_current_column(it, stream);
            row_has_item = 1;
        }
        if (has_tail) {
            int projected = current_column + ((items->count > 0) ? 3 : 0) + tail_length;
            if (items->count > 0 && projected > right_margin) {
                pprint_write_newline_and_indent_raw(it, stream, base_indent);
                tail_new_line = 1;
            }
            if (items->count > 0) output_stream_write_text(it, stream, tail_new_line ? ". " : " . ");
            output_stream_write_text(it, stream, tail_text);
        }
    }
    if (colon_p) output_stream_write_char_raw(it, stream, ')');
    for (i = 0; i < items->count; ++i) free(texts[i]);
    free(texts);
    free(lengths);
    free(tail_text);
    return 1;
}

static int pprint_emit_tabular_list(Interp *it,
                                    Env *env,
                                    Value *stream,
                                    const ValueArray *items,
                                    Value *tail,
                                    int colon_p,
                                    int right_margin,
                                    int tabsize,
                                    char *err,
                                    size_t errsz) {
    PrintRenderOptions render;
    WriteKeywordOptions opts;
    char **texts = NULL;
    int *lengths = NULL;
    char *tail_text = NULL;
    int tail_length = 0;
    int base_indent = 0;
    int current_column = 0;
    int row_start = 0;
    int i = 0;
    int has_tail = 0;
    memset(&opts, 0, sizeof(opts));
    if (tabsize <= 0) tabsize = 1;
    if (!resolve_print_render_options(it, env, &opts, &render, err, errsz)) return 0;
    if (!pprint_render_list_texts(it, env, items, tail, &render, &texts, &lengths, &tail_text, &tail_length, err, errsz)) {
        return 0;
    }
    has_tail = (tail_text != NULL);
    if (colon_p) output_stream_write_char_raw(it, stream, '(');
    base_indent = output_stream_current_column(it, stream);
    row_start = base_indent;
    output_stream_set_pretty_indent_column(it, stream, base_indent);
    if (items->count == 0 && !has_tail) {
        if (colon_p) output_stream_write_char_raw(it, stream, ')');
        for (i = 0; i < items->count; ++i) free(texts[i]);
        free(texts);
        free(lengths);
        free(tail_text);
        return 1;
    }
    if (right_margin < 0) {
        for (i = 0; i < items->count; ++i) {
            if (i > 0) {
                int next_start = row_start + (((current_column - row_start + 1) + tabsize - 1) / tabsize) * tabsize;
                int pad = next_start - current_column;
                if (pad < 1) pad = 1;
                pprint_write_spaces_raw(it, stream, pad);
            }
            output_stream_write_text(it, stream, texts[i]);
            current_column = output_stream_current_column(it, stream);
        }
        if (has_tail) {
            if (items->count > 0) output_stream_write_text(it, stream, " . ");
            output_stream_write_text(it, stream, tail_text);
        }
    } else {
        current_column = output_stream_current_column(it, stream);
        int row_has_item = 0;
        int tail_new_line = 0;
        for (i = 0; i < items->count; ++i) {
            if (row_has_item) {
                int next_start = row_start + (((current_column - row_start + 1) + tabsize - 1) / tabsize) * tabsize;
                int projected = next_start + lengths[i];
                if (projected > right_margin) {
                    pprint_write_newline_and_indent_raw(it, stream, base_indent);
                    row_start = output_stream_current_column(it, stream);
                    current_column = row_start;
                    row_has_item = 0;
                } else {
                    int pad = next_start - current_column;
                    if (pad < 1) pad = 1;
                    pprint_write_spaces_raw(it, stream, pad);
                    current_column = output_stream_current_column(it, stream);
                }
            }
            output_stream_write_text(it, stream, texts[i]);
            current_column = output_stream_current_column(it, stream);
            row_has_item = 1;
        }
        if (has_tail) {
            int projected = current_column + ((items->count > 0) ? 3 : 0) + tail_length;
            if (items->count > 0 && projected > right_margin) {
                pprint_write_newline_and_indent_raw(it, stream, base_indent);
                tail_new_line = 1;
            }
            if (items->count > 0) output_stream_write_text(it, stream, tail_new_line ? ". " : " . ");
            output_stream_write_text(it, stream, tail_text);
        }
    }
    if (colon_p) output_stream_write_char_raw(it, stream, ')');
    for (i = 0; i < items->count; ++i) free(texts[i]);
    free(texts);
    free(lengths);
    free(tail_text);
    return 1;
}

static int builtin_pprint_fill(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    Value *stream = NULL;
    Value *object = NULL;
    ValueArray items;
    Value *tail = it->nil;
    int colon_p = 1;
    int pretty = 0;
    int right_margin = 0;
    if (args->count < 2 || args->count > 4) {
        snprintf(err, errsz, "pprint-fill expects stream, object, and optional colon-p and at-sign-p");
        return 0;
    }
    stream = args->items[0];
    object = args->items[1];
    if (args->count >= 3) colon_p = value_is_truthy(args->items[2]);
    if (!resolve_output_stream_designator(it, stream, "pprint-fill", &stream, err, errsz)) return 0;
    if (!value_is_list_like(object)) {
        PrintRenderOptions render;
        WriteKeywordOptions opts;
        char *text = NULL;
        memset(&opts, 0, sizeof(opts));
        if (!resolve_print_render_options(it, env, &opts, &render, err, errsz)) return 0;
        if (!render_write_text(it, env, object, &render, &text)) return 0;
        output_stream_write_text(it, stream, text);
        free(text);
        *out = object;
        return 1;
    }
    pretty = runtime_special_truthy(it, env, "*print-pretty*");
    if (!pprint_collect_list_elements(it, object, &items, &tail, err, errsz)) return 0;
    if (!pretty) {
        int ok = pprint_emit_minimum_whitespace_list(it, env, stream, &items, tail, colon_p, err, errsz);
        value_array_dispose(&items);
        *out = ok ? object : NULL;
        return ok;
    }
    if (!pprint_right_margin_value(it, env, &right_margin, err, errsz)) {
        value_array_dispose(&items);
        return 0;
    }
    {
        int miser_base = output_stream_current_column(it, stream) + (colon_p ? 1 : 0);
        int miser_mode = pprint_miser_mode_active(it, env, miser_base, right_margin, err, errsz);
        if (miser_mode < 0) {
            value_array_dispose(&items);
            return 0;
        }
        if (miser_mode) {
            int ok = pprint_emit_linear_list(it, env, stream, &items, tail, colon_p, right_margin, err, errsz);
            value_array_dispose(&items);
            *out = ok ? object : NULL;
            return ok;
        }
    }
    if (!pprint_emit_fill_list(it, env, stream, &items, tail, colon_p, right_margin, err, errsz)) {
        value_array_dispose(&items);
        return 0;
    }
    value_array_dispose(&items);
    *out = object;
    return 1;
}

