static int builtin_file_position(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    Value *stream = NULL;
    Value *spec = NULL;
    int64_t n = 0;
    (void)it;
    (void)env;
    if (args->count != 1 && args->count != 2) {
        snprintf(err, errsz, "file-position expects a stream and optional position");
        return 0;
    }
    stream = args->items[0];
    if (!value_is_stream_object(stream) || !stream_object_is_open(stream)) {
        snprintf(err, errsz, "file-position expects an open stream");
        return 0;
    }
    if (args->count == 1) {
        if (stream->type == VALUE_STRING_INPUT_STREAM) {
            *out = make_int_value(bigint_from_i64((int64_t)(stream->as.string_input_stream.pos - stream->as.string_input_stream.start)));
            return 1;
        }
        if (stream->type == VALUE_FILE_STREAM) {
            long pos = 0;
            if (!file_stream_logical_position(stream, &pos, err, errsz)) return 0;
            *out = make_int_value(bigint_from_i64((int64_t)pos));
            return 1;
        }
        *out = make_int_value(bigint_from_i64((int64_t)stream->as.string_output_stream.pos));
        return 1;
    }
    spec = args->items[1];
    if (spec->type == VALUE_SYMBOL && keyword_matches(spec, ":start")) {
        if (stream->type == VALUE_STRING_INPUT_STREAM) {
            stream->as.string_input_stream.pos = stream->as.string_input_stream.start;
        } else if (stream->type == VALUE_FILE_STREAM) {
            if (!file_stream_seek_absolute(stream, 0L, err, errsz)) return 0;
        } else {
            stream->as.string_output_stream.pos = 0;
            stream->as.string_output_stream.at_line_start = 1;
            stream->as.string_output_stream.current_column = 0;
        }
        *out = it->true_value;
        return 1;
    }
    if (spec->type == VALUE_SYMBOL && keyword_matches(spec, ":end")) {
        if (stream->type == VALUE_STRING_INPUT_STREAM) {
            stream->as.string_input_stream.pos = stream->as.string_input_stream.end;
        } else if (stream->type == VALUE_FILE_STREAM) {
            clearerr(stream->as.file_stream.handle);
            if (fseek(stream->as.file_stream.handle, 0L, SEEK_END) != 0) {
                snprintf(err, errsz, "cannot seek file stream '%s': %s",
                         (stream->as.file_stream.path != NULL) ? stream->as.file_stream.path : "<stream>",
                         strerror(errno));
                return 0;
            }
            stream->as.file_stream.has_pushback = 0;
            stream->as.file_stream.has_last_read_char = 0;
            if ((stream->as.file_stream.direction_flags & FILE_STREAM_DIRECTION_OUTPUT) != 0 &&
                !file_stream_update_at_line_start(stream, err, errsz)) return 0;
        } else {
            stream->as.string_output_stream.pos = (int)stream->as.string_output_stream.buf.len;
            string_output_stream_recompute_tracking(stream);
        }
        *out = it->true_value;
        return 1;
    }
    if (spec->type != VALUE_INT || !bigint_to_i64_checked(spec->as.bigint, &n) || n < 0 || n > INT_MAX) {
        snprintf(err, errsz, "file-position expects a non-negative fixnum, :start, or :end");
        return 0;
    }
    if (stream->type == VALUE_STRING_INPUT_STREAM) {
        if (n > (int64_t)(stream->as.string_input_stream.end - stream->as.string_input_stream.start)) {
            *out = it->false_value;
            return 1;
        }
        stream->as.string_input_stream.pos = stream->as.string_input_stream.start + (int)n;
        *out = it->true_value;
        return 1;
    }
    if (stream->type == VALUE_FILE_STREAM) {
        if (!file_stream_seek_absolute(stream, (long)n, err, errsz)) {
            if (errno == EINVAL) {
                *out = it->false_value;
                return 1;
            }
            return 0;
        }
        *out = it->true_value;
        return 1;
    }
    if (n > (int64_t)stream->as.string_output_stream.buf.len) {
        *out = it->false_value;
        return 1;
    }
    stream->as.string_output_stream.pos = (int)n;
    string_output_stream_recompute_tracking(stream);
    *out = it->true_value;
    return 1;
}

