static int builtin_file_string_length(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    Value *stream = NULL;
    long len = 0;
    (void)it;
    (void)env;
    if (args->count != 2) {
        snprintf(err, errsz, "file-string-length expects a stream and a string or character");
        return 0;
    }
    stream = args->items[0];
    if (stream->type != VALUE_FILE_STREAM || !stream_object_is_open(stream) || !value_is_output_stream_object(stream)) {
        snprintf(err, errsz, "file-string-length expects an open output file stream");
        return 0;
    }
    if (file_stream_is_binary(stream)) {
        snprintf(err, errsz, "file-string-length expects a character file stream");
        return 0;
    }
    if (args->items[1]->type == VALUE_STRING) {
        len = (long)strlen(args->items[1]->as.str);
    } else {
        int ch = 0;
        if (!value_to_char_code_compat(args->items[1], &ch)) {
            snprintf(err, errsz, "file-string-length expects a string or character");
            return 0;
        }
        len = 1L;
    }
    *out = make_int_value(bigint_from_i64((int64_t)len));
    return 1;
}

static int builtin_make_string_output_stream(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    int i;
    (void)it;
    (void)env;
    if ((args->count % 2) != 0) {
        snprintf(err, errsz, "make-string-output-stream expects keyword/value pairs");
        return 0;
    }
    for (i = 0; i < args->count; i += 2) {
        Value *key = args->items[i];
        Value *val = args->items[i + 1];
        if (!value_is_keyword(key)) {
            snprintf(err, errsz, "expected a keyword argument, got %s", value_type_name(key));
            return 0;
        }
        if (keyword_matches(key, ":element-type")) {
            if (!validate_string_output_stream_element_type(val, "make-string-output-stream", err, errsz)) return 0;
        } else {
            snprintf(err, errsz, "unsupported make-string-output-stream keyword '%s'", key->as.str);
            return 0;
        }
    }
    *out = make_string_output_stream_value(STRING_STREAM_ELEMENT_CHARACTER);
    return 1;
}

