    Value *v; int i; ValueArray items; (void)it; (void)env;
    if (args->count != 1) { snprintf(err, errsz, "broadcast-stream-streams expects one argument"); return 0; }
    v = args->items[0];
    if (v->type != VALUE_BROADCAST_STREAM) { snprintf(err, errsz, "broadcast-stream-streams expects a broadcast stream"); return 0; }
    if (v->as.broadcast_stream.closed) { snprintf(err, errsz, "broadcast-stream-streams: stream is closed"); return 0; }
