static int builtin_make_string_input_stream(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    int start = 0;
    int end = 0;
    Value *start_value = NULL;
    Value *end_value = NULL;
    (void)env;
    if (args->count < 1 || args->count > 3) {
        snprintf(err, errsz, "make-string-input-stream expects a string and optional start/end");
        return 0;
    }
    if (args->items[0]->type != VALUE_STRING) {
        snprintf(err, errsz, "make-string-input-stream expects a string");
        return 0;
    }
    if (args->count >= 2) start_value = args->items[1];
    if (args->count == 3) end_value = args->items[2];
    if (!parse_string_bounds(it, args->items[0], start_value, end_value, "make-string-input-stream", &start, &end, err, errsz)) return 0;
    {
        char *text = value_string_copy_text(args->items[0], 1);
        *out = make_string_input_stream_value(text, start, end);
        free(text);
    }
    return 1;
}

static int parse_read_common_args(Interp *it,
                                  Env *env,
                                  const ValueArray *args,
                                  const char *who,
                                  int allow_preserve,
                                  Value **stream_out,
                                  int *eof_error_p_out,
                                  Value **eof_value_out,
                                  char *err,
                                  size_t errsz) {
    Value *stream = NULL;
    int eof_error_p = 1;
    Value *eof_value = it->nil;
    (void)allow_preserve;
    if (args->count > 4) {
        snprintf(err, errsz, "%s expects up to four optional arguments", who);
        return 0;
    }
    if (args->count >= 1) stream = args->items[0];
    if (args->count >= 2) eof_error_p = value_is_truthy(args->items[1]);
    if (args->count >= 3) eof_value = args->items[2];
    if (!resolve_input_stream_designator(it, env, stream, who, stream_out, err, errsz)) return 0;
    if (eof_error_p_out != NULL) *eof_error_p_out = eof_error_p;
    if (eof_value_out != NULL) *eof_value_out = eof_value;
    return 1;
}

static int parse_sequence_io_bounds(Value *seq,
                                    Value *start_value,
                                    Value *end_value,
                                    const char *who,
                                    int *start_out,
                                    int *end_out,
                                    char *err,
                                    size_t errsz) {
    int len = 0;
    int start = 0;
    int end = 0;
    int64_t n = 0;
    if (!sequence_length_any(seq, &len, err, errsz)) return 0;
    end = len;
    if (start_value != NULL) {
        if (start_value->type != VALUE_INT || !bigint_to_i64_checked(start_value->as.bigint, &n) || n < 0 || n > INT_MAX) {
            snprintf(err, errsz, "%s expects :start to be a non-negative fixnum", who);
            return 0;
        }
        start = (int)n;
    }
    if (end_value != NULL) {
        if (end_value->type != VALUE_INT || !bigint_to_i64_checked(end_value->as.bigint, &n) || n < 0 || n > INT_MAX) {
            snprintf(err, errsz, "%s expects :end to be a non-negative fixnum", who);
            return 0;
        }
        end = (int)n;
    }
    if (start > end || end > len) {
        snprintf(err, errsz, "%s bounds out of range", who);
        return 0;
    }
    *start_out = start;
    *end_out = end;
    return 1;
}

static int builtin_read_common(Interp *it,
                               Env *env,
                               const ValueArray *args,
                               const char *who,
                               int preserve_whitespace,
                               Value **out,
                               char *err,
                               size_t errsz) {
    Value *stream = NULL;
    Value *eof_value = it->nil;
    Value *form = NULL;
    int eof_error_p = 1;
    int eof = 0;
    int pos = 0;
    if (!parse_read_common_args(it, env, args, who, preserve_whitespace, &stream, &eof_error_p, &eof_value, err, errsz)) return 0;
    if (value_is_string_input_stream(stream)) {
        if (!parse_single_form_from_string_range(it,
                                                 env,
                                                 stream->as.string_input_stream.text,
                                                 stream->as.string_input_stream.pos,
                                                 stream->as.string_input_stream.end,
                                                 preserve_whitespace,
                                                 &form,
                                                 &pos,
                                                 &eof,
                                                 err,
                                                 errsz)) {
            return 0;
        }
        stream->as.string_input_stream.pos = pos;
    } else {
        char *text = NULL;
        long logical_pos = 0;
        long len = 0;
        if (!file_stream_read_remaining_text(stream, &text, &logical_pos, &len, err, errsz)) return 0;
        if (len > INT_MAX) {
            free(text);
            snprintf(err, errsz, "%s file stream slice is too large to parse", who);
            return 0;
        }
        if (!parse_single_form_from_string_range(it,
                                                 env,
                                                 text,
                                                 0,
                                                 (int)len,
                                                 preserve_whitespace,
                                                 &form,
                                                 &pos,
                                                 &eof,
                                                 err,
                                                 errsz)) {
            free(text);
            return 0;
        }
        free(text);
        if (!file_stream_seek_absolute(stream, logical_pos + (long)pos, err, errsz)) return 0;
    }
    if (eof) {
        if (eof_error_p) {
            snprintf(err, errsz, "%s reached EOF before reading an object", who);
            return 0;
        }
        *out = eof_value;
        return 1;
    }
    *out = form;
    return 1;
}

