static int builtin_peek_char(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    Value *peek_type = it->nil;
    Value *stream = NULL;
    Value *stream_arg = NULL;
    Value *eof_value = it->nil;
    int eof_error_p = 1;
    int pos = 0;
    if (args->count > 5) {
        snprintf(err, errsz, "peek-char expects up to five optional arguments");
        return 0;
    }
    if (args->count >= 1) peek_type = args->items[0];
    if (args->count >= 2) stream_arg = args->items[1];
    if (args->count >= 3) eof_error_p = value_is_truthy(args->items[2]);
    if (args->count >= 4) eof_value = args->items[3];
    if (!resolve_input_stream_designator(it, env, stream_arg, "peek-char", &stream, err, errsz)) return 0;
    if (value_is_string_input_stream(stream)) {
        if (!string_input_stream_peek_position(it, stream, peek_type, &pos, err, errsz)) return 0;
        if (pos >= stream->as.string_input_stream.end) {
            if (eof_error_p) {
                snprintf(err, errsz, "peek-char reached EOF");
                return 0;
            }
            *out = eof_value;
            return 1;
        }
        *out = make_char_value((unsigned char)stream->as.string_input_stream.text[pos]);
    } else {
        char *text = NULL;
        long logical_pos = 0;
        long len = 0;
        if (!file_stream_read_remaining_text(stream, &text, &logical_pos, &len, err, errsz)) return 0;
        (void)logical_pos;
        if (len > INT_MAX) {
            free(text);
            snprintf(err, errsz, "peek-char file stream slice is too large");
            return 0;
        }
        if (!input_text_peek_position(it, text, 0, (int)len, peek_type, &pos, err, errsz)) {
            free(text);
            return 0;
        }
        if (pos >= (int)len) {
            free(text);
            if (eof_error_p) {
                snprintf(err, errsz, "peek-char reached EOF");
                return 0;
            }
            *out = eof_value;
            return 1;
        }
        *out = make_char_value((unsigned char)text[pos]);
        free(text);
    }
    return 1;
}

