static int builtin_char_compare_common(Interp *it, const ValueArray *args, const char *who, int case_insensitive, Value **out, char *err, size_t errsz) {
    int i;
    int prev = 0;
    (void)it;
    if (args->count < 1) {
        snprintf(err, errsz, "%s expects at least one character", who);
        return 0;
    }
    if (!value_to_char_code_compat(args->items[0], &prev)) {
        snprintf(err, errsz, "%s expects characters or single-character strings", who);
        return 0;
    }
    for (i = 1; i < args->count; ++i) {
        int cur = 0;
        int match = 0;
        if (!value_to_char_code_compat(args->items[i], &cur)) {
            snprintf(err, errsz, "%s expects characters or single-character strings", who);
            return 0;
        }
        match = case_insensitive ? char_equal_ci(prev, cur) : (prev == cur);
        if (!match) {
            *out = it->false_value;
            return 1;
        }
        prev = cur;
    }
    *out = it->true_value;
    return 1;
}

static int char_compare_codes(int a, int b, int case_insensitive) {
    if (case_insensitive) {
        a = tolower((unsigned char)a);
        b = tolower((unsigned char)b);
    }
    if (a < b) return -1;
    if (a > b) return 1;
    return 0;
}

static int builtin_char_distinct_common(Interp *it, const ValueArray *args, const char *who, int case_insensitive, Value **out, char *err, size_t errsz) {
    int i;
    int j;
    (void)it;
    if (args->count < 1) {
        snprintf(err, errsz, "%s expects at least one character", who);
        return 0;
    }
    for (i = 0; i < args->count; ++i) {
        int a = 0;
        if (!value_to_char_code_compat(args->items[i], &a)) {
            snprintf(err, errsz, "%s expects characters or single-character strings", who);
            return 0;
        }
        for (j = i + 1; j < args->count; ++j) {
            int b = 0;
            if (!value_to_char_code_compat(args->items[j], &b)) {
                snprintf(err, errsz, "%s expects characters or single-character strings", who);
                return 0;
            }
            if (case_insensitive ? char_equal_ci(a, b) : (a == b)) {
                *out = it->false_value;
                return 1;
            }
        }
    }
    *out = it->true_value;
    return 1;
}

static int builtin_char_order_common(Interp *it, const ValueArray *args, const char *who, int case_insensitive, int relation, Value **out, char *err, size_t errsz) {
    int i;
    int prev = 0;
    (void)it;
    if (args->count < 1) {
        snprintf(err, errsz, "%s expects at least one character", who);
        return 0;
    }
    if (!value_to_char_code_compat(args->items[0], &prev)) {
        snprintf(err, errsz, "%s expects characters or single-character strings", who);
        return 0;
    }
    for (i = 1; i < args->count; ++i) {
        int cur = 0;
        int cmp = 0;
        if (!value_to_char_code_compat(args->items[i], &cur)) {
            snprintf(err, errsz, "%s expects characters or single-character strings", who);
            return 0;
        }
        cmp = char_compare_codes(prev, cur, case_insensitive);
        if ((relation == 0 && !(cmp < 0)) ||
            (relation == 1 && !(cmp <= 0)) ||
            (relation == 2 && !(cmp > 0)) ||
            (relation == 3 && !(cmp >= 0))) {
            *out = it->false_value;
            return 1;
        }
        prev = cur;
    }
    *out = it->true_value;
    return 1;
}

