static int builtin_code_char(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    Num n;
    double d = 0.0;
    (void)env;
    if (args->count != 1) {
        snprintf(err, errsz, "code-char expects exactly one integer code");
        return 0;
    }
    if (!value_to_num(it, args->items[0], &n, err, errsz)) return 0;
    if (!num_to_double_checked(n, &d) || floor(d) != d) {
        snprintf(err, errsz, "code-char expects an integer code");
        return 0;
    }
    if (d < 0.0 || d > 1114111.0) {
        *out = it->nil;
        return 1;
    }
    *out = make_char_value((int)d);
    return 1;
}

static int builtin_digit_char_p(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    int ch = 0;
    int radix = 10;
    int weight = -1;
    Num n;
    double d = 0.0;
    (void)env;
    if (args->count < 1 || args->count > 2) {
        snprintf(err, errsz, "digit-char-p expects one character and an optional radix");
        return 0;
    }
    if (!value_to_char_code_compat(args->items[0], &ch)) {
        snprintf(err, errsz, "digit-char-p expects a character or single-character string");
        return 0;
    }
    if (args->count == 2) {
        if (!value_to_num(it, args->items[1], &n, err, errsz)) return 0;
        if (!num_to_double_checked(n, &d) || floor(d) != d || d < 2.0 || d > 36.0) {
            snprintf(err, errsz, "digit-char-p radix must be an integer between 2 and 36");
            return 0;
        }
        radix = (int)d;
    }
    weight = digit_char_weight(ch);
    *out = (weight >= 0 && weight < radix) ? make_int_value(bigint_from_i64(weight)) : it->nil;
    return 1;
}

