static int builtin_digit_char(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    int weight = 0;
    int radix = 10;
    Num n;
    double d = 0.0;
    static const char digits[] = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ";
    (void)env;
    if (args->count < 1 || args->count > 2) {
        snprintf(err, errsz, "digit-char expects a weight and an optional radix");
        return 0;
    }
    if (!value_to_num(it, args->items[0], &n, err, errsz)) return 0;
    if (!num_to_double_checked(n, &d) || floor(d) != d || d < 0.0) {
        *out = it->nil;
        return 1;
    }
    weight = (int)d;
    if (args->count == 2) {
        if (!value_to_num(it, args->items[1], &n, err, errsz)) return 0;
        if (!num_to_double_checked(n, &d) || floor(d) != d || d < 2.0 || d > 36.0) {
            snprintf(err, errsz, "digit-char radix must be an integer between 2 and 36");
            return 0;
        }
        radix = (int)d;
    }
    if (weight < 0 || weight >= radix) {
        *out = it->nil;
        return 1;
    }
    *out = make_char_value((unsigned char)digits[weight]);
    return 1;
}

