static int builtin_char_property_common(Interp *it, const ValueArray *args, const char *who, int kind, Value **out, char *err, size_t errsz) {
    int ch = 0;
    int truthy = 0;
    (void)it;
    if (args->count != 1) {
        snprintf(err, errsz, "%s expects exactly one character", who);
        return 0;
    }
    if (!value_to_char_code_compat(args->items[0], &ch)) {
        snprintf(err, errsz, "%s expects a character or single-character string", who);
        return 0;
    }
    switch (kind) {
        case 0: truthy = isalpha((unsigned char)ch) != 0; break;
        case 1: truthy = isalnum((unsigned char)ch) != 0; break;
        case 2: truthy = isupper((unsigned char)ch) != 0; break;
        case 3: truthy = islower((unsigned char)ch) != 0; break;
        default: truthy = char_has_case_code(ch); break;
    }
    *out = truthy ? it->true_value : it->false_value;
    return 1;
}

