static int builtin_copy_seq(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    Value *seq = NULL;
    ValueArray items;
    (void)env;
    if (args->count != 1) {
        snprintf(err, errsz, "copy-seq expects exactly one sequence");
        return 0;
    }
    seq = args->items[0];
    if (seq->type == VALUE_STRING) {
        char *text = value_string_copy_text(seq, 1);
        *out = make_string_value(text);
        free(text);
        return 1;
    }
    if (seq->type == VALUE_VECTOR) {
        if (!sequence_to_array(seq, &items, err, errsz)) return 0;
        *out = make_vector_like(seq, &items);
        return 1;
    }
    if (value_is_list_like(seq)) {
        if (!sequence_to_array(seq, &items, err, errsz)) return 0;
        *out = runtime_list_from_array(it->nil, &items);
        return 1;
    }
    snprintf(err, errsz, "copy-seq expects a list, vector, or string");
    return 0;
}

static int builtin_reverse(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    Value *seq = NULL;
    ValueArray items;
    (void)env;
    if (args->count != 1) {
        snprintf(err, errsz, "reverse expects exactly one sequence");
        return 0;
    }
    seq = args->items[0];
    if (seq->type == VALUE_STRING) {
        size_t len = (size_t)value_string_sequence_length(seq);
        char *buf = (char *)xmalloc(len + 1U);
        size_t i;
        for (i = 0; i < len; ++i) {
            int ch = 0;
            if (!string_storage_read_char(seq, (int)(len - 1U - i), &ch)) {
                free(buf);
                snprintf(err, errsz, "reverse expects a list, vector, or string");
                return 0;
            }
            buf[i] = (char)(ch & 0xFF);
        }
        buf[len] = '\0';
        *out = make_string_value(buf);
        free(buf);
        return 1;
    }
    if (seq->type == VALUE_VECTOR) {
        if (!sequence_to_array(seq, &items, err, errsz)) return 0;
        value_array_reverse(&items);
        *out = make_vector_like(seq, &items);
        return 1;
    }
    if (value_is_list_like(seq)) {
        if (!sequence_to_array(seq, &items, err, errsz)) return 0;
        value_array_reverse(&items);
        *out = runtime_list_from_array(it->nil, &items);
        return 1;
    }
    snprintf(err, errsz, "reverse expects a list, vector, or string");
    return 0;
}

static int builtin_nreverse(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    Value *seq = NULL;
    (void)env;
    if (args->count != 1) {
        snprintf(err, errsz, "nreverse expects exactly one sequence");
        return 0;
    }
    seq = args->items[0];
    if (seq->type == VALUE_NIL) {
        *out = it->nil;
        return 1;
    }
    if (seq->type == VALUE_CONS) {
        Value *prev = it->nil;
        Value *cur = seq;
        Value *next = NULL;
        int ignored = 0;
        if (!sequence_length(seq, &ignored, err, errsz)) return 0;
        while (cur->type == VALUE_CONS) {
            next = cur->as.cons.cdr;
            cur->as.cons.cdr = prev;
            prev = cur;
            cur = next;
        }
        *out = prev;
        return 1;
    }
    if (seq->type == VALUE_LIST || seq->type == VALUE_VECTOR) {
        value_array_reverse(&seq->as.array);
        *out = seq;
        return 1;
    }
    if (seq->type == VALUE_STRING) {
        size_t i = 0U;
        size_t j = (size_t)value_string_sequence_length(seq);
        if (j == 0U) {
            *out = seq;
            return 1;
        }
        --j;
        while (i < j) {
            int left = 0;
            int right = 0;
            if (!string_storage_read_char(seq, (int)i, &left) ||
                !string_storage_read_char(seq, (int)j, &right) ||
                !string_storage_write_char(seq, (int)i, right) ||
                !string_storage_write_char(seq, (int)j, left)) {
                snprintf(err, errsz, "nreverse expects a list, vector, or string");
                return 0;
            }
            ++i;
            --j;
        }
        *out = seq;
        return 1;
    }
    snprintf(err, errsz, "nreverse expects a list, vector, or string");
    return 0;
}

