static int sequence_test_match(Interp *it, Env *env, SequenceKeywordOptions *opts, Value *item, Value *candidate, int *out_match, char *err, size_t errsz) {
    if (opts->test_fn != NULL) {
        ValueArray call_args;
        Value *res = NULL;
        value_array_init(&call_args);
        value_array_push(&call_args, item);
        value_array_push(&call_args, candidate);
        if (!apply_callable(it, env, opts->test_fn, &call_args, &res, err, errsz)) return 0;
        *out_match = value_is_truthy(res);
        return 1;
    }
    *out_match = value_eql_impl(item, candidate);
    return 1;
}

static int sequence_predicate_match(Interp *it, Env *env, Value *predicate, SequenceKeywordOptions *opts, Value *elem, int *out_match, char *err, size_t errsz) {
    Value *keyed = NULL;
    Value *res = NULL;
    ValueArray call_args;
    if (!sequence_apply_key(it, env, opts, elem, &keyed, err, errsz)) return 0;
    value_array_init(&call_args);
    value_array_push(&call_args, keyed);
    if (!apply_callable(it, env, predicate, &call_args, &res, err, errsz)) return 0;
    *out_match = value_is_truthy(res);
    return 1;
}

static int sequence_match_index(Interp *it, Env *env, Value *item, Value *seq, SequenceKeywordOptions *opts, int *out_index, char *err, size_t errsz) {
    int len = 0;
    int start = 0;
    int end = 0;
    int i;
    if (!sequence_length_any(seq, &len, err, errsz)) return 0;
    start = opts->start;
    end = opts->has_end ? opts->end : len;
    if (start > end || end > len) {
        snprintf(err, errsz, "sequence bounds out of range");
        return 0;
    }
    *out_index = -1;
    if (opts->from_end) {
        for (i = end - 1; i >= start; --i) {
            Value *elem = NULL;
            Value *keyed = NULL;
            int match = 0;
            if (!sequence_element_any(seq, i, &elem, err, errsz)) return 0;
            if (!sequence_apply_key(it, env, opts, elem, &keyed, err, errsz)) return 0;
            if (!sequence_test_match(it, env, opts, item, keyed, &match, err, errsz)) return 0;
            if (match) {
                *out_index = i;
                return 1;
            }
        }
        return 1;
    }
    for (i = start; i < end; ++i) {
        Value *elem = NULL;
        Value *keyed = NULL;
        int match = 0;
        if (!sequence_element_any(seq, i, &elem, err, errsz)) return 0;
        if (!sequence_apply_key(it, env, opts, elem, &keyed, err, errsz)) return 0;
        if (!sequence_test_match(it, env, opts, item, keyed, &match, err, errsz)) return 0;
        if (match) {
            *out_index = i;
            return 1;
        }
    }
    return 1;
}

static int sequence_match_predicate_index_common(Interp *it, Env *env, Value *predicate, Value *seq, SequenceKeywordOptions *opts, int invert_match, int *out_index, char *err, size_t errsz) {
    int len = 0;
    int start = 0;
    int end = 0;
    int i;
    if (!sequence_length_any(seq, &len, err, errsz)) return 0;
    start = opts->start;
    end = opts->has_end ? opts->end : len;
    if (start > end || end > len) {
        snprintf(err, errsz, "sequence bounds out of range");
        return 0;
    }
    *out_index = -1;
    if (opts->from_end) {
        for (i = end - 1; i >= start; --i) {
            Value *elem = NULL;
            int match = 0;
            if (!sequence_element_any(seq, i, &elem, err, errsz)) return 0;
            if (!sequence_predicate_match(it, env, predicate, opts, elem, &match, err, errsz)) return 0;
            if (invert_match) match = !match;
            if (match) {
                *out_index = i;
                return 1;
            }
        }
        return 1;
    }
    for (i = start; i < end; ++i) {
        Value *elem = NULL;
        int match = 0;
        if (!sequence_element_any(seq, i, &elem, err, errsz)) return 0;
        if (!sequence_predicate_match(it, env, predicate, opts, elem, &match, err, errsz)) return 0;
        if (invert_match) match = !match;
        if (match) {
            *out_index = i;
            return 1;
        }
    }
    return 1;
}

