static int sequence_count_matches(Interp *it, Env *env, Value *item, Value *seq, SequenceKeywordOptions *opts, Value **out, char *err, size_t errsz) {
    int len = 0;
    int start = 0;
    int end = 0;
    int i;
    int count = 0;
    if (!sequence_length_any(seq, &len, err, errsz)) return 0;
    start = opts->start;
    end = opts->has_end ? opts->end : len;
    if (start > end || end > len) {
        snprintf(err, errsz, "sequence bounds out of range");
        return 0;
    }
    for (i = start; i < end; ++i) {
        Value *elem = NULL;
        Value *keyed = NULL;
        int match = 0;
        if (!sequence_element_any(seq, i, &elem, err, errsz)) return 0;
        if (!sequence_apply_key(it, env, opts, elem, &keyed, err, errsz)) return 0;
        if (!sequence_test_match(it, env, opts, item, keyed, &match, err, errsz)) return 0;
        if (match) ++count;
    }
    *out = make_int_value(bigint_from_i64(count));
    return 1;
}

