static int builtin_mismatch(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    DualSequenceKeywordOptions opts;
    int start1 = 0;
    int end1 = 0;
    int start2 = 0;
    int end2 = 0;
    if (args->count < 2) {
        snprintf(err, errsz, "mismatch expects two sequences and optional keyword arguments");
        return 0;
    }
    if (!parse_dual_sequence_keyword_options(it, args, 2, &opts, err, errsz)) return 0;
    if (!sequence_dual_bounds(args->items[0], args->items[1], &opts, &start1, &end1, &start2, &end2, err, errsz)) return 0;
    if (opts.from_end) {
        int i1 = end1 - 1;
        int i2 = end2 - 1;
        while (i1 >= start1 && i2 >= start2) {
            Value *left = NULL;
            Value *right = NULL;
            int match = 0;
            if (!sequence_element_any(args->items[0], i1, &left, err, errsz)) return 0;
            if (!sequence_element_any(args->items[1], i2, &right, err, errsz)) return 0;
            if (!dual_sequence_compare_elements(it, env, left, right, &opts, &match, err, errsz)) return 0;
            if (!match) {
                *out = make_int_value(bigint_from_i64(i1));
                return 1;
            }
            --i1;
            --i2;
        }
        if (i1 >= start1) {
            *out = make_int_value(bigint_from_i64(i1));
            return 1;
        }
        if (i2 >= start2) {
            *out = make_int_value(bigint_from_i64(start1));
            return 1;
        }
        *out = it->nil;
        return 1;
    } else {
        int i1 = start1;
        int i2 = start2;
        while (i1 < end1 && i2 < end2) {
            Value *left = NULL;
            Value *right = NULL;
            int match = 0;
            if (!sequence_element_any(args->items[0], i1, &left, err, errsz)) return 0;
            if (!sequence_element_any(args->items[1], i2, &right, err, errsz)) return 0;
            if (!dual_sequence_compare_elements(it, env, left, right, &opts, &match, err, errsz)) return 0;
            if (!match) {
                *out = make_int_value(bigint_from_i64(i1));
                return 1;
            }
            ++i1;
            ++i2;
        }
        if (i1 < end1 || i2 < end2) {
            *out = make_int_value(bigint_from_i64(i1));
            return 1;
        }
        *out = it->nil;
        return 1;
    }
}

static int builtin_search(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    DualSequenceKeywordOptions opts;
    int start1 = 0;
    int end1 = 0;
    int start2 = 0;
    int end2 = 0;
    int pat_len = 0;
    int src_len = 0;
    int pos;
    if (args->count < 2) {
        snprintf(err, errsz, "search expects two sequences and optional keyword arguments");
        return 0;
    }
    if (!parse_dual_sequence_keyword_options(it, args, 2, &opts, err, errsz)) return 0;
    if (!sequence_dual_bounds(args->items[0], args->items[1], &opts, &start1, &end1, &start2, &end2, err, errsz)) return 0;
    pat_len = end1 - start1;
    src_len = end2 - start2;
    if (pat_len == 0) {
        *out = make_int_value(bigint_from_i64(opts.from_end ? end2 : start2));
        return 1;
    }
    if (pat_len > src_len) {
        *out = it->nil;
        return 1;
    }
    if (opts.from_end) {
        for (pos = end2 - pat_len; pos >= start2; --pos) {
            int offset;
            int matched = 1;
            for (offset = 0; offset < pat_len; ++offset) {
                Value *left = NULL;
                Value *right = NULL;
                int match = 0;
                if (!sequence_element_any(args->items[0], start1 + offset, &left, err, errsz)) return 0;
                if (!sequence_element_any(args->items[1], pos + offset, &right, err, errsz)) return 0;
                if (!dual_sequence_compare_elements(it, env, left, right, &opts, &match, err, errsz)) return 0;
                if (!match) {
                    matched = 0;
                    break;
                }
            }
            if (matched) {
                *out = make_int_value(bigint_from_i64(pos));
                return 1;
            }
        }
    } else {
        for (pos = start2; pos <= end2 - pat_len; ++pos) {
            int offset;
            int matched = 1;
            for (offset = 0; offset < pat_len; ++offset) {
                Value *left = NULL;
                Value *right = NULL;
                int match = 0;
                if (!sequence_element_any(args->items[0], start1 + offset, &left, err, errsz)) return 0;
                if (!sequence_element_any(args->items[1], pos + offset, &right, err, errsz)) return 0;
                if (!dual_sequence_compare_elements(it, env, left, right, &opts, &match, err, errsz)) return 0;
                if (!match) {
                    matched = 0;
                    break;
                }
            }
            if (matched) {
                *out = make_int_value(bigint_from_i64(pos));
                return 1;
            }
        }
    }
    *out = it->nil;
    return 1;
}

