static int builtin_member(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    SequenceKeywordOptions opts;
    int len = 0;
    int i;
    if (args->count < 2) {
        snprintf(err, errsz, "member expects an item, a list, and optional keyword arguments");
        return 0;
    }
    if (!parse_sequence_keyword_options(it, args, 2, &opts, err, errsz)) return 0;
    if (!validate_member_assoc_options(&opts, 1, "member", err, errsz)) return 0;
    if (!value_is_list_like(args->items[1])) {
        snprintf(err, errsz, "member expects a list");
        return 0;
    }
    if (!sequence_length(args->items[1], &len, err, errsz)) return 0;
    for (i = 0; i < len; ++i) {
        Value *elem = NULL;
        Value *keyed = NULL;
        int match = 0;
        if (!sequence_element_any(args->items[1], i, &elem, err, errsz)) return 0;
        if (!sequence_apply_key(it, env, &opts, elem, &keyed, err, errsz)) return 0;
        if (!sequence_test_match(it, env, &opts, args->items[0], keyed, &match, err, errsz)) return 0;
        if (match) return list_tail_from_index(it, args->items[1], i, out, err, errsz);
    }
    *out = it->nil;
    return 1;
}

