static int builtin_unintern(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    Value *pkg = NULL;
    Value *entry_symbol = NULL;
    Value *symbol = NULL;
    int externalp = 0;
    const char *name = NULL;
    if (args->count != 1 && args->count != 2) {
        snprintf(err, errsz, "unintern expects a symbol and optional package designator");
        return 0;
    }
    symbol = args->items[0];
    if (!(symbol->type == VALUE_SYMBOL || symbol->type == VALUE_NIL)) {
        snprintf(err, errsz, "unintern expects a symbol");
        return 0;
    }
    pkg = (args->count == 2) ? NULL : current_package_runtime(it, env);
    if (args->count == 2 && !resolve_package_designator(it, env, args->items[1], "unintern", &pkg, err, errsz)) return 0;
    name = package_symbol_entry_name(symbol);
    if (!package_entry_lookup_present(pkg, name, NULL)) {
        *out = it->nil;
        return 1;
    }
    if (!package_entry_lookup_present(pkg, name, NULL) ||
        !package_symbol_present_status(pkg, symbol, NULL)) {
        *out = it->nil;
        return 1;
    }
    if (!package_symbol_mutation_allowed(it, pkg, symbol, "unintern", err, errsz)) return 0;
    if (!package_check_unintern_conflict(pkg, name, err, errsz)) return 0;
    if (!package_remove_present_symbol(pkg, name, &entry_symbol, &externalp) || entry_symbol != symbol) {
        *out = it->nil;
        return 1;
    }
    package_remove_shadowing_name(pkg, name);
    if (symbol->type == VALUE_SYMBOL && symbol->symbol_package == pkg) {
        symbol->symbol_package = NULL;
        symbol->symbol_interned = 0;
        symbol->symbol_id = ++it->symbol_uid_counter;
        symbol->common_lisp_named_syntax_kind = COMMON_LISP_NAMED_SYNTAX_UNSET;
    }
    *out = it->true_value;
    return 1;
}

