static int builtin_get_setf_expansion(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    SetfExpansionForm access;
    Value *store = NULL;
    Env *use_env = env;
    ValueArray stores;
    ValueArray writer_rest;
    ValueArray values;
    Value *temps_list = NULL;
    Value *vals_list = NULL;
    Value *stores_list = NULL;
    Value *writer = NULL;
    if (args->count != 1 && args->count != 2) {
        snprintf(err, errsz, "get-setf-expansion expects a place and optional environment");
        return 0;
    }
    if (args->count == 2 &&
        !resolve_environment_argument(env, args->items[1], "get-setf-expansion", &use_env, err, errsz)) {
        return 0;
    }
    setf_expansion_form_init(&access);
    if (!build_get_setf_access_form(it, use_env, args->items[0], &access, err, errsz)) return 0;
    if (access.writer_form != NULL) {
        writer = access.writer_form;
        value_array_copy(&stores, &access.stores);
    } else {
        store = make_setf_expansion_temp(it, "setf-store");
        value_array_init(&stores);
        value_array_push(&stores, store);
        value_array_init(&writer_rest);
        value_array_push(&writer_rest, access.access_form);
        value_array_push(&writer_rest, store);
        writer = make_runtime_form_with_head(it, make_symbol_value("setf"), &writer_rest);
    }
    temps_list = runtime_list_from_array(it->nil, &access.temps);
    vals_list = runtime_list_from_array(it->nil, &access.vals);
    stores_list = runtime_list_from_array(it->nil, &stores);
    value_array_init(&values);
    value_array_push(&values, temps_list);
    value_array_push(&values, vals_list);
    value_array_push(&values, stores_list);
    value_array_push(&values, writer);
    value_array_push(&values, access.access_form);
    interp_set_values(it, &values);
    *out = temps_list;
    return 1;
}

