static int builtin_symbol_function(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    const char *name = NULL;
    Value *fn = NULL;
    if (args->count != 1) {
        snprintf(err, errsz, "symbol-function expects exactly one symbol");
        return 0;
    }
    if (!form_symbolic_name(args->items[0], &name, err, errsz)) {
        snprintf(err, errsz, "symbol-function expects exactly one symbol");
        return 0;
    }
    if (special_operator_symbol_p(it, args->items[0])) {
        *out = make_special_operator_marker(name);
        return 1;
    }
    if (!global_function_lookup_symbol(env, args->items[0], &fn)) {
        snprintf(err, errsz, "undefined function '%s'", name);
        return 0;
    }
    if (!value_is_function_object(fn) && !(fn->type == VALUE_CLOSURE && fn->as.closure.is_macro) && fn->type != VALUE_GENERIC_FUNCTION) {
        snprintf(err, errsz, "global function cell '%s' does not contain a function-like definition", name);
        return 0;
    }
    *out = fn;
    return 1;
}

