static Value *closure_lambda_expression(Value *fn) {
    ValueArray arr;
    ValueArray body_items;
    int body_start = 0;
    value_array_init(&arr);
    value_array_push(&arr, make_symbol_value("lambda"));
    value_array_push(&arr, fn->as.closure.params);
    if (proper_form_to_array(fn->as.closure.body, &body_items)) {
        int i;
        while (body_start < body_items.count && form_head_symbol_named(body_items.items[body_start], "declare")) {
            value_array_push(&arr, body_items.items[body_start]);
            ++body_start;
        }
        if (fn->as.closure.documentation != NULL) value_array_push(&arr, fn->as.closure.documentation);
        for (i = body_start; i < body_items.count; ++i) value_array_push(&arr, body_items.items[i]);
    } else {
        if (fn->as.closure.documentation != NULL) value_array_push(&arr, fn->as.closure.documentation);
        value_array_push(&arr, fn->as.closure.body);
    }
    return make_list_value(&arr);
}

