static int builtin_logcount(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    BigInt *source = NULL;
    uint32_t *words = NULL;
    int count = 0;
    int i = 0;
    BigInt *acc = bigint_new_zero();
    (void)env;
    if (args->count != 1 || args->items[0]->type != VALUE_INT) {
        snprintf(err, errsz, "logcount expects exactly one exact integer");
        return 0;
    }
    if (args->items[0]->as.bigint->d.sign >= 0) {
        source = bigint_copy(args->items[0]->as.bigint);
    } else {
        source = bigint_abs_minus_one_positive(args->items[0]->as.bigint);
    }
    if (!bigint_abs_to_bitwise_words(source, &words, &count)) {
        bigint_free(source);
        bigint_free(acc);
        snprintf(err, errsz, "logcount could not compute the exact integer result");
        return 0;
    }
    for (i = 0; i < count; ++i) {
        BigInt *next = bigint_add_small(acc, bitwise_popcount_word(words[i]));
        bigint_free(acc);
        acc = next;
    }
    bigint_free(source);
    free(words);
    *out = make_int_value(acc);
    (void)it;
    return 1;
}

static int builtin_ash(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    int64_t shift = 0;
    BigInt *result = NULL;
    (void)env;
    if (args->count != 2 || args->items[0]->type != VALUE_INT || args->items[1]->type != VALUE_INT) {
        snprintf(err, errsz, "ash expects an exact integer and an integer shift count");
        return 0;
    }
    if (!bigint_to_i64_checked(args->items[1]->as.bigint, &shift)) {
        snprintf(err, errsz, "ash currently supports shift counts up to signed 64-bit range");
        return 0;
    }
    if (shift >= 0) {
        result = bigint_shift_left(args->items[0]->as.bigint, (uint64_t)shift);
    } else if (args->items[0]->as.bigint->d.sign >= 0) {
        result = bigint_shift_right_positive(args->items[0]->as.bigint, (uint64_t)(-shift), NULL);
    } else {
        int had_remainder = 0;
        BigInt *abs_value = bigint_copy(args->items[0]->as.bigint);
        abs_value->d.sign = 1;
        result = bigint_shift_right_positive(abs_value, (uint64_t)(-shift), &had_remainder);
        bigint_free(abs_value);
        if (result != NULL && had_remainder) {
            BigInt *tmp = bigint_add_small(result, 1U);
            bigint_free(result);
            result = tmp;
        }
        if (result != NULL && result->d.sign != 0) result->d.sign = -1;
        if (result != NULL && result->d.sign == 0 && args->items[0]->as.bigint->d.sign < 0 && shift < 0) {
            bigint_free(result);
            result = bigint_from_i64(-1);
        }
    }
    if (result == NULL) {
        snprintf(err, errsz, "ash could not compute the exact integer result");
        return 0;
    }
    *out = make_int_value(result);
    (void)it;
    return 1;
}

