static Value *make_unary_type_spec(Interp *it, const char *name, Value *arg) {
    ValueArray arr;
    value_array_init(&arr);
    value_array_push(&arr, common_lisp_runtime_symbol_or_fallback(it, name));
    value_array_push(&arr, arg);
    return make_list_value(&arr);
}

static Value *make_binary_type_spec(Interp *it, const char *name, Value *arg1, Value *arg2) {
    ValueArray arr;
    value_array_init(&arr);
    value_array_push(&arr, common_lisp_runtime_symbol_or_fallback(it, name));
    value_array_push(&arr, arg1);
    value_array_push(&arr, arg2);
    return make_list_value(&arr);
}

static Value *make_array_type_spec_from_value(Interp *it, const char *name, Value *value) {
    Value *dims = NULL;
    Value *elem = array_actual_element_type_value(value);
    char tmp_err[64];
    if (!array_build_dimensions_list(it, value, &dims, tmp_err, sizeof(tmp_err))) {
        ValueArray empty;
        value_array_init(&empty);
        dims = make_list_value(&empty);
    }
    if (elem != NULL && elem->type == VALUE_SYMBOL) {
        elem = common_lisp_runtime_symbol_or_fallback(it, package_symbol_entry_name(elem));
    }
    return make_binary_type_spec(it, name, elem, dims);
}

static Value *portable_type_of_value(Interp *it, Value *value) {
    int64_t i64 = 0;
    switch (value->type) {
        case VALUE_NIL:
            return common_lisp_runtime_symbol_or_fallback(it, "null");
        case VALUE_BOOL:
            return common_lisp_runtime_symbol_or_fallback(it, "boolean");
        case VALUE_INT:
            return common_lisp_runtime_symbol_or_fallback(it, bigint_to_i64_checked(value->as.bigint, &i64) ? "fixnum" : "bignum");
        case VALUE_FLOAT:
            return common_lisp_runtime_symbol_or_fallback(it, "float");
        case VALUE_RATIO:
            return common_lisp_runtime_symbol_or_fallback(it, "ratio");
        case VALUE_COMPLEX:
            return common_lisp_runtime_symbol_or_fallback(it, "complex");
        case VALUE_CHAR:
            return common_lisp_runtime_symbol_or_fallback(it, char_is_standard_code(value->as.ch) ? "standard-char" : "character");
        case VALUE_STRING:
            if (!value->has_fill_pointer && !value->adjustable && value->displaced_to == NULL) {
                return common_lisp_runtime_symbol_or_fallback(it, "simple-base-string");
            }
            return make_unary_type_spec(it, "string", make_int_value(bigint_from_i64((int64_t)value_string_total_size(value))));
        case VALUE_PATHNAME:
            return value->as.pathname.logicalp
                ? common_lisp_runtime_symbol_or_fallback(it, "logical-pathname")
                : common_lisp_runtime_symbol_or_fallback(it, "pathname");
        case VALUE_SYMBOL:
            return common_lisp_runtime_symbol_or_fallback(it, value_is_keyword(value) ? "keyword" : "symbol");
        case VALUE_CONS: {
            ValueArray items;
            char tmp_err[32];
            return proper_list_to_array(value, &items, tmp_err, sizeof(tmp_err))
                ? common_lisp_runtime_symbol_or_fallback(it, "list")
                : common_lisp_runtime_symbol_or_fallback(it, "cons");
        }
        case VALUE_LIST:
            return (value->as.array.count == 0)
                ? common_lisp_runtime_symbol_or_fallback(it, "null")
                : common_lisp_runtime_symbol_or_fallback(it, "list");
        case VALUE_VECTOR:
            if (value_array_rank(value) == 1) {
                if (value_vector_has_bit_element_type(value)) {
                    return make_unary_type_spec(it,
                                                (!value->has_fill_pointer && !value->adjustable && !value_vector_is_displaced(value))
                                                    ? "simple-bit-vector"
                                                    : "bit-vector",
                                                make_int_value(bigint_from_i64(value_vector_total_size(value))));
                }
                {
                    Value *elem = array_actual_element_type_value(value);
                    if (elem == NULL) elem = common_lisp_runtime_symbol_or_fallback(it, "t");
                    if (elem->type == VALUE_SYMBOL) {
                        elem = common_lisp_runtime_symbol_or_fallback(it, package_symbol_entry_name(elem));
                    }
                    return make_binary_type_spec(it,
                                                 "vector",
                                                 elem,
                                                 make_int_value(bigint_from_i64(value_vector_total_size(value))));
                }
            }
            return make_array_type_spec_from_value(it,
                                                  (!value->has_fill_pointer && !value->adjustable && !value_vector_is_displaced(value))
                                                      ? "simple-array"
                                                      : "array",
                                                  value);
        case VALUE_BUILTIN:
            return common_lisp_runtime_symbol_or_fallback(it, "compiled-function");
        case VALUE_CLOSURE:
            return common_lisp_runtime_symbol_or_fallback(it, value->as.closure.is_compiled ? "compiled-function" : "function");
        case VALUE_STRING_OUTPUT_STREAM:
            return common_lisp_runtime_symbol_or_fallback(it, "string-stream");
        case VALUE_STRING_INPUT_STREAM:
            return common_lisp_runtime_symbol_or_fallback(it, "string-stream");
        case VALUE_FILE_STREAM:
            return common_lisp_runtime_symbol_or_fallback(it, "file-stream");
        case VALUE_ENVIRONMENT:
            return common_lisp_runtime_symbol_or_fallback(it, "environment");
        case VALUE_HASH_TABLE:
            return common_lisp_runtime_symbol_or_fallback(it, "hash-table");
        case VALUE_READTABLE:
            return common_lisp_runtime_symbol_or_fallback(it, "readtable");
        case VALUE_PACKAGE:
            return common_lisp_runtime_symbol_or_fallback(it, "package");
        case VALUE_STRUCT:
            return value->as.structure.type_name;
        case VALUE_MODEL:
            return common_lisp_runtime_symbol_or_fallback(it, "t");
        default:
            return common_lisp_runtime_symbol_or_fallback(it, "t");
    }
    (void)it;
}

static int list_like_nth_value(Value *list, int index, Value **out) {
    if (list == NULL || index < 0) return 0;
    if (list->type == VALUE_LIST) {
        if (index >= list->as.array.count) return 0;
        *out = list->as.array.items[index];
        return 1;
    }
    while (list->type == VALUE_CONS && index > 0) {
        list = list->as.cons.cdr;
        --index;
    }
    if (index == 0 && list->type == VALUE_CONS) {
        *out = list->as.cons.car;
        return 1;
    }
    return 0;
}

static int list_like_set_nth(Value *list, int index, Value *new_value) {
    if (list == NULL || index < 0) return 0;
    if (list->type == VALUE_LIST) {
        if (index >= list->as.array.count) return 0;
        list->as.array.items[index] = new_value;
        return 1;
    }
    while (list->type == VALUE_CONS && index > 0) {
        list = list->as.cons.cdr;
        --index;
    }
    if (index == 0 && list->type == VALUE_CONS) {
        list->as.cons.car = new_value;
        return 1;
    }
    return 0;
}

static int struct_value_matches_expected_type(Interp *it, Env *env, Value *value, Value *expected_type) {
    Value *descriptor = NULL;
    Value *slot_positions = NULL;
    ValueArray items;
    char tmp_err[64];
    int representation_kind = STRUCT_REPR_HEAP;
    int minimum_size = 0;
    int name_position = -1;
    if (expected_type == NULL) return value != NULL && value->type == VALUE_STRUCT;
    if (value == NULL || expected_type->type != VALUE_SYMBOL) return 0;
    if (!struct_descriptor_lookup(it, env, expected_type, &descriptor) ||
        !struct_descriptor_representation_info(descriptor, &representation_kind, NULL, NULL) ||
        !struct_descriptor_layout_info(descriptor, &slot_positions, &minimum_size, &name_position)) {
        return 0;
    }
    if (representation_kind == STRUCT_REPR_HEAP) {
        return value->type == VALUE_STRUCT &&
               struct_type_symbol_is_subtype(it, env, value->as.structure.type_name, expected_type);
    }
    if (representation_kind == STRUCT_REPR_LIST) {
        if (!value_is_list_like(value) || !sequence_to_array(value, &items, tmp_err, sizeof(tmp_err))) return 0;
    } else if (representation_kind == STRUCT_REPR_VECTOR) {
        if (value->type != VALUE_VECTOR || value_array_rank(value) != 1 ||
            !sequence_to_array(value, &items, tmp_err, sizeof(tmp_err))) {
            return 0;
        }
    } else if (representation_kind == STRUCT_REPR_STRING) {
        if (value->type != VALUE_STRING || !sequence_to_array(value, &items, tmp_err, sizeof(tmp_err))) return 0;
    } else {
        return 0;
    }
    if (items.count < minimum_size) return 0;
    if (name_position >= 0) {
        if (name_position >= items.count || !value_eq_impl(items.items[name_position], expected_type)) {
            if (!struct_type_symbol_is_subtype(it, env, items.items[name_position], expected_type)) return 0;
        }
    }
    return 1;
}

static int struct_expect_instance(Interp *it,
                                  Env *env,
                                  Value *value,
                                  Value *expected_type,
                                  const char *who,
                                  char *err,
                                  size_t errsz) {
    if (!struct_value_matches_expected_type(it, env, value, expected_type)) {
        if (expected_type == NULL) {
            snprintf(err, errsz, "%s expects a structure object", who);
            return 0;
        }
        snprintf(err,
                 errsz,
                 "%s expects a %s structure",
                 who,
                 package_symbol_entry_name(expected_type));
        return 0;
    }
    return 1;
}

static int struct_arg_index(Value *value, int *out, const char *who, char *err, size_t errsz) {
    int64_t i64 = 0;
    if (value == NULL || value->type != VALUE_INT || !bigint_to_i64_checked(value->as.bigint, &i64) || i64 < 0) {
        snprintf(err, errsz, "%s expects a non-negative fixnum slot index", who);
        return 0;
    }
    *out = (int)i64;
    return 1;
}

static int struct_slot_value_satisfies_declared_type(Interp *it,
                                                     Env *env,
                                                     Value *descriptor,
                                                     int index,
                                                     Value *slot_value,
                                                     const char *who,
                                                     char *err,
                                                     size_t errsz) {
    Value *slot_names = NULL;
    Value *slot_type_specs_value = NULL;
    ValueArray names;
    ValueArray slot_type_specs;
    int match = 0;
    if (it->struct_unbound_value != NULL && slot_value == it->struct_unbound_value) return 1;
    if (!struct_descriptor_parts(descriptor, &slot_names, NULL, NULL, NULL, NULL, NULL) ||
        !struct_descriptor_slot_type_specs(it, descriptor, &slot_type_specs_value) ||
        !proper_form_to_array(slot_names, &names) ||
        !proper_form_to_array(slot_type_specs_value, &slot_type_specs) ||
        index < 0 || index >= names.count || index >= slot_type_specs.count) {
        snprintf(err, errsz, "%s internal structure descriptor error", who);
        return 0;
    }
    if (!value_matches_type_spec(it, env, slot_value, slot_type_specs.items[index], &match, err, errsz)) return 0;
    if (!match) {
        snprintf(err,
                 errsz,
                 "%s slot '%s' does not satisfy its declared :type",
                 who,
                 package_symbol_entry_name(names.items[index]));
        return 0;
    }
    return 1;
}

static int builtin_internal_make_struct_instance(Interp *it,
                                                 Env *env,
                                                 const ValueArray *args,
                                                 Value **out,
                                                 char *err,
                                                 size_t errsz) {
    Value *descriptor = NULL;
    Value *slot_names = NULL;
    Value *slot_positions_value = NULL;
    Value *vector_element_type_spec = NULL;
    Value *upgraded_vector_element_type = NULL;
    ValueArray items;
    ValueArray names;
    ValueArray slot_positions;
    ValueArray slots;
    int representation_kind = STRUCT_REPR_HEAP;
    int minimum_size = 0;
    int name_position = -1;
    int i;
    if (args->count < 1 || args->items[0]->type != VALUE_SYMBOL) {
        snprintf(err, errsz, "%%make-struct-instance expects a structure type name and slot values");
        return 0;
    }
    if (!struct_descriptor_lookup(it, env, args->items[0], &descriptor) ||
        !struct_descriptor_parts(descriptor, &slot_names, NULL, NULL, NULL, NULL, NULL) ||
        !struct_descriptor_representation_info(descriptor, &representation_kind, NULL, NULL) ||
        !struct_descriptor_layout_info(descriptor, &slot_positions_value, &minimum_size, &name_position) ||
        !proper_form_to_array(slot_positions_value, &slot_positions) ||
        !proper_form_to_array(slot_names, &names)) {
        snprintf(err, errsz, "%%make-struct-instance expects a known structure type");
        return 0;
    }
    if (args->count != names.count + 1) {
        snprintf(err, errsz, "%%make-struct-instance slot count mismatch");
        return 0;
    }
    value_array_init(&slots);
    for (i = 1; i < args->count; ++i) value_array_push(&slots, args->items[i]);
    for (i = 0; i < slots.count; ++i) {
        if (!struct_slot_value_satisfies_declared_type(it,
                                                       env,
                                                       descriptor,
                                                       i,
                                                       slots.items[i],
                                                       "%make-struct-instance",
                                                       err,
                                                       errsz)) {
            return 0;
        }
    }
    if (representation_kind == STRUCT_REPR_HEAP) {
        *out = make_struct_value(args->items[0], &slots);
        return 1;
    }
    value_array_init(&items);
    if (representation_kind == STRUCT_REPR_VECTOR &&
        struct_descriptor_vector_element_type_spec(it, descriptor, &vector_element_type_spec)) {
        upgraded_vector_element_type = upgraded_array_element_type_value(it, env, vector_element_type_spec);
    }
    for (i = 0; i < minimum_size; ++i) {
        value_array_push(&items,
                         (representation_kind == STRUCT_REPR_VECTOR)
                             ? default_vector_initial_element(it, upgraded_vector_element_type)
                             : it->nil);
    }
    if (!struct_descriptor_apply_named_tags(it, env, args->items[0], &items, err, errsz)) return 0;
    if (name_position >= 0) items.items[name_position] = args->items[0];
    for (i = 0; i < slots.count; ++i) {
        int64_t pos_i64 = 0;
        if (slot_positions.items[i]->type != VALUE_INT ||
            !bigint_to_i64_checked(slot_positions.items[i]->as.bigint, &pos_i64) ||
            pos_i64 < 0 || pos_i64 >= items.count) {
            snprintf(err, errsz, "%%make-struct-instance internal slot layout error");
            return 0;
        }
        items.items[(int)pos_i64] = slots.items[i];
    }
    if (representation_kind == STRUCT_REPR_LIST) {
        *out = runtime_list_from_array(it->nil, &items);
        return 1;
    }
    if (representation_kind == STRUCT_REPR_VECTOR) {
        *out = make_vector_value_typed(&items,
                                       (upgraded_vector_element_type != NULL)
                                           ? upgraded_vector_element_type
                                           : make_symbol_value("t"));
        return 1;
    }
    if (representation_kind == STRUCT_REPR_STRING) {
        char *buf = (char *)xmalloc((size_t)minimum_size + 1U);
        memset(buf, ' ', (size_t)minimum_size);
        buf[minimum_size] = '\0';
        for (i = 0; i < slots.count; ++i) {
            int64_t pos_i64 = 0;
            int ch = 0;
            if (slot_positions.items[i]->type != VALUE_INT ||
                !bigint_to_i64_checked(slot_positions.items[i]->as.bigint, &pos_i64) ||
                pos_i64 < 0 || pos_i64 >= minimum_size) {
                free(buf);
                snprintf(err, errsz, "%%make-struct-instance internal slot layout error");
                return 0;
            }
            if (!value_to_char_code_compat(slots.items[i], &ch) || ch == 0) {
                free(buf);
                snprintf(err, errsz, "%%make-struct-instance string-based structures require character slot values");
                return 0;
            }
            buf[(int)pos_i64] = (char)(ch & 0xFF);
        }
        *out = make_string_value_sized_with_metadata(buf, minimum_size, 0, minimum_size, 0);
        free(buf);
        return 1;
    }
    snprintf(err, errsz, "%%make-struct-instance internal structure representation error");
    return 0;
}

static int builtin_internal_struct_ref(Interp *it,
                                       Env *env,
                                       const ValueArray *args,
                                       Value **out,
                                       char *err,
                                       size_t errsz) {
    int index = 0;
    Value *slot_value = NULL;
    Value *descriptor = NULL;
    Value *slot_names = NULL;
    Value *slot_positions_value = NULL;
    ValueArray names;
    ValueArray slot_positions;
    int representation_kind = STRUCT_REPR_HEAP;
    int pos = 0;
    (void)env;
    if (args->count != 3 || args->items[0]->type != VALUE_SYMBOL) {
        snprintf(err, errsz, "%%struct-ref expects structure type, slot index, and object");
        return 0;
    }
    if (!struct_arg_index(args->items[1], &index, "%struct-ref", err, errsz)) return 0;
    if (!struct_expect_instance(it, env, args->items[2], args->items[0], "%struct-ref", err, errsz)) return 0;
    if (!struct_descriptor_lookup(it, env, args->items[0], &descriptor) ||
        !struct_descriptor_parts(descriptor, &slot_names, NULL, NULL, NULL, NULL, NULL) ||
        !struct_descriptor_representation_info(descriptor, &representation_kind, NULL, NULL) ||
        !struct_descriptor_layout_info(descriptor, &slot_positions_value, NULL, NULL) ||
        !proper_form_to_array(slot_positions_value, &slot_positions) ||
        !proper_form_to_array(slot_names, &names)) {
        snprintf(err, errsz, "%%struct-ref internal structure descriptor error");
        return 0;
    }
    if (index >= names.count) {
        snprintf(err, errsz, "%%struct-ref slot index out of range");
        return 0;
    }
    {
        int64_t pos_i64 = 0;
        if (slot_positions.items[index]->type != VALUE_INT ||
            !bigint_to_i64_checked(slot_positions.items[index]->as.bigint, &pos_i64) ||
            pos_i64 < 0) {
            snprintf(err, errsz, "%%struct-ref internal slot layout error");
            return 0;
        }
        pos = (int)pos_i64;
    }
    if (representation_kind == STRUCT_REPR_HEAP) {
        slot_value = args->items[2]->as.structure.slots.items[index];
    } else if (representation_kind == STRUCT_REPR_LIST) {
        if (!list_like_nth_value(args->items[2], pos, &slot_value)) {
            snprintf(err, errsz, "%%struct-ref slot index out of range");
            return 0;
        }
    } else if (representation_kind == STRUCT_REPR_STRING) {
        if (!array_row_major_read(args->items[2], pos, &slot_value, err, errsz)) return 0;
    } else if (representation_kind == STRUCT_REPR_VECTOR) {
        if (pos >= args->items[2]->as.array.count) {
            snprintf(err, errsz, "%%struct-ref slot index out of range");
            return 0;
        }
        slot_value = args->items[2]->as.array.items[pos];
    } else {
        snprintf(err, errsz, "%%struct-ref internal structure representation error");
        return 0;
    }
    if (it->struct_unbound_value != NULL && slot_value == it->struct_unbound_value) {
        snprintf(err, errsz, "%%struct-ref encountered an uninitialized slot");
        return 0;
    }
    *out = slot_value;
    return 1;
}

static int builtin_internal_struct_set(Interp *it,
                                       Env *env,
                                       const ValueArray *args,
                                       Value **out,
                                       char *err,
                                       size_t errsz) {
    int index = 0;
    int pos = 0;
    int representation_kind = STRUCT_REPR_HEAP;
    Value *expected_descriptor = NULL;
    Value *expected_slot_names = NULL;
    Value *slot_positions_value = NULL;
    ValueArray expected_names;
    ValueArray slot_positions;
    Value *actual_descriptor = NULL;
    Value *actual_slot_read_only_flags = NULL;
    ValueArray read_only_flags;
    if (args->count != 4 || args->items[0]->type != VALUE_SYMBOL) {
        snprintf(err, errsz, "%%struct-set expects structure type, slot index, object, and value");
        return 0;
    }
    if (!struct_arg_index(args->items[1], &index, "%struct-set", err, errsz)) return 0;
    if (!struct_expect_instance(it, env, args->items[2], args->items[0], "%struct-set", err, errsz)) return 0;
    if (!struct_descriptor_lookup(it, env, args->items[0], &expected_descriptor) ||
        !struct_descriptor_parts(expected_descriptor, &expected_slot_names, NULL, NULL, NULL, NULL, NULL) ||
        !struct_descriptor_representation_info(expected_descriptor, &representation_kind, NULL, NULL) ||
        !struct_descriptor_layout_info(expected_descriptor, &slot_positions_value, NULL, NULL) ||
        !proper_form_to_array(slot_positions_value, &slot_positions) ||
        !proper_form_to_array(expected_slot_names, &expected_names)) {
        snprintf(err, errsz, "%%struct-set internal structure descriptor error");
        return 0;
    }
    if (index >= expected_names.count) {
        snprintf(err, errsz, "%%struct-set slot index out of range");
        return 0;
    }
    {
        int64_t pos_i64 = 0;
        if (slot_positions.items[index]->type != VALUE_INT ||
            !bigint_to_i64_checked(slot_positions.items[index]->as.bigint, &pos_i64) ||
            pos_i64 < 0) {
            snprintf(err, errsz, "%%struct-set internal slot layout error");
            return 0;
        }
        pos = (int)pos_i64;
    }
    if (!struct_descriptor_effective_for_value(it, env, args->items[2], args->items[0], expected_descriptor, &actual_descriptor)) {
        snprintf(err, errsz, "%%struct-set internal structure descriptor error");
        return 0;
    }
    if (actual_descriptor != NULL &&
        struct_descriptor_parts(actual_descriptor, NULL, NULL, NULL, NULL, &actual_slot_read_only_flags, NULL) &&
        proper_form_to_array(actual_slot_read_only_flags, &read_only_flags) &&
        index < read_only_flags.count &&
        value_is_truthy(read_only_flags.items[index])) {
        snprintf(err, errsz, "%%struct-set cannot modify read-only slot");
        return 0;
    }
    if (!struct_slot_value_satisfies_declared_type(it,
                                                   env,
                                                   (actual_descriptor != NULL) ? actual_descriptor : expected_descriptor,
                                                   index,
                                                   args->items[3],
                                                   "%struct-set",
                                                   err,
                                                   errsz)) {
        return 0;
    }
    if (representation_kind == STRUCT_REPR_HEAP) {
        args->items[2]->as.structure.slots.items[index] = args->items[3];
    } else if (representation_kind == STRUCT_REPR_LIST) {
        if (!list_like_set_nth(args->items[2], pos, args->items[3])) {
            snprintf(err, errsz, "%%struct-set slot index out of range");
            return 0;
        }
    } else if (representation_kind == STRUCT_REPR_STRING) {
        if (!array_row_major_write(args->items[2], pos, args->items[3], out, err, errsz)) return 0;
    } else if (representation_kind == STRUCT_REPR_VECTOR) {
        if (pos >= args->items[2]->as.array.count) {
            snprintf(err, errsz, "%%struct-set slot index out of range");
            return 0;
        }
        if (!array_row_major_write(args->items[2], pos, args->items[3], out, err, errsz)) return 0;
    } else {
        snprintf(err, errsz, "%%struct-set internal structure representation error");
        return 0;
    }
    *out = args->items[3];
    return 1;
}

static int builtin_internal_struct_type_p(Interp *it,
                                          Env *env,
                                          const ValueArray *args,
                                          Value **out,
                                          char *err,
                                          size_t errsz) {
    if (args->count != 2 || args->items[0]->type != VALUE_SYMBOL) {
        snprintf(err, errsz, "%%struct-type-p expects structure type and object");
        return 0;
    }
    *out = struct_value_matches_expected_type(it, env, args->items[1], args->items[0])
        ? it->true_value
        : it->false_value;
    return 1;
}

static int builtin_internal_copy_struct_instance(Interp *it,
                                                 Env *env,
                                                 const ValueArray *args,
                                                 Value **out,
                                                 char *err,
                                                 size_t errsz) {
    Value *descriptor = NULL;
    Value *vector_element_type_spec = NULL;
    ValueArray items;
    char tmp_err[64];
    int representation_kind = STRUCT_REPR_HEAP;
    if (args->count != 2 || args->items[0]->type != VALUE_SYMBOL) {
        snprintf(err, errsz, "%%copy-struct-instance expects structure type and object");
        return 0;
    }
    if (!struct_expect_instance(it, env, args->items[1], args->items[0], "%copy-struct-instance", err, errsz)) return 0;
    if (!struct_descriptor_lookup(it, env, args->items[0], &descriptor) ||
        !struct_descriptor_representation_info(descriptor, &representation_kind, NULL, NULL)) {
        snprintf(err, errsz, "%%copy-struct-instance internal structure descriptor error");
        return 0;
    }
    if (representation_kind == STRUCT_REPR_HEAP) {
        *out = copy_struct_value(args->items[1]);
        return 1;
    }
    if (representation_kind == STRUCT_REPR_STRING) {
        char *text = value_string_copy_text(args->items[1], 0);
        if (text == NULL) {
            snprintf(err, errsz, "%%copy-struct-instance could not copy the structure representation");
            return 0;
        }
        *out = make_string_value(text);
        free(text);
        return 1;
    }
    if (!sequence_to_array(args->items[1], &items, tmp_err, sizeof(tmp_err))) {
        snprintf(err, errsz, "%%copy-struct-instance could not copy the structure representation");
        return 0;
    }
    if (representation_kind == STRUCT_REPR_LIST) {
        *out = runtime_list_from_array(it->nil, &items);
        return 1;
    }
    if (!struct_descriptor_vector_element_type_spec(it, descriptor, &vector_element_type_spec)) {
        snprintf(err, errsz, "%%copy-struct-instance internal structure descriptor error");
        return 0;
    }
    *out = make_vector_value_typed(&items, upgraded_array_element_type_value(it, env, vector_element_type_spec));
    return 1;
}

static int builtin_copy_structure(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    (void)it;
    (void)env;
    if (args->count != 1) {
        snprintf(err, errsz, "copy-structure expects exactly one structure object");
        return 0;
    }
    if (!struct_expect_instance(it, env, args->items[0], NULL, "copy-structure", err, errsz)) return 0;
    *out = copy_struct_value(args->items[0]);
    return 1;
}

enum {
    COERCE_TARGET_IDENTITY = 1,
    COERCE_TARGET_LIST = 2,
    COERCE_TARGET_VECTOR = 3,
    COERCE_TARGET_STRING = 4,
    COERCE_TARGET_CHARACTER = 5,
    COERCE_TARGET_FLOAT = 6,
    COERCE_TARGET_COMPLEX = 7,
    COERCE_TARGET_FUNCTION = 8,
    COERCE_TARGET_BIT_VECTOR = 9,
    COERCE_TARGET_BYTE_VECTOR = 10
};

static int value_to_character_designator_code(Value *value, int *out) {
    if (value->type == VALUE_CHAR) {
        *out = value->as.ch & 0x1FFFFF;
        return 1;
    }
    if (value->type == VALUE_SYMBOL && strlen(value->as.str) == 1U) {
        *out = (unsigned char)value->as.str[0];
        return 1;
    }
    if (value->type == VALUE_STRING && value_string_sequence_length(value) == 1) {
        return string_storage_read_char(value, 0, out);
    }
    return 0;
}

static int coerce_target_kind(Interp *it, Env *env, Value *spec, int *kind, char *err, size_t errsz) {
    ValueArray items;
    const char *head = NULL;
    if (!expand_type_specifier_fully(it, env, spec, &spec, err, errsz)) return 0;
    if (spec->type == VALUE_SYMBOL) {
        if (builtin_type_symbol_named(spec, "t")) {
            *kind = COERCE_TARGET_IDENTITY;
            return 1;
        }
        if (builtin_type_symbol_named(spec, "list") || builtin_type_symbol_named(spec, "null") ||
            builtin_type_symbol_named(spec, "cons")) {
            *kind = COERCE_TARGET_LIST;
            return 1;
        }
        if (builtin_type_symbol_named(spec, "vector") || builtin_type_symbol_named(spec, "simple-vector")) {
            *kind = COERCE_TARGET_VECTOR;
            return 1;
        }
        if (builtin_type_symbol_named(spec, "bit-vector") || builtin_type_symbol_named(spec, "simple-bit-vector")) {
            *kind = COERCE_TARGET_BIT_VECTOR;
            return 1;
        }
        if (builtin_type_symbol_named(spec, "string") || builtin_type_symbol_named(spec, "simple-string") ||
            (symbol_name(spec, &head) && str_ieq(head, "simple-base-string")) ||
            builtin_type_symbol_named(spec, "base-string")) {
            *kind = COERCE_TARGET_STRING;
            return 1;
        }
        if (builtin_type_symbol_named(spec, "character") || builtin_type_symbol_named(spec, "base-char") ||
            builtin_type_symbol_named(spec, "standard-char")) {
            *kind = COERCE_TARGET_CHARACTER;
            return 1;
        }
        if (builtin_type_symbol_named(spec, "float") || builtin_type_symbol_named(spec, "short-float") ||
            builtin_type_symbol_named(spec, "single-float") || builtin_type_symbol_named(spec, "double-float") ||
            builtin_type_symbol_named(spec, "long-float")) {
            *kind = COERCE_TARGET_FLOAT;
            return 1;
        }
        if (builtin_type_symbol_named(spec, "complex")) {
            *kind = COERCE_TARGET_COMPLEX;
            return 1;
        }
        if (builtin_type_symbol_named(spec, "function")) {
            *kind = COERCE_TARGET_FUNCTION;
            return 1;
        }
        snprintf(err, errsz, "coerce does not support result-type '%s'", spec->as.str);
        return 0;
    }
    if (!type_spec_to_array(spec, &items) || items.count <= 0 || !symbol_name(items.items[0], &head)) {
        snprintf(err, errsz, "coerce result-type must be a symbol or proper list type specifier");
        return 0;
    }
    if (builtin_type_symbol_named(items.items[0], "cons") || builtin_type_symbol_named(items.items[0], "list") ||
        builtin_type_symbol_named(items.items[0], "null")) {
        *kind = COERCE_TARGET_LIST;
        return 1;
    }
    if (builtin_type_symbol_named(items.items[0], "vector") || builtin_type_symbol_named(items.items[0], "simple-vector")) {
        if (items.count >= 2) {
            Value *upgraded = builtin_type_symbol_named(items.items[1], "*")
                ? common_lisp_runtime_symbol_or_fallback(it, "t")
                : upgraded_array_element_type_value(it, env, items.items[1]);
            if (builtin_type_symbol_named(upgraded, "bit")) {
                *kind = COERCE_TARGET_BIT_VECTOR;
                return 1;
            }
            if (type_spec_is_unsigned_byte_8(upgraded)) {
                *kind = COERCE_TARGET_BYTE_VECTOR;
                return 1;
            }
        }
        *kind = COERCE_TARGET_VECTOR;
        return 1;
    }
    if (builtin_type_symbol_named(items.items[0], "bit-vector") || builtin_type_symbol_named(items.items[0], "simple-bit-vector")) {
        *kind = COERCE_TARGET_BIT_VECTOR;
        return 1;
    }
    if (builtin_type_symbol_named(items.items[0], "string") || builtin_type_symbol_named(items.items[0], "simple-string") ||
        builtin_type_symbol_named(items.items[0], "base-string")) {
        *kind = COERCE_TARGET_STRING;
        return 1;
    }
    snprintf(err, errsz, "coerce does not support result-type '%s'", head);
    return 0;
}

static int build_string_from_value_array(const ValueArray *items, Value **out, const char *who, char *err, size_t errsz) {
    char *buf = NULL;
    int i;
    buf = (char *)xmalloc((size_t)items->count + 1U);
    for (i = 0; i < items->count; ++i) {
        int ch = 0;
        if (!value_to_character_designator_code(items->items[i], &ch)) {
            free(buf);
            snprintf(err, errsz, "%s cannot build a string from %s elements", who, value_type_name(items->items[i]));
            return 0;
        }
        buf[i] = (char)(ch & 0xFF);
    }
    buf[items->count] = '\0';
    *out = make_string_value(buf);
    free(buf);
    return 1;
}

static int build_bit_vector_from_value_array(const ValueArray *items, Value **out, const char *who, char *err, size_t errsz) {
    if (!value_array_matches_vector_element_type(items, make_symbol_value("bit"), who, err, errsz)) return 0;
    *out = make_vector_value_typed(items, make_symbol_value("bit"));
    return 1;
}

static int build_byte_vector_from_value_array(Interp *it, const ValueArray *items, Value **out, const char *who, char *err, size_t errsz) {
    Value *spec = make_unsigned_byte_8_type_spec(it);
    if (!value_array_matches_vector_element_type(items, spec, who, err, errsz)) return 0;
    *out = make_vector_value_typed(items, spec);
    return 1;
}

static Value *make_vector_like(Value *source, const ValueArray *items) {
    if (source != NULL && source->type == VALUE_VECTOR) {
        return make_vector_value_typed(items, array_actual_element_type_value(source));
    }
    return make_vector_value(items);
}

static int build_sequence_from_items(Interp *it, int kind, const ValueArray *items, Value **out, const char *who, char *err, size_t errsz) {
    switch (kind) {
        case COERCE_TARGET_LIST:
            *out = runtime_list_from_array(it->nil, items);
            return 1;
        case COERCE_TARGET_VECTOR:
            *out = make_vector_value(items);
            return 1;
        case COERCE_TARGET_BIT_VECTOR:
            return build_bit_vector_from_value_array(items, out, who, err, errsz);
        case COERCE_TARGET_BYTE_VECTOR:
            return build_byte_vector_from_value_array(it, items, out, who, err, errsz);
        case COERCE_TARGET_STRING:
            return build_string_from_value_array(items, out, who, err, errsz);
        default:
            snprintf(err, errsz, "%s result-type must be a supported sequence type", who);
            return 0;
    }
}

static int parse_sort_keyword_options(const ValueArray *args, int start_index, Value **key_fn, const char *who, char *err, size_t errsz) {
    int i;
    *key_fn = NULL;
    if (((args->count - start_index) % 2) != 0) {
        snprintf(err, errsz, "%s keywords must appear in keyword/value pairs", who);
        return 0;
    }
    for (i = start_index; i < args->count; i += 2) {
        Value *key = args->items[i];
        Value *val = args->items[i + 1];
        if (!value_is_keyword(key)) {
            snprintf(err, errsz, "expected a keyword argument, got %s", value_type_name(key));
            return 0;
        }
        if (keyword_matches(key, ":key")) {
            *key_fn = val;
        } else {
            snprintf(err, errsz, "%s does not support the %s keyword", who, key->as.str);
            return 0;
        }
    }
    return 1;
}

static int sort_keyed_value(Interp *it, Env *env, Value *key_fn, Value *value, Value **out, char *err, size_t errsz) {
    ValueArray call_args;
    if (key_fn == NULL) {
        *out = value;
        return 1;
    }
    value_array_init(&call_args);
    value_array_push(&call_args, value);
    return apply_callable(it, env, key_fn, &call_args, out, err, errsz);
}

static int sort_predicate_before(Interp *it, Env *env, Value *predicate, Value *key_fn, Value *left, Value *right, int *out_before, char *err, size_t errsz) {
    Value *keyed_left = left;
    Value *keyed_right = right;
    Value *res = NULL;
    ValueArray call_args;
    if (!sort_keyed_value(it, env, key_fn, left, &keyed_left, err, errsz)) return 0;
    if (!sort_keyed_value(it, env, key_fn, right, &keyed_right, err, errsz)) return 0;
    value_array_init(&call_args);
    value_array_push(&call_args, keyed_left);
    value_array_push(&call_args, keyed_right);
    if (!apply_callable(it, env, predicate, &call_args, &res, err, errsz)) return 0;
    *out_before = value_is_truthy(res);
    return 1;
}

static int stable_sort_value_array(Interp *it, Env *env, ValueArray *items, Value *predicate, Value *key_fn, char *err, size_t errsz) {
    int i;
    for (i = 1; i < items->count; ++i) {
        Value *current = items->items[i];
        int j = i;
        while (j > 0) {
            int before = 0;
            if (!sort_predicate_before(it, env, predicate, key_fn, current, items->items[j - 1], &before, err, errsz)) return 0;
            if (!before) break;
            items->items[j] = items->items[j - 1];
            --j;
        }
        items->items[j] = current;
    }
    return 1;
}

static int sequence_overwrite_from_array(Value *seq, const ValueArray *items, const char *who, char *err, size_t errsz) {
    int len = 0;
    int i;
    if (!sequence_length_any(seq, &len, err, errsz)) return 0;
    if (len != items->count) {
        snprintf(err, errsz, "%s internal sequence size mismatch", who);
        return 0;
    }
    for (i = 0; i < items->count; ++i) {
        if (!sequence_set_element_any(seq, i, items->items[i], who, err, errsz)) return 0;
    }
    return 1;
}

static int coerce_sequence_to_list(Interp *it, Value *object, Value **out, char *err, size_t errsz) {
    ValueArray items;
    if (!sequence_to_array(object, &items, err, errsz)) {
        snprintf(err, errsz, "coerce expects a sequence when result-type is list-like");
        return 0;
    }
    *out = runtime_list_from_array(it->nil, &items);
    return 1;
}

static int coerce_sequence_to_vector(Value *object, Value **out, char *err, size_t errsz) {
    ValueArray items;
    if (!sequence_to_array(object, &items, err, errsz)) {
        snprintf(err, errsz, "coerce expects a sequence when result-type is vector-like");
        return 0;
    }
    *out = make_vector_value(&items);
    return 1;
}

static int coerce_sequence_to_byte_vector(Interp *it, Value *object, Value **out, char *err, size_t errsz) {
    ValueArray items;
    if (!sequence_to_array(object, &items, err, errsz)) {
        snprintf(err, errsz, "coerce expects a sequence when result-type is unsigned-byte 8 vector-like");
        return 0;
    }
    return build_byte_vector_from_value_array(it, &items, out, "coerce", err, errsz);
}

static int coerce_sequence_to_bit_vector(Value *object, Value **out, char *err, size_t errsz) {
    ValueArray items;
    if (!sequence_to_array(object, &items, err, errsz)) {
        snprintf(err, errsz, "coerce expects a sequence when result-type is bit-vector-like");
        return 0;
    }
    return build_bit_vector_from_value_array(&items, out, "coerce", err, errsz);
}

static int coerce_sequence_to_string(Value *object, Value **out, char *err, size_t errsz) {
    ValueArray items;
    if (!sequence_to_array(object, &items, err, errsz)) {
        snprintf(err, errsz, "coerce expects a sequence when result-type is string");
        return 0;
    }
    return build_string_from_value_array(&items, out, "coerce", err, errsz);
}

static int coerce_to_float(Interp *it, Value *object, Value **out, char *err, size_t errsz) {
    Num n;
    double d = 0.0;
    if (!value_to_num(it, object, &n, err, errsz)) {
        snprintf(err, errsz, "coerce expects a real when result-type is float");
        return 0;
    }
    if (!num_to_double_checked(n, &d) || !isfinite(d)) {
        snprintf(err, errsz, "coerce produced a non-finite float");
        return 0;
    }
    *out = make_float_value(d);
    return 1;
}

static int coerce_to_complex(Interp *it, Value *object, Value **out, char *err, size_t errsz) {
    (void)it;
    if (value_is_complex_value(object)) {
        *out = object;
        return 1;
    }
    if (!value_is_real_numeric_value(object)) {
        snprintf(err, errsz, "coerce expects a real when result-type is complex");
        return 0;
    }
    *out = make_complex_value(object, make_int_value(bigint_new_zero()));
    if (*out == NULL) {
        snprintf(err, errsz, "coerce could not build a complex number");
        return 0;
    }
    return 1;
}

static int builtin_float(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    double prototype = 0.0;
    (void)env;
    if (args->count < 1 || args->count > 2) {
        snprintf(err, errsz, "float expects one or two arguments");
        return 0;
    }
    if (args->count == 2 &&
        !value_to_finite_float_only(args->items[1], "float", "its optional prototype", &prototype, err, errsz)) {
        return 0;
    }
    (void)prototype;
    return coerce_to_float(it, args->items[0], out, err, errsz);
}

static Env *env_global_root(Env *env) {
    while (env != NULL && env->parent != NULL) env = env->parent;
    return env;
}

static int coerce_lambda_expression_to_function(Env *env, Value *object, Value **out, char *err, size_t errsz) {
    ValueArray items;
    ValueArray params;
    ValueArray body;
    int i;
    if (!proper_form_to_array(object, &items) || items.count < 3 ||
        !symbol_matches_common_lisp_or_internal_name(items.items[0], "lambda")) {
        snprintf(err, errsz, "coerce expects a function designator or lambda expression when result-type is function");
        return 0;
    }
    if (!proper_form_to_array(items.items[1], &params)) {
        snprintf(err, errsz, "coerce lambda expression must use a proper lambda list");
        return 0;
    }
    value_array_init(&body);
    for (i = 2; i < items.count; ++i) value_array_push(&body, items.items[i]);
    *out = make_closure_value(make_list_value(&params), make_list_value(&body), env_global_root(env), 0);
    return 1;
}

static int coerce_result_must_match(Interp *it, Env *env, Value *result, Value *spec, char *err, size_t errsz) {
    int matches = 0;
    if (spec != NULL && spec->type == VALUE_SYMBOL && builtin_type_symbol_named(spec, "complex") &&
        (result->type == VALUE_INT || result->type == VALUE_RATIO)) {
        return 1;
    }
    if (!value_matches_type_spec(it, env, result, spec, &matches, err, errsz)) return 0;
    if (!matches) {
        snprintf(err, errsz, "coerce result does not satisfy the requested type");
        return 0;
    }
    return 1;
}

static int builtin_type_of(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    (void)env;
    if (args->count != 1) {
        snprintf(err, errsz, "type-of expects exactly one argument");
        return 0;
    }
    *out = portable_type_of_value(it, args->items[0]);
    return 1;
}

static int builtin_coerce(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    int matches = 0;
    int kind = 0;
    Value *result = NULL;
    if (args->count != 2) {
        snprintf(err, errsz, "coerce expects exactly two arguments");
        return 0;
    }
    if (args->items[1]->type == VALUE_NIL ||
        (args->items[1]->type == VALUE_SYMBOL && builtin_type_symbol_named(args->items[1], "nil"))) {
        snprintf(err, errsz, "coerce cannot convert to type nil");
        return 0;
    }
    if (!value_matches_type_spec(it, env, args->items[0], args->items[1], &matches, err, errsz)) {
        const char *type_name = NULL;
        if (args->items[1]->type == VALUE_SYMBOL) {
            type_name = args->items[1]->as.str;
            if (builtin_type_symbol_named(args->items[1], "function")) {
                matches = 0;
            } else {
                return 0;
            }
        } else {
            return 0;
        }
    }
    if (matches) {
        *out = args->items[0];
        return 1;
    }
    if (!coerce_target_kind(it, env, args->items[1], &kind, err, errsz)) return 0;
    switch (kind) {
        case COERCE_TARGET_IDENTITY:
            result = args->items[0];
            break;
        case COERCE_TARGET_LIST:
            if (!coerce_sequence_to_list(it, args->items[0], &result, err, errsz)) return 0;
            break;
        case COERCE_TARGET_VECTOR:
            if (!coerce_sequence_to_vector(args->items[0], &result, err, errsz)) return 0;
            break;
        case COERCE_TARGET_BIT_VECTOR:
            if (!coerce_sequence_to_bit_vector(args->items[0], &result, err, errsz)) return 0;
            break;
        case COERCE_TARGET_BYTE_VECTOR:
            if (!coerce_sequence_to_byte_vector(it, args->items[0], &result, err, errsz)) return 0;
            break;
        case COERCE_TARGET_STRING:
            if (!coerce_sequence_to_string(args->items[0], &result, err, errsz)) return 0;
            break;
        case COERCE_TARGET_CHARACTER: {
            int ch = 0;
            if (!value_to_character_designator_code(args->items[0], &ch)) {
                snprintf(err, errsz, "coerce expects a character designator when result-type is character");
                return 0;
            }
            result = make_char_value(ch);
            break;
        }
        case COERCE_TARGET_FLOAT:
            if (!coerce_to_float(it, args->items[0], &result, err, errsz)) return 0;
            break;
        case COERCE_TARGET_COMPLEX:
            if (!coerce_to_complex(it, args->items[0], &result, err, errsz)) return 0;
            break;
        case COERCE_TARGET_FUNCTION:
            if (args->items[0]->type == VALUE_SYMBOL) {
                if (!resolve_function_designator(env, args->items[0], &result, err, errsz)) return 0;
            } else if (value_is_function_object(args->items[0])) {
                result = args->items[0];
            } else {
                if (!coerce_lambda_expression_to_function(env, args->items[0], &result, err, errsz)) return 0;
            }
            break;
        default:
            snprintf(err, errsz, "unsupported coerce target kind");
            return 0;
    }
    if (!coerce_result_must_match(it, env, result, args->items[1], err, errsz)) return 0;
    *out = result;
    return 1;
}

static const char *hash_table_test_name(int test_kind) {
    switch (test_kind) {
        case HASH_TEST_EQ: return "eq";
        case HASH_TEST_EQL: return "eql";
        case HASH_TEST_EQUAL: return "equal";
        case HASH_TEST_EQUALP: return "equalp";
        default: return "eql";
    }
}

static int hash_table_test_kind_from_designator(Env *env, Value *designator, int *out_kind, char *err, size_t errsz) {
    Value *fn = NULL;
    const char *name = NULL;
    if (designator->type == VALUE_SYMBOL) {
        if (symbol_matches_common_lisp_or_internal_name(designator, "eq")) *out_kind = HASH_TEST_EQ;
        else if (symbol_matches_common_lisp_or_internal_name(designator, "eql")) *out_kind = HASH_TEST_EQL;
        else if (symbol_matches_common_lisp_or_internal_name(designator, "equal")) *out_kind = HASH_TEST_EQUAL;
        else if (symbol_matches_common_lisp_or_internal_name(designator, "equalp")) *out_kind = HASH_TEST_EQUALP;
        else {
            snprintf(err, errsz, "make-hash-table currently supports only eq, eql, equal, or equalp tests");
            return 0;
        }
        return 1;
    } else if (designator->type == VALUE_BUILTIN) {
        name = designator->as.builtin.name;
    } else {
        if (!resolve_function_designator(env, designator, &fn, err, errsz)) return 0;
        if (fn->type != VALUE_BUILTIN) {
            snprintf(err, errsz, "make-hash-table currently supports only eq, eql, equal, or equalp tests");
            return 0;
        }
        name = fn->as.builtin.name;
    }
    if (str_ieq(name, "eq")) *out_kind = HASH_TEST_EQ;
    else if (str_ieq(name, "eql")) *out_kind = HASH_TEST_EQL;
    else if (str_ieq(name, "equal")) *out_kind = HASH_TEST_EQUAL;
    else if (str_ieq(name, "equalp")) *out_kind = HASH_TEST_EQUALP;
    else {
        snprintf(err, errsz, "make-hash-table currently supports only eq, eql, equal, or equalp tests");
        return 0;
    }
    return 1;
}

static int hash_table_key_equal(int test_kind, Value *left, Value *right) {
    switch (test_kind) {
        case HASH_TEST_EQ: return value_eq_impl(left, right);
        case HASH_TEST_EQL: return value_eql_impl(left, right);
        case HASH_TEST_EQUAL: return value_equal_impl(left, right);
        case HASH_TEST_EQUALP: return value_equalp_impl(left, right);
        default: return value_eql_impl(left, right);
    }
}

static int hash_table_find_entry(Value *table, Value *key) {
    int i;
    for (i = 0; i < table->as.hash_table.count; ++i) {
        if (hash_table_key_equal(table->as.hash_table.test_kind, table->as.hash_table.entries[i].key, key)) return i;
    }
    return -1;
}

static int hash_table_next_capacity(Value *table) {
    int cap = table->as.hash_table.cap;
    double rehash_size = table->as.hash_table.rehash_size;
    if (cap <= 0) cap = 16;
    else if (rehash_size > 1.0 && floor(rehash_size) == rehash_size) cap += (int)rehash_size;
    else cap = (int)ceil((double)cap * rehash_size);
    if (cap <= table->as.hash_table.cap) cap = table->as.hash_table.cap + 1;
    return cap;
}

static int hash_table_ensure_capacity(Value *table) {
    int new_cap = 0;
    if (table->as.hash_table.count < table->as.hash_table.cap) return 1;
    new_cap = hash_table_next_capacity(table);
    table->as.hash_table.entries = (HashEntry *)xrealloc(table->as.hash_table.entries, (size_t)new_cap * sizeof(HashEntry));
    table->as.hash_table.cap = new_cap;
    return 1;
}

static int value_to_non_negative_fixnum(Value *value, const char *who, const char *field, int *out, char *err, size_t errsz) {
    int64_t n = 0;
    if (value->type != VALUE_INT || !bigint_to_i64_checked(value->as.bigint, &n) || n < 0 || n > INT_MAX) {
        snprintf(err, errsz, "%s expects %s to be a non-negative fixnum", who, field);
        return 0;
    }
    *out = (int)n;
    return 1;
}

static int value_to_positive_rehash_size(Value *value, double *out, char *err, size_t errsz) {
    int64_t i64 = 0;
    if (value->type == VALUE_INT) {
        if (!bigint_to_i64_checked(value->as.bigint, &i64) || i64 <= 0) {
            snprintf(err, errsz, "make-hash-table expects :rehash-size to be a positive integer or float greater than 1");
            return 0;
        }
        *out = (double)i64;
        return 1;
    }
    if (value->type == VALUE_FLOAT && isfinite(value->as.flt) && value->as.flt > 1.0) {
        *out = value->as.flt;
        return 1;
    }
    snprintf(err, errsz, "make-hash-table expects :rehash-size to be a positive integer or float greater than 1");
    return 0;
}

static int value_to_rehash_threshold(Value *value, double *out, char *err, size_t errsz) {
    int64_t i64 = 0;
    double d = 0.0;
    if (value->type == VALUE_INT) {
        if (!bigint_to_i64_checked(value->as.bigint, &i64)) {
            snprintf(err, errsz, "make-hash-table expects :rehash-threshold to be a real in [0, 1]");
            return 0;
        }
        d = (double)i64;
    } else if (value->type == VALUE_FLOAT && isfinite(value->as.flt)) {
        d = value->as.flt;
    } else {
        snprintf(err, errsz, "make-hash-table expects :rehash-threshold to be a real in [0, 1]");
        return 0;
    }
    if (d < 0.0 || d > 1.0) {
        snprintf(err, errsz, "make-hash-table expects :rehash-threshold to be a real in [0, 1]");
        return 0;
    }
    *out = d;
    return 1;
}

static int builtin_make_hash_table(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    int i;
    int test_kind = HASH_TEST_EQL;
    int initial_size = 16;
    double rehash_size = 1.5;
    double rehash_threshold = 1.0;
    (void)it;
    if ((args->count % 2) != 0) {
        snprintf(err, errsz, "make-hash-table expects keyword/value pairs");
        return 0;
    }
    for (i = 0; i < args->count; i += 2) {
        if (!value_is_keyword(args->items[i])) {
            snprintf(err, errsz, "make-hash-table expects keyword arguments");
            return 0;
        }
        if (keyword_matches(args->items[i], ":test")) {
            if (!hash_table_test_kind_from_designator(env, args->items[i + 1], &test_kind, err, errsz)) return 0;
        } else if (keyword_matches(args->items[i], ":size")) {
            if (!value_to_non_negative_fixnum(args->items[i + 1], "make-hash-table", ":size", &initial_size, err, errsz)) return 0;
        } else if (keyword_matches(args->items[i], ":rehash-size")) {
            if (!value_to_positive_rehash_size(args->items[i + 1], &rehash_size, err, errsz)) return 0;
        } else if (keyword_matches(args->items[i], ":rehash-threshold")) {
            if (!value_to_rehash_threshold(args->items[i + 1], &rehash_threshold, err, errsz)) return 0;
        } else {
            snprintf(err, errsz, "make-hash-table does not support the %s keyword", args->items[i]->as.str);
            return 0;
        }
    }
    *out = make_hash_table_value(test_kind, initial_size, rehash_size, rehash_threshold);
    return 1;
}

