static int builtin_gethash(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    ValueArray values;
    Value *default_value = NULL;
    int idx = -1;
    (void)env;
    if (args->count != 2 && args->count != 3) {
        snprintf(err, errsz, "gethash expects key, hash-table, and optional default");
        return 0;
    }
    if (args->items[1]->type != VALUE_HASH_TABLE) {
        snprintf(err, errsz, "gethash expects a hash-table as its second argument");
        return 0;
    }
    default_value = (args->count == 3) ? args->items[2] : it->nil;
    idx = hash_table_find_entry(args->items[1], args->items[0]);
    value_array_init(&values);
    if (idx >= 0) {
        value_array_push(&values, args->items[1]->as.hash_table.entries[idx].value);
        value_array_push(&values, it->true_value);
    } else {
        value_array_push(&values, default_value);
        value_array_push(&values, it->false_value);
    }
    interp_set_values(it, &values);
    *out = values.items[0];
    return 1;
}

static int builtin_remhash(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    int idx = -1;
    (void)env;
    if (args->count != 2) {
        snprintf(err, errsz, "remhash expects exactly two arguments");
        return 0;
    }
    if (args->items[1]->type != VALUE_HASH_TABLE) {
        snprintf(err, errsz, "remhash expects a hash-table as its second argument");
        return 0;
    }
    idx = hash_table_find_entry(args->items[1], args->items[0]);
    if (idx < 0) {
        *out = it->false_value;
        return 1;
    }
    if (idx + 1 < args->items[1]->as.hash_table.count) {
        memmove(&args->items[1]->as.hash_table.entries[idx],
                &args->items[1]->as.hash_table.entries[idx + 1],
                (size_t)(args->items[1]->as.hash_table.count - idx - 1) * sizeof(HashEntry));
    }
    --args->items[1]->as.hash_table.count;
    *out = it->true_value;
    return 1;
}

