static int builtin_filter(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    ValueArray arr;
    ValueArray seq_items;
    Value *fn;
    int i;
    if (args->count != 2 || !value_is_sequence(args->items[1])) {
        snprintf(err, errsz, "filter expects a function and a sequence");
        return 0;
    }
    fn = args->items[0];
    if (!sequence_to_array(args->items[1], &seq_items, err, errsz)) return 0;
    value_array_init(&arr);
    for (i = 0; i < seq_items.count; ++i) {
        Value *keep = NULL;
        if (!call_unary_function(it, env, fn, seq_items.items[i], &keep, err, errsz)) return 0;
        if (value_is_truthy(keep)) value_array_push(&arr, seq_items.items[i]);
    }
    *out = runtime_list_from_array(it->nil, &arr);
    return 1;
}

static int builtin_fold(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    Value *fn;
    Value *acc;
    Value *seq;
    ValueArray seq_items;
    int i;
    if (args->count != 3 || !value_is_sequence(args->items[2])) {
        snprintf(err, errsz, "fold expects a function, init and sequence");
        return 0;
    }
    fn = args->items[0];
    acc = args->items[1];
    seq = args->items[2];
    if (!sequence_to_array(seq, &seq_items, err, errsz)) return 0;
    for (i = 0; i < seq_items.count; ++i) {
        ValueArray call_args;
        Value *next = NULL;
        value_array_init(&call_args);
        value_array_push(&call_args, acc);
        value_array_push(&call_args, seq_items.items[i]);
        if (!apply_callable(it, env, fn, &call_args, &next, err, errsz)) return 0;
        acc = next;
    }
    *out = acc;
    return 1;
}

static int builtin_reduce(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    Value *fn;
    Value *seq;
    ReduceKeywordOptions opts;
    int start_index = 2;
    int len = 0;
    int start = 0;
    int end = 0;
    int i;
    if (args->count < 2) {
        snprintf(err, errsz, "reduce expects a function, a sequence, and optional keyword arguments");
        return 0;
    }
    fn = args->items[0];
    seq = args->items[1];
    if (args->count >= 3 && !value_is_keyword(args->items[2])) {
        if (args->count != 3) {
            snprintf(err, errsz, "legacy positional reduce initial value cannot be mixed with additional arguments; use :initial-value");
            return 0;
        }
        reduce_keyword_options_init(&opts);
        opts.initial_value = args->items[2];
        opts.has_initial_value = 1;
    } else {
        if (!parse_reduce_keyword_options(it, args, start_index, &opts, err, errsz)) return 0;
    }
    if (!sequence_length_any(seq, &len, err, errsz)) return 0;
    start = opts.start;
    end = opts.has_end ? opts.end : len;
    if (start > end || end > len) {
        snprintf(err, errsz, "reduce bounds out of range");
        return 0;
    }
    if (start == end) {
        if (opts.has_initial_value) {
            *out = opts.initial_value;
            return 1;
        }
        {
            ValueArray call_args;
            value_array_init(&call_args);
            return apply_callable(it, env, fn, &call_args, out, err, errsz);
        }
    }
    if (!opts.has_initial_value && end - start == 1) {
        Value *single = NULL;
        Value *ignored = NULL;
        if (!sequence_element_any(seq, start, &single, err, errsz)) return 0;
        if (!reduce_apply_key(it, env, opts.key_fn, single, &ignored, err, errsz)) return 0;
        *out = single;
        return 1;
    }
    if (opts.from_end) {
        Value *acc = NULL;
        int idx = end - 1;
        if (opts.has_initial_value) {
            acc = opts.initial_value;
        } else {
            Value *elem = NULL;
            if (!sequence_element_any(seq, idx, &elem, err, errsz)) return 0;
            if (!reduce_apply_key(it, env, opts.key_fn, elem, &acc, err, errsz)) return 0;
            --idx;
        }
        for (; idx >= start; --idx) {
            Value *elem = NULL;
            Value *keyed = NULL;
            Value *next = NULL;
            ValueArray call_args;
            if (!sequence_element_any(seq, idx, &elem, err, errsz)) return 0;
            if (!reduce_apply_key(it, env, opts.key_fn, elem, &keyed, err, errsz)) return 0;
            value_array_init(&call_args);
            value_array_push(&call_args, keyed);
            value_array_push(&call_args, acc);
            if (!apply_callable(it, env, fn, &call_args, &next, err, errsz)) return 0;
            acc = next;
        }
        *out = acc;
        return 1;
    } else {
        Value *acc = NULL;
        int idx = start;
        if (opts.has_initial_value) {
            acc = opts.initial_value;
        } else {
            Value *elem = NULL;
            if (!sequence_element_any(seq, idx, &elem, err, errsz)) return 0;
            if (!reduce_apply_key(it, env, opts.key_fn, elem, &acc, err, errsz)) return 0;
            ++idx;
        }
        for (; idx < end; ++idx) {
            Value *elem = NULL;
            Value *keyed = NULL;
            Value *next = NULL;
            ValueArray call_args;
            if (!sequence_element_any(seq, idx, &elem, err, errsz)) return 0;
            if (!reduce_apply_key(it, env, opts.key_fn, elem, &keyed, err, errsz)) return 0;
            value_array_init(&call_args);
            value_array_push(&call_args, acc);
            value_array_push(&call_args, keyed);
            if (!apply_callable(it, env, fn, &call_args, &next, err, errsz)) return 0;
            acc = next;
        }
        *out = acc;
        return 1;
    }
}

static int builtin_print(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    Value *stream = NULL;
    char *text = NULL;
    WriteKeywordOptions opts;
    PrintRenderOptions render;
    if (args->count < 1 || args->count > 2) {
        snprintf(err, errsz, "print expects one argument and an optional output-stream");
        return 0;
    }
    if (args->count == 2) stream = args->items[1];
    if (!resolve_output_stream_designator(it, stream, "print", &stream, err, errsz)) return 0;
    memset(&opts, 0, sizeof(opts));
    opts.escape = 1;
    opts.have_escape = 1;
    if (!resolve_print_render_options(it, env, &opts, &render, err, errsz)) return 0;
    if (!output_stream_at_line_start(it, stream))
        output_stream_write_char(it, stream, '\n');
    if (!render_write_text(it, env, args->items[0], &render, &text)) return 0;
    output_stream_write_text(it, stream, text);
    free(text);
    output_stream_write_char(it, stream, ' ');
    *out = args->items[0];
    return 1;
}

static int builtin_pprint(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    Value *stream = NULL;
    char *text = NULL;
    WriteKeywordOptions opts;
    PrintRenderOptions render;
    if (args->count < 1 || args->count > 2) {
        snprintf(err, errsz, "pprint expects one argument and an optional output-stream");
        return 0;
    }
    if (args->count == 2) stream = args->items[1];
    if (!resolve_output_stream_designator(it, stream, "pprint", &stream, err, errsz)) return 0;
    memset(&opts, 0, sizeof(opts));
    opts.escape = 1;
    opts.have_escape = 1;
    opts.pretty = 1;
    opts.have_pretty = 1;
    if (!resolve_print_render_options(it, env, &opts, &render, err, errsz)) return 0;
    if (!render_write_text(it, env, args->items[0], &render, &text)) return 0;
    output_stream_write_text(it, stream, text);
    free(text);
    interp_set_no_values(it);
    *out = it->nil;
    return 1;
}

