static int special_quote(Interp *it, Env *env, Value *form, Value **out, char *err, size_t errsz) {
    (void)env;
    if (form->as.array.count != 2) {
        snprintf(err, errsz, "quote expects exactly one argument");
        return 0;
    }
    if (!quoted_to_datum(it, form->as.array.items[1], out, err, errsz)) return 0;
    interp_set_single_value(it, *out);
    return 1;
}

static int special_quasiquote(Interp *it, Env *env, Value *form, Value **out, char *err, size_t errsz) {
    if (form->as.array.count != 2) {
        snprintf(err, errsz, "quasiquote expects exactly one argument");
        return 0;
    }
    if (!quasiquote_eval(it, env, form->as.array.items[1], 1, out, err, errsz)) return 0;
    interp_set_single_value(it, *out);
    return 1;
}

