static int builtin_translate_pathname(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    Value *source = NULL;
    Value *from = NULL;
    Value *to = NULL;
    (void)env;
    if (args->count < 3 || args->count > 3) {
        snprintf(err, errsz, "translate-pathname expects source, from-wildcard, and to-wildcard");
        return 0;
    }
    if (!pathname_designator_value(args->items[0], "translate-pathname", &source, err, errsz)) return 0;
    if (!pathname_designator_value(args->items[1], "translate-pathname", &from, err, errsz)) return 0;
    if (!pathname_designator_value(args->items[2], "translate-pathname", &to, err, errsz)) return 0;
    if (from->type != VALUE_PATHNAME || to->type != VALUE_PATHNAME || source->type != VALUE_PATHNAME) {
        snprintf(err, errsz, "translate-pathname expects pathname designators");
        return 0;
    }
    if (!pathname_matches_wildcard_pathname(source, from)) {
        snprintf(err, errsz, "translate-pathname source does not match from-wildcard");
        return 0;
    }
    if (!pathname_translate_using_root(it, source, to, "translate-pathname", out, err, errsz)) return 0;
    return 1;
}

