static int builtin_parse_namestring(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    char *text = NULL;
    int start = 0;
    int end = -1;
    int i;
    int text_len;
    char *sub = NULL;
    (void)env;
    if (args->count < 1) {
        snprintf(err, errsz, "parse-namestring expects a string designator and optional keyword arguments");
        return 0;
    }
    if (!value_to_string_designator_text(args->items[0], "parse-namestring", &text, err, errsz)) return 0;
    if (((args->count - 1) % 2) != 0) {
        free(text);
        snprintf(err, errsz, "parse-namestring keyword arguments must appear in keyword/value pairs");
        return 0;
    }
    for (i = 1; i < args->count; i += 2) {
        Value *key = args->items[i];
        Value *val = args->items[i + 1];
        if (!value_is_keyword(key)) {
            free(text);
            snprintf(err, errsz, "parse-namestring expected a keyword argument, got %s", value_type_name(key));
            return 0;
        }
        if (keyword_matches(key, ":start")) {
            if (!value_to_non_negative_index(it, val, "parse-namestring", &start, err, errsz)) {
                free(text);
                return 0;
            }
        } else if (keyword_matches(key, ":end")) {
            if (!value_to_non_negative_index(it, val, "parse-namestring", &end, err, errsz)) {
                free(text);
                return 0;
            }
        } else if (keyword_matches(key, ":junk-allowed")) {
            /* Accepted for compatibility */
        } else {
            free(text);
            snprintf(err, errsz, "unsupported parse-namestring keyword '%s'", key->as.str);
            return 0;
        }
    }
    text_len = (int)strlen(text);
    if (end < 0 || end > text_len) end = text_len;
    if (start > end) {
        free(text);
        snprintf(err, errsz, "parse-namestring :start is greater than :end or string length");
        return 0;
    }
    if (start == 0 && end == text_len) {
        sub = text;
        text = NULL;
    } else {
        sub = (char *)xmalloc((size_t)(end - start) + 1U);
        memcpy(sub, text + start, (size_t)(end - start));
        sub[end - start] = '\0';
    }
    *out = make_pathname_value(sub);
    free(sub);
    if (text != NULL) free(text);
    return 1;
}

static int builtin_enough_namestring(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    Value *pathname = NULL;
    Value *defaults = NULL;
    const char *path = NULL;
    const char *def_path = NULL;
    const char *rel_start = NULL;
    if (args->count < 1 || args->count > 2) {
        snprintf(err, errsz, "enough-namestring expects a pathname designator and optional defaults");
        return 0;
    }
    if (!pathname_designator_value(args->items[0], "enough-namestring", &pathname, err, errsz)) return 0;
    if (args->count >= 2) {
        if (!pathname_designator_value(args->items[1], "enough-namestring", &defaults, err, errsz)) return 0;
    }
    if (defaults == NULL) {
        defaults = default_pathname_defaults_value(it, env);
    }
    path = pathname->as.pathname.namestring;
    def_path = defaults->as.pathname.namestring;
    if (def_path != NULL && def_path[0] != '\0') {
        size_t def_len = strlen(def_path);
        if (strncmp(path, def_path, def_len) == 0) {
            rel_start = path + def_len;
            if (*rel_start == '/') ++rel_start;
            if (*rel_start == '\0') {
                *out = make_string_value("");
                return 1;
            }
            *out = make_string_value(rel_start);
            return 1;
        }
    }
    *out = make_string_value(path);
    return 1;
}

static int builtin_user_homedir_pathname(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    const char *home = NULL;
    char *path = NULL;
    (void)env;
    if (args->count > 1) {
        snprintf(err, errsz, "user-homedir-pathname expects at most one optional host argument");
        return 0;
    }
#if defined(_WIN32)
    home = getenv("USERPROFILE");
    if (home == NULL) {
        const char *drive = getenv("HOMEDRIVE");
        const char *hpath = getenv("HOMEPATH");
        if (drive != NULL && hpath != NULL) {
            StrBuf buf;
            strbuf_init(&buf);
            strbuf_append(&buf, drive);
            strbuf_append(&buf, hpath);
            path = strbuf_take(&buf);
            *out = make_pathname_value(path);
            free(path);
            return 1;
        }
    }
#else
    home = getenv("HOME");
#endif
    if (home == NULL || home[0] == '\0') {
        *out = make_pathname_value("/");
        return 1;
    }
    *out = make_pathname_value(home);
    return 1;
}

static int builtin_directory_pathname_p(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    Value *pathname = NULL;
    (void)it;
    (void)env;
    if (args->count != 1) {
        snprintf(err, errsz, "directory-pathname-p expects exactly one pathname designator");
        return 0;
    }
    if (!pathname_designator_value(args->items[0], "directory-pathname-p", &pathname, err, errsz)) return 0;
    *out = (pathname->as.pathname.name == NULL) ? it->true_value : it->nil;
    return 1;
}

static int builtin_pathname_suffix(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    Value *pathname = NULL;
    (void)it;
    (void)env;
    if (args->count != 1) {
        snprintf(err, errsz, "pathname-suffix expects exactly one pathname designator");
        return 0;
    }
    if (!pathname_designator_value(args->items[0], "pathname-suffix", &pathname, err, errsz)) return 0;
    *out = pathname_component_or_nil(it, pathname->as.pathname.type);
    return 1;
}

static int builtin_setf_pathname_suffix(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    Value *pathname = NULL;
    Value *type_val = NULL;
    char *namestring = NULL;
    (void)env;
    if (args->count != 2) {
        snprintf(err, errsz, "setf-pathname-suffix expects a new suffix and a pathname designator");
        return 0;
    }
    if (args->items[0]->type == VALUE_STRING) {
        type_val = args->items[0];
    } else if (args->items[0]->type == VALUE_NIL) {
        type_val = NULL;
    } else {
        snprintf(err, errsz, "setf-pathname-suffix new suffix must be a string or nil");
        return 0;
    }
    if (!pathname_designator_value(args->items[1], "setf-pathname-suffix", &pathname, err, errsz)) return 0;
    if (!pathname_build_namestring(pathname->as.pathname.host,
                                    pathname->as.pathname.device,
                                    pathname->as.pathname.directory,
                                    pathname->as.pathname.name,
                                    type_val,
                                    "setf-pathname-suffix",
                                    &namestring,
                                    err,
                                    errsz)) return 0;
    *out = make_pathname_value_components(namestring,
                                           pathname->as.pathname.host,
                                           pathname->as.pathname.device,
                                           pathname->as.pathname.directory,
                                           pathname->as.pathname.name,
                                           type_val,
                                           pathname->as.pathname.version,
                                           pathname->as.pathname.logicalp);
    free(namestring);
    return 1;
}

static int builtin_load_logical_pathname_translations(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    char *host_name = NULL;
    Value *existing = NULL;
    (void)env;
    if (args->count != 1) {
        snprintf(err, errsz, "load-logical-pathname-translations expects exactly one host designator");
        return 0;
    }
    if (!value_to_string_designator_text(args->items[0], "load-logical-pathname-translations", &host_name, err, errsz)) return 0;
    existing = logical_pathname_translations_lookup(it, host_name);
    free(host_name);
    if (existing != NULL && existing->type != VALUE_NIL) {
        *out = it->true_value;
        return 1;
    }
    snprintf(err, errsz, "load-logical-pathname-translations cannot find translations for host");
    return 0;
}

static int builtin_make_pathname(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    Value *defaults_path = NULL;
    Value *host = NULL;
    Value *device = NULL;
    Value *directory = NULL;
    Value *name = NULL;
    Value *type = NULL;
    Value *version = NULL;
    int have_host = 0;
    int have_device = 0;
    int have_directory = 0;
    int have_name = 0;
    int have_type = 0;
    int have_version = 0;
    int i;
    char *namestring = NULL;
    if ((args->count % 2) != 0) {
        snprintf(err, errsz, "make-pathname expects keyword/value pairs");
        return 0;
    }
    for (i = 0; i < args->count; i += 2) {
        Value *key = args->items[i];
        Value *value = args->items[i + 1];
        if (!value_is_keyword(key)) {
            snprintf(err, errsz, "make-pathname expects keyword arguments");
            return 0;
        }
        if (keyword_matches(key, ":defaults")) {
            if (!pathname_designator_value(value, "make-pathname", &defaults_path, err, errsz)) return 0;
        } else if (keyword_matches(key, ":host")) {
            host = value;
            have_host = 1;
        } else if (keyword_matches(key, ":device")) {
            device = value;
            have_device = 1;
        } else if (keyword_matches(key, ":directory")) {
            directory = value;
            have_directory = 1;
        } else if (keyword_matches(key, ":name")) {
            name = value;
            have_name = 1;
        } else if (keyword_matches(key, ":type")) {
            type = value;
            have_type = 1;
        } else if (keyword_matches(key, ":version")) {
            version = value;
            have_version = 1;
        } else if (keyword_matches(key, ":case")) {
            if (value != it->nil && (!keyword_matches(value, ":local") && !keyword_matches(value, ":common"))) {
                snprintf(err, errsz, "make-pathname :case must be nil, :local, or :common");
                return 0;
            }
        } else {
            snprintf(err, errsz, "make-pathname does not support the %s keyword", key->as.str);
            return 0;
        }
    }
    if (defaults_path != NULL) {
        if (!have_host) host = defaults_path->as.pathname.host;
        if (!have_device) device = defaults_path->as.pathname.device;
        if (!have_directory) directory = defaults_path->as.pathname.directory;
        if (!have_name) name = defaults_path->as.pathname.name;
        if (!have_type) type = defaults_path->as.pathname.type;
        if (!have_version) version = defaults_path->as.pathname.version;
    }
    if (host == it->nil) host = NULL;
    if (device == it->nil) device = NULL;
    if (directory == it->nil) directory = NULL;
    if (name == it->nil) name = NULL;
    if (type == it->nil) type = NULL;
    if (version == it->nil) version = NULL;
    if (!pathname_build_namestring(host, device, directory, name, type, "make-pathname", &namestring, err, errsz)) return 0;
    *out = make_pathname_value_components(namestring, host, device, directory, name, type, pathname_version_value_from_default(it, version), 0);
    free(namestring);
    return 1;
}

static Value *default_pathname_defaults_value(Interp *it, Env *env) {
    Value *value = NULL;
    int is_bound = 0;
    if (symbol_value_lookup_runtime_special(it, env, "*default-pathname-defaults*", &value, &is_bound) && is_bound) {
        Value *pathname = NULL;
        char err[128];
        if (pathname_designator_value(value, "merge-pathnames", &pathname, err, sizeof(err))) return pathname;
    }
    return make_pathname_value("");
}

static int merge_pathnames_values(Interp *it,
                                  Value *pathname,
                                  Value *defaults,
                                  Value *version,
                                  const char *who,
                                  Value **out,
                                  char *err,
                                  size_t errsz) {
    Value *merged_version = NULL;
    Value *host = NULL;
    Value *device = NULL;
    Value *directory = NULL;
    Value *name = NULL;
    Value *type = NULL;
    char *namestring = NULL;
    if (pathname == NULL || pathname->type != VALUE_PATHNAME || defaults == NULL || defaults->type != VALUE_PATHNAME) {
        snprintf(err, errsz, "%s expects pathname objects internally", who);
        return 0;
    }
    host = (pathname->as.pathname.host != NULL) ? pathname->as.pathname.host : defaults->as.pathname.host;
    device = (pathname->as.pathname.device != NULL) ? pathname->as.pathname.device : defaults->as.pathname.device;
    directory = pathname_merge_directory(pathname->as.pathname.directory, defaults->as.pathname.directory);
    name = (pathname->as.pathname.name != NULL) ? pathname->as.pathname.name : defaults->as.pathname.name;
    type = (pathname->as.pathname.type != NULL) ? pathname->as.pathname.type : defaults->as.pathname.type;
    if (pathname->as.pathname.version != NULL) {
        merged_version = pathname->as.pathname.version;
    } else if (pathname->as.pathname.name == NULL) {
        merged_version = (defaults->as.pathname.version != NULL) ? defaults->as.pathname.version : pathname_version_value_from_default(it, version);
    } else {
        merged_version = pathname_version_value_from_default(it, version);
    }
    if (!pathname_build_namestring(host, device, directory, name, type, who, &namestring, err, errsz)) return 0;
    *out = make_pathname_value_components(namestring, host, device, directory, name, type, merged_version, 0);
    free(namestring);
    return 1;
}

static int merged_pathname_designator_value(Interp *it, Env *env, Value *designator, const char *who, Value **out, char *err, size_t errsz) {
    Value *pathname = NULL;
    Value *defaults = default_pathname_defaults_value(it, env);
    if (!pathname_designator_value(designator, who, &pathname, err, errsz)) return 0;
    return merge_pathnames_values(it, pathname, defaults, NULL, who, out, err, errsz);
}

static int filesystem_probe_existing_path(const char *path, int *exists, int *is_dir, char *err, size_t errsz) {
#if defined(_WIN32)
    struct _stat st;
    int result = 0;
    result = _stat(path, &st);
    if (result != 0) {
        size_t plen = strlen(path);
        if (plen > 0 && (path[plen - 1] == '/' || path[plen - 1] == '\\')) {
            char *trimmed = xstrdup_c(path);
            while (plen > 0 && (trimmed[plen - 1] == '/' || trimmed[plen - 1] == '\\'))
                trimmed[--plen] = '\0';
            if (plen > 0) result = _stat(trimmed, &st);
            free(trimmed);
        }
    }
    if (result == 0) {
        if (exists != NULL) *exists = 1;
        if (is_dir != NULL) *is_dir = ((st.st_mode & _S_IFDIR) != 0);
        return 1;
    }
#else
    struct stat st;
    if (stat(path, &st) == 0) {
        if (exists != NULL) *exists = 1;
        if (is_dir != NULL) *is_dir = S_ISDIR(st.st_mode);
        return 1;
    }
#endif
    if (errno == ENOENT || errno == ENOTDIR) {
        if (exists != NULL) *exists = 0;
        if (is_dir != NULL) *is_dir = 0;
        return 1;
    }
    snprintf(err, errsz, "filesystem probe failed for '%s': %s", path, strerror(errno));
    return 0;
}

static int filesystem_create_directory_single(const char *path, char *err, size_t errsz) {
    if (path == NULL || path[0] == '\0') return 1;
#if defined(_WIN32)
    if (_mkdir(path) == 0) return 1;
#else
    if (mkdir(path, 0777) == 0) return 1;
#endif
    if (errno == EEXIST) {
        int exists = 0;
        int is_dir = 0;
        if (!filesystem_probe_existing_path(path, &exists, &is_dir, err, errsz)) return 0;
        if (exists && is_dir) return 1;
        snprintf(err, errsz, "directory '%s' already exists but is not a directory", path);
        return 0;
    }
    snprintf(err, errsz, "could not create directory '%s': %s", path, strerror(errno));
    return 0;
}

static int filesystem_ensure_directories_exist_text(const char *path, int *created, char *err, size_t errsz) {
    char *mutable_path = NULL;
    size_t len = 0;
    size_t i = 0;
    int made_any = 0;
    if (created != NULL) *created = 0;
    if (path == NULL || path[0] == '\0') return 1;
    mutable_path = xstrdup_c(path);
    len = strlen(mutable_path);
    for (i = 0; i < len; ++i) {
        int exists = 0;
        int is_dir = 0;
        if (!pathname_is_separator((unsigned char)mutable_path[i])) continue;
        if (i == 0) continue;
        if (i > 0 && pathname_is_separator((unsigned char)mutable_path[i - 1])) continue;
#if defined(_WIN32)
        if (i == 2 && isalpha((unsigned char)mutable_path[0]) && mutable_path[1] == ':') {
            continue;
        }
#endif
        mutable_path[i] = '\0';
        if (mutable_path[0] != '\0') {
            if (!filesystem_probe_existing_path(mutable_path, &exists, &is_dir, err, errsz)) {
                mutable_path[i] = path[i];
                free(mutable_path);
                return 0;
            }
            if (!exists) {
                if (!filesystem_create_directory_single(mutable_path, err, errsz)) {
                    mutable_path[i] = path[i];
                    free(mutable_path);
                    return 0;
                }
                made_any = 1;
            } else if (!is_dir) {
                snprintf(err, errsz, "ensure-directories-exist found a non-directory component '%s'", mutable_path);
                mutable_path[i] = path[i];
                free(mutable_path);
                return 0;
            }
        }
        mutable_path[i] = path[i];
    }
    if (created != NULL) *created = made_any;
    free(mutable_path);
    return 1;
}

static char *canonicalize_existing_path(const char *path, int is_dir, char *err, size_t errsz);

static int filesystem_file_write_date_universal(const char *path, int64_t *out, char *err, size_t errsz) {
#if defined(_WIN32)
    struct _stat st;
    if (_stat(path, &st) != 0) {
        snprintf(err, errsz, "cannot stat '%s': %s", path, strerror(errno));
        return 0;
    }
#else
    struct stat st;
    if (stat(path, &st) != 0) {
        snprintf(err, errsz, "cannot stat '%s': %s", path, strerror(errno));
        return 0;
    }
#endif
    if (out != NULL) *out = (int64_t)st.st_mtime + 2208988800LL;
    return 1;
}

static int filesystem_file_author_text(const char *path, char **out, char *err, size_t errsz) {
#if defined(_WIN32)
    PSECURITY_DESCRIPTOR security = NULL;
    PSID owner = NULL;
    DWORD status = ERROR_SUCCESS;
    char name[256];
    char domain[256];
    DWORD name_len = (DWORD)(sizeof(name) / sizeof(name[0]));
    DWORD domain_len = (DWORD)(sizeof(domain) / sizeof(domain[0]));
    SID_NAME_USE use = SidTypeUnknown;
    *out = NULL;
    status = GetNamedSecurityInfoA((LPSTR)path,
                                   SE_FILE_OBJECT,
                                   OWNER_SECURITY_INFORMATION,
                                   &owner,
                                   NULL,
                                   NULL,
                                   NULL,
                                   &security);
    if (status != ERROR_SUCCESS) {
        snprintf(err, errsz, "file-author could not inspect '%s' (win32 %lu)", path, (unsigned long)status);
        return 0;
    }
    if (owner == NULL) {
        if (security != NULL) LocalFree(security);
        return 1;
    }
    if (!LookupAccountSidA(NULL, owner, name, &name_len, domain, &domain_len, &use)) {
        DWORD lookup_status = GetLastError();
        if (security != NULL) LocalFree(security);
        if (lookup_status == ERROR_NONE_MAPPED) return 1;
        snprintf(err, errsz, "file-author could not resolve owner for '%s' (win32 %lu)", path, (unsigned long)lookup_status);
        return 0;
    }
    if (domain[0] != '\0') {
        size_t domain_n = strlen(domain);
        size_t name_n = strlen(name);
        char *combined = (char *)xmalloc(domain_n + 1U + name_n + 1U);
        memcpy(combined, domain, domain_n);
        combined[domain_n] = '\\';
        memcpy(combined + domain_n + 1U, name, name_n + 1U);
        *out = combined;
    } else {
        *out = xstrdup_c(name);
    }
    if (security != NULL) LocalFree(security);
    return 1;
#else
    struct stat st;
    struct passwd *pw = NULL;
    *out = NULL;
    if (stat(path, &st) != 0) {
        snprintf(err, errsz, "cannot stat '%s': %s", path, strerror(errno));
        return 0;
    }
    pw = getpwuid(st.st_uid);
    if (pw == NULL) return 1;
    *out = xstrdup_c(pw->pw_name);
    return 1;
#endif
}

static int pathname_version_is_newest(Value *pathname) {
    return pathname != NULL &&
           pathname->type == VALUE_PATHNAME &&
           pathname->as.pathname.version != NULL &&
           value_is_keyword(pathname->as.pathname.version) &&
           keyword_matches(pathname->as.pathname.version, ":newest");
}

static char *filesystem_unique_backup_path(const char *path, const char *suffix_base, char *err, size_t errsz) {
    int index = 0;
    for (;;) {
        StrBuf buf;
        char *candidate = NULL;
        int exists = 0;
        int is_dir = 0;
        strbuf_init(&buf);
        strbuf_append(&buf, path);
        strbuf_append_char(&buf, '.');
        strbuf_append(&buf, suffix_base);
        if (index > 0) strbuf_appendf(&buf, ".%d", index + 1);
        candidate = strbuf_take(&buf);
        if (!filesystem_probe_existing_path(candidate, &exists, &is_dir, err, errsz)) {
            free(candidate);
            return NULL;
        }
        if (!exists) return candidate;
        free(candidate);
        ++index;
        if (index >= 10000) {
            snprintf(err, errsz, "could not find a backup pathname for '%s'", path);
            return NULL;
        }
    }
}

static int filesystem_prepare_replacement_backup(const char *path,
                                                 int delete_backup,
                                                 char **backup_out,
                                                 char *err,
                                                 size_t errsz) {
    char *backup = NULL;
    *backup_out = NULL;
    backup = filesystem_unique_backup_path(path, "bak", err, errsz);
    if (backup == NULL) return 0;
    if (rename(path, backup) != 0) {
        snprintf(err, errsz, "open could not rename '%s' to '%s': %s", path, backup, strerror(errno));
        free(backup);
        return 0;
    }
    if (delete_backup) {
        if (remove(backup) != 0) {
            int saved_errno = errno;
            rename(backup, path);
            snprintf(err, errsz, "open could not delete renamed backup '%s': %s", backup, strerror(saved_errno));
            free(backup);
            return 0;
        }
        free(backup);
        return 1;
    }
    *backup_out = backup;
    return 1;
}

static void filesystem_restore_replacement_backup(const char *path, char **backup_io) {
    if (backup_io == NULL || *backup_io == NULL) return;
    rename(*backup_io, path);
    free(*backup_io);
    *backup_io = NULL;
}

static int filesystem_namestring_has_wildcards(const char *path) {
    if (path == NULL) return 0;
    while (*path != '\0') {
        if (*path == '*' || *path == '?') return 1;
        ++path;
    }
    return 0;
}

static int pathname_namestring_ends_with_separator(const char *path) {
    size_t len;
    if (path == NULL) return 0;
    len = strlen(path);
    return len > 0U && pathname_is_separator((unsigned char)path[len - 1U]);
}

static char *filesystem_join_directory_entry(const char *dir, const char *entry) {
    StrBuf buf;
    size_t len = (dir != NULL) ? strlen(dir) : 0U;
    char sep = '/';
#if defined(_WIN32)
    sep = '\\';
#endif
    strbuf_init(&buf);
    if (dir != NULL && dir[0] != '\0') strbuf_append(&buf, dir);
    if (buf.len > 0 && !pathname_is_separator((unsigned char)buf.data[buf.len - 1])) strbuf_append_char(&buf, sep);
    if (entry != NULL) strbuf_append(&buf, entry);
    else if (len == 2U && dir[1] == ':') strbuf_append_char(&buf, sep);
    return strbuf_take(&buf);
}

static int pathname_search_base_directory(Value *pathname,
                                          char **base_dir_out,
                                          int *directory_has_wildcards_out,
                                          char *err,
                                          size_t errsz) {
    int absolute = 0;
    char **segments = NULL;
    char **prefix = NULL;
    int count = 0;
    int prefix_count = 0;
    int i;
    Value *prefix_dir = NULL;
    char *base_dir = NULL;
    *base_dir_out = NULL;
    *directory_has_wildcards_out = 0;
    if (!pathname_directory_to_parts(pathname->as.pathname.directory, "directory", &absolute, &segments, &count, err, errsz)) {
        pathname_directory_free_parts(segments, count);
        return 0;
    }
    for (i = 0; i < count; ++i) {
        if (pathname_text_has_wildcards(segments[i])) {
            *directory_has_wildcards_out = 1;
            break;
        }
        ++prefix_count;
    }
    if (prefix_count > 0) {
        prefix = (char **)xmalloc((size_t)prefix_count * sizeof(char *));
        for (i = 0; i < prefix_count; ++i) prefix[i] = xstrdup_c(segments[i]);
    }
    prefix_dir = pathname_directory_from_parts(absolute, prefix, prefix_count);
    pathname_directory_free_parts(prefix, prefix_count);
    pathname_directory_free_parts(segments, count);
    if (!pathname_build_namestring(pathname->as.pathname.host,
                                   pathname->as.pathname.device,
                                   prefix_dir,
                                   NULL,
                                   NULL,
                                   "directory",
                                   &base_dir,
                                   err,
                                   errsz)) {
        return 0;
    }
    if (base_dir[0] == '\0') {
        free(base_dir);
        base_dir = xstrdup_c(".");
    }
    *base_dir_out = base_dir;
    return 1;
}

static int directory_push_if_matching(const char *path,
                                      int is_dir,
                                      Value *wildcard,
                                      int dirs_only,
                                      ValueArray *matches,
                                      char *err,
                                      size_t errsz) {
    char *resolved = NULL;
    Value *candidate = NULL;
    if (dirs_only && !is_dir) return 1;
    resolved = canonicalize_existing_path(path, is_dir, err, errsz);
    if (resolved == NULL) return 0;
    candidate = make_pathname_value(resolved);
    free(resolved);
    if (!pathname_matches_wildcard_pathname(candidate, wildcard)) return 1;
    value_array_push(matches, candidate);
    return 1;
}

static int filesystem_collect_directory_wildcards(const char *dir,
                                                  Value *wildcard,
                                                  int recursive,
                                                  int dirs_only,
                                                  ValueArray *matches,
                                                  char *err,
                                                  size_t errsz) {
#if defined(_WIN32)
    struct _finddata_t info;
    intptr_t handle = -1;
    char *search = NULL;
    search = filesystem_join_directory_entry((dir != NULL && dir[0] != '\0') ? dir : ".", "*");
    handle = _findfirst(search, &info);
    free(search);
    if (handle == -1) {
        if (errno == ENOENT || errno == ENOTDIR) return 1;
        snprintf(err, errsz, "directory could not search '%s': %s", (dir != NULL && dir[0] != '\0') ? dir : ".", strerror(errno));
        return 0;
    }
    do {
        char *full_path = NULL;
        int exists = 0;
        int is_dir = 0;
        if (strcmp(info.name, ".") == 0 || strcmp(info.name, "..") == 0) continue;
        full_path = filesystem_join_directory_entry(dir, info.name);
        if (!filesystem_probe_existing_path(full_path, &exists, &is_dir, err, errsz)) {
            free(full_path);
            _findclose(handle);
            return 0;
        }
        if (exists) {
            if (!directory_push_if_matching(full_path, is_dir, wildcard, dirs_only, matches, err, errsz)) {
                free(full_path);
                _findclose(handle);
                return 0;
            }
            if (recursive && is_dir &&
                !filesystem_collect_directory_wildcards(full_path, wildcard, recursive, dirs_only, matches, err, errsz)) {
                free(full_path);
                _findclose(handle);
                return 0;
            }
        }
        free(full_path);
    } while (_findnext(handle, &info) == 0);
    _findclose(handle);
    return 1;
#else
    DIR *dp = NULL;
    struct dirent *entry = NULL;
    const char *base_dir = (dir != NULL && dir[0] != '\0') ? dir : ".";
    dp = opendir(base_dir);
    if (dp == NULL) {
        if (errno == ENOENT || errno == ENOTDIR) return 1;
        snprintf(err, errsz, "directory could not open '%s': %s", base_dir, strerror(errno));
        return 0;
    }
    while ((entry = readdir(dp)) != NULL) {
        char *full_path = NULL;
        int exists = 0;
        int is_dir = 0;
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) continue;
        full_path = filesystem_join_directory_entry(dir, entry->d_name);
        if (!filesystem_probe_existing_path(full_path, &exists, &is_dir, err, errsz)) {
            free(full_path);
            closedir(dp);
            return 0;
        }
        if (exists) {
            if (!directory_push_if_matching(full_path, is_dir, wildcard, dirs_only, matches, err, errsz)) {
                free(full_path);
                closedir(dp);
                return 0;
            }
            if (recursive && is_dir &&
                !filesystem_collect_directory_wildcards(full_path, wildcard, recursive, dirs_only, matches, err, errsz)) {
                free(full_path);
                closedir(dp);
                return 0;
            }
        }
        free(full_path);
    }
    closedir(dp);
    return 1;
#endif
}

static int filesystem_directory_matches(const char *dir,
                                        const char *pattern,
                                        ValueArray *matches,
                                        char *err,
                                        size_t errsz) {
#if defined(_WIN32)
    struct _finddata_t info;
    intptr_t handle = -1;
    char *search = NULL;
    search = filesystem_join_directory_entry((dir != NULL && dir[0] != '\0') ? dir : ".", pattern);
    handle = _findfirst(search, &info);
    free(search);
    if (handle == -1) {
        if (errno == ENOENT) return 1;
        snprintf(err, errsz, "directory could not search '%s': %s", (dir != NULL) ? dir : ".", strerror(errno));
        return 0;
    }
    do {
        char *full_path = NULL;
        char *resolved = NULL;
        int exists = 0;
        int is_dir = 0;
        if (strcmp(info.name, ".") == 0 || strcmp(info.name, "..") == 0) continue;
        full_path = filesystem_join_directory_entry(dir, info.name);
        if (!filesystem_probe_existing_path(full_path, &exists, &is_dir, err, errsz)) {
            free(full_path);
            _findclose(handle);
            return 0;
        }
        if (!exists) {
            free(full_path);
            continue;
        }
        resolved = canonicalize_existing_path(full_path, is_dir, err, errsz);
        free(full_path);
        if (resolved == NULL) {
            _findclose(handle);
            return 0;
        }
        value_array_push(matches, make_pathname_value(resolved));
        free(resolved);
    } while (_findnext(handle, &info) == 0);
    _findclose(handle);
    return 1;
#else
    DIR *dp = NULL;
    struct dirent *entry = NULL;
    const char *base_dir = (dir != NULL && dir[0] != '\0') ? dir : ".";
    dp = opendir(base_dir);
    if (dp == NULL) {
        if (errno == ENOENT || errno == ENOTDIR) return 1;
        snprintf(err, errsz, "directory could not open '%s': %s", base_dir, strerror(errno));
        return 0;
    }
    while ((entry = readdir(dp)) != NULL) {
        char *full_path = NULL;
        char *resolved = NULL;
        int exists = 0;
        int is_dir = 0;
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) continue;
        if (fnmatch(pattern, entry->d_name, 0) != 0) continue;
        full_path = filesystem_join_directory_entry(dir, entry->d_name);
        if (!filesystem_probe_existing_path(full_path, &exists, &is_dir, err, errsz)) {
            free(full_path);
            closedir(dp);
            return 0;
        }
        if (!exists) {
            free(full_path);
            continue;
        }
        resolved = canonicalize_existing_path(full_path, is_dir, err, errsz);
        free(full_path);
        if (resolved == NULL) {
            closedir(dp);
            return 0;
        }
        value_array_push(matches, make_pathname_value(resolved));
        free(resolved);
    }
    closedir(dp);
    return 1;
#endif
}

static char *path_with_directory_hint(const char *path, int is_dir) {
    StrBuf buf;
    size_t len = strlen(path);
    char sep = '/';
#if defined(_WIN32)
    sep = '\\';
#endif
    if (!is_dir || len <= 0U || pathname_is_separator((unsigned char)path[len - 1U])) return xstrdup_c(path);
    strbuf_init(&buf);
    strbuf_append(&buf, path);
    strbuf_append_char(&buf, sep);
    return strbuf_take(&buf);
}

static char *canonicalize_existing_path(const char *path, int is_dir, char *err, size_t errsz) {
    (void)err; (void)errsz;
#if defined(_WIN32)
    char *resolved = _fullpath(NULL, path, 0);
    if (resolved == NULL) {
        snprintf(err, errsz, "cannot resolve '%s': %s", path, strerror(errno));
        return NULL;
    }
    {
        char *hinted = path_with_directory_hint(resolved, is_dir);
        free(resolved);
        return hinted;
    }
#else
    return path_with_directory_hint(path, is_dir);
#endif
}

static int builtin_merge_pathnames(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    Value *pathname = NULL;
    Value *defaults = NULL;
    Value *version = NULL;
    if (args->count < 1 || args->count > 3) {
        snprintf(err, errsz, "merge-pathnames expects one pathname designator and optional defaults");
        return 0;
    }
    if (!pathname_designator_value(args->items[0], "merge-pathnames", &pathname, err, errsz)) return 0;
    defaults = (args->count >= 2) ? NULL : default_pathname_defaults_value(it, env);
    if (args->count >= 2 && !pathname_designator_value(args->items[1], "merge-pathnames", &defaults, err, errsz)) return 0;
    if (args->count >= 3) version = args->items[2];
    return merge_pathnames_values(it, pathname, defaults, version, "merge-pathnames", out, err, errsz);
}

static int builtin_probe_file(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    Value *pathname = NULL;
    Value *filesystem_pathname = NULL;
    char *resolved_text = NULL;
    int exists = 0;
    int is_dir = 0;
    if (args->count != 1) {
        snprintf(err, errsz, "probe-file expects exactly one pathname designator");
        return 0;
    }
    if (!merged_pathname_designator_value(it, env, args->items[0], "probe-file", &pathname, err, errsz)) return 0;
    if (!pathname_translate_logical(it, pathname, "probe-file", &filesystem_pathname, err, errsz)) return 0;
    if (!filesystem_probe_existing_path(filesystem_pathname->as.pathname.namestring, &exists, &is_dir, err, errsz)) return 0;
    if (!exists) {
        *out = it->nil;
        return 1;
    }
    resolved_text = canonicalize_existing_path(filesystem_pathname->as.pathname.namestring, is_dir, err, errsz);
    if (resolved_text == NULL) return 0;
    *out = make_pathname_value(resolved_text);
    free(resolved_text);
    return 1;
}

