static int builtin_file_author(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    Value *pathname = NULL;
    char *author = NULL;
    int exists = 0;
    int is_dir = 0;
    int wildp = 0;
    if (args->count != 1) {
        snprintf(err, errsz, "file-author expects exactly one pathname designator");
        return 0;
    }
    if (!merged_pathname_designator_value(it, env, args->items[0], "file-author", &pathname, err, errsz)) return 0;
    if (!pathname_field_has_wildcards(pathname, NULL, &wildp, err, errsz)) return 0;
    if (wildp) {
        snprintf(err, errsz, "file-author does not accept wild pathname '%s'", pathname->as.pathname.namestring);
        return 0;
    }
    if (!filesystem_probe_existing_path(pathname->as.pathname.namestring, &exists, &is_dir, err, errsz)) return 0;
    if (!exists) {
        snprintf(err, errsz, "file-author could not find '%s'", pathname->as.pathname.namestring);
        return 0;
    }
    if (!filesystem_file_author_text(pathname->as.pathname.namestring, &author, err, errsz)) return 0;
    if (author == NULL) {
        *out = it->nil;
        return 1;
    }
    *out = make_string_value(author);
    free(author);
    return 1;
}

static int builtin_directory(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    Value *pathname = NULL;
    ValueArray matches;
    char *dir_text = NULL;
    char *file_text = NULL;
    char *base_dir = NULL;
    char *resolved = NULL;
    const char *path = NULL;
    int exists = 0;
    int is_dir = 0;
    int has_wildcards = 0;
    int directory_has_wildcards = 0;
    int dirs_only = 0;
    if (args->count != 1) {
        snprintf(err, errsz, "directory expects exactly one pathname designator");
        return 0;
    }
    if (!merged_pathname_designator_value(it, env, args->items[0], "directory", &pathname, err, errsz)) return 0;
    path = pathname->as.pathname.namestring;
    has_wildcards = filesystem_namestring_has_wildcards(path);
    dirs_only = pathname_namestring_ends_with_separator(path);
    value_array_init(&matches);
    if (!has_wildcards) {
        if (!filesystem_probe_existing_path(path, &exists, &is_dir, err, errsz)) return 0;
        if (!exists) {
            *out = it->nil;
            return 1;
        }
        if (!is_dir) {
            resolved = canonicalize_existing_path(path, 0, err, errsz);
            if (resolved == NULL) return 0;
            value_array_push(&matches, make_pathname_value(resolved));
            free(resolved);
            *out = make_list_value(&matches);
            return 1;
        }
        if (!filesystem_directory_matches(path, "*", &matches, err, errsz)) return 0;
        *out = (matches.count > 0) ? make_list_value(&matches) : it->nil;
        return 1;
    }
    if (!pathname_search_base_directory(pathname, &base_dir, &directory_has_wildcards, err, errsz)) return 0;
    if (!filesystem_probe_existing_path(base_dir, &exists, &is_dir, err, errsz)) {
        free(base_dir);
        return 0;
    }
    if (!exists || !is_dir) {
        free(base_dir);
        *out = it->nil;
        return 1;
    }
    if (directory_has_wildcards) {
        if (!directory_push_if_matching(base_dir, 1, pathname, dirs_only, &matches, err, errsz) ||
            !filesystem_collect_directory_wildcards(base_dir, pathname, 1, dirs_only, &matches, err, errsz)) {
            free(base_dir);
            return 0;
        }
        free(base_dir);
        *out = (matches.count > 0) ? make_list_value(&matches) : it->nil;
        return 1;
    }
    free(base_dir);
    dir_text = pathname_directory_namestring_text(path);
    file_text = pathname_file_namestring_text(path);
    if (file_text[0] == '\0') {
        free(file_text);
        file_text = xstrdup_c("*");
    }
    {
        size_t dlen = strlen(dir_text);
        while (dlen > 0 && (dir_text[dlen - 1] == '/' || dir_text[dlen - 1] == '\\'))
            dir_text[--dlen] = '\0';
    }
    if (!filesystem_probe_existing_path((dir_text[0] != '\0') ? dir_text : ".", &exists, &is_dir, err, errsz)) {
        free(dir_text);
        free(file_text);
        return 0;
    }
    if (!exists || !is_dir) {
        free(dir_text);
        free(file_text);
        *out = it->nil;
        return 1;
    }
    if (!filesystem_directory_matches(dir_text, file_text, &matches, err, errsz)) {
        free(dir_text);
        free(file_text);
        return 0;
    }
    free(dir_text);
    free(file_text);
    *out = (matches.count > 0) ? make_list_value(&matches) : it->nil;
    return 1;
}

static int builtin_ensure_directories_exist(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    Value *pathname = NULL;
    ValueArray values;
    char *dir_text = NULL;
    int created = 0;
    int verbose = 0;
    int wildp = 0;
    int i;
    (void)env;
    if (args->count < 1) {
        snprintf(err, errsz, "ensure-directories-exist expects a pathname designator");
        return 0;
    }
    if (((args->count - 1) % 2) != 0) {
        snprintf(err, errsz, "ensure-directories-exist keyword arguments must appear in keyword/value pairs");
        return 0;
    }
    for (i = 1; i < args->count; i += 2) {
        Value *key = args->items[i];
        Value *value = args->items[i + 1];
        if (!value_is_keyword(key)) {
            snprintf(err, errsz, "ensure-directories-exist expects keyword arguments");
            return 0;
        }
        if (keyword_matches(key, ":verbose")) {
            verbose = value_is_truthy(value) ? 1 : 0;
        } else {
            snprintf(err, errsz, "ensure-directories-exist does not support the %s keyword", key->as.str);
            return 0;
        }
    }
    if (!merged_pathname_designator_value(it, env, args->items[0], "ensure-directories-exist", &pathname, err, errsz)) return 0;
    if (!pathname_field_has_wildcards(pathname, NULL, &wildp, err, errsz)) return 0;
    if (wildp) {
        snprintf(err, errsz, "ensure-directories-exist does not accept wild pathname '%s'", pathname->as.pathname.namestring);
        return 0;
    }
    dir_text = pathname_directory_namestring_text(pathname->as.pathname.namestring);
    if (dir_text[0] != '\0') {
        if (!filesystem_ensure_directories_exist_text(dir_text, &created, err, errsz)) {
            free(dir_text);
            return 0;
        }
    }
    (void)verbose;
    value_array_init(&values);
    value_array_push(&values, pathname);
    value_array_push(&values, created ? it->true_value : it->nil);
    interp_set_values(it, &values);
    free(dir_text);
    *out = pathname;
    return 1;
}

static int builtin_open(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    Value *pathname = NULL;
    Value *direction = NULL;
    Value *element_type = NULL;
    Value *if_exists = NULL;
    Value *if_does_not_exist = NULL;
    Value *external_format = NULL;
    FILE *fp = NULL;
    const char *mode = NULL;
    const char *path = NULL;
    const char *if_exists_name = NULL;
    int direction_flags = FILE_STREAM_DIRECTION_INPUT;
    int probe_only = 0;
    int element_type_kind = STRING_STREAM_ELEMENT_CHARACTER;
    int exists = 0;
    int is_dir = 0;
    int if_exists_nil = 0;
    int needs_backup_restore = 0;
    int wildp = 0;
    int i;
    char *backup_path = NULL;
    Value *filesystem_pathname = NULL;
    if (args->count < 1) {
        snprintf(err, errsz, "open expects a pathname designator");
        return 0;
    }
    if (((args->count - 1) % 2) != 0) {
        snprintf(err, errsz, "open keyword arguments must appear in keyword/value pairs");
        return 0;
    }
    for (i = 1; i < args->count; i += 2) {
        Value *key = args->items[i];
        Value *value = args->items[i + 1];
        if (!value_is_keyword(key)) {
            snprintf(err, errsz, "expected a keyword argument, got %s", value_type_name(key));
            return 0;
        }
        if (keyword_matches(key, ":direction")) {
            direction = value;
        } else if (keyword_matches(key, ":element-type")) {
            element_type = value;
        } else if (keyword_matches(key, ":if-exists")) {
            if_exists = value;
        } else if (keyword_matches(key, ":if-does-not-exist")) {
            if_does_not_exist = value;
        } else if (keyword_matches(key, ":external-format")) {
            external_format = value;
        } else {
            snprintf(err, errsz, "unsupported open keyword '%s'", key->as.str);
            return 0;
        }
    }
    if (direction != NULL) {
        if (!value_is_keyword(direction)) {
            snprintf(err, errsz, "open :direction expects a keyword");
            return 0;
        }
        if (keyword_matches(direction, ":input")) {
            direction_flags = FILE_STREAM_DIRECTION_INPUT;
        } else if (keyword_matches(direction, ":output")) {
            direction_flags = FILE_STREAM_DIRECTION_OUTPUT;
        } else if (keyword_matches(direction, ":io")) {
            direction_flags = FILE_STREAM_DIRECTION_INPUT | FILE_STREAM_DIRECTION_OUTPUT;
        } else if (keyword_matches(direction, ":probe")) {
            direction_flags = 0;
            probe_only = 1;
        } else {
            snprintf(err, errsz, "unsupported open :direction '%s'", direction->as.str);
            return 0;
        }
    }
    if (element_type != NULL && !validate_file_stream_element_type(element_type, "open", err, errsz)) return 0;
    if (element_type != NULL) element_type_kind = file_stream_element_type_kind(element_type);
    if (external_format != NULL) {
        /* Accepted for compatibility; encoding selection is still a no-op. */
    }
    if (!merged_pathname_designator_value(it, env, args->items[0], "open", &pathname, err, errsz)) return 0;
    if (!pathname_field_has_wildcards(pathname, NULL, &wildp, err, errsz)) return 0;
    if (!pathname_translate_logical(it, pathname, "open", &filesystem_pathname, err, errsz)) return 0;
    path = filesystem_pathname->as.pathname.namestring;
    if (wildp) {
        snprintf(err, errsz, "open does not accept wild pathname '%s'", path);
        return 0;
    }
    if (if_exists != NULL) {
        if (if_exists->type == VALUE_NIL) {
            if_exists_nil = 1;
        } else if (value_is_keyword(if_exists)) {
            if_exists_name = if_exists->as.str;
        }
    } else if (pathname_version_is_newest(pathname) &&
               (direction_flags & FILE_STREAM_DIRECTION_OUTPUT) != 0) {
        if_exists_name = ":new-version";
    }
    if (!filesystem_probe_existing_path(path, &exists, &is_dir, err, errsz)) return 0;
    if (exists && is_dir) {
        snprintf(err, errsz, "open cannot open directory '%s' as a file stream", path);
        return 0;
    }
    if (probe_only) {
        if (!exists) {
            if (if_does_not_exist == NULL || if_does_not_exist->type == VALUE_NIL) {
                *out = it->nil;
                return 1;
            }
            if (!value_is_keyword(if_does_not_exist)) {
                snprintf(err, errsz, "unsupported open :if-does-not-exist value");
                return 0;
            }
            if (keyword_matches(if_does_not_exist, ":error")) {
                snprintf(err, errsz, "open could not find '%s'", path);
                return 0;
            }
            if (!keyword_matches(if_does_not_exist, ":create")) {
                snprintf(err, errsz, "unsupported open :if-does-not-exist value");
                return 0;
            }
            fp = fopen(path, "w+b");
            if (fp == NULL) {
                snprintf(err, errsz, "open could not create '%s': %s", path, strerror(errno));
                return 0;
            }
            fclose(fp);
        }
        *out = make_probe_file_stream_value(path, element_type_kind);
        return 1;
    }
    if (direction_flags == FILE_STREAM_DIRECTION_INPUT) {
        if (!exists) {
            if (if_does_not_exist == NULL || keyword_matches(if_does_not_exist, ":error")) {
                snprintf(err, errsz, "open could not find '%s'", path);
                return 0;
            }
            if (if_does_not_exist->type == VALUE_NIL) {
                *out = it->nil;
                return 1;
            }
            if (!keyword_matches(if_does_not_exist, ":create")) {
                snprintf(err, errsz, "unsupported open :if-does-not-exist value");
                return 0;
            }
            mode = "w+b";
        } else {
            mode = "rb";
        }
    } else if (direction_flags == FILE_STREAM_DIRECTION_OUTPUT) {
        if (!exists) {
            if (if_does_not_exist == NULL) {
                if (if_exists_name != NULL &&
                    (str_ieq(if_exists_name, ":overwrite") || str_ieq(if_exists_name, ":append"))) {
                    snprintf(err, errsz, "open could not find '%s'", path);
                    return 0;
                }
                mode = "w+b";
            } else if (keyword_matches(if_does_not_exist, ":create")) {
                mode = "w+b";
            } else if (if_does_not_exist->type == VALUE_NIL) {
                *out = it->nil;
                return 1;
            } else if (keyword_matches(if_does_not_exist, ":error")) {
                snprintf(err, errsz, "open could not create '%s'", path);
                return 0;
            } else {
                snprintf(err, errsz, "unsupported open :if-does-not-exist value");
                return 0;
            }
        } else {
            if ((if_exists == NULL && if_exists_name == NULL) ||
                (if_exists_name != NULL && str_ieq(if_exists_name, ":error"))) {
                snprintf(err, errsz, "open would overwrite existing file '%s'", path);
                return 0;
            }
            if (if_exists_nil) {
                *out = it->nil;
                return 1;
            }
            if (if_exists_name == NULL) {
                snprintf(err, errsz, "open :if-exists expects a keyword or nil");
                return 0;
            }
            if (str_ieq(if_exists_name, ":supersede")) {
                mode = "w+b";
            } else if (str_ieq(if_exists_name, ":append")) {
                mode = "a+b";
            } else if (str_ieq(if_exists_name, ":overwrite")) {
                mode = "r+b";
            } else if (str_ieq(if_exists_name, ":new-version") || str_ieq(if_exists_name, ":rename")) {
                if (!filesystem_prepare_replacement_backup(path, 0, &backup_path, err, errsz)) return 0;
                needs_backup_restore = 1;
                mode = "w+b";
            } else if (str_ieq(if_exists_name, ":rename-and-delete")) {
                if (!filesystem_prepare_replacement_backup(path, 1, &backup_path, err, errsz)) return 0;
                mode = "w+b";
            } else {
                snprintf(err, errsz, "unsupported open :if-exists value '%s'", if_exists_name);
                return 0;
            }
        }
    } else {
        if (!exists) {
            if (if_does_not_exist == NULL) {
                if (if_exists_name != NULL &&
                    (str_ieq(if_exists_name, ":overwrite") || str_ieq(if_exists_name, ":append"))) {
                    snprintf(err, errsz, "open could not find '%s'", path);
                    return 0;
                }
                mode = "w+b";
            } else if (keyword_matches(if_does_not_exist, ":create")) {
                mode = "w+b";
            } else if (if_does_not_exist->type == VALUE_NIL) {
                *out = it->nil;
                return 1;
            } else if (keyword_matches(if_does_not_exist, ":error")) {
                snprintf(err, errsz, "open could not create '%s'", path);
                return 0;
            } else {
                snprintf(err, errsz, "unsupported open :if-does-not-exist value");
                return 0;
            }
        } else {
            if (if_exists_nil) {
                *out = it->nil;
                return 1;
            }
            if (if_exists != NULL && if_exists_name == NULL) {
                snprintf(err, errsz, "open :if-exists expects a keyword or nil");
                return 0;
            }
            if ((if_exists == NULL && if_exists_name == NULL) ||
                (if_exists_name != NULL && str_ieq(if_exists_name, ":error"))) {
                snprintf(err, errsz, "open would overwrite existing file '%s'", path);
                return 0;
            }
            if (str_ieq(if_exists_name, ":overwrite")) {
                mode = "r+b";
            } else if (str_ieq(if_exists_name, ":append")) {
                mode = "a+b";
            } else if (str_ieq(if_exists_name, ":supersede")) {
                mode = "w+b";
            } else if (str_ieq(if_exists_name, ":new-version") || str_ieq(if_exists_name, ":rename")) {
                if (!filesystem_prepare_replacement_backup(path, 0, &backup_path, err, errsz)) return 0;
                needs_backup_restore = 1;
                mode = "w+b";
            } else if (str_ieq(if_exists_name, ":rename-and-delete")) {
                if (!filesystem_prepare_replacement_backup(path, 1, &backup_path, err, errsz)) return 0;
                mode = "w+b";
            } else {
                snprintf(err, errsz, "unsupported open :if-exists value '%s'", if_exists_name);
                return 0;
            }
        }
    }
    fp = fopen(path, mode);
    if (fp == NULL) {
        if (needs_backup_restore) filesystem_restore_replacement_backup(path, &backup_path);
        snprintf(err, errsz, "open could not access '%s': %s", path, strerror(errno));
        return 0;
    }
    if ((direction_flags & FILE_STREAM_DIRECTION_OUTPUT) != 0 &&
        if_exists_name != NULL &&
        str_ieq(if_exists_name, ":append") &&
        fseek(fp, 0L, SEEK_END) != 0) {
        fclose(fp);
        if (needs_backup_restore) filesystem_restore_replacement_backup(path, &backup_path);
        snprintf(err, errsz, "open could not seek '%s': %s", path, strerror(errno));
        return 0;
    }
    *out = make_file_stream_value(fp, path, direction_flags, element_type_kind);
    (*out)->as.file_stream.append_mode =
        ((direction_flags & FILE_STREAM_DIRECTION_OUTPUT) != 0 &&
         if_exists_name != NULL &&
         str_ieq(if_exists_name, ":append")) ? 1 : 0;
    if ((direction_flags & FILE_STREAM_DIRECTION_OUTPUT) != 0 &&
        !file_stream_update_at_line_start(*out, err, errsz)) {
        fclose(fp);
        (*out)->as.file_stream.handle = NULL;
        (*out)->as.file_stream.closed = 1;
        if (needs_backup_restore) filesystem_restore_replacement_backup(path, &backup_path);
        return 0;
    }
    free(backup_path);
    return 1;
}

static void compile_file_options_init(CompileFileOptions *opts) {
    opts->output_file = NULL;
    opts->have_verbose = 0;
    opts->verbose = 0;
    opts->have_print = 0;
    opts->print = 0;
}

static void compile_file_options_dispose(CompileFileOptions *opts) {
    free(opts->output_file);
    opts->output_file = NULL;
}

static int parse_compile_file_options(const ValueArray *args, int start_index, const char *who, CompileFileOptions *opts, char *err, size_t errsz) {
    int i;
    compile_file_options_init(opts);
    if (((args->count - start_index) % 2) != 0) {
        snprintf(err, errsz, "%s keyword arguments must appear in keyword/value pairs", who);
        return 0;
    }
    for (i = start_index; i < args->count; i += 2) {
        Value *key = args->items[i];
        Value *value = args->items[i + 1];
        if (!value_is_keyword(key)) {
            snprintf(err, errsz, "expected a keyword argument, got %s", value_type_name(key));
            return 0;
        }
        if (keyword_matches(key, ":output-file")) {
            char *output_file = NULL;
            if (!value_to_pathname_designator_text(value, who, &output_file, err, errsz)) return 0;
            free(opts->output_file);
            opts->output_file = output_file;
        } else if (keyword_matches(key, ":verbose")) {
            opts->have_verbose = 1;
            opts->verbose = value_is_truthy(value);
        } else if (keyword_matches(key, ":print")) {
            opts->have_print = 1;
            opts->print = value_is_truthy(value);
        } else if (keyword_matches(key, ":external-format")) {
            continue;
        } else {
            snprintf(err, errsz, "unsupported %s keyword '%s'", who, key->as.str);
            return 0;
        }
    }
    return 1;
}

static char *compile_file_output_path(const char *input_path, const char *output_file) {
    if (output_file != NULL) return xstrdup_c(output_file);
    return replace_ext(input_path, ".fasl");
}

static int runtime_special_truthy(Interp *it, Env *env, const char *name) {
    Value *value = NULL;
    int is_bound = 0;
    if (symbol_value_lookup_runtime_special(it, env, name, &value, &is_bound) && is_bound) {
        return value_is_truthy(value);
    }
    return 0;
}

static int compile_file_should_process_top_level(Interp *it, Value *form) {
    ValueArray items;
    if (!proper_form_to_array(form, &items) || items.count <= 0) return 0;
    return symbol_matches_common_lisp_named_syntax(it, items.items[0], "eval-when") ||
           symbol_matches_common_lisp_named_syntax(it, items.items[0], "defpackage") ||
           symbol_matches_common_lisp_named_syntax(it, items.items[0], "in-package") ||
           symbol_matches_common_lisp_named_syntax(it, items.items[0], "with-compilation-unit") ||
           symbol_matches_common_lisp_named_syntax(it, items.items[0], "declaim") ||
           symbol_matches_common_lisp_named_syntax(it, items.items[0], "proclaim") ||
           symbol_matches_common_lisp_named_syntax(it, items.items[0], "defvar") ||
           symbol_matches_common_lisp_named_syntax(it, items.items[0], "defparameter") ||
           symbol_matches_common_lisp_named_syntax(it, items.items[0], "defconstant") ||
           symbol_matches_common_lisp_named_syntax(it, items.items[0], "defmacro") ||
           symbol_matches_common_lisp_named_syntax(it, items.items[0], "define-compiler-macro") ||
           symbol_matches_common_lisp_named_syntax(it, items.items[0], "define-modify-macro") ||
           symbol_matches_common_lisp_named_syntax(it, items.items[0], "define-symbol-macro") ||
           symbol_matches_common_lisp_named_syntax(it, items.items[0], "deftype") ||
           symbol_matches_common_lisp_named_syntax(it, items.items[0], "defstruct") ||
           symbol_matches_common_lisp_named_syntax(it, items.items[0], "defsetf") ||
           symbol_matches_common_lisp_named_syntax(it, items.items[0], "define-setf-expander");
}

static int compile_file_transform_text(Interp *it,
                                       Env *env,
                                       const char *path,
                                       const char *text,
                                       Value **out,
                                       char *err,
                                       size_t errsz) {
    Parser p;
    Value *ignored = it->nil;
    Value *form = NULL;
    Value *next = NULL;
    ValueArray transformed;
    int eof = 0;
    parser_init_text(&p, env, path, text);
    value_array_init(&transformed);
    for (;;) {
        if (!parse_next_top_level_form(it, &p, &form, &eof, err, errsz)) return 0;
        if (eof) break;
        if (compile_file_should_process_top_level(it, form) &&
            !eval_with_next_context(it, env, form, EVAL_WHEN_COMPILE_TOPLEVEL, &ignored, err, errsz)) {
            return 0;
        }
        if (!compiler_macroexpand_expr(it, env, form, &next, err, errsz)) return 0;
        value_array_push(&transformed, next);
    }
    *out = make_list_value(&transformed);
    return 1;
}

static char *render_program_readably(Interp *it, Value *program) {
    StrBuf buf;
    ValueArray items;
    int i;
    Value *saved_package = NULL;
    Value *saved_print_package = NULL;
    strbuf_init(&buf);
    if (program->type == VALUE_LIST) {
        value_array_copy(&items, &program->as.array);
    } else {
        value_array_init(&items);
        value_array_push(&items, program);
    }
    saved_package = it->current_package;
    saved_print_package = it->print_package;
    it->print_package = it->keyword_package;
    for (i = 0; i < items.count; ++i) {
        Value *form = items.items[i];
        value_repr(it, items.items[i], &buf);
        strbuf_append_char(&buf, '\n');
        if (form != NULL &&
            value_is_list_like(form) &&
            form->type == VALUE_LIST &&
            form->as.array.count == 2 &&
            symbol_matches_common_lisp_named_syntax(it, form->as.array.items[0], "in-package")) {
            Value *next_package = NULL;
            char tmp_err[256];
            if (resolve_package_designator(it,
                                           NULL,
                                           form->as.array.items[1],
                                           "render-program-readably",
                                           &next_package,
                                           tmp_err,
                                           sizeof(tmp_err))) {
                it->current_package = next_package;
            }
        }
    }
    it->current_package = saved_package;
    it->print_package = saved_print_package;
    value_array_dispose(&items);
    return strbuf_take(&buf);
}

static int builtin_compile_file_pathname(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    CompileFileOptions opts;
    char *input_path = NULL;
    char *path = NULL;
    (void)it;
    (void)env;
    compile_file_options_init(&opts);
    if (args->count < 1) {
        snprintf(err, errsz, "compile-file-pathname expects a pathname designator and optional keyword arguments");
        return 0;
    }
    if (!value_to_pathname_designator_text(args->items[0], "compile-file-pathname", &input_path, err, errsz)) return 0;
    if (!parse_compile_file_options(args, 1, "compile-file-pathname", &opts, err, errsz)) {
        free(input_path);
        compile_file_options_dispose(&opts);
        return 0;
    }
    path = compile_file_output_path(input_path, opts.output_file);
    *out = make_pathname_value(path);
    free(input_path);
    free(path);
    compile_file_options_dispose(&opts);
    return 1;
}

static int builtin_compile_file(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    CompileFileOptions opts;
    Env *compile_env = NULL;
    Value *compiled_program = NULL;
    Value *saved_package = it->current_package;
    Value *compile_file_pathname_symbol = common_lisp_runtime_symbol_or_fallback(it, "*compile-file-pathname*");
    Value *compile_file_truename_symbol = common_lisp_runtime_symbol_or_fallback(it, "*compile-file-truename*");
    Value *compile_verbose_symbol = common_lisp_runtime_symbol_or_fallback(it, "*compile-verbose*");
    Value *compile_print_symbol = common_lisp_runtime_symbol_or_fallback(it, "*compile-print*");
    Value *compile_file_pathname_value = NULL;
    Value *compile_file_truename_value = it->nil;
    DynamicFrame frame;
    ValueArray values;
    char *input_path = NULL;
    char *text = NULL;
    char *compiled_text = NULL;
    char *output_path = NULL;
    char *truename_text = NULL;
    char path_err[256];
    CompilationUnitFrame unit_frame;
    uint64_t warning_count_before = 0;
    int compile_had_warning = 0;
    int effective_verbose = 0;
    int effective_print = 0;
    int exists = 0;
    int is_dir = 0;
    compile_file_options_init(&opts);
    if (args->count < 1) {
        snprintf(err, errsz, "compile-file expects a pathname designator and optional keyword arguments");
        return 0;
    }
    if (!value_to_pathname_designator_text(args->items[0], "compile-file", &input_path, err, errsz)) return 0;
    if (!merged_pathname_designator_value(it, env, args->items[0], "compile-file", &compile_file_pathname_value, err, errsz)) {
        free(input_path);
        compile_file_options_dispose(&opts);
        return 0;
    }
    if (!parse_compile_file_options(args, 1, "compile-file", &opts, err, errsz)) {
        free(input_path);
        compile_file_options_dispose(&opts);
        return 0;
    }
    effective_verbose = opts.have_verbose ? opts.verbose : runtime_special_truthy(it, env, "*compile-verbose*");
    effective_print = opts.have_print ? opts.print : runtime_special_truthy(it, env, "*compile-print*");
    warning_count_before = it->warning_count;
    text = read_text_file(input_path, err, errsz);
    if (text == NULL) {
        free(input_path);
        compile_file_options_dispose(&opts);
        return 0;
    }
    if (filesystem_probe_existing_path(compile_file_pathname_value->as.pathname.namestring, &exists, &is_dir, path_err, sizeof(path_err)) && exists) {
        truename_text = canonicalize_existing_path(compile_file_pathname_value->as.pathname.namestring, is_dir, path_err, sizeof(path_err));
        if (truename_text != NULL) {
            compile_file_truename_value = make_pathname_value(truename_text);
            free(truename_text);
            truename_text = NULL;
        }
    }
    compile_env = env_clone_root_surface(env);
    compilation_unit_frame_init(&unit_frame, it->compilation_units, 0);
    it->compilation_units = &unit_frame;
    frame.prev = it->dynamic;
    frame.bindings = NULL;
    frame.count = 0;
    dynamic_frame_bind(&frame, compile_file_pathname_symbol, compile_file_pathname_value, 1);
    dynamic_frame_bind(&frame, compile_file_truename_symbol, compile_file_truename_value, 1);
    dynamic_frame_bind(&frame, compile_verbose_symbol, effective_verbose ? it->true_value : it->nil, 1);
    dynamic_frame_bind(&frame, compile_print_symbol, effective_print ? it->true_value : it->nil, 1);
    it->dynamic = &frame;
    if (!compile_file_transform_text(it, compile_env, input_path, text, &compiled_program, err, errsz)) {
        it->dynamic = frame.prev;
        dynamic_frame_dispose(&frame);
        it->compilation_units = unit_frame.prev;
        compilation_unit_frame_dispose(&unit_frame);
        it->current_package = saved_package;
        symbol_value_set_runtime_special(it, env, "*package*", saved_package);
        free(input_path);
        free(text);
        compile_file_options_dispose(&opts);
        return 0;
    }
    it->dynamic = frame.prev;
    dynamic_frame_dispose(&frame);
    if (!compilation_unit_flush_warnings(it, env, &unit_frame, err, errsz)) {
        it->compilation_units = unit_frame.prev;
        compilation_unit_frame_dispose(&unit_frame);
        it->current_package = saved_package;
        symbol_value_set_runtime_special(it, env, "*package*", saved_package);
        free(input_path);
        free(text);
        compile_file_options_dispose(&opts);
        return 0;
    }
    it->compilation_units = unit_frame.prev;
    compilation_unit_frame_dispose(&unit_frame);
    it->current_package = saved_package;
    symbol_value_set_runtime_special(it, env, "*package*", saved_package);
    compile_had_warning = (it->warning_count > warning_count_before);
    output_path = compile_file_output_path(input_path, opts.output_file);
    {
        int write_rc = write_fasl_binary_file(output_path, compiled_program, err, errsz);
        if (write_rc < 0) {
            compiled_text = render_program_readably(it, compiled_program);
            if (!write_fasl_file(output_path, compiled_text, strlen(compiled_text), err, errsz)) {
                free(input_path);
                free(output_path);
                free(compiled_text);
                free(text);
                compile_file_options_dispose(&opts);
                return 0;
            }
        } else if (write_rc == 0) {
            free(input_path);
            free(output_path);
            free(compiled_text);
            free(text);
            compile_file_options_dispose(&opts);
            return 0;
        }
    }
    value_array_init(&values);
    value_array_push(&values, make_pathname_value(output_path));
    value_array_push(&values, compile_had_warning ? it->true_value : it->nil);
    value_array_push(&values, it->nil);
    interp_set_values(it, &values);
    *out = values.items[0];
    free(input_path);
    free(output_path);
    free(compiled_text);
    free(text);
    compile_file_options_dispose(&opts);
    return 1;
}

static void define_builtin(Interp *it, Env *env, const char *name, BuiltinFn fn) {
    Value *symbol = NULL;
    char tmp_err[256];
    if (it != NULL &&
        it->common_lisp_package != NULL &&
        package_intern_name(it, it->common_lisp_package, name, &symbol, NULL, tmp_err, sizeof(tmp_err))) {
        env_define_function_symbol(env, symbol, make_builtin_value(name, fn));
        return;
    }
    env_define_function(env, name, make_builtin_value(name, fn));
}

static void export_common_lisp_name(Interp *it, const char *name) {
    Value *symbol = NULL;
    char tmp_err[256];
    if (it == NULL || it->common_lisp_package == NULL || name == NULL) return;
    if (!package_intern_name(it, it->common_lisp_package, name, &symbol, NULL, tmp_err, sizeof(tmp_err))) return;
    (void)package_mark_symbol_external(it->common_lisp_package, symbol, tmp_err, sizeof(tmp_err));
}

