static int builtin_slot_value_using_class(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    Value *class_obj; Value *instance; Value *slot_name; const char *slot_key;
    if (args->count < 3) { snprintf(err, errsz, "slot-value-using-class expects class instance slot-name"); return 0; }
    class_obj = args->items[0]; instance = args->items[1]; slot_name = args->items[2];
    if (!symbol_name(slot_name, &slot_key)) { *out = it->nil; interp_set_single_value(it, it->nil); return 1; }
    if (class_obj && class_obj->type == VALUE_CLASS) {
        int cumulative_idx; Value *def_class; int local_idx; int is_class;
        if (clos_find_slot_hierarchical(it, class_obj, env, slot_key, &cumulative_idx, &def_class, &local_idx, &is_class)) {
            if (is_class) {
                if (local_idx < def_class->as.class.class_slot_values.count) {
                    *out = def_class->as.class.class_slot_values.items[local_idx];
                } else {
                    *out = it->clos_unbound_value;
                }
                interp_set_single_value(it, *out); return 1;
            }
            if (cumulative_idx + 1 < instance->array_total_size) {
                *out = instance->as.array.items[cumulative_idx + 1];
                interp_set_single_value(it, *out); return 1;
            }
        }
    }
    *out = it->nil; interp_set_single_value(it, it->nil); return 1;
}

static int builtin_setf_slot_value_using_class(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    Value *class_obj; Value *instance; Value *slot_name; Value *new_value; const char *slot_key;
    if (args->count < 4) { snprintf(err, errsz, "setf slot-value-using-class expects class instance slot-name new-value"); return 0; }
    class_obj = args->items[0]; instance = args->items[1]; slot_name = args->items[2]; new_value = args->items[3];
    if (!symbol_name(slot_name, &slot_key)) { snprintf(err, errsz, "slot-name must be a symbol"); return 0; }
    if (class_obj && class_obj->type == VALUE_CLASS) {
        int cumulative_idx; Value *def_class; int local_idx; int is_class;
        if (clos_find_slot_hierarchical(it, class_obj, env, slot_key, &cumulative_idx, &def_class, &local_idx, &is_class)) {
            if (is_class) {
                while (def_class->as.class.class_slot_values.count <= local_idx) {
                    value_array_push(&def_class->as.class.class_slot_values, it->clos_unbound_value);
                }
                def_class->as.class.class_slot_values.items[local_idx] = new_value;
                *out = new_value; interp_set_single_value(it, *out); return 1;
            }
            if (cumulative_idx + 1 < instance->array_total_size) {
                instance->as.array.items[cumulative_idx + 1] = new_value;
                *out = new_value; interp_set_single_value(it, *out); return 1;
            }
        }
    }
    snprintf(err, errsz, "slot not found"); return 0;
}

static int builtin_slot_boundp_using_class(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    Value *class_obj; Value *instance; Value *slot_name; const char *slot_key;
    if (args->count < 3) { snprintf(err, errsz, "slot-boundp-using-class expects class instance slot-name"); return 0; }
    class_obj = args->items[0]; instance = args->items[1]; slot_name = args->items[2];
    if (!symbol_name(slot_name, &slot_key)) { *out = it->nil; interp_set_single_value(it, it->nil); return 1; }
    if (class_obj && class_obj->type == VALUE_CLASS) {
        int cumulative_idx; Value *def_class; int local_idx; int is_class;
        if (clos_find_slot_hierarchical(it, class_obj, env, slot_key, &cumulative_idx, &def_class, &local_idx, &is_class)) {
            if (is_class) {
                Value *val = (local_idx < def_class->as.class.class_slot_values.count)
                    ? def_class->as.class.class_slot_values.items[local_idx]
                    : it->clos_unbound_value;
                *out = (val != it->clos_unbound_value) ? it->true_value : it->nil;
                interp_set_single_value(it, *out); return 1;
            }
            if (cumulative_idx + 1 < instance->array_total_size) {
                Value *val = instance->as.array.items[cumulative_idx + 1];
                *out = (val != it->clos_unbound_value) ? it->true_value : it->nil;
                interp_set_single_value(it, *out); return 1;
            }
        }
    }
    *out = it->nil; interp_set_single_value(it, it->nil); return 1;
}

