static int builtin_method_generic_function(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    int i;
    (void)env;
    if (args->count < 1) { snprintf(err, errsz, "method-generic-function expects a method"); return 0; }
    if (args->items[0]->type != VALUE_METHOD) { snprintf(err, errsz, "method-generic-function expects a method"); return 0; }
    if (it->class_table != NULL && it->class_table->as.hash_table.entries != NULL) {
        for (i = 0; i < it->class_table->as.hash_table.count; ++i) {
            HashEntry *entry = &it->class_table->as.hash_table.entries[i];
            if (entry->key != NULL && entry->value != NULL && entry->value->type == VALUE_GENERIC_FUNCTION) {
                Value *gf = entry->value;
                if (gf->as.gf.methods != NULL && value_is_list_like(gf->as.gf.methods)) {
                    int j;
                    for (j = 0; j < gf->as.gf.methods->as.array.count; ++j) {
                        if (gf->as.gf.methods->as.array.items[j] == args->items[0]) {
                            *out = gf; interp_set_single_value(it, *out); return 1;
                        }
                    }
                }
            }
        }
    }
    *out = it->nil; interp_set_single_value(it, *out); return 1;
}

