static int builtin_compute_effective_slot_definition(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    Value *class_obj; Value *slot_name; const char *sn; int i;
    (void)env;
    if (args->count < 2) { snprintf(err, errsz, "compute-effective-slot-definition expects class slot-name"); return 0; }
    class_obj = args->items[0];
    if (class_obj->type != VALUE_CLASS) {
        if (class_obj->type == VALUE_SYMBOL && env_lookup_function_symbol(env, class_obj, &class_obj) && class_obj && class_obj->type == VALUE_CLASS) {}
        else { snprintf(err, errsz, "class not found"); return 0; }
    }
    if (!symbol_name(args->items[1], &sn)) { *out = it->nil; interp_set_single_value(it, it->nil); return 1; }
    if (value_is_list_like(class_obj->as.class.direct_slots)) {
        for (i = 0; i < class_obj->as.class.direct_slots->as.array.count; ++i) {
            Value *spec = class_obj->as.class.direct_slots->as.array.items[i];
            Value *ssn = clos_slot_name_from_spec(spec);
            const char *sk; if (ssn && symbol_name(ssn, &sk) && str_ieq(sk, sn)) { *out = spec; interp_set_single_value(it, *out); return 1; }
        }
    }
    *out = it->nil; interp_set_single_value(it, it->nil); return 1;
}

