static int clos_list_count(Value *v) {
    if (v == NULL || v->type == VALUE_NIL) return 0;
    if (v->type == VALUE_LIST) return v->as.array.count;
    if (v->type == VALUE_CONS) { int n = 0; while (v->type == VALUE_CONS) { n++; v = v->as.cons.cdr; } return n; }
    return 0;
}

static Value *clos_list_nth(Value *v, int idx) {
    if (v == NULL || v->type == VALUE_NIL) return NULL;
    if (v->type == VALUE_LIST) return (idx >= 0 && idx < v->as.array.count) ? v->as.array.items[idx] : NULL;
    if (v->type == VALUE_CONS) { int n = 0; while (v->type == VALUE_CONS) { if (n == idx) return v->as.cons.car; v = v->as.cons.cdr; n++; } }
    return NULL;
}

static int builtin_find_method(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    Value *gf; Value *qualifiers; Value *specializers; Value *errorp; int i, j;
    if (args->count < 2 || args->count > 4) { snprintf(err, errsz, "find-method expects gf qualifiers specializers &optional errorp"); return 0; }
    if (args->items[0]->type == VALUE_GENERIC_FUNCTION) { gf = args->items[0]; }
    else if (args->items[0]->type == VALUE_SYMBOL) {
        if (!env_lookup_function_symbol(env, args->items[0], &gf) || !gf || gf->type != VALUE_GENERIC_FUNCTION) {
            snprintf(err, errsz, "find-method: generic function not found"); return 0;
        }
    } else { snprintf(err, errsz, "find-method expects a generic function"); return 0; }
    qualifiers = args->items[1]; specializers = args->items[2];
    errorp = (args->count >= 4) ? args->items[3] : it->true_value;
    if (value_is_list_like(gf->as.gf.methods)) {
        int nmethods = gf->as.gf.methods->as.array.count;
        ValueArray qitems;
        ValueArray sitems;
        value_array_init(&qitems);
        value_array_init(&sitems);
        if (qualifiers != NULL && qualifiers->type != VALUE_NIL && (!value_is_list_like(qualifiers) || !sequence_to_array(qualifiers, &qitems, err, errsz))) return 0;
        if (specializers != NULL && specializers->type != VALUE_NIL && (!value_is_list_like(specializers) || !sequence_to_array(specializers, &sitems, err, errsz))) return 0;
        for (i = 0; i < nmethods; ++i) {
            Value *m = gf->as.gf.methods->as.array.items[i];
            if (m == NULL || m->type != VALUE_METHOD) continue;
            ValueArray mqitems;
            ValueArray msitems;
            int qc = qitems.count;
            int mqc = 0;
            value_array_init(&mqitems);
            value_array_init(&msitems);
            if (m->as.method.qualifiers != NULL && m->as.method.qualifiers->type != VALUE_NIL) {
                if (!value_is_list_like(m->as.method.qualifiers) || !sequence_to_array(m->as.method.qualifiers, &mqitems, err, errsz)) return 0;
                mqc = mqitems.count;
            }
            if (qc != mqc) continue;
            int qmatch = 1;
            for (j = 0; j < qc; ++j) {
                if (qitems.items[j] != mqitems.items[j]) { qmatch = 0; break; }
            }
            if (!qmatch) continue;
            int sc = sitems.count;
            int msc = 0;
            if (m->as.method.specializers != NULL && m->as.method.specializers->type != VALUE_NIL) {
                if (!value_is_list_like(m->as.method.specializers) || !sequence_to_array(m->as.method.specializers, &msitems, err, errsz)) return 0;
                msc = msitems.count;
            }
            if (sc != msc) continue;
            int smatch = 1;
            for (j = 0; j < sc; ++j) {
                Value *qs = sitems.items[j];
                Value *ms = msitems.items[j];
                if (qs == ms) continue;
                const char *msn = NULL;
                if (ms != NULL && ms->type == VALUE_SYMBOL && symbol_name(ms, &msn)) {
                    const char *qsn = NULL;
                    if (qs != NULL && qs->type == VALUE_CLASS && qs->as.class.name != NULL) {
                        if (symbol_name(qs->as.class.name, &qsn) && str_ieq(qsn, msn)) continue;
                    } else if (qs != NULL && qs->type == VALUE_SYMBOL && symbol_name(qs, &qsn) && str_ieq(qsn, msn)) {
                        continue;
                    }
                }
                smatch = 0; break;
            }
            if (smatch) { *out = m; interp_set_single_value(it, *out); return 1; }
        }
    }
    if (value_is_truthy(errorp)) { snprintf(err, errsz, "find-method: method not found"); return 0; }
    *out = it->nil; interp_set_single_value(it, it->nil); return 1;
}

static int builtin_add_method(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    Value *gf; Value *method; int i;
    if (args->count < 2) { snprintf(err, errsz, "add-method expects gf method"); return 0; }
    if (args->items[0]->type == VALUE_GENERIC_FUNCTION) { gf = args->items[0]; }
    else if (args->items[0]->type == VALUE_SYMBOL) {
        if (!env_lookup_function_symbol(env, args->items[0], &gf) || !gf || gf->type != VALUE_GENERIC_FUNCTION) {
            snprintf(err, errsz, "add-method: generic function not found"); return 0;
        }
    } else { snprintf(err, errsz, "add-method expects a generic function"); return 0; }
    method = args->items[1];
    if (method == NULL || method->type != VALUE_METHOD) { snprintf(err, errsz, "add-method expects a method"); return 0; }
    if (gf->as.gf.methods == it->nil || !value_is_list_like(gf->as.gf.methods)) {
        ValueArray ms; value_array_init(&ms); value_array_push(&ms, method);
        gf->as.gf.methods = make_list_value(&ms); value_array_dispose(&ms);
    } else {
        ValueArray ms; value_array_init(&ms);
        for (i = 0; i < gf->as.gf.methods->as.array.count; ++i) value_array_push(&ms, gf->as.gf.methods->as.array.items[i]);
        value_array_push(&ms, method);
        gf->as.gf.methods = make_list_value(&ms); value_array_dispose(&ms);
    }
    *out = method; interp_set_single_value(it, *out); return 1;
}

static int builtin_ensure_class(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    Value *name; Value *class_obj; (void)it;
    if (args->count < 1) { snprintf(err, errsz, "ensure-class expects a name"); return 0; }
    name = args->items[0];
    if (name->type != VALUE_SYMBOL) { snprintf(err, errsz, "ensure-class name must be a symbol"); return 0; }
    if (env_lookup_function_symbol(env, name, &class_obj) && class_obj != NULL && class_obj->type == VALUE_CLASS) {
        *out = class_obj; interp_set_single_value(it, *out); return 1;
    }
    class_obj = value_new(VALUE_CLASS);
    class_obj->as.class.name = name;
    class_obj->as.class.direct_superclasses = it->nil;
    class_obj->as.class.direct_slots = it->nil;
    class_obj->as.class.default_initargs = it->nil;
    class_obj->as.class.documentation = it->nil;
    class_obj->as.class.finalize_p = 1;
    class_obj->as.class.obsolete_p = 0;
    class_obj->as.class.cpl_cache = NULL;
    value_array_init(&class_obj->as.class.class_slot_values);
    if (args->count >= 2 && value_is_list_like(args->items[1])) {
        class_obj->as.class.direct_superclasses = args->items[1];
    }
    if (args->count >= 3 && value_is_list_like(args->items[2])) {
        class_obj->as.class.direct_slots = args->items[2];
    }
    if (args->count >= 4) class_obj->as.class.default_initargs = args->items[3];
    global_function_set_symbol(env, name, class_obj);
    *out = class_obj; interp_set_single_value(it, *out); return 1;
}

