static int builtin_remove_method(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    Value *gf_name; Value *method; Value *gf; int i;
    if (args->count < 2) { snprintf(err, errsz, "remove-method expects gf method"); return 0; }
    gf_name = args->items[0]; method = args->items[1];
    if (gf_name->type == VALUE_SYMBOL) {
        if (!env_lookup_function_symbol(env, gf_name, &gf) || !gf || gf->type != VALUE_GENERIC_FUNCTION) {
            snprintf(err, errsz, "remove-method: generic function not found"); return 0;
        }
    } else if (gf_name->type == VALUE_GENERIC_FUNCTION) {
        gf = gf_name;
    } else { snprintf(err, errsz, "remove-method expects a generic function or name"); return 0; }
    if (!value_is_list_like(gf->as.gf.methods)) {
        snprintf(err, errsz, "remove-method: generic function has no methods"); return 0;
    }
    {
        ValueArray new_methods; value_array_init(&new_methods);
        int removed = 0;
        for (i = 0; i < gf->as.gf.methods->as.array.count; ++i) {
            Value *m = gf->as.gf.methods->as.array.items[i];
            if (m == method || (method != NULL && method->type == VALUE_METHOD && m->type == VALUE_METHOD && m->as.method.specializers == method->as.method.specializers && m->as.method.qualifiers == method->as.method.qualifiers)) { removed = 1; continue; }
            value_array_push(&new_methods, m);
        }
        if (!removed) { snprintf(err, errsz, "remove-method: method not found"); value_array_dispose(&new_methods); return 0; }
        gf->as.gf.methods = (new_methods.count > 0) ? make_list_value(&new_methods) : it->nil;
        value_array_dispose(&new_methods);
    }
    *out = gf_name; interp_set_single_value(it, *out); return 1;
}

static int special_like_transform(Interp *it, Env *env, Value *form, const char *target_name, int min_args, int max_args, Value **out, char *err, size_t errsz) {
    ValueArray items; int i;
    if (!value_is_list_like(form) || form->as.array.count < min_args + 1 || (max_args >= 0 && form->as.array.count > max_args + 1)) {
        snprintf(err, errsz, "%s: invalid form", target_name); return 0;
    }
    value_array_init(&items);
    value_array_push(&items, common_lisp_runtime_symbol_or_fallback(it, target_name));
    for (i = 1; i < form->as.array.count; ++i) value_array_push(&items, make_runtime_quote_form(it, form->as.array.items[i]));
    if (!eval(it, env, make_list_value(&items), out, err, errsz)) { value_array_dispose(&items); return 0; }
    value_array_dispose(&items); return 1;
}

/* ===== defgeneric / defmethod / dispatch ===== */

static int builtin_defgeneric_check(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    Value *name = NULL;
    Value *gf = NULL;
    int i;
    (void)env;
    if (args->count < 1) { snprintf(err, errsz, "defgeneric expects a name"); return 0; }
    name = args->items[0];
    if (name == NULL || name->type != VALUE_SYMBOL) { snprintf(err, errsz, "defgeneric name must be a symbol"); return 0; }
    gf = value_new(VALUE_GENERIC_FUNCTION);
    gf->as.gf.name = name;
    gf->as.gf.lambda_list = (args->count >= 2) ? args->items[1] : it->nil;
    gf->as.gf.methods = it->nil;
    gf->as.gf.method_combination = it->nil;
    gf->as.gf.documentation = it->nil;
    for (i = 2; i < args->count; ++i) {
        if (value_is_list_like(args->items[i]) && args->items[i]->type != VALUE_NIL) {
            ValueArray option_items;
            char tmp_err[64];
            const char *key = NULL;
            if (!sequence_to_array(args->items[i], &option_items, tmp_err, sizeof(tmp_err)) || option_items.count < 2) continue;
            if (symbol_name(option_items.items[0], &key)) {
                if (clos_name_matches(key, "method-combination")) {
                    if (option_items.count == 2) {
                        gf->as.gf.method_combination = option_items.items[1];
                    } else {
                        ValueArray mc_spec;
                        int mi;
                        value_array_init(&mc_spec);
                        for (mi = 1; mi < option_items.count; ++mi) value_array_push(&mc_spec, option_items.items[mi]);
                        gf->as.gf.method_combination = make_list_value(&mc_spec);
                        value_array_dispose(&mc_spec);
                    }
                }
                if (clos_name_matches(key, "documentation")) {
                    gf->as.gf.documentation = option_items.items[1];
                }
            }
        }
    }
    global_function_set_symbol(env, name, gf);
    *out = name;
    interp_set_single_value(it, *out);
    return 1;
}

static int clos_value_looks_like_qualifier_list(Value *value) {
    ValueArray items;
    int i;
    char tmp_err[64];
    if (value == NULL || value->type == VALUE_NIL) return 1;
    if (!value_is_list_like(value)) return 0;
    if (!sequence_to_array(value, &items, tmp_err, sizeof(tmp_err))) return 0;
    for (i = 0; i < items.count; ++i) {
        if (items.items[i] == NULL || items.items[i]->type != VALUE_SYMBOL) return 0;
    }
    return 1;
}

static int clos_value_looks_like_low_level_qualifier_list(Value *value) {
    ValueArray items;
    int i;
    char tmp_err[64];
    if (value == NULL || value->type == VALUE_NIL) return 1;
    if (!value_is_list_like(value)) return 0;
    if (!sequence_to_array(value, &items, tmp_err, sizeof(tmp_err))) return 0;
    if (items.count == 0) return 1;
    for (i = 0; i < items.count; ++i) {
        const char *name = NULL;
        if (items.items[i] == NULL || !symbol_name(items.items[i], &name)) return 0;
        if (name[0] == ':' || clos_method_combination_builtin_name(name)) continue;
        return 0;
    }
    return 1;
}

static int clos_value_looks_like_specializer_list(Value *value) {
    ValueArray items;
    int i;
    char tmp_err[64];
    if (value == NULL || value->type == VALUE_NIL) return 1;
    if (!value_is_list_like(value)) return 0;
    if (!sequence_to_array(value, &items, tmp_err, sizeof(tmp_err))) return 0;
    for (i = 0; i < items.count; ++i) {
        if (items.items[i] == NULL) return 0;
        if (items.items[i]->type == VALUE_SYMBOL || items.items[i]->type == VALUE_CLASS || value_is_list_like(items.items[i])) continue;
        return 0;
    }
    return 1;
}

static int clos_value_looks_like_specialized_lambda_list(Value *value) {
    ValueArray items;
    int i;
    char tmp_err[64];
    if (value == NULL || !value_is_list_like(value)) return 0;
    if (value->type == VALUE_NIL) return 1;
    if (!sequence_to_array(value, &items, tmp_err, sizeof(tmp_err))) return 0;
    for (i = 0; i < items.count; ++i) {
        Value *item = items.items[i];
        const char *name = NULL;
        ValueArray pair;
        if (item == NULL) return 0;
        if (symbol_name(item, &name)) continue;
        if (value_is_list_like(item) && item->type != VALUE_NIL && sequence_to_array(item, &pair, tmp_err, sizeof(tmp_err)) && pair.count >= 1 && pair.items[0]->type == VALUE_SYMBOL) continue;
        return 0;
    }
    return 1;
}

static int clos_parse_specialized_lambda_list(Interp *it, Value *specialized, Value **params_out, Value **specializers_out, char *err, size_t errsz) {
    ValueArray raw;
    ValueArray params;
    ValueArray specializers;
    int i;
    int collecting_specializers = 1;
    if (!sequence_to_array(specialized, &raw, err, errsz)) {
        snprintf(err, errsz, "defmethod specialized lambda list must be a list");
        return 0;
    }
    value_array_init(&params);
    value_array_init(&specializers);
    for (i = 0; i < raw.count; ++i) {
        Value *item = raw.items[i];
        const char *name = NULL;
        if (symbol_name(item, &name) && name[0] == '&') {
            collecting_specializers = 0;
            value_array_push(&params, item);
            continue;
        }
        if (collecting_specializers) {
            if (item != NULL && item->type == VALUE_SYMBOL) {
                value_array_push(&params, item);
                value_array_push(&specializers, common_lisp_runtime_symbol_or_fallback(it, "t"));
                continue;
            }
            if (value_is_list_like(item) && item->type != VALUE_NIL) {
                ValueArray pair;
                if (!sequence_to_array(item, &pair, err, errsz) || pair.count < 1 || pair.items[0]->type != VALUE_SYMBOL) {
                    snprintf(err, errsz, "defmethod parameter specializer must be (var specializer)");
                    return 0;
                }
                value_array_push(&params, pair.items[0]);
                value_array_push(&specializers, (pair.count >= 2) ? pair.items[1] : common_lisp_runtime_symbol_or_fallback(it, "t"));
                continue;
            }
        }
        /* After &key/&rest etc, normalize list-like items from CONS to VALUE_LIST
           so that bind_key_params can process (var default) patterns correctly */
        if (!collecting_specializers && (item->type == VALUE_CONS || item->type == VALUE_NIL)) {
            ValueArray na;
            char na_err[64];
            value_array_init(&na);
            if (sequence_to_array(item, &na, na_err, sizeof(na_err))) {
                item = make_list_value(&na);
                value_array_dispose(&na);
            }
        }
        value_array_push(&params, item);
    }
    *params_out = make_list_value(&params);
    *specializers_out = (specializers.count > 0) ? make_list_value(&specializers) : it->nil;
    value_array_dispose(&params);
    value_array_dispose(&specializers);
    return 1;
}

static Value *clos_make_body_list(Interp *it, const ValueArray *args, int body_start) {
    ValueArray body;
    int i;
    value_array_init(&body);
    for (i = body_start; i < args->count; ++i) value_array_push(&body, args->items[i]);
    if (body.count == 0) value_array_push(&body, it->nil);
    return make_list_value(&body);
}

static int builtin_defmethod_check(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    Value *name = NULL;
    Value *qualifiers = NULL;
    Value *specializers = NULL;
    Value *lambda_list = NULL;
    Value *body = NULL;
    Value *gf = NULL;
    Value *method = NULL;
    int i;
    (void)env;
    if (args->count < 2) { snprintf(err, errsz, "defmethod expects at least name and body"); return 0; }
    name = args->items[0];
    if (name == NULL) { snprintf(err, errsz, "defmethod name must be a symbol or (setf symbol)"); return 0; }
    /* Support (setf name) method names */
    if (name->type == VALUE_CONS && name->as.cons.car != NULL && name->as.cons.car->type == VALUE_SYMBOL
        && str_ieq(name->as.cons.car->as.str, "SETF")) {
        /* (setf name) method - keep the cons as the GF name */
    } else if (name->type != VALUE_SYMBOL) {
        snprintf(err, errsz, "defmethod name must be a symbol or (setf symbol)"); return 0;
    }
    qualifiers = it->nil;
    specializers = it->nil;
    lambda_list = it->nil;
    if (args->count >= 4 &&
        clos_value_looks_like_low_level_qualifier_list(args->items[1]) &&
        clos_value_looks_like_specializer_list(args->items[2])) {
        qualifiers = args->items[1];
        specializers = args->items[2];
        body = clos_make_body_list(it, args, 3);
    } else {
        int lambda_index = -1;
        ValueArray qs;
        for (i = 1; i < args->count; ++i) {
            if (clos_value_looks_like_specialized_lambda_list(args->items[i])) {
                lambda_index = i;
                break;
            }
        }
        if (lambda_index < 0 || lambda_index + 1 >= args->count) {
            snprintf(err, errsz, "defmethod expects qualifiers, specialized lambda list, and body");
            return 0;
        }
        value_array_init(&qs);
        for (i = 1; i < lambda_index; ++i) value_array_push(&qs, args->items[i]);
        qualifiers = (qs.count > 0) ? make_list_value(&qs) : it->nil;
        value_array_dispose(&qs);
        if (!clos_parse_specialized_lambda_list(it, args->items[lambda_index], &lambda_list, &specializers, err, errsz)) return 0;
        body = clos_make_body_list(it, args, lambda_index + 1);
    }
    if (!env_lookup_function_symbol(env, name, &gf) || gf == NULL || gf->type != VALUE_GENERIC_FUNCTION) {
        gf = value_new(VALUE_GENERIC_FUNCTION);
        gf->as.gf.name = name;
        gf->as.gf.lambda_list = it->nil;
        gf->as.gf.methods = it->nil;
        gf->as.gf.method_class = it->nil;
        gf->as.gf.method_combination = it->nil;
        gf->as.gf.argument_precedence_order = it->nil;
        gf->as.gf.documentation = it->nil;
        global_function_set_symbol(env, name, gf);
    }
    method = make_method_value(it, qualifiers, specializers, lambda_list, body, env);
    if (gf->as.gf.methods == it->nil) {
        ValueArray methods;
        value_array_init(&methods);
        value_array_push(&methods, method);
        gf->as.gf.methods = make_list_value(&methods);
        value_array_dispose(&methods);
    } else {
        ValueArray methods;
        value_array_init(&methods);
        for (i = 0; i < gf->as.gf.methods->as.array.count; ++i) value_array_push(&methods, gf->as.gf.methods->as.array.items[i]);
        value_array_push(&methods, method);
        gf->as.gf.methods = make_list_value(&methods);
        value_array_dispose(&methods);
    }
    *out = name;
    interp_set_single_value(it, *out);
    return 1;
}

static int builtin_compute_cpl(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    Value *class_obj = NULL;
    Value *cpl = NULL;
    int error_flag = 0;
    int hti;
    (void)env;
    if (args->count < 1) { snprintf(err, errsz, "compute-cpl expects a class or class name"); return 0; }
    if (args->items[0]->type == VALUE_CLASS) {
        class_obj = args->items[0];
    } else if (args->items[0]->type == VALUE_SYMBOL) {
        hti = hash_table_find_entry(it->class_table, args->items[0]);
        if (hti >= 0) class_obj = it->class_table->as.hash_table.entries[hti].value;
    }
    if (class_obj == NULL || class_obj->type != VALUE_CLASS) { snprintf(err, errsz, "compute-cpl: class not found"); return 0; }
    cpl = compute_cpl(it, class_obj, &error_flag, err, errsz);
    if (cpl == NULL || error_flag) { snprintf(err, errsz, "compute-cpl: error computing CPL"); return 0; }
    *out = cpl;
    interp_set_single_value(it, *out);
    return 1;
}

