static int builtin_class_precedence_list(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    Value *class_obj = NULL;
    Value *cpl = NULL;
    int error_flag = 0;
    int hti;
    (void)env;
    if (args->count < 1) { snprintf(err, errsz, "class-precedence-list expects a class or class name"); return 0; }
    if (args->items[0]->type == VALUE_CLASS) {
        class_obj = args->items[0];
    } else if (args->items[0]->type == VALUE_SYMBOL) {
        hti = hash_table_find_entry(it->class_table, args->items[0]);
        if (hti >= 0) class_obj = it->class_table->as.hash_table.entries[hti].value;
    }
    if (class_obj == NULL || class_obj->type != VALUE_CLASS) { snprintf(err, errsz, "class-precedence-list: class not found"); return 0; }
    if (class_obj->as.class.cpl_cache != NULL) {
        cpl = class_obj->as.class.cpl_cache;
    } else {
        cpl = compute_cpl(it, class_obj, &error_flag, err, errsz);
        if (cpl == NULL || error_flag) { snprintf(err, errsz, "class-precedence-list: error computing CPL"); return 0; }
        class_obj->as.class.cpl_cache = cpl;
    }
    *out = cpl;
    interp_set_single_value(it, *out);
    return 1;
}

