    define_builtin(it, env, "slot-exists-p-using-class", builtin_slot_exists_p_using_class);
    define_builtin(it, env, "slot-makunbound-using-class", builtin_slot_makunbound_using_class);
    define_builtin(it, env, "gf-methods", builtin_gf_methods);
    define_builtin(it, env, "generic-function-methods", builtin_gf_methods);
    define_builtin(it, env, "method-qualifiers", builtin_method_qualifiers);
    define_builtin(it, env, "method-generic-function", builtin_method_generic_function);
    define_builtin(it, env, "remove-method", builtin_remove_method);
    define_builtin(it, env, "compute-slots", builtin_compute_slots);
    define_builtin(it, env, "class-direct-superclasses", builtin_class_direct_superclasses);
    define_builtin(it, env, "class-precedence-list", builtin_class_precedence_list);
    define_builtin(it, env, "class-direct-slots", builtin_class_direct_slots);
    define_builtin(it, env, "class-slots", builtin_class_slots);
    define_builtin(it, env, "slot-definition-name", builtin_slot_definition_name);
    define_builtin(it, env, "slot-definition-initform", builtin_slot_definition_initform);
    define_builtin(it, env, "slot-definition-initarg", builtin_slot_definition_initarg);
