static int builtin_py_set_attr(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    if (args->count != 3) {
        snprintf(err, errsz, "%s", "py:%set-attr requires 3 arguments: object attr-name value");
        return 0;
    }
    (void)env;
    Value *obj = args->items[0];
    Value *attr = args->items[1];
    Value *val = args->items[2];
    const char *name = NULL;
    char name_buf[256];
    if (attr->type == VALUE_STRING) {
        name = attr->as.str;
    } else if (attr->type == VALUE_SYMBOL || value_is_keyword(attr)) {
        const char *src = attr->as.str;
        if (*src == ':') src++;
        size_t len = strlen(src);
        if (len + 1 > sizeof(name_buf)) {
            snprintf(err, errsz, "py:%%set-attr: attribute name too long");
            return 0;
        }
        for (size_t i = 0; i < len; i++)
            name_buf[i] = (char)tolower((unsigned char)src[i]);
        name_buf[len] = '\0';
        name = name_buf;
    } else {
        snprintf(err, errsz, "py:%%set-attr: attribute name must be symbol, string, or keyword");
        return 0;
    }
    if (obj->type != VALUE_PYTHON || obj->as.python.obj == NULL) {
        snprintf(err, errsz, "py:%%set-attr: object is not a Python object");
        return 0;
    }
    PY_GIL_ENSURE();
    PyObject *py_val = lisp_to_python(it, env, val, err, errsz);
    if (!py_val) { PY_GIL_RELEASE(); return 0; }
    int rc = PyObject_SetAttrString((PyObject*)obj->as.python.obj, name, py_val);
    Py_DECREF(py_val);
    if (rc < 0) { py_bridge_check_error(err, errsz); PY_GIL_RELEASE(); return 0; }
    PY_GIL_RELEASE();
    *out = val;
    interp_set_single_value(it, val);
    return 1;
}

