static int builtin_py_help(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    if (args->count != 1) { snprintf(err, errsz, "py:help requires 1 argument"); return 0; }
    Value *obj = args->items[0];
    PY_GIL_ENSURE();
    PyObject *py_obj = NULL;
    int need_decref = 0;
    if (obj->type == VALUE_PYTHON && obj->as.python.obj != NULL) {
        py_obj = (PyObject*)obj->as.python.obj;
    } else {
        py_obj = lisp_to_python(it, env, obj, err, errsz);
        if (!py_obj) { PY_GIL_RELEASE(); return 0; }
        need_decref = 1;
    }
    PyObject *builtins = PyImport_ImportModule("builtins");
    if (!builtins) { if (need_decref) Py_DECREF(py_obj); py_bridge_check_error(err, errsz); PY_GIL_RELEASE(); return 0; }
    PyObject *help_fn = PyObject_GetAttrString(builtins, "help");
    Py_DECREF(builtins);
    if (!help_fn) { if (need_decref) Py_DECREF(py_obj); py_bridge_check_error(err, errsz); PY_GIL_RELEASE(); return 0; }
    PyObject *py_args = PyTuple_Pack(1, py_obj);
    if (need_decref) Py_DECREF(py_obj);
    PyObject *py_result = PyObject_Call(help_fn, py_args, NULL);
    Py_DECREF(help_fn);
    Py_DECREF(py_args);
    if (!py_result) { py_bridge_check_error(err, errsz); PY_GIL_RELEASE(); return 0; }
    Py_DECREF(py_result);
    PY_GIL_RELEASE();
    *out = it->nil;
    return 1;
}

