/* ---- Python Debugger Bridge ---- */

static int builtin_py_last_traceback(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    (void)env; (void)args;
    PY_GIL_ENSURE();
    {
        PyObject *main_mod = PyImport_AddModule("__main__");
        if (!main_mod) { PY_GIL_RELEASE(); *out = it->nil; interp_set_single_value(it, it->nil); return 1; }
        PyObject *tb = PyObject_GetAttrString(main_mod, "_lispy_last_tb");
        if (!tb || tb == Py_None) {
            Py_XDECREF(tb);
            PY_GIL_RELEASE();
            *out = it->nil;
            interp_set_single_value(it, it->nil);
            return 1;
        }
        /* Walk traceback chain and collect frames */
        ValueArray frame_list;
        value_array_init(&frame_list);
        PyObject *current = tb;
        Py_INCREF(current); /* own a reference for the loop */
        while (current && current != Py_None) {
            PyObject *frame = PyObject_GetAttrString(current, "tb_frame");
            if (frame && frame != Py_None) {
                value_array_push(&frame_list, make_python_value((void*)frame));
            } else {
                Py_XDECREF(frame);
            }
            PyObject *next = PyObject_GetAttrString(current, "tb_next");
            Py_DECREF(current);
            current = next;
        }
        Py_DECREF(tb);
        *out = make_list_value(&frame_list);
        value_array_dispose(&frame_list);
    }
    PY_GIL_RELEASE();
    interp_set_single_value(it, *out);
    return 1;
}

static int builtin_py_frame_locals(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    (void)env;
    if (args->count != 1) { snprintf(err, errsz, "py:frame-locals requires 1 argument: frame"); return 0; }
    Value *fv = args->items[0];
    if (fv->type != VALUE_PYTHON || fv->as.python.obj == NULL) {
        snprintf(err, errsz, "py:frame-locals: not a Python object"); return 0;
    }
    PY_GIL_ENSURE();
    PyObject *locals = PyObject_GetAttrString((PyObject*)fv->as.python.obj, "f_locals");
    if (!locals) { py_bridge_check_error(err, errsz); PY_GIL_RELEASE(); return 0; }
    *out = python_to_lisp(it, locals, err, errsz);
    Py_DECREF(locals);
    PY_GIL_RELEASE();
    interp_set_single_value(it, *out);
    return 1;
}

static int builtin_py_frame_globals(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    (void)env;
    if (args->count != 1) { snprintf(err, errsz, "py:frame-globals requires 1 argument: frame"); return 0; }
    Value *fv = args->items[0];
    if (fv->type != VALUE_PYTHON || fv->as.python.obj == NULL) {
        snprintf(err, errsz, "py:frame-globals: not a Python object"); return 0;
    }
    PY_GIL_ENSURE();
    PyObject *globals = PyObject_GetAttrString((PyObject*)fv->as.python.obj, "f_globals");
    if (!globals) { py_bridge_check_error(err, errsz); PY_GIL_RELEASE(); return 0; }
    *out = python_to_lisp(it, globals, err, errsz);
    Py_DECREF(globals);
    PY_GIL_RELEASE();
    interp_set_single_value(it, *out);
    return 1;
}

static int builtin_py_frame_eval(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    (void)env;
    if (args->count != 2) { snprintf(err, errsz, "py:frame-eval requires 2 arguments: expr-string frame"); return 0; }
    const char *code = NULL;
    if (args->items[0]->type == VALUE_STRING) code = args->items[0]->as.str;
    else if (args->items[0]->type == VALUE_SYMBOL) code = args->items[0]->as.str;
    else { snprintf(err, errsz, "py:frame-eval: first argument must be a string"); return 0; }
    Value *fv = args->items[1];
    if (fv->type != VALUE_PYTHON || fv->as.python.obj == NULL) {
        snprintf(err, errsz, "py:frame-eval: second argument must be a Python frame object"); return 0;
    }
    PY_GIL_ENSURE();
    PyObject *frame = (PyObject*)fv->as.python.obj;
    PyObject *globals = PyObject_GetAttrString(frame, "f_globals");
    if (!globals) { py_bridge_check_error(err, errsz); PY_GIL_RELEASE(); return 0; }
    PyObject *locals = PyObject_GetAttrString(frame, "f_locals");
    if (!locals) { Py_DECREF(globals); py_bridge_check_error(err, errsz); PY_GIL_RELEASE(); return 0; }
    PyObject *py_result = PyRun_String(code, Py_eval_input, globals, locals);
    Py_DECREF(globals);
    Py_DECREF(locals);
    if (!py_result) { py_bridge_check_error(err, errsz); PY_GIL_RELEASE(); return 0; }
    PY_GIL_RELEASE();
    *out = python_to_lisp(it, py_result, err, errsz);
    Py_DECREF(py_result);
    interp_set_single_value(it, *out);
    return 1;
}

/* Global for callback bridge */
static Interp* g_lispy_interp = NULL;

static PyObject* lispy_py_callback_impl(PyObject *self, PyObject *py_args) {
    /* Called from Python: lispy_callback(fn_name, *args) */
    (void)self;
    if (!g_lispy_interp) Py_RETURN_NONE;
    Interp *it = g_lispy_interp;
    Py_ssize_t n = PyTuple_Size(py_args);
    if (n < 1) Py_RETURN_NONE;
    PyObject *py_fn = PyTuple_GetItem(py_args, 0);
    const char *fn_name = PyUnicode_AsUTF8(py_fn);
    if (!fn_name) Py_RETURN_NONE;
    ValueArray lisp_args;
    value_array_init(&lisp_args);
    char tmp_err[256];
    for (Py_ssize_t i = 1; i < n; i++) {
        PyObject *py_arg = PyTuple_GetItem(py_args, i);
        Value *lv = python_to_lisp(it, py_arg, tmp_err, sizeof(tmp_err));
        value_array_push(&lisp_args, lv);
    }
    Value *sym = make_symbol_value(fn_name);
    Value *fn_lisp = NULL;
    /* Try function lookup first, then value lookup */
    if (it->global_env) {
        env_lookup_function_symbol(it->global_env, sym, &fn_lisp);
    }
    if (!fn_lisp && it->global_env) {
        int is_bound = 0;
        symbol_value_lookup_symbol(it, it->global_env, sym, &fn_lisp, &is_bound);
    }
    /* Fallback: try *name* for dynamic/special variables */
    if (!fn_lisp && fn_name && fn_name[0] != '*') {
        char star_name[256];
        snprintf(star_name, sizeof(star_name), "*%s*", fn_name);
        Value *star_sym = make_symbol_value(star_name);
        if (it->global_env) {
            env_lookup_function_symbol(it->global_env, star_sym, &fn_lisp);
        }
        if (!fn_lisp && it->global_env) {
            int is_bound = 0;
            symbol_value_lookup_symbol(it, it->global_env, star_sym, &fn_lisp, &is_bound);
        }
    }
    /* Fallback: try Python __main__ module globals (no args only) */
    PyObject *result = NULL;
    if (!fn_lisp && n == 1) {
        PyObject *main_module = PyImport_AddModule("__main__");
        if (main_module) {
            PyObject *main_dict = PyModule_GetDict(main_module);
            if (main_dict) {
                PyObject *py_val = PyDict_GetItemString(main_dict, fn_name);
                if (py_val) {
                    Py_INCREF(py_val);
                    result = py_val;
                }
            }
        }
    }
    if (fn_lisp) {
        int is_lisp_callable = (fn_lisp->type == VALUE_BUILTIN ||
                                (fn_lisp->type == VALUE_CLOSURE && !fn_lisp->as.closure.is_macro) ||
                                fn_lisp->type == VALUE_GENERIC_FUNCTION);
        int is_py_callable = (fn_lisp->type == VALUE_PYTHON && python_value_is_callable(fn_lisp));
        if (is_lisp_callable || is_py_callable) {
            Value *lv_result = NULL;
            if (apply_callable(it, it->global_env, fn_lisp, &lisp_args, &lv_result, tmp_err, sizeof(tmp_err))) {
                result = lisp_to_python(it, it->global_env ? it->global_env : NULL, lv_result, tmp_err, sizeof(tmp_err));
            }
        } else {
            result = lisp_to_python(it, it->global_env ? it->global_env : NULL, fn_lisp, tmp_err, sizeof(tmp_err));
        }
    }
    value_array_dispose(&lisp_args);
    if (result) return result;
    Py_RETURN_NONE;
}

static int builtin_py_register_callback(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    (void)env;
    if (args->count < 1) { snprintf(err, errsz, "py:register-callback requires at least 1 argument: lisp-function-name"); return 0; }
    Value *fn_val = args->items[0];
    const char *fn_name = NULL;
    if (fn_val->type == VALUE_SYMBOL) fn_name = fn_val->as.str;
    else if (fn_val->type == VALUE_STRING) fn_name = fn_val->as.str;
    else { snprintf(err, errsz, "py:register-callback: argument must be a symbol or string"); return 0; }
    PY_GIL_ENSURE();
    {
        static int c_callback_registered = 0;
        if (!c_callback_registered) {
            PyObject *builtins = PyImport_ImportModule("builtins");
            if (builtins) {
                static PyMethodDef def = {"lispy_callback_c", lispy_py_callback_impl, METH_VARARGS, NULL};
                PyObject *fn = PyCFunction_New(&def, NULL);
                if (fn) {
                    /* Try to set vectorcall flag for CPython 3.14+ */
                    PyObject_SetAttrString(builtins, "lispy_callback_c", fn);
                    Py_DECREF(fn);
                }
                /* Also inject a Python wrapper that catches errors gracefully */
                PyRun_SimpleString(
                    "import builtins\n"
                    "def lispy_callback(fn_name, *args):\n"
                    "    try:\n"
                    "        return builtins.lispy_callback_c(fn_name, *args)\n"
                    "    except Exception as e:\n"
                    "        import sys\n"
                    "        m = sys.modules.get('__main__')\n"
                    "        if m: m._lispy_cb = (fn_name, args)\n"
                    "        raise\n"
                    "builtins.lispy_callback = lispy_callback\n");
                Py_DECREF(builtins);
            }
            c_callback_registered = 1;
        }
        /* Also create dedicated wrapper for this specific function */
        char py_name[256];
        size_t i;
        for (i = 0; i < sizeof(py_name) - 1 && fn_name[i]; i++) {
            char ch = (char)tolower((unsigned char)fn_name[i]);
            if ((ch >= 'a' && ch <= 'z') || (ch >= '0' && ch <= '9') || ch == '_')
                py_name[i] = ch;
            else
                py_name[i] = '_';
        }
        py_name[i] = '\0';
        if (i > 0 && py_name[0] >= '0' && py_name[0] <= '9') {
            if (i + 1 < sizeof(py_name)) {
                memmove(py_name + 1, py_name, i + 1);
                py_name[0] = '_';
            }
        }
        char buf[2048];
        snprintf(buf, sizeof(buf),
            "import builtins\n"
            "def %s_cb(*args):\n"
            "    try:\n"
            "        return builtins.lispy_callback_c('%s', *args)\n"
            "    except Exception as e:\n"
            "        import sys\n"
            "        m = sys.modules.get('__main__')\n"
            "        if m: m._lispy_cb = ('%s', args)\n"
            "        raise\n"
            "builtins.%s_cb = %s_cb\n"
            "builtins.%s = %s_cb\n",
            py_name, fn_name, fn_name, py_name, py_name, py_name, py_name);
        PyRun_SimpleString(buf);
    }
    PY_GIL_RELEASE();
    *out = it->true_value;
    interp_set_single_value(it, it->true_value);
    return 1;
}

/* ---- Hybrid syntax loader (embedded preprocessor) ---- */

static const char *LP_PREPROCESS_PY =
    "import re\n"
    "\n"
    "def _lp_name_to_py(name):\n"
    "    result = re.sub(r'[^a-zA-Z0-9]', '_', name).lower()\n"
    "    if result and result[0].isdigit():\n"
    "        result = '_' + result\n"
    "    return result\n"
    "\n"
    "def _lp_extract_defs(src):\n"
    "    fns = set()\n"
    "    for m in re.finditer(r'\\(\\s*def(?:un|macro)\\s+([^\\s()]+)', src, re.I):\n"
    "        fns.add(m.group(1))\n"
    "    for m in re.finditer(r'\\(\\s*def(?:var|parameter)\\s+([^\\s()]+)', src, re.I):\n"
    "        pass\n"
    "    return fns\n"
    "\n"
    "def _lp_paren_delta(line):\n"
    "    d = 0\n"
    "    in_str = False\n"
    "    esc = False\n"
    "    for ch in line:\n"
    "        if esc:\n"
    "            esc = False\n"
    "            continue\n"
    "        if ch == '\\\\':\n"
    "            esc = True\n"
    "            continue\n"
    "        if ch == '\\\"':\n"
    "            in_str = not in_str\n"
    "            continue\n"
    "        if not in_str:\n"
    "            if ch == '(':\n"
    "                d += 1\n"
    "            elif ch == ')':\n"
    "                d -= 1\n"
    "    return d\n"
    "\n"
    "def _lp_split_blocks(lines):\n"
    "    blocks = []\n"
    "    i = 0\n"
    "    n = len(lines)\n"
    "    while i < n:\n"
    "        s = lines[i]\n"
    "        st = s.rstrip()\n"
    "        if st.strip() == '' or st.strip().startswith(';'):\n"
    "            blocks.append(('x', [s]))\n"
    "            i += 1\n"
    "            continue\n"
    "        if st.lstrip().startswith('('):\n"
    "            blk = [s]\n"
    "            depth = _lp_paren_delta(s)\n"
    "            nq = st.count('\\\"')\n"
    "            i += 1\n"
    "            while i < n and (depth > 0 or nq % 2 == 1):\n"
    "                ns = lines[i]\n"
    "                blk.append(ns)\n"
    "                depth += _lp_paren_delta(ns)\n"
    "                nq += ns.count('\\\"')\n"
    "                i += 1\n"
    "            blocks.append(('lisp', blk))\n"
    "            continue\n"
    "        py_lines = []\n"
    "        base_indent = None\n"
    "        while i < n:\n"
    "            s = lines[i]\n"
    "            st = s.rstrip()\n"
    "            if st.strip().startswith(';'):\n"
    "                break\n"
    "            if st.strip() == '':\n"
    "                py_lines.append(s)\n"
    "                i += 1\n"
    "                continue\n"
    "            if st.lstrip().startswith('('):\n"
    "                break\n"
    "            indent = len(s) - len(s.lstrip())\n"
    "            if base_indent is None:\n"
    "                base_indent = indent\n"
    "            if indent < base_indent and st.strip() != '':\n"
    "                break\n"
    "            py_lines.append(s)\n"
    "            i += 1\n"
    "        if py_lines and ''.join(py_lines).strip():\n"
    "            blocks.append(('python', py_lines))\n"
    "        elif not py_lines:\n"
    "            i += 1\n"
    "    return blocks\n"
    "\n"
    "def _replace_at_vars(txt):\n"
    "    result = []\n"
    "    i = 0\n"
    "    n = len(txt)\n"
    "    in_single = False\n"
    "    in_double = False\n"
    "    in_triple_single = False\n"
    "    in_triple_double = False\n"
    "    in_fstring_single = False\n"
    "    in_fstring_double = False\n"
    "    brace_depth = 0\n"
    "    escaped = False\n"
    "    in_comment = False\n"
    "    while i < n:\n"
    "        ch = txt[i]\n"
    "        if escaped:\n"
    "            escaped = False\n"
    "            result.append(ch)\n"
    "            i += 1\n"
    "            continue\n"
    "        if ch == '\\\\':\n"
    "            escaped = True\n"
    "            result.append(ch)\n"
    "            i += 1\n"
    "            continue\n"
    "        if in_comment:\n"
    "            result.append(ch)\n"
    "            if ch == '\\n':\n"
    "                in_comment = False\n"
    "            i += 1\n"
    "            continue\n"
    "        if ch == '#':\n"
    "            in_comment = True\n"
    "            result.append(ch)\n"
    "            i += 1\n"
    "            continue\n"
    "        if in_triple_double:\n"
    "            result.append(ch)\n"
    "            if ch == '\"' and i + 2 < n and txt[i:i+3] == '\"\"\"':\n"
    "                in_triple_double = False\n"
    "                result.append(txt[i+1]); result.append(txt[i+2])\n"
    "                i += 3\n"
    "                continue\n"
    "            i += 1\n"
    "            continue\n"
    "        if in_triple_single:\n"
    "            result.append(ch)\n"
    "            if ch == \"'\" and i + 2 < n and txt[i:i+3] == \"'''\":\n"
    "                in_triple_single = False\n"
    "                result.append(txt[i+1]); result.append(txt[i+2])\n"
    "                i += 3\n"
    "                continue\n"
    "            i += 1\n"
    "            continue\n"
    "        if in_single:\n"
    "            if ch == '{' and in_fstring_single:\n"
    "                brace_depth += 1\n"
    "            elif ch == '}' and in_fstring_single and brace_depth > 0:\n"
    "                brace_depth -= 1\n"
    "            elif ch == \"'\":\n"
    "                in_single = False\n"
    "                if in_fstring_single:\n"
    "                    in_fstring_single = False\n"
    "            result.append(ch)\n"
    "            i += 1\n"
    "            continue\n"
    "        if in_double:\n"
    "            if ch == '{' and in_fstring_double:\n"
    "                brace_depth += 1\n"
    "            elif ch == '}' and in_fstring_double and brace_depth > 0:\n"
    "                brace_depth -= 1\n"
    "            elif ch == '\"':\n"
    "                in_double = False\n"
    "                if in_fstring_double:\n"
    "                    in_fstring_double = False\n"
    "            result.append(ch)\n"
    "            i += 1\n"
    "            continue\n"
    "        if ch == '\"' and i + 2 < n and txt[i:i+3] == '\"\"\"':\n"
    "            in_triple_double = True\n"
    "            result.append(ch)\n"
    "            i += 1\n"
    "            continue\n"
    "        if ch == \"'\" and i + 2 < n and txt[i:i+3] == \"'''\":\n"
    "            in_triple_single = True\n"
    "            result.append(ch)\n"
    "            i += 1\n"
    "            continue\n"
    "        if ch == 'f' or ch == 'F':\n"
    "            if i + 1 < n and txt[i+1] == '\"':\n"
    "                in_fstring_double = True\n"
    "                in_double = True\n"
    "                brace_depth = 0\n"
    "                result.append(ch)\n"
    "                i += 1\n"
    "                continue\n"
    "            if i + 1 < n and txt[i+1] == \"'\":\n"
    "                in_fstring_single = True\n"
    "                in_single = True\n"
    "                brace_depth = 0\n"
    "                result.append(ch)\n"
    "                i += 1\n"
    "                continue\n"
    "        if ch == '\"':\n"
    "            in_double = True\n"
    "            result.append(ch)\n"
    "            i += 1\n"
    "            continue\n"
    "        if ch == \"'\":\n"
    "            in_single = True\n"
    "            result.append(ch)\n"
    "            i += 1\n"
    "            continue\n"
    "        if ch == '@':\n"
    "            j = i + 1\n"
    "            while j < n and txt[j] != '\\n' and txt[j] != ' ' and txt[j] != '\\t' and txt[j] != ',' and txt[j] != ')' and txt[j] != ']' and txt[j] != '}' and txt[j] != ':' and txt[j] != '.' and txt[j] != '\"' and txt[j] != \"'\" and txt[j] != '#' and txt[j] != ';':\n"
    "                j += 1\n"
    "            if j > i + 1:\n"
    "                var_name = txt[i+1:j]\n"
    "                if re.match(r'^[\\w*+\\-/<>?!=]+$', var_name):\n"
    "                    result.append(f\"builtins.lispy_callback_c('{var_name}')\")\n"
    "                    i = j\n"
    "                    continue\n"
    "        result.append(ch)\n"
    "        i += 1\n"
    "    return ''.join(result)\n"
    "\n"
    "def preprocess(source):\n"
    "    lines = source.split('\\n')\n"
    "    fns = _lp_extract_defs(source)\n"
    "    emitted = set()\n"
    "    out = []\n"
    "    for block_type, block_lines in _lp_split_blocks(lines):\n"
    "        if block_type == 'x':\n"
    "            out.append(block_lines[0])\n"
    "            continue\n"
    "        if block_type == 'lisp':\n"
    "            out.append('\\n'.join(block_lines))\n"
    "            continue\n"
    "        txt = '\\n'.join(block_lines)\n"
    "        for fn in sorted(fns, key=len, reverse=True):\n"
    "            py_name = _lp_name_to_py(fn)\n"
    "            if re.search(r'(?<![.\\w])' + re.escape(fn) + r'\\s*\\(', txt, re.I):\n"
    "                if fn not in emitted:\n"
    "                    out.append(f\"(py:register-callback '{fn})\")\n"
    "                    emitted.add(fn)\n"
    "        for fn in sorted(fns, key=len, reverse=True):\n"
    "            py_name = _lp_name_to_py(fn)\n"
    "            txt = re.sub(\n"
    "                r'(?<![.\\w])' + re.escape(fn) + r'\\s*\\(',\n"
    "                f'builtins.{py_name}_cb(',\n"
    "                txt,\n"
    "                flags=re.I\n"
    "            )\n"
    "        txt = _replace_at_vars(txt)\n"
    "        esc = txt.replace('\\\\', '\\\\\\\\').replace('\"', '\\\\\"')\n"
    "        out.append(f'(py:run \"{esc}\")')\n"
    "    return '\\n'.join(out)\n";

static int builtin_load_hybrid(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    (void)env;
    if (args->count < 1) {
        snprintf(err, errsz, "py:load-hybrid requires a pathname string");
        return 0;
    }
    const char *path = NULL;
    if (args->items[0]->type == VALUE_STRING) path = args->items[0]->as.str;
    else if (args->items[0]->type == VALUE_PATHNAME) path = args->items[0]->as.pathname.namestring;
    else { snprintf(err, errsz, "py:load-hybrid: argument must be a string or pathname"); return 0; }
    char *content = read_text_file(path, err, errsz);
    if (!content) return 0;
    char *processed = hybrid_preprocess_source(content);
    const char *eval_text = processed ? processed : content;
    if (!eval_top_level_text(it, env, path, eval_text, out, err, errsz)) {
        if (processed) free(processed);
        free(content);
        return 0;
    }
    *out = it->true_value;
    interp_set_single_value(it, it->true_value);
    if (processed) free(processed);
    free(content);
    return 1;
}

/* Auto-detection and C wrapper */
static int source_is_hybrid(const char *src) {
    const char *p = src;
    int paren_depth = 0;
    while (*p) {
        while (*p == ' ' || *p == '\t' || *p == '\r' || *p == '\n') p++;
        if (*p == '\0') break;
        if (*p == ';') { while (*p && *p != '\n') p++; continue; }
        if (*p == '#') {
            /* All # constructs are Lisp (#+, #-, #|, #_, #\, #', etc.) */
            if (p[1] == '|') {
                /* #| ... |# block comment: skip to matching |# */
                p += 2;
                while (*p) {
                    if (*p == '|' && p[1] == '#') { p += 2; break; }
                    p++;
                }
            } else {
                /* Other # constructs: skip current line */
                while (*p && *p != '\n') p++;
                if (*p == '\n') p++;
            }
            continue;
        }
        if (*p == '(') {
            int in_string = 0;
            while (*p && *p != '\n') {
                if (in_string) {
                    if (*p == '\\' && p[1]) { p += 2; continue; }
                    if (*p == '"') in_string = 0;
                    p++; continue;
                }
                if (*p == '"') { in_string = 1; p++; continue; }
                if (*p == '(') paren_depth++;
                if (*p == ')') { if (paren_depth > 0) paren_depth--; }
                p++;
            }
            if (*p == '\n') p++;
            continue;
        }
        if (*p == ')') {
            if (paren_depth > 0) paren_depth--;
            p++;
            while (*p && *p != '\n') p++;
            if (*p == '\n') p++;
            continue;
        }
        if (paren_depth > 0) {
            while (*p && *p != '\n') p++;
            if (*p == '\n') p++;
            continue;
        }
        return 1;
    }
    return 0;
}

static char *hybrid_preprocess_source(const char *src) {
    char *result = NULL;
    if (!source_is_hybrid(src)) return NULL;
    PY_GIL_ENSURE();
    {
        PyObject *main_dict = PyModule_GetDict(PyImport_AddModule("__main__"));
        PyObject *py_src = PyUnicode_FromString(src);
        PyDict_SetItemString(main_dict, "_lp_src", py_src);
        Py_DECREF(py_src);

        /* Load embedded preprocessor (once) */
        static int pp_loaded = 0;
        if (!pp_loaded) {
            PyObject *pp_res = PyRun_String(LP_PREPROCESS_PY, Py_file_input, main_dict, main_dict);
            if (!pp_res) { PY_GIL_RELEASE(); return NULL; }
            Py_DECREF(pp_res);
            pp_loaded = 1;
        }

        /* Call preprocess(_lp_src) */
        PyObject *call_res = PyRun_String("_lp_result = preprocess(_lp_src)\n", Py_file_input, main_dict, main_dict);
        if (!call_res) { PY_GIL_RELEASE(); return NULL; }
        Py_DECREF(call_res);

        PyObject *py_processed = PyDict_GetItemString(main_dict, "_lp_result");
        if (!py_processed) { PY_GIL_RELEASE(); return NULL; }
        const char *processed = PyUnicode_AsUTF8(py_processed);
        if (!processed) { PY_GIL_RELEASE(); return NULL; }
        result = xstrdup_c(processed);
    }
    PY_GIL_RELEASE();
    return result;
}

/* ---- Pickle bridge for save/load world ---- */

static int builtin_py_pickle_dumps(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    (void)env;
    if (args->count != 1) { snprintf(err, errsz, "py:pickle-dumps requires 1 argument: python-object"); return 0; }
    Value *obj = args->items[0];
    if (obj->type != VALUE_PYTHON || obj->as.python.obj == NULL) {
        snprintf(err, errsz, "py:pickle-dumps: not a Python object"); return 0;
    }
    PY_GIL_ENSURE();
    PyObject *pickle_mod = PyImport_ImportModule("pickle");
    if (!pickle_mod) { PY_GIL_RELEASE(); snprintf(err, errsz, "py:pickle-dumps: cannot import pickle"); return 0; }
    PyObject *py_bytes = PyObject_CallMethod(pickle_mod, "dumps", "O", (PyObject*)obj->as.python.obj);
    Py_DECREF(pickle_mod);
    if (!py_bytes) { py_bridge_check_error(err, errsz); PY_GIL_RELEASE(); return 0; }
    /* Convert bytes to hex string via Python */
    {
        PyObject *binascii = PyImport_ImportModule("binascii");
        PyObject *py_hex_bytes = NULL;
        if (binascii) {
            py_hex_bytes = PyObject_CallMethod(binascii, "hexlify", "O", py_bytes);
            Py_DECREF(binascii);
        }
        Py_DECREF(py_bytes);
        if (!py_hex_bytes) { PY_GIL_RELEASE(); snprintf(err, errsz, "py:pickle-dumps: hex encode failed"); return 0; }
        /* Decode bytes to str so python_to_lisp gives a Lisp string */
        PyObject *py_hex_str = PyObject_CallMethod(py_hex_bytes, "decode", "s", "ascii");
        Py_DECREF(py_hex_bytes);
        if (!py_hex_str) { PY_GIL_RELEASE(); snprintf(err, errsz, "py:pickle-dumps: decode failed"); return 0; }
        PY_GIL_RELEASE();
        *out = python_to_lisp(it, py_hex_str, err, errsz);
        Py_DECREF(py_hex_str);
    }
    interp_set_single_value(it, *out);
    return 1;
}

static int builtin_py_pickle_loads(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    (void)env;
    if (args->count != 1) { snprintf(err, errsz, "py:pickle-loads requires 1 argument: hex-string"); return 0; }
    const char *hex_str = NULL;
    Value *arg = args->items[0];
    if (arg->type == VALUE_STRING) hex_str = arg->as.str;
    else { snprintf(err, errsz, "py:pickle-loads: argument must be a hex string"); return 0; }
    PY_GIL_ENSURE();
    /* Decode hex to bytes via Python */
    PyObject *py_hex = PyUnicode_FromString(hex_str ? hex_str : "");
    if (!py_hex) { PY_GIL_RELEASE(); snprintf(err, errsz, "py:pickle-loads: cannot create string"); return 0; }
    PyObject *binascii = PyImport_ImportModule("binascii");
    PyObject *py_bytes = NULL;
    if (binascii) {
        py_bytes = PyObject_CallMethod(binascii, "unhexlify", "O", py_hex);
        Py_DECREF(binascii);
    }
    Py_DECREF(py_hex);
    if (!py_bytes) { PY_GIL_RELEASE(); snprintf(err, errsz, "py:pickle-loads: hex decode failed"); return 0; }
    PyObject *pickle_mod = PyImport_ImportModule("pickle");
    if (!pickle_mod) { Py_DECREF(py_bytes); PY_GIL_RELEASE(); snprintf(err, errsz, "py:pickle-loads: cannot import pickle"); return 0; }
    PyObject *py_obj = PyObject_CallMethod(pickle_mod, "loads", "O", py_bytes);
    Py_DECREF(pickle_mod);
    Py_DECREF(py_bytes);
    if (!py_obj) { py_bridge_check_error(err, errsz); PY_GIL_RELEASE(); return 0; }
    PY_GIL_RELEASE();
    *out = make_python_value((void*)py_obj);
    interp_set_single_value(it, *out);
    return 1;
}

#if defined(_WIN32)
static int found_python_home(wchar_t *out_path, size_t out_size) {
    wchar_t prog_path[MAX_PATH];
    wchar_t *last_sep;
    wchar_t candidate[MAX_PATH];
    GetModuleFileNameW(NULL, prog_path, MAX_PATH);
    last_sep = wcsrchr(prog_path, L'\\');
    if (last_sep == NULL) return 0;
    *last_sep = L'\0';
    /* Installed layout: exe_dir/Lib */
    wcscpy(candidate, prog_path);
    wcscat(candidate, L"\\Lib");
    if (GetFileAttributesW(candidate) != INVALID_FILE_ATTRIBUTES) {
        wcsncpy(out_path, prog_path, out_size - 1);
        out_path[out_size - 1] = L'\0';
        return 1;
    }
    /* Dev layout (bin/): exe_dir/../Python-3.14.5/Lib */
    last_sep = wcsrchr(prog_path, L'\\');
    if (last_sep != NULL) {
        *last_sep = L'\0';
        wcscpy(candidate, prog_path);
        wcscat(candidate, L"\\Python-3.14.5\\Lib");
        if (GetFileAttributesW(candidate) != INVALID_FILE_ATTRIBUTES) {
            wcscpy(candidate, prog_path);
            wcscat(candidate, L"\\Python-3.14.5");
            wcsncpy(out_path, candidate, out_size - 1);
            out_path[out_size - 1] = L'\0';
            return 1;
        }
    }
    return 0;
}
#endif

static char *parse_pyvenv_cfg_home(const char *venv_path) {
    char cfg_path[4096];
    int n = snprintf(cfg_path, sizeof(cfg_path), "%s\\pyvenv.cfg", venv_path);
    if (n < 0 || (size_t)n >= sizeof(cfg_path)) return NULL;
    FILE *f = fopen(cfg_path, "r");
    if (!f) {
        n = snprintf(cfg_path, sizeof(cfg_path), "%s/pyvenv.cfg", venv_path);
        if (n < 0 || (size_t)n >= sizeof(cfg_path)) return NULL;
        f = fopen(cfg_path, "r");
    }
    if (!f) return NULL;
    char line[4096];
    char *home = NULL;
    while (fgets(line, sizeof(line), f)) {
        const char *p = line;
        while (*p == ' ' || *p == '\t') p++;
        if (strncmp(p, "home", 4) != 0) continue;
        p += 4;
        while (*p == ' ' || *p == '\t') p++;
        if (*p != '=') continue;
        p++;
        while (*p == ' ' || *p == '\t') p++;
        size_t len = strlen(p);
        while (len > 0 && (p[len-1] == '\r' || p[len-1] == '\n' || p[len-1] == ' ' || p[len-1] == '\t'))
            len--;
        if (len == 0) break;
        home = (char *)malloc(len + 1);
        if (home) {
            memcpy(home, p, len);
            home[len] = '\0';
        }
        break;
    }
    fclose(f);
    return home;
}

#if defined(_WIN32)
static int str_to_wide(const char *src, wchar_t *dst, size_t dst_size) {
    int r = MultiByteToWideChar(CP_UTF8, 0, src, -1, dst, (int)dst_size);
    return (r > 0);
}
#else
static int str_to_wide(const char *src, wchar_t *dst, size_t dst_size) {
    size_t r = mbstowcs(dst, src, dst_size);
    return (r != (size_t)-1 && r < dst_size);
}
#endif

static int python_runtime_init(Interp *it, const char *venv_path, char *err, size_t errsz) {
    g_lispy_interp = it;
    if (!Py_IsInitialized()) {
        char abs_venv[MAX_PATH];
        char *base_home = NULL;
        char *home_prefix = NULL;
        abs_venv[0] = '\0';
        if (venv_path != NULL) {
#if defined(_WIN32)
            GetFullPathNameA(venv_path, MAX_PATH, abs_venv, NULL);
#else
            if (realpath(venv_path, abs_venv) == NULL)
                abs_venv[0] = '\0';
#endif
            if (abs_venv[0] != '\0') {
                base_home = parse_pyvenv_cfg_home(abs_venv);
                if (base_home != NULL) {
#if defined(_WIN32)
                    SetEnvironmentVariableA("VIRTUAL_ENV", abs_venv);
#else
                    setenv("VIRTUAL_ENV", abs_venv, 1);
#endif
                } else {
                    abs_venv[0] = '\0';
                }
            }
        }
        PyConfig config;
        PyConfig_InitPythonConfig(&config);
        if (base_home != NULL) {
#ifndef _WIN32
            size_t home_len = strlen(base_home);
            if (home_len >= 4 && strcmp(base_home + home_len - 4, "/bin") == 0) {
                base_home[home_len - 4] = '\0';
                home_len -= 4;
            }
            home_prefix = xstrdup_c(base_home);
#endif
            wchar_t home_wide[MAX_PATH] = {0};
            if (str_to_wide(base_home, home_wide, MAX_PATH)) {
                PyConfig_SetString(&config, &config.home, home_wide);
            }
            free(base_home);
        } else {
#if defined(_WIN32)
            wchar_t home_path[MAX_PATH] = {0};
            if (found_python_home(home_path, MAX_PATH)) {
                PyConfig_SetString(&config, &config.home, home_path);
            }
#endif
        }
        PyStatus status = Py_InitializeFromConfig(&config);
        PyConfig_Clear(&config);
        if (PyStatus_Exception(status)) {
            snprintf(err, errsz, "failed to initialize Python runtime: %s",
                     status.err_msg ? status.err_msg : "unknown");
            return 0;
        }
        if (!Py_IsInitialized()) {
            snprintf(err, errsz, "failed to initialize Python runtime");
            return 0;
        }
        if (abs_venv[0] != '\0') {
            char venv_path_fwd[MAX_PATH];
            size_t vi = 0;
            for (const char *s = abs_venv; *s && vi < MAX_PATH - 1; s++, vi++)
                venv_path_fwd[vi] = (*s == '\\') ? '/' : *s;
            venv_path_fwd[vi] = '\0';
            char setup_code[16384];
            snprintf(setup_code, sizeof(setup_code),
                "import sys, site, os as _os\n"
                "_venv = '%s'\n"
                "_sys_base = sys.base_prefix\n"
                "sys.prefix = sys.exec_prefix = _venv\n"
                "sys.base_prefix = sys.base_exec_prefix = '%s'\n"
                "for _p in list(sys.path):\n"
                "    if ('site-packages' in _p or 'dist-packages' in _p) and _p.startswith(_sys_base):\n"
                "        sys.path.remove(_p)\n"
                "_pv = 'python' + str(sys.version_info[0]) + '.' + str(sys.version_info[1])\n"
                "for _sp in [_os.path.join(_venv, 'lib', _pv, 'site-packages'), _os.path.join(_venv, 'Lib', 'site-packages')]:\n"
                "    if _os.path.isdir(_sp):\n"
                "        site.addsitedir(_sp)\n"
                "        if _sp in sys.path:\n"
                "            sys.path.remove(_sp)\n"
                "        sys.path.insert(1, _sp)\n",
                venv_path_fwd, home_prefix ? home_prefix : venv_path_fwd);
            PyRun_SimpleString(setup_code);
#ifndef _WIN32
            free(home_prefix);
#endif
        }
        PyRun_SimpleString("import sys; sys.path.insert(0, '.')");
        PyRun_SimpleString("import os; os.environ.setdefault('PIP_REQUIRE_VIRTUALENV', 'false'); os.environ.setdefault('NO_COLOR', '1')");
        PyRun_SimpleString("import __main__");
    }
    {
        PyObject *builtins = PyImport_ImportModule("builtins");
        if (builtins) {
            static PyMethodDef cb_def = {"lispy_callback_c", lispy_py_callback_impl, METH_VARARGS, NULL};
            PyObject *cb_fn = PyCFunction_New(&cb_def, NULL);
            if (cb_fn) {
                PyObject_SetAttrString(builtins, "lispy_callback_c", cb_fn);
                Py_DECREF(cb_fn);
            }
            PyRun_SimpleString(
                "import builtins\n"
                "def lispy_callback(fn_name, *args):\n"
                "    try:\n"
                "        return builtins.lispy_callback_c(fn_name, *args)\n"
                "    except Exception as e:\n"
                "        import sys\n"
                "        m = sys.modules.get('__main__')\n"
                "        if m: m._lispy_cb = (fn_name, args)\n"
                "        raise\n"
                "builtins.lispy_callback = lispy_callback\n");
            Py_DECREF(builtins);
        }
    }
    return 1;
}

static void python_runtime_finalize(void) {
    if (Py_IsInitialized()) {
        Py_Finalize();
    }
}

static int builtin_py_chain(Interp *it, Env *env, const ValueArray *args, Value **out, char *err, size_t errsz) {
    if (args->count < 1) { snprintf(err, errsz, "py:%%chain requires at least 1 argument"); return 0; }
    Value *current = NULL;
    {
        Value *first = args->items[0];
        const char *first_name = NULL;
        if (first->type == VALUE_SYMBOL) first_name = first->as.str;
        else if (first->type == VALUE_STRING) first_name = first->as.str;
        if (first_name != NULL) {
            Value *pv = NULL;
            if (eval_python_symbol(it, first, &pv, err, errsz)) {
                current = pv;
            } else {
                int is_bound = 0;
                Value *bound = NULL;
                {
                    Value *sym = first;
                    if (sym->type != VALUE_SYMBOL) {
                        sym = make_symbol_value(first_name);
                    }
                    if (symbol_value_lookup_symbol(it, env, sym, &bound, &is_bound) && is_bound) {
                        current = bound;
                        if (sym != first) { /* free temporary symbol */ }
                    }
                }
                if (current == NULL) {
                    /* Fallback: try *name* for dynamic/special variables */
                    if (first_name[0] != '*') {
                        char star_name[256];
                        snprintf(star_name, sizeof(star_name), "*%s*", first_name);
                        Value *star_sym = make_symbol_value(star_name);
                        int is_bound2 = 0;
                        Value *bound2 = NULL;
                        if (symbol_value_lookup_symbol(it, env, star_sym, &bound2, &is_bound2) && is_bound2)
                            current = bound2;
                    }
                    if (current == NULL) {
                        snprintf(err, errsz, "py:%%chain: cannot resolve '%s' as module or variable", first_name);
                        return 0;
                    }
                }
            }
        } else if (first->type == VALUE_PYTHON) {
            current = first;
        } else {
            snprintf(err, errsz, "py:%%chain: first argument must be symbol, string, or Python object");
            return 0;
        }
    }
    for (int i = 1; i < args->count; i++) {
        const char *attr_name = NULL;
        char attr_name_buf[256];
        Value *attr = args->items[i];
        if (attr->type == VALUE_STRING) {
            attr_name = attr->as.str;
        } else if (attr->type == VALUE_SYMBOL || value_is_keyword(attr)) {
            const char *src = attr->as.str;
            if (*src == ':') src++;
            size_t len = strlen(src);
            if (len + 1 > sizeof(attr_name_buf)) {
                snprintf(err, errsz, "py:%%chain: attribute name too long");
                return 0;
            }
            for (size_t j = 0; j < len; j++)
                attr_name_buf[j] = (char)tolower((unsigned char)src[j]);
            attr_name_buf[len] = '\0';
            attr_name = attr_name_buf;
        } else {
            snprintf(err, errsz, "py:%%chain: attribute name must be symbol or string");
            return 0;
        }
        if (current->type != VALUE_PYTHON || current->as.python.obj == NULL) {
            snprintf(err, errsz, "py:%%chain: intermediate value is not a Python object");
            return 0;
        }
        PY_GIL_ENSURE();
        PyObject *py_attr = PyObject_GetAttrString((PyObject*)current->as.python.obj, attr_name);
        if (!py_attr) { py_bridge_check_error(err, errsz); PY_GIL_RELEASE(); return 0; }
        PY_GIL_RELEASE();
        current = python_to_lisp(it, py_attr, err, errsz);
        Py_DECREF(py_attr);
    }
    /* Auto-convert Python scalars to Lisp values for transparent @var access */
    if (current != NULL && current->type == VALUE_PYTHON) {
        Value *converted = python_to_lisp(it, (PyObject*)current->as.python.obj, err, errsz);
        if (converted != NULL && converted->type != VALUE_PYTHON) {
            current = converted;
        }
    }
    *out = current;
    interp_set_single_value(it, current);
    return 1;
}

