    define_runtime_constant_variable(&it, global_env, "most-negative-fixnum", make_int_value(bigint_from_i64(-16777216)));
    define_runtime_constant_variable(&it, global_env, "array-dimension-limit", make_int_value(bigint_from_i64(1073741824)));
    define_runtime_constant_variable(&it, global_env, "array-total-size-limit", make_int_value(bigint_from_i64(1073741824)));
    {
        ValueArray kwlist;
        value_array_init(&kwlist);
        value_array_push(&kwlist, make_keyword_value("&OPTIONAL"));
        value_array_push(&kwlist, make_keyword_value("&REST"));
        value_array_push(&kwlist, make_keyword_value("&KEY"));
        value_array_push(&kwlist, make_keyword_value("&ALLOW-OTHER-KEYS"));
        value_array_push(&kwlist, make_keyword_value("&AUX"));
        value_array_push(&kwlist, make_keyword_value("&BODY"));
        value_array_push(&kwlist, make_keyword_value("&WHOLE"));
        value_array_push(&kwlist, make_keyword_value("&ENVIRONMENT"));
        define_runtime_constant_variable(&it, global_env, "lambda-list-keywords", make_list_value(&kwlist));
    }
